RG.HK["16"] = [{"id":"16_toyama_jo","n":"富山城（佐々成政と富山藩の城）","yomi":"とやまじょう","cat":"城","rank":"S","y":1585,"era":["azuchi","edo","showa"],"sh":"","ad":"富山市本丸","st":"JR・あいの風とやま鉄道の富山駅から歩いて約10分（市内電車「国際会議場前」「丸の内」すぐ）","la":36.6926,"lo":137.2104,"hook":"秀吉に逆らった男・佐々成政がこもり、のちに加賀百万石の «分家» が250年守った城。いまの天守は、戦後の復興を願って建てた «夢の天守» だ。","lead":"富山城は、神通川のそばに建てられた平城です。戦国時代には佐々成政が城主となり、豊臣秀吉の大軍に囲まれて降伏しました。江戸時代は富山藩10万石の城になり、いま公園に立つ天守は1954年に建てられた «模擬天守» で、中は郷土博物館になっています。","story":["富山城のはじまりは、戦国時代の中ごろ。越中（富山県）の西半分に力をもっていた神保氏が、東の敵に備えて神通川のほとりに城をかまえたのが最初といわれます。川を天然の堀として使えるこの場所は、越中の東と西をつなぐ «のど元»。だからこそ、上杉謙信もこの城を何度もねらいました。","1580年ごろ、織田信長の命令で越中にやってきたのが佐々成政です。成政は城を大きく作り直し、越中一国の主となりました。ところが本能寺の変のあと、成政は羽柴（豊臣）秀吉と対立する道を選びます。«わしは信長さまへの恩を忘れぬ。猿（秀吉）の下にはつかぬ» ――そんな気持ちだったのかもしれません。","1584年の冬、成政は徳川家康に «一緒に秀吉と戦おう» と頼むため、雪の北アルプスを越えて浜松へ向かったと伝わります。これが有名な «さらさら越え»。けれど家康はすでに秀吉と和解しており、成政の命がけの旅はむくわれませんでした。翌1585年、秀吉は10万ともいわれる大軍で越中に攻めこみ、成政は頭を丸めて降伏しました。","その後、城は前田家のものになります。加賀藩の2代目・前田利長は1605年に隠居してこの城に住みましたが、1609年の大火で城は焼けてしまい、利長は高岡に新しい城を築いて移りました。なぜすぐ直さなかったのでしょう？ 一国一城の考え方が広まるなか、幕府の目も気になったのかもしれません。","1639年、加賀藩から10万石を分けて富山藩が生まれ、前田利次が初代藩主になりました。利次は城を整え直し、以後明治まで13代の藩主がこの城で越中の中部を治めます。富山藩は «売薬» を育てて財政を支えたことでも知られます。明治になって城は取りこわされましたが、石垣と堀の一部は今も残ります。","戦争で焼け野原になった富山市は、1954年の «富山産業大博覧会» にあわせて、城跡に天守を建てました。これは昔の天守の絵図にもとづく復元ではなく、犬山城や彦根城を参考にした «模擬天守»。それでも焼け跡から立ち上がる市民のシンボルとして愛され、2004年には国の登録有形文化財になりました。"],"tl":[["1543年ごろ","神保氏が城を築いたとされる（諸説）"],["1580年ごろ","佐々成政が越中に入り、のちに富山城を本拠とする"],["1584年12月","成政が «さらさら越え» で家康に会いに行くと伝わる"],["1585年","秀吉の «富山の役»。成政が降伏"],["1609年","前田利長の隠居城となっていた城が大火で焼ける"],["1639年","富山藩が成立。初代藩主・前田利次"],["1871年","廃藩置県。やがて城の建物は取りこわされる"],["1954年","富山産業大博覧会で模擬天守が建てられる"],["2004年","天守が国の登録有形文化財に"]],"who":[["佐々成政","織田家の武将。越中の主となり、秀吉と対立した"],["豊臣秀吉","1585年に大軍で越中へ攻めこみ、成政を降伏させた"],["前田利長","加賀藩2代。隠居後に富山城に住み、焼失後は高岡へ"],["前田利次","富山藩の初代藩主"],["前田正甫","富山藩2代藩主。売薬を広めたと伝わる"]],"deep":["本丸の南側に残る石垣には、ひときわ大きな «鏡石» が使われています。見る人を圧倒するための石で、城主の力を見せつける意味があったといわれます。","«さらさら越え» のルートは、立山のザラ峠を通ったとする説が有名ですが、はっきりした記録はなく諸説あります。真冬の3000m級の山を本当に越えられたのか、昔から議論があります。","天守の形は、江戸時代の富山城にあった天守を再現したものではありません。江戸時代の富山城は天守を建てる計画はあったものの、実際には建てられなかったとする見方が一般的です。","城の門の一つ «千歳御門» は、1849年に建てられた富山城の数少ない現存建物です。一度よそに移されましたが、のちに城址公園内に戻されました。","富山藩は «加賀藩の分家»。本家の加賀藩の顔色をうかがいながらの藩運営で財政は苦しく、売薬の奨励はその打開策の一つだったといわれます。","神通川はもともと城のすぐ北を大きく曲がって流れていました。明治時代の «馳越線» 工事で流れがまっすぐに変えられ、旧河道のあとが今の松川や市街地になりました。"],"look":["本丸南側の石垣と «鏡石»","模擬天守（富山市郷土博物館）の城の歴史展示","千歳御門","お堀と松川沿いの遊歩道","隣の «佐藤記念美術館»（天守とつながる建物）"],"q":["佐々成政が冬の山を越えて家康に会いに行った旅は、何とよばれる？","«さらさら越え»。ルートは立山のザラ峠とする説が有名ですが、諸説あります。"],"koji":[],"myth":"«さらさら越え» のルート・時期、築城者・築城年は諸説。成政の側室・早百合の «黒百合» の伝説は後世の物語です。","img":["佐々成政","前田利次","富山城址公園"],"wp":"富山城","rel":{"ev":[],"grave":[]},"ph":[["c:a/a9/Toyama_Municipal_Folk_Museum_%28mock_keep_tower_of_the_Toyama_Castle%29_20180503.jpg",4288,2412,"富山城"],["c:9/94/View_of_Toyama_Castle_from_Toyama_City_Hall.jpg",4608,3456],["c:7/7f/Toyama_Castle06st3200.jpg",3200,2130],["c:1/14/Sato_Memorial_Art_Museum_Toyama02st3200.jpg",3200,2130],["c:0/0e/Toyama_Castle_Tower.jpg",1920,2560],["c:e/ef/Toyama_Castle_Chitose_Gate.jpg",1920,2560],["c:8/8d/Toyama_Castle05.jpg",2503,1825],["c:d/d9/A_Bus_at_Toyama_castle.jpg",2477,1717]]},{"id":"16_takaoka_jo","n":"高岡城（前田利長が築いた水の城）","yomi":"たかおかじょう","cat":"城","rank":"S","y":1609,"era":["edo","meiji"],"sh":"国指定史跡","ad":"高岡市古城","st":"あいの風とやま鉄道・JR高岡駅から歩いて約15分","la":36.7485,"lo":137.0237,"hook":"城の面積の3分の1が «水»。天守も石垣の高い塔もないのに、400年たっても堀の形がほぼそのまま残る、珍しい城。","lead":"高岡城は、加賀藩2代藩主・前田利長が1609年に築いた城です。わずか6年ほどで «一国一城令» により城としての役目を終えましたが、その後も加賀藩が大切に守ったため、水堀や土塁が今もよく残っています。いまは «高岡古城公園» として市民に親しまれています。","story":["1609年、富山城で隠居生活を送っていた前田利長は、大火で住まいを失いました。利長が新しい城の場所に選んだのは、射水郡の «関野» という台地。ここに城と町をいっしょに作り、地名を «高岡» と改めました。中国の古い詩集『詩経』の «鳳凰鳴けり 彼の高き岡に» ということばからとったと伝わります。","城の設計（縄張り）には、キリシタン大名として知られる高山右近がかかわったといわれます。右近は利長に招かれて加賀藩にいました。本丸・二の丸・三の丸などの «くるわ» が水堀で囲まれ、まるで島が浮かんでいるような形。«ここなら敵も簡単には近づけまい» ――水を生かした守りの城でした。","ところが利長は1614年に亡くなり、翌1615年には幕府の «一国一城令» が出ます。加賀藩の越中での城は1つに減らされ、高岡城は廃城になりました。できてわずか6年。«これでは高岡の町もさびれてしまう» と心配した町人も多かったことでしょう。","そこで3代藩主・前田利常は、高岡を «商工業の町» に切りかえる政策をとりました。城のあとには米蔵や塩蔵、火薬の倉庫などが置かれ、藩の大事な施設として管理されます。建物はなくなっても、堀や土塁はこわされずに残りました。これが «遺構がよく残る理由» です。","明治になって城跡は公園になり、本丸には射水神社が移されてきました。1875年に開かれた «高岡古城公園» は、今では春の桜、秋の紅葉の名所。2015年には国の史跡に指定され、日本100名城にも選ばれています。池のような堀をボートでめぐると、利長がえがいた «水の城» の大きさが実感できます。"],"tl":[["1609年","前田利長が関野に築城を始め、地名を «高岡» と改める"],["1614年","前田利長が亡くなる"],["1615年","一国一城令により廃城"],["江戸時代","加賀藩の米蔵・塩蔵などとして城跡が管理される"],["1875年","公園として開かれる。のちに本丸に射水神社が移る"],["2015年","国の史跡に指定"]],"who":[["前田利長","加賀藩2代藩主。高岡城と高岡の町をつくった"],["高山右近","キリシタン大名。縄張りにかかわったと伝わる"],["前田利常","加賀藩3代藩主。廃城後、高岡を商工業の町として育てた"],["前田利家","利長の父。加賀藩の祖"]],"deep":["堀の面積は城域の約3分の1を占めるといわれ、«水の城» とよばれるゆえんです。土塁と水堀の配置が、築城当時の姿をかなりよく伝えています。","高山右近の関与は、右近が当時加賀藩にいたことと城の縄張りの特徴から語られますが、それを直接示す確実な史料は少なく、«伝わる» 段階の話です。","本丸と二の丸をつなぐ部分などに石垣が残り、石には «刻印» が見つかっています。石を運んだ担当者の目印と考えられ、石垣を調べる楽しみの一つです。","高岡は利長の死後、«城下町» から «商工業の町» へと性格を変えました。高岡銅器（鋳物）の始まりも、利長が鋳物師を呼び寄せたことにさかのぼるといわれます。","城は «廃城» になったものの、加賀藩は城跡をこわさず «御城» として立ち入りを制限しました。これは、いざというときの再利用を考えていたからだという見方もあります。","本丸広場には前田利長の銅像があり、公園内には高岡市立博物館もあります。城と町の成り立ちを学ぶなら、まずここを訪ねるのがおすすめです。"],"look":["池のように広い水堀（ボートで回れる季節あり）","本丸の土塁と石垣の刻印","前田利長の銅像","射水神社","高岡市立博物館"],"q":["«高岡» という地名は、どんな本のことばからとったといわれる？","中国の古い詩集『詩経』の «鳳凰鳴けり 彼の高き岡に» からとったと伝わります。"],"koji":[{"w":"鳳凰鳴けり 彼の高き岡に","m":"すぐれた人（鳳凰）が高い岡で鳴く、という意味。めでたい土地であることを願って地名にしたと伝わる"}],"myth":"高山右近の縄張り関与は伝承。地名の由来は『詩経』説が広く知られています。","img":["前田利長","高山右近","高岡古城公園"],"wp":"高岡城","rel":{"ev":[],"grave":[]},"ph":[["c:a/af/Takaoka_Castle.jpg",4608,3456,"高岡城"],["c:5/5e/Prunus_sp_in_Takaoka_Kojo_Park_13.jpg",2304,1728],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:6/68/Maeda_Toshinaga.jpg",354,396,"前田利長"],["c:3/38/Takayama-Ukon.jpg",1380,1850,"高山右近"]]},{"id":"16_zuiryuji","n":"瑞龍寺（前田利長の菩提寺・国宝）","yomi":"ずいりゅうじ","cat":"寺社","rank":"S","y":1663,"era":["edo"],"sh":"国宝（山門・仏殿・法堂）","ad":"高岡市関本町","st":"あいの風とやま鉄道・JR高岡駅の南口から歩いて約10分","la":36.7359,"lo":137.0165,"hook":"弟が兄のために建てた、富山県でただ一つの国宝の寺。仏殿の屋根はなんと «鉛» でふかれている。","lead":"瑞龍寺は、加賀藩3代藩主・前田利常が、兄で2代藩主の前田利長の菩提（死後の幸せ）をとむらうために建てた禅寺（曹洞宗）です。山門・仏殿・法堂の3つの建物が国宝。お堂が回廊でぐるりと囲まれた、江戸時代はじめの禅宗の寺の姿をよく残しています。","story":["1614年、前田利長は高岡で亡くなりました。子どものいなかった利長は、年のはなれた異母弟・利常をあとつぎに選んでいました。«兄上がいなければ、今のわたしはない» ――利常にとって利長は、藩主の座をゆずってくれた恩人でした。","利常は兄の菩提寺を高岡につくると決め、大工の棟梁・山上善右衛門嘉広に工事をまかせます。工事は長い年月をかけて進められ、利長の50回忌のころにあたる1663年ごろ、ようやく伽藍（寺の建物群）がととのったといわれます。利常自身はその完成を見ることなく亡くなりました。","寺に入ると、まず大きな山門、その奥に仏殿、さらに奥に法堂が一直線に並びます。まわりを回廊がぐるりと囲み、左右には禅堂や大庫裏。上から見ると «伽藍» が整然と並ぶこの形は、中国の禅寺をお手本にしたものです。なぜこんなにきっちりした形なのでしょう？ 禅の修行の «規律» を建物で表しているともいわれます。","とくにおもしろいのが仏殿の屋根です。ふつうの瓦ではなく、なんと鉛の板でふかれています。重さは約47トンともいわれます。«いざ戦になれば、屋根をとかして鉄砲の弾にするためだ» という話がよく語られますが、これは言い伝え。鉛は雪に強く長持ちする、という実用的な理由もあったと考えられます。","明治時代、寺は荒れた時期もありました。しかし昭和の終わりから平成にかけて大修理が行われ、1997年には山門・仏殿・法堂が国宝に指定されます。今では夜のライトアップも行われ、高岡の人たちの誇りになっています。寺の東には約870m（八丁）の «八丁道» がのび、利長の墓所へとつながっています。"],"tl":[["1614年","前田利長が高岡で亡くなる"],["1645年ごろ","前田利常が菩提寺の造営を本格化させたとされる"],["1658年","前田利常が亡くなる"],["1663年ごろ","利長の50回忌のころ、伽藍がととのう"],["1818年","山門が再建される（火災ののち）"],["1985〜1996年","平成の大修理"],["1997年","山門・仏殿・法堂が国宝に指定"]],"who":[["前田利長","加賀藩2代藩主。この寺でとむらわれている"],["前田利常","加賀藩3代藩主。兄のために寺を建てた"],["山上善右衛門嘉広","加賀藩の大工棟梁。伽藍の建築を担った"]],"deep":["国宝は山門・仏殿・法堂の3棟。ほかに総門・禅堂・大庫裏・回廊などが国の重要文化財です。伽藍全体がそろって残る例は全国的にも貴重です。","仏殿の鉛瓦は、金沢城の石川門などでも使われている加賀藩らしい技術です。«弾丸にするため» という話は言い伝えで、確かな史料はありません。","山門は1818年に再建されたもので、二重の屋根をもつ堂々とした門。仏殿は江戸時代初めの建築で、禅宗様（唐様）の特徴である «詰組»（柱の上だけでなく間にも組物を置く）がよく見られます。","法堂の内部には利長の位牌が安置されています。天井や柱の意匠は仏殿より落ち着いたもので、建物ごとに違う表情を比べるのも楽しみです。","八丁道の先にある «前田利長墓所» も国の史跡です。高さ約12mの墓碑は、藩主の墓としては全国でも最大級といわれます。","瑞龍寺の «瑞龍» は利長の法名（瑞龍院）にちなむ名前。寺名そのものが、兄をしのぶ弟の気持ちを伝えています。"],"look":["一直線に並ぶ山門・仏殿・法堂","仏殿の鉛瓦（色の違いに注目）","回廊にかこまれた広い中庭","法堂の利長の位牌","八丁道と前田利長墓所"],"q":["瑞龍寺の仏殿の屋根は、何でふかれている？","鉛。«弾にするため» という話は言い伝えで、雪に強いことも理由と考えられます。"],"koji":[],"myth":"鉛瓦を «戦のときに弾にするため» とする話は伝承です。完成年は資料によって幅があります。","img":["前田利長","前田利常","前田利長墓所"],"wp":"瑞龍寺","rel":{"ev":[],"grave":[]},"ph":[["c:6/68/Maeda_Toshinaga.jpg",354,396,"前田利長"],["c:b/b9/Maeda_Toshitsune.png",1294,1725,"前田利常"],["c:d/df/Maedatoshinagakoubosho2.jpg",2272,1704,"前田利長墓所"]]},{"id":"16_shokoji","n":"勝興寺（越中国府跡に建つ一向一揆の拠点）","yomi":"しょうこうじ","cat":"寺社","rank":"S","y":1584,"era":["nara","muromachi","edo"],"sh":"国宝（本堂・大広間及び式台）・国の重要文化財","ad":"高岡市伏木古国府","st":"JR氷見線の伏木駅から歩いて約10分","la":36.7921,"lo":137.0555,"hook":"かつて大伴家持が国司として暮らした «越中国府» の跡地に、戦国の一向一揆の大寺が建つ。1300年の歴史が重なる場所。","lead":"勝興寺は浄土真宗の大きなお寺です。戦国時代には越中の一向一揆の中心の一つとなり、1584年ごろに今の伏木の地へ移ってきました。ここは奈良時代に越中の役所（国府）があったとされる場所。2022年には本堂と大広間・式台が国宝に指定されました。","story":["奈良時代、この台地には越中国の役所 «国府» がありました。746年、ここに国司として赴任してきたのが、『万葉集』をまとめたといわれる歌人・大伴家持です。家持は5年ほどの在任中に、立山や二上山、越中の海をよんだ歌をたくさん残しました。«都から遠く離れたこの地で、なぜこんなに歌が生まれたのか?» ――雄大な自然が家持の心を動かしたのかもしれません。","時代は下って15世紀。本願寺の蓮如が北陸に教えを広めると、越中でも浄土真宗の信者が急増しました。勝興寺のはじまりは、蓮如が越中の砺波地方に開いた «土山御坊» と伝わります。寺は何度か場所を変えながら、井波の瑞泉寺と並ぶ越中一向一揆の中心になっていきました。","戦国時代、一向一揆は大名とも渡り合う大きな力でした。上杉謙信や織田信長とも戦い、勝興寺も戦火に巻きこまれます。1584年ごろ、越中を治めていた佐々成政から «古国府» の地を与えられ、寺はこの伏木の台地に移ってきました。こうして、奈良の国府跡に戦国の大寺が建つことになったのです。","江戸時代、勝興寺は加賀藩の前田家と深く結びつき、藩主の一族から住職を迎えるなど高い格式をもちました。本堂は1795年に完成した大きな建物で、京都の西本願寺の阿弥陀堂を手本にしたといわれます。広い境内には大広間や書院、唐門などが並び、まるで一つの町のようです。","長い年月で建物は傷みましたが、1998年から約23年におよぶ «平成の大修理» で、江戸時代の姿がよみがえりました。そして2022年、本堂と大広間及び式台が国宝に指定されます。寺には «七不思議» と呼ばれる言い伝えも残り、境内を歩きながら探すのも楽しみの一つです。"],"tl":[["746年","大伴家持が越中国守として国府に赴任"],["1471年ごろ","蓮如が越中に土山御坊を開いたとされる（勝興寺の起源）"],["1584年ごろ","佐々成政から古国府の地を与えられ移転"],["1795年","現在の本堂が完成"],["1998〜2021年","平成の大修理"],["2022年","本堂・大広間及び式台が国宝に指定"]],"who":[["大伴家持","奈良時代の歌人。越中国守としてこの地の国府に赴任"],["蓮如","本願寺8世。北陸に教えを広め、勝興寺の起源をつくった"],["佐々成政","越中の大名。寺に古国府の地を与えた"],["前田家","加賀藩主。江戸時代の勝興寺を保護した"]],"deep":["越中国府の正確な位置は、発掘で建物跡がはっきり確かめられていないため諸説ありますが、勝興寺の境内とその周辺が有力とされています。","大伴家持が越中時代によんだ歌は、『万葉集』の中で200首をこえるといわれます。近くには «高岡市万葉歴史館» があり、家持と越中の関係を詳しく学べます。","国宝の本堂は、間口・奥行きともに大きな真宗寺院らしい建物で、たくさんの門徒が集まれるよう内部が広々としています。修理では江戸時代の彩色も調べて復元されました。","重要文化財に指定された建物は、唐門・式台門・経堂・鼓堂など多数あります。これだけの建物群がまとまって残る真宗寺院は全国でも貴重です。","勝興寺の «七不思議» には、«実ならずの銀杏» «天から降った石» などの話があります。どれも言い伝えで、寺の歴史の古さを物語るものとして語り継がれています。","加賀藩と勝興寺の結びつきは政治的にも重要でした。一向一揆のような門徒の力を、藩が寺を通じてまとめる役割もあったと考えられます。"],"look":["国宝の本堂（大きな屋根と内部の広さ）","大広間と式台","唐門","境内に点在する «七不思議»","近くの越中国分寺跡・万葉歴史館"],"q":["勝興寺が建つ伏木の台地には、奈良時代に何があったとされる？","越中国の役所 «国府»。大伴家持が国守として赴任しました。"],"koji":[],"myth":"国府の正確な位置、寺の起源（土山御坊）の年代、七不思議は伝承・諸説を含みます。","img":["大伴家持","蓮如","越中国府"],"wp":"勝興寺","rel":{"ev":[],"grave":[]},"ph":[["c:5/5a/Fushiki_Shokoji_main_hall_ac.jpg",5863,3899,"勝興寺"],["c:a/a3/Fushiki_Shokoji_kyodo_ac.jpg",5674,3773],["c:1/17/Fushiki_Shokoji_kodo_ac_%282%29.jpg",5591,3717],["c:d/d7/Fushiki_Shokoji_ac_%283%29.jpg",5792,3851],["c:c/cc/Fushiki_Shokoji_ac_%282%29.jpg",5863,3899],["c:0/0d/Fushiki_Shokoji_ac_%281%29.jpg",5509,3663],["c:5/58/Sh%C5%8Dk%C5%8D-ji_Karamon.jpg",3973,2980],["c:9/99/%E5%8B%9D%E8%88%88%E5%AF%BA%E5%94%90%E9%96%80.JPG",3888,2592]]},{"id":"16_kurikara","n":"倶利伽羅峠（木曽義仲の火牛の計）","yomi":"くりからとうげ","cat":"古戦場","rank":"S","y":1183,"era":["heian"],"sh":"","ad":"小矢部市石坂（石川県津幡町との境）","st":"あいの風とやま鉄道の石動駅から車で約15分。徒歩の古道ハイキングもできる","la":36.705,"lo":136.833,"hook":"夜の峠に、角にたいまつを結んだ牛の群れがなだれこむ――。«火牛の計» の伝説で知られる源平合戦の大逆転の舞台。","lead":"倶利伽羅峠は、富山県と石川県の境にある峠です。1183年、ここで木曽（源）義仲の軍が平家の大軍を夜襲でうち破りました。この勝利で義仲は勢いをつけ、ついに京都へ攻めのぼります。牛の角に火をつけて突っこませた «火牛の計» の話が有名ですが、これは後の軍記物語に出てくる話です。","story":["1183年の春、平家は «木曽の山猿を討て» と、平維盛を大将とする大軍を北陸へ送りました。『平家物語』は10万騎とも書きますが、これは大げさな数字と考えられています。対する木曽義仲は、信濃（長野県）で兵をあげた源氏の武将。北陸の武士たちを味方にしながら、越中へと進んでいました。","平家軍は加賀から越中へ入ろうと、倶利伽羅峠のある砺波山に登りました。義仲は、平家を山の上にくぎづけにしておいて、夜にいっきに攻めかかる作戦を立てたといわれます。昼のあいだは «小ぜりあい» だけをくりかえし、平家に «今日は戦はないだろう» と油断させたのです。","そして夜。義仲の軍は正面と背後からときの声をあげて攻めかかりました。暗闇の中、逃げ場を失った平家の兵たちは、谷へ谷へと追いつめられ、次々に深い谷に落ちていったと『平家物語』は語ります。その谷は後に «地獄谷» とよばれるようになったといわれます。","ここで有名なのが «火牛の計»。数百頭の牛の角にたいまつを結び、平家の陣に突っこませたという話です。でもこれは『源平盛衰記』という後の物語に出てくる場面で、『平家物語』の古い形には出てきません。中国の戦国時代の «田単» の話をもとにした脚色だろう、という見方が強いのです。","この戦いのあと、義仲は加賀の篠原でも平家を破り、7月には京都に入りました。平家は都を捨てて西へ落ちていきます。しかし義仲の栄光は長く続かず、翌年には源頼朝が送った軍に敗れて近江の粟津で討たれました。峠には今、平家の兵をとむらう «源平供養塔» と、火牛の像が静かに立っています。"],"tl":[["1180年","木曽義仲が信濃で兵をあげる"],["1183年4月","平維盛を大将とする平家の大軍が北陸へ出陣"],["1183年5月","倶利伽羅峠の戦い。義仲軍が夜襲で大勝"],["1183年6月","篠原の戦いで義仲が再び平家を破る"],["1183年7月","義仲が京都に入り、平家は都落ち"],["1184年1月","義仲が粟津の戦いで討たれる"]],"who":[["木曽義仲（源義仲）","信濃の源氏の武将。倶利伽羅峠で平家を破った"],["平維盛","平清盛の孫。平家軍の総大将"],["巴御前","義仲に従ったと伝わる女性の武者（『平家物語』などに登場）"],["覚明","義仲の祐筆（書記）。埴生八幡宮に願文を書いたと伝わる"]],"deep":["戦いの前、義仲は近くの «埴生護国八幡宮» に戦勝を祈り、祐筆の覚明が願文を書いたと『平家物語』などに見えます。その八幡宮は今も小矢部市埴生にあります。","«火牛の計» は『源平盛衰記』に詳しく書かれた場面です。戦いの実態を記した同時代の確かな記録は少なく、夜襲で平家が大敗したこと以外は、物語的な脚色が多いと考えられています。","峠道は古代からの «北陸道»。加賀と越中を結ぶ大事な道で、江戸時代には加賀藩の参勤交代もこの道を通りました。","峠の «猿ヶ馬場» は平家の本陣があった場所と伝えられる広場です。平家本陣跡の碑や、源平の武将をしのぶ石碑・句碑が点在し、晴れた日には砺波平野を見わたせます。","松尾芭蕉も『おくのほそ道』の旅でこの峠を越え、義仲をしのぶ句を残しています。義仲に心を寄せた芭蕉は、のちに近江の義仲寺に葬られました。","峠の石川県側には «倶利伽羅不動寺» があり、不動明王の信仰の地としても知られます。«倶利伽羅» とは、不動明王の剣に巻きつく竜のことです。"],"look":["猿ヶ馬場（平家本陣跡と伝わる場所）","火牛の像","源平供養塔","埴生護国八幡宮（麓）","倶利伽羅峠の古道（ハイキングコース）"],"q":["牛の角にたいまつを結んで敵陣に突っこませたという作戦を何という？","«火牛の計»。『源平盛衰記』に出てくる話で、史実かどうかは疑問とされています。"],"koji":[],"myth":"«火牛の計» は軍記物語の脚色とみられます。平家軍の兵数、«地獄谷» の由来、巴御前の実在も諸説あります。","img":["源義仲","平維盛","埴生護国八幡宮"],"wp":"倶利伽羅峠の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:c/c6/Battle_of_Kurikaradani_Kassen_Zu.jpg",8498,4293,"倶利伽羅峠の戦い"],["c:4/4e/Honden_shirayama_hime_shrine_ishikawa.jpg",750,500],["j:f/ff/Kiso-Yoshinaka%26Tomoe-gozen_statue_Kiso-t.jpg",480,640],["c:2/27/Minamoto_no_Yoshinaka.jpg",843,767,"源義仲"],["c:6/6a/Taira_no_Koremori.jpg",283,283,"平維盛"],["c:8/82/Hanyu_Gokoku_Hachiman-gu_Shrine.jpg",3417,2026,"埴生護国八幡宮"]]},{"id":"16_ainokura","n":"相倉合掌造り集落（五箇山）","yomi":"あいのくらがっしょうづくりしゅうらく","cat":"町","rank":"S","y":1700,"era":["edo","heisei"],"sh":"国指定史跡・世界遺産","ad":"南砺市相倉","st":"あいの風とやま鉄道の高岡駅またはJR城端駅から世界遺産バスで «相倉口» 下車、歩いて約5分","la":36.4275,"lo":136.9325,"hook":"雪に閉ざされる山あいの村で、人びとは屋根の下で «火薬の原料» を作っていた。合掌造りの家に隠された、加賀藩の秘密。","lead":"相倉は、五箇山とよばれる山深い地域にある小さな集落です。手を合わせたような急な屋根の «合掌造り» の家が約20棟残り、1995年に岐阜県の白川郷などとともに世界遺産になりました。江戸時代、五箇山では加賀藩のために火薬の原料 «塩硝» や和紙が作られていました。","story":["庄川の深い谷にそって点在する村々を、昔から «五箇山» とよびます。まわりを高い山に囲まれ、冬には2mをこえる雪が積もることもありました。道も険しく、外の世界と行き来するのはたいへん。«陸の孤島» とよばれるほどの場所で、人びとはどうやって暮らしていたのでしょう。","答えの一つが «塩硝» です。塩硝は鉄砲の火薬の原料。五箇山では、家の床下に穴を掘り、草や蚕のふんなどをまぜて何年も寝かせ、その土から塩硝を取り出していました。加賀藩はこれを大切な «軍需品» として買い上げたのです。外から人が入りにくい土地は、秘密を守るのにも都合がよかったといわれます。","合掌造りの家は、大きな屋根の下が2階、3階と何層にも分かれています。そこは蚕を育てる «養蚕» の場所。急な屋根は雪を落としやすく、屋根裏を広く使うためのくふうでした。茅（かや）でふいた屋根は数十年ごとにふき替えが必要で、村じゅうの人が力を合わせる «結（ゆい）» という助け合いで行われてきました。","五箇山は加賀藩の «流刑地» でもありました。罪を犯した人が送られ、村の «お小屋» で暮らしたといいます。深い谷と川が、逃げられない天然の牢屋になっていたのです。今も隣の地区には流刑小屋が復元されています。","昭和の高度成長期、多くの合掌造りが取りこわされました。«このままでは村の風景が消えてしまう» ――相倉の人たちは保存の道を選び、1970年に集落が国の史跡に、1995年には世界遺産になりました。今も人びとが暮らす «生きた集落» なので、訪れるときは静かにマナーを守って歩きましょう。"],"tl":[["江戸時代","五箇山で加賀藩向けの塩硝づくりが盛んになる"],["江戸時代","五箇山が加賀藩の流刑地とされる"],["1970年","相倉集落が国の史跡に指定"],["1994年","重要伝統的建造物群保存地区に選定"],["1995年","«白川郷・五箇山の合掌造り集落» として世界遺産に登録"]],"who":[["加賀藩","五箇山の塩硝・和紙を買い上げ、流刑地としても使った"],["五箇山の村人","塩硝・養蚕・和紙づくりで暮らし、結で家を守ってきた"],["保存にとりくんだ住民","昭和の時代に集落の保存を選んだ"]],"deep":["相倉には合掌造りの家が約20棟残ります。いちばん古いものは江戸時代にさかのぼるとされ、明治以降のものも含めて、さまざまな時代の家が並んでいます。","塩硝づくりは «培養法» とよばれる方法で、床下の土を数年かけて発酵させました。五箇山の塩硝は品質がよかったといわれ、加賀藩の重要な財源・軍事資源でした。","世界遺産の構成資産は、岐阜県の白川郷荻町と、五箇山の相倉・菅沼の3集落です。白川郷とくらべると規模は小さいぶん、昔の山村の雰囲気がよく残っています。","五箇山は民謡 «こきりこ節» のふるさととしても知られます。竹の楽器 «こきりこ» や、ささらを鳴らして踊る素朴な歌で、日本最古の民謡の一つともいわれます。","五箇山和紙は今も作られています。加賀藩に納められた丈夫な和紙で、障子紙や文書に使われました。","集落の上の展望所からは、田んぼと合掌造りの屋根がつくる «日本の原風景» が見わたせます。冬のライトアップは幻想的で人気です。"],"look":["集落全体を見下ろす展望所","相倉民俗館・相倉伝統産業館","合掌造りの内部（屋根裏の骨組み）","田んぼと茅場","近くの菅沼集落と塩硝の館"],"q":["五箇山で加賀藩のために作られていた、鉄砲の火薬の原料は？","«塩硝»。家の床下の土を何年も発酵させて作りました。"],"koji":[],"myth":"«秘密を守るために五箇山が選ばれた» という見方は推測を含みます。こきりこ節の起源は諸説。","img":["五箇山","塩硝","菅沼集落"],"wp":"白川郷・五箇山の合掌造り集落","rel":{"ev":[],"grave":[]},"ph":[["c:e/e6/Ogi_Shirakawa-g%C5%8D%2C_Gifu%2C_Japan.jpg",3200,2133,"白川郷・五箇山の合掌造り集落"],["c:c/c8/Ogi_Shirakawa22s3s4110.jpg",4110,2740],["c:a/aa/Shirakawa_2024.jpg",3264,2448],["c:1/1b/Miboro_Dam.jpg",3072,2304],["c:3/33/Suganuma-Shigo-496.jpg",3008,2000],["c:9/99/Gokayama-Suganuma-503.jpg",3008,2000],["c:5/54/Shirakawago_Japanese_Old_Village_006.jpg",2816,2112],["c:7/73/Gassho-zukuri_farmhouse-03.jpg",2592,1944]]},{"id":"16_kome_uozu","n":"米騒動発祥の地（魚津・旧十二銀行米蔵）","yomi":"こめそうどうはっしょうのち","cat":"事件","rank":"S","y":1918,"era":["taisho"],"sh":"","ad":"魚津市本町（大町海岸付近）","st":"あいの風とやま鉄道の魚津駅から歩いて約15分","la":36.8215,"lo":137.404,"hook":"«米を運び出さんといて!» ――漁師町の女性たちの小さな行動が、全国の騒ぎになり、ついに内閣を倒した。","lead":"1918年の夏、魚津の浜で、漁師の家の女性たちが米の積み出しをやめてほしいとうったえました。米の値段が急に上がり、家族を食べさせることができなくなっていたのです。この動きは新聞で «越中の女一揆» と報じられて全国に広がり、«米騒動» となりました。浜辺には当時の米蔵が今も残ります。","story":["1918年（大正7年）、米の値段がみるみる上がっていきました。第一次世界大戦で景気がよくなり、町で米を食べる人が増えたこと。さらにシベリア出兵を見こした商人の買いしめ。漁師町の家では、1日の稼ぎで家族の米を買うことがむずかしくなっていました。","その年の7月、魚津の浜では、十二銀行の米蔵から北海道へ向かう船に米が積み出されようとしていました。«このうえ米がよそへ行ったら、うちの子は何を食べるの»――女性たちは浜に集まり、積み出しをやめてほしいとうったえたと伝わります。夫たちは北海道などへ出稼ぎの漁に出ていて、家を守っていたのは女性たちでした。","8月に入ると、同じ富山湾沿いの水橋や滑川などでも、女性たちが米屋や役場に押しかけ、米の安売りを求めました。新聞はこれを «越中女一揆» と大きく報じます。記事を読んだ全国の人びとが、«自分たちも声を上げよう» と立ち上がりました。","騒動は約50日のあいだに全国の多くの市町村に広がり、各地で米屋や商店が襲われるなど大混乱となりました。政府は軍隊まで出して鎮めようとします。9月、寺内正毅内閣は責任をとって総辞職し、かわって原敬が本格的な政党内閣をつくりました。","魚津の浜には、当時の «旧十二銀行米蔵» が残っています。レンガと土壁の素朴な倉庫です。騒動では、地元の人びとも暴動の側・襲われた側の両方の立場を経験しました。今この場所は、«食べることの大切さ» と «声をあげることの意味» を静かに伝えています。"],"tl":[["1914年","第一次世界大戦が始まり、やがて日本は好景気に"],["1918年7月","魚津の浜で女性たちが米の積み出し停止をうったえる"],["1918年8月初め","水橋・滑川などで女性たちの行動が広がり «越中女一揆» と報道"],["1918年8月","米騒動が全国に広がる"],["1918年9月","寺内正毅内閣が総辞職、原敬内閣が成立"]],"who":[["魚津の漁師町の女性たち","米の積み出しをやめるよう求めて浜に集まった"],["寺内正毅","当時の首相。米騒動の責任をとって辞職"],["原敬","米騒動後に首相となり、本格的な政党内閣をつくった"]],"deep":["米騒動の «発祥の地» は魚津・水橋・滑川など諸説あります。7月の魚津の行動を最初とする見方が知られていますが、富山湾沿いの各地で同じような動きがありました。","富山湾沿いの女性たちは、昔から米を船に運ぶ «仲仕» として働く人も多く、米の流れをよく知っていました。それが積み出しへの抗議につながったと考えられます。","新聞報道の力はとても大きく、«越中女一揆» の見出しが全国の人びとを動かしました。一方で、報道を規制しようとする政府と新聞の対立も起きています。","米騒動では、軍隊が出動し、各地で多くの人が検挙されました。騒動は «暴動» の面ももっていたことを忘れずに見ておく必要があります。","旧十二銀行米蔵は、十二銀行（のちの北陸銀行の前身の一つ）が使っていた米倉庫です。魚津市は2020年代にこの建物を保存・活用する取り組みを進めています。","米騒動をきっかけに、政府は外国米の輸入や米の値段の調整など、食べものの政策を見直していきました。"],"look":["旧十二銀行米蔵の外観","米蔵前の浜（大町海岸）と説明板","米騒動をしのぶ碑","魚津歴史民俗博物館"],"q":["1918年の米騒動のあと、首相になって本格的な政党内閣をつくった人は？","原敬。騒動の責任をとって寺内正毅内閣が総辞職しました。"],"koji":[],"myth":"発祥の地・始まった日付には諸説あります（魚津・水橋・滑川など）。米蔵の建築年は確かめていません。","img":["原敬","寺内正毅","十二銀行"],"wp":"米騒動","rel":{"ev":[],"grave":[]},"ph":[["c:b/bf/Takashi_Hara_formal.jpg",1024,1319,"原敬"],["c:7/71/Masatake_Terauchi_2.jpg",1024,1335,"寺内正毅"],["c:5/52/Uozu_montage_2019.png",1184,2061,"近く: 魚津市"],["c:e/ea/Uozu_CCIS_Building.jpg",2304,3456,"近く: 新川インフォメーションセンター"],["c:6/69/Dentetsu_uozu_station_001.jpeg",652,719,"近く: 電鉄魚津駅"],["c:3/3f/Uozu-police-station_2018.jpg",1024,768,"近く: 魚津警察署"],["c:b/b1/%E6%B2%B3%E5%86%85%E5%B1%8B_%E9%AD%9A%E6%B4%A5%E5%B8%82_%285323873892%29.jpg",1200,1600,"近く: 鮨蒲本舗河内屋"],["c:a/a3/Uozu-Jinja006.jpg",3296,2472,"近く: 魚津神社"]]},{"id":"16_itai","n":"イタイイタイ病資料館（神通川の公害）","yomi":"いたいいたいびょうしりょうかん","cat":"昭和","rank":"S","y":1968,"era":["taisho","showa"],"sh":"","ad":"富山市友杉","st":"富山駅から車で約20分（路線バスもある）","la":36.647,"lo":137.214,"hook":"«痛い、痛い»――その叫びが病名になった。日本で最初に «公害病» と認められた病気の歴史を、ここで学ぶ。","lead":"イタイイタイ病は、神通川の上流にあった鉱山から流れ出たカドミウムが原因で起きた病気です。川の水を使った田んぼの米などを通して体に入り、骨がもろくなって激しい痛みに苦しみました。1968年、国が日本で初めて «公害病» と認めました。資料館では、被害と、患者や地域の人たちの闘いを伝えています。","story":["神通川は、富山平野をうるおす大きな川です。その上流、岐阜県の神岡には、古くから亜鉛や鉛をほる鉱山がありました。鉱石を処理したあとの水や、たまった «かす» にはカドミウムという有害な金属がふくまれていて、それが川に流れこんでいったのです。","大正時代のころから、神通川の下流で、ひざや腰の痛みを訴える人が現れました。多くは子どもを産み育てた中年以降の女性たち。骨がもろくなって、せきをしただけで骨が折れることもあったといいます。«痛い、痛い» と苦しむ姿から、地元では «イタイイタイ病» とよばれるようになりました。","原因はなかなか分かりませんでした。«風土病ではないか»«栄養不足ではないか» といわれ、患者たちは偏見にも苦しみます。地元の開業医・萩野昇は、長年患者を診察し、研究者と協力して «鉱山から出たカドミウムが原因ではないか» という説を唱えました。けれどもその説は、はじめはなかなか受け入れられませんでした。","1968年、国はついにイタイイタイ病を «公害病» と認めます。同じ年、患者と遺族は鉱山を経営する会社を相手に裁判を起こしました。1972年、名古屋高裁金沢支部の判決で患者側が全面的に勝ち、会社は責任を認めます。翌日には、被害者団体と会社のあいだで、公害を防ぐための約束が結ばれました。","その後、汚れた田んぼの土を入れ替える «土壌復元» が長い年月をかけて行われ、発生源の対策も進められました。2012年に開館した資料館では、患者の証言映像や、裁判と地域の取り組みを伝えています。«同じことを二度と起こさないために»――それが、この資料館にこめられた願いです。"],"tl":[["大正時代","神通川流域で原因不明の痛みを訴える人が出始める"],["1955年","萩野昇医師らがこの病気を学会で報告"],["1968年3月","患者らが鉱山会社を相手に裁判を起こす"],["1968年5月","国がイタイイタイ病を日本初の公害病と認定"],["1971年","第一審で患者側が勝訴"],["1972年8月","控訴審で患者側が全面勝訴。公害防止の約束が結ばれる"],["2012年","汚染田の土壌復元事業が完了。資料館が開館"]],"who":[["萩野昇","地元の開業医。患者を診察し、原因究明に力をつくした"],["患者と家族","長く苦しみながら声をあげ、裁判で責任を明らかにした"],["被害者団体・弁護団","裁判と、発生源対策の監視を続けた"]],"deep":["イタイイタイ病は、水俣病・新潟水俣病・四日市ぜんそくと並ぶ «四大公害病» の一つ。国が公害病と認めたのは、この病気が最初でした。","カドミウムは腎臓をいため、それが骨をもろくする «骨軟化症» の症状につながると考えられています。とくに出産を重ねた女性に患者が多かったことも特徴です。","1972年の判決の翌日に結ばれた約束により、被害者団体は鉱山に立ち入って調査することが認められました。この «立入調査» は今も続けられており、全国でも例のない取り組みといわれます。","汚染された田んぼの土を入れ替える事業は、神通川流域の約860ヘクタールにおよび、長い年月をかけて行われました。","資料館は «富山県立イタイイタイ病資料館»。展示は無料で、語り部の映像や、当時の生活の様子を再現したコーナーもあります。","病名は地元の人びとの間で自然に生まれたといわれ、新聞記者が記事で使ったことで広まったと伝えられています。"],"look":["患者と家族の証言映像","萩野昇医師の診療の記録","裁判の経過と判決の展示","土壌復元のしくみの展示","神通川の流域模型"],"q":["イタイイタイ病の原因となった有害な金属は？","カドミウム。神通川上流の鉱山から流れ出ました。"],"koji":[],"myth":"病名の命名者・発生時期は諸説があります。土壌復元の面積は資料により細かい数字が異なります。","img":["神通川","神岡鉱山","萩野昇"],"wp":"イタイイタイ病","rel":{"ev":[],"grave":[]},"ph":[["c:9/9a/Cadmium_%2848_Cd%29.jpg",608,608,"イタイイタイ病"],["c:d/d3/Sphalerite_-_Creede%2C_Mineral_County%2C_Colorado%2C_USA.jpg",5000,6000],["j:8/89/%E3%82%A4%E3%82%BF%E3%82%A4%E3%82%A4%E3%82%BF%E3%82%A4%E7%97%85_%E9%B5%9C%E5%9D%82%E5%9C%B0%E5%8C%BA%E3%82%AB%E3%83%89%E3%83%9F%E3%82%A6%E3%83%A0%E6%B1%9A%E6%9F%93%E7%94%B0%E5%BE%A9%E5%85%83%E8%A8%98%E5%BF%B5%E7%A2%911.jpg",480,640],["c:d/da/Jinzu_River.jpg",4608,3456,"神通川"]]},{"id":"16_kurobe_dam","n":"黒部ダム（くろよん）","yomi":"くろべだむ","cat":"昭和","rank":"S","y":1963,"era":["showa"],"sh":"","ad":"中新川郡立山町芦峅寺","st":"立山黒部アルペンルート（長野県側の扇沢から関電トンネル電気バスで約16分、富山県側は立山駅から乗り継ぎ）","la":36.5665,"lo":137.662,"hook":"高さ186m、日本一のダム。工事で171人が命を落とした «世紀の難工事» は、映画にもなった。","lead":"黒部ダムは、北アルプスの奥深く、黒部川につくられたアーチ式のダムです。関西の電気不足を救うため、1956年から7年の歳月をかけて完成しました。高さは186mで日本一。工事では大町トンネルの «破砕帯» に苦しめられ、171人が亡くなりました。","story":["戦争が終わったあとの日本、とくに関西では電気がまったく足りませんでした。工場は止まり、家庭では停電がくりかえされます。«電気がなければ、日本の復興はない»――関西電力の社長・太田垣士郎は、黒部川の奥に巨大なダムと発電所をつくるという大きな決断をしました。","けれども、黒部の奥は «人を寄せつけない谷»。資材を運ぶ道すらありません。そこで長野県の大町側から山をくりぬく «大町トンネル» を掘り、トラックで資材を運ぶ計画が立てられました。ところが1957年、トンネルを掘り進めると、細かく砕けた岩と冷たい地下水が噴き出す «破砕帯» にぶつかってしまいます。","破砕帯は、わずか約80mを突破するのに7か月もかかりました。水を抜くための細いトンネルを何本も掘り、薬液で地盤を固め、少しずつ前へ進みます。«この先に光はあるのか»――暗闇の中で作業員たちはひたすら掘り続けました。ついに破砕帯を抜けたとき、現場は大きな歓声に包まれたといいます。","その後、コンクリートを打ちこむ工事が急ピッチで進み、1963年、黒部ダムは完成しました。工事全体で亡くなった人は171人。ダムのそばには殉職者の慰霊碑が建てられ、その名前が刻まれています。","この物語は、1968年に石原裕次郎・三船敏郎の主演で映画『黒部の太陽』となり、多くの人の心を打ちました（映画は事実をもとにした作品で、脚色も含まれます）。今では立山黒部アルペンルートの人気スポットとなり、夏から秋には «観光放水» の豪快な水しぶきを見ることができます。"],"tl":[["1956年","黒部川第四発電所（くろよん）の工事が始まる"],["1957年","大町トンネルで破砕帯にぶつかる"],["1957年12月","破砕帯を突破"],["1963年","黒部ダムが完成"],["1968年","映画『黒部の太陽』公開"],["1971年","立山黒部アルペンルートが全線開通"]],"who":[["太田垣士郎","関西電力社長。黒部ダム建設を決断した"],["工事にかかわった人びと","のべ約1000万人が働いたといわれ、171人が殉職した"],["石原裕次郎・三船敏郎","映画『黒部の太陽』で主演した俳優"]],"deep":["黒部ダムは «ドーム型アーチ式» のダムで、上から見るとダム本体が上流側へ弓なりにカーブしています。水の圧力を両岸の岩盤で受けとめるしくみです。","«くろよん» は «黒部川第四発電所» の略。発電所はダムから約10km下流の地下にあり、ダムの水をトンネルで送って発電しています。","工事の総費用は当時の金額で約513億円といわれ、関西電力の資本金の数倍にもなる、まさに社運をかけた事業でした。","大町トンネルは現在 «関電トンネル» として観光用の電気バスが走っています。車内から破砕帯の場所を示す青いライトの区間を見ることができます。","殉職者慰霊碑には171人の名前が刻まれています。ダム観光の際は、工事で命を落とした人びとへの思いもこめて立ち寄りたい場所です。","黒部川はもともと険しい峡谷で、ダム以前にも黒部川第三発電所の工事で «高熱隧道» とよばれる灼熱のトンネル工事があり、多くの犠牲者を出しました（吉村昭の小説『高熱隧道』の題材）。"],"look":["ダムの堤頂（上）から見る黒部湖と北アルプス","観光放水（6月下旬〜10月中旬ごろ）","殉職者慰霊碑","ダム展望台（220段の階段の上）","関電トンネルの破砕帯の表示"],"q":["黒部ダムの工事で、トンネルを掘る人たちを苦しめた、砕けた岩と地下水の多い場所を何という？","«破砕帯»。約80mを抜けるのに7か月かかりました。"],"koji":[],"myth":"映画『黒部の太陽』は事実をもとにした作品ですが脚色を含みます。働いた人数・費用は資料により数字が異なります。","img":["黒部川第四発電所","関電トンネル","黒部の太陽"],"wp":"黒部ダム","rel":{"ev":["kurobe"],"grave":[]},"ph":[["c:7/78/Kurobe_Dam_survey_2.jpg",2112,2816,"黒部ダム"],["c:d/dc/Kurobe_Dam_from_below.jpg",5472,3648],["c:5/54/Kurobe_Dam_Lake_Aerial_photograph.jpg",3398,5750],["c:8/83/KurobeDamView.JPG",4000,3000],["c:5/5b/KurobeDamObservatoryFromOtherside.JPG",4000,3000],["c:b/b3/KurobeDamObservatory.JPG",4000,3000],["c:6/63/KurobeDamFromObservatory.JPG",3000,4000],["c:c/c6/KurobeDamDownstream.JPG",4000,3000]]},{"id":"16_oyama_jinja","n":"雄山神社（立山信仰の総本社）","yomi":"おやまじんじゃ","cat":"寺社","rank":"S","y":701,"era":["asuka","heian","edo"],"sh":"国の重要文化財（前立社壇本殿）","ad":"中新川郡立山町芦峅寺・岩峅寺、立山雄山山頂","st":"富山地方鉄道立山線の岩峅寺駅（前立社壇）・千垣駅（中宮祈願殿）から歩いてそれぞれ約10〜20分。峰本社は室堂から徒歩登山","la":36.5838,"lo":137.3861,"hook":"標高3003mの山頂にまで本社がある神社。«立山には地獄と極楽がある» と信じた人びとの祈りが、1300年つづく。","lead":"雄山神社は、立山を神としてまつる神社です。立山の山頂（雄山）の «峰本社»、ふもとの芦峅寺の «中宮祈願殿»、岩峅寺の «前立社壇» の3つをあわせて一つの神社になっています。立山は、富士山・白山とならぶ «日本三霊山» の一つで、古くから信仰の山でした。","story":["伝説によると、立山を開いたのは、越中の国司の子 «佐伯有頼» という少年でした。701年、有頼は父の大切な白い鷹を追って山に入り、一頭の熊に出会います。矢を射ると熊は血を流して洞くつへ逃げこみました。追っていくと、そこには胸に矢の刺さった阿弥陀如来の姿が――。«熊は仏さまの化身だったのか!» 有頼は弓を捨てて出家し、立山を開いたと伝わります。","立山には、ぐつぐつと煮えたぎる湯がわく «地獄谷» があります。昔の人は、この荒々しい景色を «死んだ人が行く地獄» と考えました。一方で、山頂近くの美しい高原は «極楽浄土»。«立山に登れば、生きたまま地獄と極楽を見て、罪を清められる» と信じられるようになったのです。","江戸時代、立山のふもとの芦峅寺と岩峅寺には «宿坊» が並び、全国から登拝者がやってきました。宿坊の人たちは «立山曼荼羅» という大きな絵を持って全国をまわり、地獄と極楽のようすを絵解きして、立山参りをすすめました。絵を前に «ほら、ここが針の山、ここが血の池地獄»――人びとは息をのんで聞き入ったことでしょう。","けれども、立山は長いあいだ女性が登ることを許されない «女人禁制» の山でした。そこで芦峅寺では、女性の救いのための儀式 «布橋灌頂会» が行われました。女性たちは白い布を敷いた橋を目隠しをして渡り、あの世とこの世の境を越えて、極楽に生まれ変わることを願ったのです。","明治時代の «神仏分離» で、立山の寺と仏の信仰は大きく変わり、神社としての雄山神社がかたちづくられました。今も夏には多くの人が山頂の峰本社を目指します。ふもとの布橋灌頂会は1996年に復活し、立山信仰の世界を伝える «立山博物館» も芦峅寺にあります。"],"tl":[["701年","佐伯有頼が立山を開いたと伝わる"],["平安時代","立山の地獄が仏教の説話集に登場する"],["江戸時代","芦峅寺・岩峅寺の宿坊がさかえ、立山曼荼羅で全国に信仰が広まる"],["1868年以降","神仏分離により、神社としての雄山神社が整えられる"],["1907年","陸地測量部の一行が剱岳に登頂し、古い錫杖の頭などを発見"],["1996年","芦峅寺の布橋灌頂会が復活"]],"who":[["佐伯有頼","立山を開いたと伝わる少年（のちの慈興上人）"],["芦峅寺・岩峅寺の衆徒","宿坊を営み、立山曼荼羅で信仰を広めた"],["立山にまいった女性たち","女人禁制のため、布橋灌頂会で救いを願った"]],"deep":["平安時代の説話集『今昔物語集』には、«日本の人は罪をつくると立山の地獄に落ちる» といった話が収められていて、立山の地獄が当時から知られていたことがわかります。","岩峅寺の前立社壇の本殿は、国の重要文化財。室町時代の建物と考えられ、立山信仰の古い姿を伝えます。","«立山曼荼羅» は現在50点ほど確認されているといわれ、地獄・極楽・開山伝説・登山のようすが一枚にえがかれています。立山博物館で本物を見ることができます。","1907年、陸地測量部の柴崎芳太郎らが «未踏峰» と思われていた剱岳に登ると、山頂で平安時代ごろのものとみられる錫杖の頭と鉄剣が見つかりました。はるか昔に修行者が登っていた証拠です（のちに小説・映画『劔岳 点の記』の題材に）。","«布橋灌頂会» は江戸時代に盛んに行われましたが、明治の神仏分離で途絶えました。現在の儀式は資料をもとに復活させたものです。","峰本社のある雄山は標高3003m。立山連峰の «立山» は一つの山の名前ではなく、雄山・大汝山・富士ノ折立などをまとめたよび名です。"],"look":["岩峅寺の前立社壇（重要文化財の本殿）","芦峅寺の中宮祈願殿と杉並木","布橋と閻魔堂","富山県［立山博物館］の立山曼荼羅","夏山シーズンの雄山山頂・峰本社"],"q":["昔の人が «地獄» と考えた、立山の煮えたぎる湯がわく場所は？","«地獄谷»。いまも火山ガスが出ているため、立ち入りが制限されることがあります。"],"koji":[],"myth":"佐伯有頼の開山と701年という年は伝承です。前立社壇本殿の年代・剱岳の錫杖の年代には諸説あります。","img":["立山","立山曼荼羅","布橋灌頂会"],"wp":"雄山神社","rel":{"ev":[],"grave":[]},"ph":[["c:f/f0/20_Tateyama_from_Mikurigaike_1998-7-17.jpg",1280,854,"雄山神社"],["c:8/85/Oyama-jinja_Mine-honsha%2C_old_honden_in_Hotel_Tateyama.jpg",6010,3990],["c:5/5f/Tateyama_Oomiya.JPG",2352,1568],["c:c/cb/Station_of_triangulation%2CTateyama.JPG",2352,1568],["c:d/de/Precincts_of_Chuuguu-kiganden.JPG",2352,1568],["c:c/c6/Mine-honsha_inside_Office.JPG",2352,1568],["c:8/8d/Mine-honsha_Shaden.JPG",2352,1568],["c:0/05/Mine-honsha_Office.JPG",2352,1568]]},{"id":"16_uozu_jo","n":"魚津城（本能寺の変の日に落ちた上杉の城）","yomi":"うおづじょう","cat":"城","rank":"S","y":1582,"era":["muromachi","azuchi"],"sh":"","ad":"魚津市本町（大町小学校付近）","st":"あいの風とやま鉄道の魚津駅から歩いて約15分","la":36.8193,"lo":137.4064,"hook":"1582年6月3日、上杉の城兵が全員で自害した。その前日、京都では信長が本能寺で倒れていた――知らせは間に合わなかった。","lead":"魚津城は、越中東部の海に近い平城です。戦国時代の終わり、上杉方の城として織田軍の大軍に囲まれ、約80日の籠城のすえ1582年6月3日に落城しました。本能寺の変のわずか翌日のことでした。いまは城の建物は残らず、小学校のそばに石碑が立つだけの «城跡» です。","story":["魚津城は、はじめ越中東部の豪族・椎名氏の城だったといわれます。やがて越後の上杉謙信が越中に勢力をのばすと、魚津城は上杉方の大切な拠点となりました。1578年に謙信が亡くなると、跡を継いだ上杉景勝に対して、西から織田信長の軍が迫ってきます。","1582年3月ごろ、柴田勝家を総大将に、佐々成政・前田利家らの織田軍が魚津城を包囲しました。城を守るのは中条景泰ら上杉の武将たちと、わずかな兵。対する織田軍は数万ともいわれます。«援軍が来るまで、なんとしても持ちこたえよ»――城兵たちは必死に守りました。","景勝も魚津城を救うため、近くの天神山城まで兵を進めました。しかし越後の本国にも、信濃から織田軍が攻めこむ動きがあり、景勝はやむなく兵を引き返します。«景勝さまは来られぬ» と知った城兵たちの心中は、どれほどだったでしょう。","6月3日、ついに城は落ちました。守将たちは自害し、その数は «十三将» とよばれます。彼らは自分の名前を書いた札を耳に穴をあけて結びつけ、死後にだれかわかるようにしたと伝わります。そして前の日、6月2日には京都で本能寺の変が起き、信長が亡くなっていたのです。","信長の死を知った織田軍は、魚津城を捨てて引きあげていきました。あと数日持ちこたえていれば――。«歴史のもしも» を感じさせる場所として、魚津城の話は今も語られています。城跡には石碑が立ち、上杉の将たちをしのぶ場所になっています。"],"tl":[["16世紀中ごろ","椎名氏の城とされる（築城年は不明）"],["1570年代","上杉謙信の越中支配の拠点となる"],["1578年","上杉謙信が亡くなる"],["1582年3月ごろ","柴田勝家らの織田軍が魚津城を包囲"],["1582年6月2日","京都で本能寺の変"],["1582年6月3日","魚津城が落城。守将たちが自害"]],"who":[["中条景泰","上杉家の武将。魚津城の守将の一人"],["上杉景勝","謙信の跡を継いだ上杉家当主。救援に来たが退いた"],["柴田勝家","織田軍の総大将として魚津城を攻めた"],["佐々成政","織田方として魚津城攻めに加わった"],["前田利家","織田方として魚津城攻めに加わった"]],"deep":["城は松倉城（山城）の «支城» で、海に近い魚津城と山の松倉城がセットで越中東部を守っていたと考えられています。","上杉景勝がこのころ書いた手紙には、越後一国で天下の大軍を相手にする覚悟を語った一文があり、上杉家の追いつめられた状況がうかがえます。","«十三将» の名前には、中条景泰・竹俣慶綱・吉江宗信らが挙げられます。ただし何人が自害したかや名前の一部には、史料によって違いがあります。","«耳に札をつけた» という話は、上杉側の記録に見える話として伝わりますが、細部には後世の脚色が入っている可能性もあります。","城跡は市街地の中にあり、はっきりした遺構はほとんど残っていません。発掘調査では堀の跡などが確認されています。","織田軍の包囲は約80日といわれます。本能寺の変の知らせが北陸の織田軍に届いたのは6月5日ごろ以降とされ、情報の伝わる速さが歴史を分けた例としてもよく語られます。"],"look":["魚津城跡の石碑（大町小学校そば）","城跡の説明板","近くの旧十二銀行米蔵・魚津歴史民俗博物館","天神山城（上杉景勝が陣をしいた山）"],"q":["魚津城が落ちた前の日、京都で起きた大事件は？","本能寺の変（1582年6月2日）。織田信長が亡くなりました。"],"koji":[],"myth":"築城者・築城年、十三将の顔ぶれ、«耳に札» の話には諸説・伝承を含みます。","img":["上杉景勝","柴田勝家","本能寺の変"],"wp":"魚津城","rel":{"ev":[],"grave":[]},"ph":[["c:e/ed/Uozu_Castle_Site.jpg",1280,960,"魚津城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:6/61/Uesugi_Kagekatsu_Portrait_Yonezawa_City_Uesugi_Museum.png",705,1708,"上杉景勝"],["c:0/0c/Shibata_Katsuie_large.jpg",1386,2965,"柴田勝家"],["c:e/e3/Honnoj.jpg",3200,1565,"本能寺の変"]]},{"id":"16_baiyaku","n":"富山の売薬（反魂丹と池田屋安兵衛商店）","yomi":"とやまのばいやく","cat":"産業","rank":"S","y":1690,"era":["edo","meiji"],"sh":"","ad":"富山市堤町通り（池田屋安兵衛商店）","st":"富山駅から市内電車で «西町» 下車、歩いて約3分","la":36.6886,"lo":137.2146,"hook":"«先に使ってもらって、代金はあとで»――300年前に生まれた «置き薬» のしくみは、いまのサブスクの大先輩!?","lead":"富山の売薬は、江戸時代に始まった薬の «置き薬» 商売です。売薬さんが全国の家々をまわって薬箱を預け、次に来たときに使った分だけ代金をもらう «先用後利» というしくみでした。池田屋安兵衛商店では、昔ながらの «越中反魂丹» を作り、丸薬づくりの体験もできます。","story":["富山の売薬のはじまりには、有名な言い伝えがあります。1690年、江戸城で、ある大名が急に腹痛で苦しみだしました。そのとき富山藩2代藩主・前田正甫が持っていた薬 «反魂丹» を飲ませると、たちまち痛みがおさまった――。«これはすごい薬だ!» と、居合わせた大名たちが自分の国でも売ってほしいと頼んだ、というのです。","この話は後の時代に語られた伝承で、どこまで本当かはわかりません。ただ、前田正甫が薬の研究に熱心で、富山の売薬を育てたことは確かだといわれます。«反魂丹» の作り方は、岡山の医者から伝えられたとされています。財政の苦しい富山藩にとって、薬はお金をかせぐ大事な産業になっていきました。","売薬さんは «懸場帳（かけばちょう）» という帳面を持っていました。どの家にどの薬を置いたか、どれだけ使ったか、家族のようすまでが細かく書かれています。«この家は子どもが生まれたから、子ども用の薬を多めに»――そんな気くばりが信用を生みました。懸場帳は財産として売り買いされるほど大切なものでした。","売薬さんは、子どもへのおまけに «紙風船» や、役者絵などの «売薬版画» を配りました。遠い富山から来る売薬さんは、各地のうわさ話や新しい知識も運んできます。全国を歩いた売薬さんは、情報の運び手でもあったのです。薩摩（鹿児島）へ行く «薩摩組» は、北海道の昆布を運び、薩摩藩とのつながりを深めたともいわれます。","明治になると、売薬の会社がつくられ、薬の製造は近代化していきました。今も富山は «くすりの富山» として、多くの製薬会社や工場が集まる県です。池田屋安兵衛商店では、昔の道具を使った丸薬づくりを体験でき、300年の歴史を肌で感じることができます。"],"tl":[["1690年","江戸城で前田正甫が反魂丹を大名に与えたと伝わる（江戸城腹痛事件）"],["江戸時代中期","富山藩が «反魂丹役所» を置き、売薬を保護・管理"],["江戸時代後期","売薬さんが全国に «組» をつくって行商"],["明治時代","売薬の会社が設立され、製造が近代化"],["現代","富山は医薬品の一大生産地に"]],"who":[["前田正甫","富山藩2代藩主。売薬を奨励したと伝わる"],["万代常閑","岡山の医者。反魂丹を伝えたとされる人物"],["売薬さん","全国を歩き、懸場帳で家々の薬を管理した行商人"],["池田屋安兵衛","堤町通りで越中反魂丹を今も作り続ける老舗"]],"deep":["«先用後利» は «用を先に、利を後に» という考え方。薬を先に預け、使った分だけ後で代金をもらうしくみで、信用がなければ成り立ちません。","江戸城での «腹痛事件» の大名は、陸奥国三春藩主とする話が広く知られていますが、同時代の確かな記録は見つかっていないといわれます。","富山藩は «反魂丹役所» を置き、売薬の品質や行商人を管理しました。藩が産業を育て、税をとるしくみだったのです。","売薬さんは行く先の地域ごとに «組» をつくり、仲間どうしのルールで商売の秩序を守りました。関東組・薩摩組など多くの組がありました。","«薩摩組» は、北海道の昆布を薩摩に運び、それが琉球を通じて中国へわたったという «昆布ロード» の話にもかかわっていると語られます。","売薬版画や紙風船は、今では民俗資料として大切にされています。富山市の «富山市売薬資料館» で行商の道具や懸場帳を見ることができます。"],"look":["池田屋安兵衛商店の店がまえと薬の道具","丸薬づくり体験","堤町通りの古い町並み","富山市売薬資料館（民俗民芸村）の懸場帳と柳行李"],"q":["売薬さんが持っていた、どの家にどの薬を置いたかを書いた帳面を何という？","«懸場帳»。財産として売り買いされるほど大切にされました。"],"koji":[{"w":"先用後利","m":"先に使ってもらい、代金は後でもらう。富山の売薬の商売の基本となった考え方"}],"myth":"江戸城腹痛事件（1690年）は伝承で、確かな同時代史料はないとされます。反魂丹の伝来経路・昆布ロードとのかかわりにも諸説あります。","img":["反魂丹","前田正甫","置き薬"],"wp":"富山の売薬","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c0/Kokandou1.JPG",2048,1536],["c:0/00/FlattenedRoundPills.jpg",2048,1536]]},{"id":"16_zuisenji","n":"井波別院瑞泉寺（越中一向一揆の拠点）","yomi":"いなみべついんずいせんじ","cat":"寺社","rank":"S","y":1390,"era":["muromachi","edo"],"sh":"県指定文化財（本堂・山門・太子堂など）","ad":"南砺市井波","st":"あいの風とやま鉄道の高岡駅またはJR砺波駅からバスで «井波» 方面へ、そこから歩いて約10分","la":36.5553,"lo":136.9667,"hook":"武士を追い出した «一揆の寺»。そして江戸時代、この寺の再建から «日本一の木彫りの町» が生まれた。","lead":"井波別院瑞泉寺は、1390年に本願寺5代目の綽如が開いた浄土真宗のお寺です。戦国時代には越中一向一揆の中心となり、武士とも戦いました。江戸時代の本堂再建のとき、京都から来た彫刻師の技を地元の大工が学んだことが、«井波彫刻» の始まりといわれます。","story":["南北朝の争いが終わりに近づいた1390年、本願寺の綽如は、越中の井波の地に寺を開きました。«北陸に教えを広めよう»――瑞泉寺は北陸の浄土真宗の大切な拠点となり、のちに本願寺8代目の蓮如の時代には、その力はいっそう大きくなりました。","1481年、瑞泉寺の門徒たちは、砺波地方の武士・石黒氏と戦い、これを破ったと伝わります（«田屋川原の戦い»）。«百姓の持ちたる国» とよばれた加賀ほどではないにしても、越中でも門徒の力が武士をしのぐようになったのです。瑞泉寺は、伏木の勝興寺と並んで越中一向一揆の中心になりました。","しかし戦国の終わり、織田信長の勢力が越中に及ぶと、瑞泉寺は攻められ、焼かれてしまいます。一向一揆の時代は終わりを告げました。やがて寺は再建され、江戸時代には加賀藩の保護のもとで東本願寺（真宗大谷派）の «別院» として栄えました。","江戸時代の中ごろ、瑞泉寺は大火で焼けてしまいました。本堂を建て直すとき、京都の本願寺から御用彫刻師の前川三四郎が派遣されてきます。井波の大工たちはその技を必死に学びました。«見て、盗め»――この技が代々受け継がれ、欄間や獅子頭などを彫る «井波彫刻» が生まれたといわれます。","今の本堂は明治時代に再建されたもので、北陸でも最大級の木造の寺院建築です。山門や太子堂には、井波の職人たちによるみごとな彫刻がほどこされています。門前の «八日町通り» には彫刻の工房が並び、ノミの音が今も町に響いています。"],"tl":[["1390年","綽如が井波に瑞泉寺を開く"],["1481年","田屋川原の戦い。門徒が石黒氏を破ったと伝わる"],["1581年ごろ","織田方の攻撃で焼かれる"],["江戸時代","東本願寺の別院として再興"],["1762年","大火で焼失。再建に前川三四郎が加わり、井波彫刻が始まる"],["1885年","現在の本堂が再建される"]],"who":[["綽如","本願寺5代目。瑞泉寺を開いた"],["蓮如","本願寺8代目。北陸に教えを広めた"],["石黒光義","砺波地方の武士。門徒に敗れたと伝わる"],["前川三四郎","京都の本願寺の御用彫刻師。井波に彫刻の技を伝えた"]],"deep":["瑞泉寺の山門は江戸時代後期の建物で、正面の «雲水一匹竜» など、井波彫刻の見事な作品が彫られています。","本堂は明治時代の再建。間口・奥行きともに大きく、北陸地方の真宗寺院らしい大屋根が特徴です。","太子堂には聖徳太子の像がまつられ、夏の «太子伝会» では太子の生涯をえがいた絵を使った絵解きが行われます。","«田屋川原の戦い» の年や経過は、寺や地元の伝承によるところが大きく、細部には諸説があります。","井波彫刻は «日本遺産» にも認定されています。欄間・獅子頭・天神像など、祝いごとの品として全国に送られてきました。","寺を開いた綽如は、南朝と北朝の争いの時代に、中国（明）の国書を読み解いた学識の高い僧だったとも伝えられます。"],"look":["山門の井波彫刻","明治に再建された大きな本堂","太子堂","門前・八日町通りの彫刻工房","井波彫刻総合会館"],"q":["瑞泉寺の再建がきっかけで生まれたといわれる、井波の伝統工芸は？","«井波彫刻»。京都から来た彫刻師の技を地元の大工が学んだのが始まりといわれます。"],"koji":[],"myth":"田屋川原の戦いの詳細、焼き討ちの年、綽如の国書の話には諸説・伝承を含みます。","img":["綽如","井波彫刻","越中一向一揆"],"wp":"瑞泉寺 (南砺市)","rel":{"ev":[],"grave":[]},"ph":[["c:3/30/InamibetsuinZuisenji.JPG",3865,2572,"瑞泉寺 (南砺市)"],["c:5/57/Inami_Shotoku_Kindergarten_20140818.JPG",4288,3216],["c:a/ac/ZuisenjiTaishido.JPG",3300,2201],["c:6/67/INAMI_TOWN_OLD_STREET.JPG",2240,1680]]},{"id":"16_shiraiwa","n":"白岩堰堤（立山砂防の要）","yomi":"しらいわえんてい","cat":"近代","rank":"S","y":1939,"era":["edo","showa"],"sh":"国の重要文化財","ad":"中新川郡立山町芦峅寺（立山カルデラ内）","st":"一般の人は自由に立ち入れない。富山地方鉄道の立山駅前「立山カルデラ砂防博物館」の見学会（抽選・季節限定）で見られる","la":36.578,"lo":137.521,"hook":"1858年の大地震で山が崩れ、土砂が富山平野をおそった。その土砂を今もせき止め続ける «巨大な階段»。","lead":"白岩堰堤は、立山カルデラの出口に、常願寺川の土砂をせき止めるためにつくられた砂防ダムです。1939年に完成し、本堤と下流の副堤をあわせた落差は100mをこえます。砂防施設としては全国で初めて国の重要文化財に指定されました。ふだんは入れない場所で、見学会で見ることができます。","story":["1858年（安政5年）、飛騨と越中の境で大地震が起きました（«飛越地震»）。立山カルデラでは «大鳶山» と «小鳶山» が大きく崩れ、大量の土砂が谷をせき止めて、巨大な «せき止め湖» ができました。これを «鳶崩れ» とよびます。","そして数週間後、せき止めていた土砂が崩れ、泥と岩の洪水 «土石流» が常願寺川を一気に流れ下りました。富山平野の村々は押し流され、多くの人が亡くなりました。«山が海までやってきた»――そう感じるほどの大災害だったといいます。平野には、今も当時流されてきた巨大な石が残っています。","それからも、立山カルデラにたまった大量の土砂は、大雨のたびに流れ出して村をおそいました。常願寺川は «暴れ川»。«これを止めなければ、富山平野に安心して住めない»――富山県は砂防工事に取り組み、1926年からは国が直接工事を行うことになりました。","その中心となったのが、カルデラの出口に築かれた白岩堰堤です。けわしい谷の奥に資材を運ぶため、工事用のトロッコ軌道も整えられました。1939年、高さ63mの本堤と7基の副堤が完成します。まるで巨大な階段のような姿で、水の勢いを弱めながら土砂を止めるしくみです。","白岩堰堤は、完成から80年以上たった今も現役で働き続けています。2009年には、砂防施設として全国で初めて国の重要文化財に指定されました。«見えないところで、今も富山を守っている»――見学会で実物を見上げると、その大きさと、工事に取り組んだ人びとの努力に圧倒されます。"],"tl":[["1858年","飛越地震で鳶山が崩れる（鳶崩れ）。続く土石流で富山平野に大きな被害"],["1906年","富山県が立山カルデラで砂防工事を始める"],["1926年","国が直接工事を行う直轄事業になる"],["1939年","白岩堰堤が完成"],["2009年","砂防施設として全国で初めて国の重要文化財に指定"]],"who":[["赤木正雄","内務省の技術者。«砂防の父» とよばれ、立山砂防の計画にかかわった"],["ヨハネス・デ・レーケ","明治時代に来日したオランダ人技師。常願寺川の治水を指導した"],["工事にかかわった人びと","けわしい山奥で長い年月をかけて工事を行った"]],"deep":["白岩堰堤は本堤の高さ63m、副堤を含めた落差は108mといわれ、日本有数の規模の砂防堰堤です。","立山カルデラには、鳶崩れなどでたまった土砂が今も約2億立方メートル残っているといわれます。もし一度に流れ出せば、富山平野を大きくおおってしまうほどの量です。","オランダ人技師デ・レーケが常願寺川を見て «これは川ではない、滝だ» と言ったという話は有名ですが、実際にはだれの発言か確かではないとされます。","工事の資材を運ぶためのトロッコ軌道（立山砂防軌道）は、18段連続のスイッチバックがあることで知られ、今も砂防工事に使われています。","白岩堰堤とともに、本宮堰堤・泥谷堰堤群も国の重要文化財に指定されています。立山の砂防施設はまとまった «近代化遺産» です。","«立山カルデラ» は火山活動と浸食でできた大きなくぼ地で、東西約6.5km・南北約4.5kmの広さがあります。"],"look":["立山カルデラ砂防博物館（立山駅前）の展示と見学会","見学会で見上げる白岩堰堤の本堤と副堤","立山砂防軌道（トロッコ）","常願寺川沿いに残る «大転石»"],"q":["1858年の飛越地震で、立山カルデラの鳶山が崩れたことを何という？","«鳶崩れ»。続く土石流で富山平野に大きな被害が出ました。"],"koji":[],"myth":"«これは川ではない、滝だ» の発言者はデ・レーケとされることが多いですが、確かではありません。","img":["立山カルデラ","飛越地震","常願寺川"],"wp":"白岩堰堤","rel":{"ev":[],"grave":[]},"ph":[["c:8/85/Siraiwadam.jpg",800,530,"白岩堰堤"],["c:1/14/Shiraiwa_Sabo_Dam_%E7%99%BD%E5%B2%A9%E5%A0%B0%E5%A0%A4_Oct_15%2C_2015_%283%29.jpg",4373,6546],["c:d/d1/Shiraiwa_Sabo_Dam_%E7%99%BD%E5%B2%A9%E5%A0%B0%E5%A0%A4_Oct_15%2C_2015_%282%29.jpg",8568,6426],["c:7/7b/Shiraiwa_Sabo_Dam_%E7%99%BD%E5%B2%A9%E5%A0%B0%E5%A0%A4_Oct_15%2C_2015_%281%29.jpg",6175,6356],["c:c/c7/Shiraiwa_Check_Dam_Facility_Aerial_photograph.1977.jpg",2380,1720],["c:c/c3/Jyouganji_river.jpg",1644,2192,"常願寺川"]]},{"id":"16_sakuramachi","n":"桜町遺跡（縄文の高床建物）","yomi":"さくらまちいせき","cat":"遺跡","rank":"S","y":-2000,"era":["jomon"],"sh":"","ad":"小矢部市桜町","st":"あいの風とやま鉄道の石動駅から車で約10分（桜町JOMONパーク）","la":36.67,"lo":136.883,"hook":"«縄文人は高床の建物なんて建てられなかった»――その常識を、泥の中から出てきた一本の柱がくつがえした。","lead":"桜町遺跡は、今から約4000年前ごろを中心とする縄文時代の遺跡です。水のしみこんだ低い土地だったため、ふつうは腐ってしまう木材がたくさん残っていました。1997年、ここで高床の建物に使われたとみられる柱が見つかり、«縄文時代にも高床建物があった» ことが注目されました。","story":["小矢部市の山ぎわ、小さな川のそばに桜町遺跡はあります。ここは地下水がたまりやすい湿った土地。«木は土に埋まるとすぐに腐る» のがふつうですが、空気にふれない泥の中では、何千年も形を残すことがあります。桜町遺跡は、そんな «木の宝箱» のような場所でした。","1997年の発掘で、調査員たちは泥の中から、四角い穴があけられた木の柱を見つけました。穴は «貫（ぬき）» という横木を通すためのもの。さらに、木と木をがっちり組み合わせる «渡腮（わたりあご）» という技法の跡がある木材も見つかりました。«これは縄文人がつくった高床建物の部材ではないか!» 考古学者たちは驚きました。","それまで、高床の建物は稲作とともに弥生時代に広まったものと考えられていました。ところが桜町遺跡の木材は、それより1000年以上も古い縄文時代のもの。縄文人は石の斧で木を切り、こうした複雑な加工をしていたのです。«縄文人の建築技術は、思っていたよりずっと高かった» と、教科書の見方が変わるきっかけの一つになりました。","桜町遺跡からは、ほかにも編みかごや漆をぬった道具、木の実のあく抜きに使ったとみられる «水さらし場» の跡なども見つかっています。縄文人は、トチの実やクリなどの木の実をたくわえ、川の水を上手に使って暮らしていたようです。","出土した木材の研究をもとに、遺跡の近くの «桜町JOMONパーク» には高床建物などが復元されています。市内の展示施設などでは実物の出土品が紹介され、4000年前の職人の «手の跡» にふれることができます。"],"tl":[["約5000〜3500年前","縄文時代中期〜後期に人びとが暮らす"],["1980年代後半","道路工事にともなう発掘調査が始まる"],["1997年","貫穴や渡腮仕口のある高床建物の部材が見つかる"],["2000年代","出土品の保存・研究が進む"],["現代","桜町JOMONパークで高床建物などを復元公開"]],"who":[["桜町に暮らした縄文人","石の道具で木を加工し、高床建物や水さらし場をつくった"],["発掘調査にあたった人びと","泥の中の木材を掘り出し、保存処理と研究を続けた"]],"deep":["«渡腮仕口（わたりあごしくち）» は、2本の木を十字に組むとき、互いに切り欠いてがっちりかみ合わせる技法です。のちの時代の建築にも使われる高度な技術です。","見つかった柱の «貫穴» は、柱と柱を横木でつなぎ、建物をゆがみにくくするためのもの。縄文時代の建物の構造を知る貴重な手がかりです。","湿った土地の木材は、掘り出すと乾いてひび割れてしまいます。そのため、薬品をしみこませる «保存処理» に長い時間がかかりました。","遺跡では、クリの木を使った «環状木柱列»（柱が円形に並ぶ遺構）も見つかっています。何のための施設だったかは、祭りの場とする説など諸説あります。","«トチの実のあく抜き» は、苦いトチの実を食べられるようにするための作業で、縄文人の食の知恵を示しています。","縄文時代の高床建物の証拠としては、ほかの遺跡の柱穴の配置からの推定もありましたが、実際の建築部材が見つかったことで、具体的な構造まで議論できるようになりました。"],"look":["桜町JOMONパークの復元高床建物","出土した木材（貫穴・渡腮の加工跡）","水さらし場の復元","市内の展示施設で見られる出土品"],"q":["桜町遺跡で見つかった、木と木をがっちり組み合わせる技法の名前は？","«渡腮（わたりあご）»。縄文時代にすでに使われていたことがわかりました。"],"koji":[],"myth":"高床建物の復元形は推定を含みます。環状木柱列の用途は諸説。発掘開始年は資料により異なる可能性があります。","img":["縄文時代","高床式","小矢部市"],"wp":"桜町遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:4/41/Yoshinogari-iseki_takayukashiki-souko.JPG",5619,3720,"高床式"],["c:5/56/%E6%BA%90%E5%B9%B3%E5%80%B6%E5%88%A9%E4%BC%BD%E7%BE%85%E5%90%88%E6%88%A6%E3%81%AE%E5%9C%B0_-_panoramio.jpg",1600,900,"小矢部市"]]},{"id":"16_masuyama_jo","n":"増山城（越中三大山城・神保氏）","yomi":"ますやまじょう","cat":"城","rank":"A","y":1560,"era":["muromachi","azuchi"],"sh":"国指定史跡","ad":"砺波市増山","st":"JR城端線の砺波駅から車で約20分（増山城跡の駐車場から歩いて登る）","la":36.61,"lo":137.035,"hook":"上杉謙信も手こずったといわれる «越中三大山城» のひとつ。尾根に刻まれた堀切と曲輪が、戦国の緊張をいまに伝える。","lead":"増山城は、砺波平野の東の丘陵に築かれた山城です。戦国時代には越中西部の有力者・神保氏の大切な拠点となり、上杉謙信や佐々成政らがこの城をめぐって争いました。建物は残っていませんが、曲輪や堀切などの地形がよく残り、2009年に国の史跡になりました。","story":["増山城は、和田川が流れる深い谷と丘陵を利用して築かれた山城です。南北朝時代の記録に見える «和田城» がこの城のことではないか、ともいわれ、古くから城がおかれていた可能性があります。その後、戦国時代になると、越中西部を治めた神保氏の «詰めの城»（いざというときにこもる城）として重要になりました。","16世紀の中ごろ、神保長職は勢力を広げ、越中東部の椎名氏と争いました。椎名氏が越後の上杉謙信に助けを求めると、1560年、謙信は越中に攻めこみます。富山城を追われた長職は、この増山城に逃げこんだと伝わります。«ここなら謙信も簡単には攻められまい»――険しい地形が長職の最後の頼りでした。","謙信はその後も何度も越中に出陣しました。増山城もたびたび攻められ、やがて上杉方の城となります。謙信の死後は織田方の佐々成政が越中を支配し、増山城も成政方の城となりました。1585年、秀吉が越中に攻めこむと、成政は降伏し、城は前田家のものになります。","江戸時代のはじめ、一国一城の考えが広まるなかで増山城は役目を終え、廃城となりました。けれども山の中だったため、曲輪や堀切、土塁などの «土の城» の形はそのまま残りました。«石垣も天守もないのに、なぜここが名城なの?»――それは、自然の地形をたくみに組み合わせた守りのくふうが、今もはっきりと見られるからです。","城跡は遊歩道が整えられ、«一の丸»«二の丸» などの曲輪をめぐることができます。毎年秋には «増山城戦国祭り» が開かれ、地域の人びとが城を守り伝えています。和田川ダムの湖を見下ろす景色も見どころです。"],"tl":[["南北朝時代","記録に見える «和田城» を増山城とする説がある"],["16世紀中ごろ","神保氏の重要な拠点となる"],["1560年","上杉謙信が越中に出陣。神保長職が増山城にのがれたと伝わる"],["1570年代","上杉方の城となる"],["1580年代前半","佐々成政の支配下に入る"],["1585年","富山の役のあと前田家の城に"],["江戸時代初め","廃城"],["2009年","国の史跡に指定"]],"who":[["神保長職","越中西部の有力者。増山城を拠点とした"],["上杉謙信","越後の大名。何度も越中に攻めこんだ"],["佐々成政","織田方の武将。越中を支配した"],["前田利長","富山の役のあと越中西部を与えられた"]],"deep":["増山城・松倉城・守山城は «越中三大山城» とよばれます。いずれも自然の地形を生かし、石垣よりも土を掘って積んだ «土の城» です。","城の中心部は «一の丸»«二の丸» などに分かれ、尾根を断ち切る深い «堀切» が何本も掘られています。敵が尾根づたいに攻めてくるのを防ぐしくみです。","城内には «無常» とよばれる曲輪があり、墓所や寺があったとも推測されていますが、はっきりしたことはわかっていません。","発掘調査では、戦国時代の陶磁器などが見つかっています。城がどの時期にどう使われていたかを知る手がかりとして研究が続いています。","«和田城» と増山城が同じ城かどうかは、史料が少ないため諸説あります。","城のふもとには城下の集落があったと考えられ、城とあわせて «城下町» の跡を探す調査も行われています。"],"look":["一の丸・二の丸の広い曲輪","尾根を断ち切る堀切","和田川ダム湖を見下ろす眺め","増山城跡の案内板・模型"],"q":["増山城・松倉城と並んで «越中三大山城» とよばれる城は？","守山城。高岡市の二上山にある山城です。"],"koji":[],"myth":"«和田城» との同一説、神保長職が逃げこんだ経緯、«無常» の由来は諸説です。","img":["神保長職","上杉謙信","越中三大山城"],"wp":"増山城","rel":{"ev":[],"grave":[]},"ph":[["c:a/a8/Masuyama_near_view.jpg",1024,768,"増山城"],["c:5/58/Masuyama-jokamati-sitamati.jpg",2592,1944],["c:2/22/Masuyama-jokamati-daimoti.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:a/a0/Masuyama-uranagikuti.JPG",1024,768],["c:b/b4/Masuyama-syorodo.JPG",1024,768],["c:1/1a/Masuyama-sangunsakai.JPG",1024,768],["c:a/aa/Masuyama-ninomaru.JPG",1024,768]]},{"id":"16_matsukura_jo","n":"松倉城（椎名氏の山城と松倉金山）","yomi":"まつくらじょう","cat":"城","rank":"A","y":1570,"era":["muromachi","azuchi"],"sh":"県指定史跡","ad":"魚津市鹿熊","st":"あいの風とやま鉄道の魚津駅から車で約20分（山頂近くまで車道あり）","la":36.7853,"lo":137.4437,"hook":"山の城のふもとには «金山» があった。越中東部を治めた椎名氏の富の源と、上杉・織田の攻防の舞台。","lead":"松倉城は、魚津市の東の山の上、標高約430mに築かれた山城です。戦国時代、越中東部の豪族・椎名氏の本拠地で、のちに上杉氏の越中支配の中心となりました。近くには «松倉金山» があり、城の繁栄をささえたといわれます。«越中三大山城» の一つです。","story":["松倉城は、魚津の町と富山湾を見下ろす山の上にあります。晴れた日には能登半島まで見わたせるこの場所は、越中東部を治めるのにぴったりでした。戦国時代、この城を本拠としたのが椎名氏です。椎名氏は、越中西部の神保氏とたびたび争いました。","城の近くには «松倉金山» がありました。«山から金がとれる»――それは戦国大名にとって、兵をやしない武器を買うための大きな力です。椎名氏は、この金山によって勢力をのばしたと考えられています。","はじめ椎名氏は、神保氏との争いで越後の上杉謙信を頼りました。ところがやがて椎名康胤は上杉から離れ、甲斐の武田信玄や一向一揆と手を結びます。«裏切られた» 謙信は越中に攻めこみ、1570年代の初めに松倉城は上杉方の手に落ちたとされます。","その後、松倉城は上杉氏の越中支配の中心となり、謙信の信頼する家臣・河田長親が城を守りました。長親は1581年にこの城で亡くなったと伝わります。翌1582年、ふもとの魚津城が織田軍に攻め落とされると、松倉城も戦わずに開け渡されました。","いまも山の上には、本丸・二の丸などの曲輪や、尾根を切る堀切がよく残っています。本丸跡からの眺めはすばらしく、椎名氏や上杉の武将たちが見た景色を想像できます。山の中には金山の坑道の跡も残るといわれますが、危険なので近づかないようにしましょう。"],"tl":[["室町時代","椎名氏の本拠として城が整えられたとされる（築城年は不明）"],["16世紀中ごろ","椎名氏が神保氏と争う"],["1570年代初め","椎名康胤が上杉から離反。謙信が松倉城を攻め落としたとされる"],["1570年代","上杉方の越中支配の中心となり、河田長親が守る"],["1581年","河田長親がこの城で亡くなったと伝わる"],["1582年","魚津城落城ののち開城"]],"who":[["椎名康胤","越中東部の豪族。松倉城を本拠とした"],["上杉謙信","椎名氏の離反後、越中に攻めこみ城を手に入れた"],["河田長親","上杉家の重臣。松倉城の城将として越中を治めた"],["柴田勝家","織田軍の総大将として魚津城・松倉城に迫った"]],"deep":["松倉金山は «越中七金山» の一つに数えられ、戦国時代から江戸時代にかけて採掘されたといわれます。金山の最盛期や産出量ははっきりしていません。","本丸・二の丸・三の丸が尾根に沿って並び、それぞれの間を堀切が区切っています。山の斜面には «畝状竪堀»（たてに何本も掘った堀）とみられる地形もあるといわれます。","魚津城は海に近い «平城»、松倉城は山の «詰めの城»。この二つの城が組になって越中東部を守っていたと考えられます。","椎名康胤が上杉から離れた理由には、神保氏と上杉が接近したことへの不満など諸説があります。","河田長親は近江（滋賀県）の出身で、若いころに謙信に見いだされたといわれる武将です。","江戸時代になると城は使われなくなりましたが、金山の歴史とともに地域の誇りとして語り継がれています。"],"look":["本丸跡からの富山湾の眺め","本丸・二の丸の間の堀切","登城道の案内板","ふもとの鹿熊地区の町並み"],"q":["松倉城のふもとにあり、椎名氏の力の源になったといわれるものは？","松倉金山。«越中七金山» の一つに数えられます。"],"koji":[],"myth":"築城年、落城の年、金山の規模、河田長親の死没地には諸説があります。","img":["椎名康胤","河田長親","魚津城"],"wp":"松倉城 (越中国)","rel":{"ev":[],"grave":[]},"ph":[["c:a/a8/Matsukura_cas..JPG",1944,2592,"松倉城 (越中国)"],["c:0/06/Matsukura-c.png",3648,2104],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:e/ed/Uozu_Castle_Site.jpg",1280,960,"魚津城"]]},{"id":"16_moriyama_jo","n":"守山城（二上山の神保氏の城）","yomi":"もりやまじょう","cat":"城","rank":"A","y":1585,"era":["muromachi","azuchi"],"sh":"","ad":"高岡市東海老坂（二上山）","st":"あいの風とやま鉄道・JR高岡駅から車で約20分（二上山の万葉ラインを利用）","la":36.787,"lo":137.019,"hook":"万葉の歌人がよんだ二上山。その峰の一つに、神保氏と前田利長が拠った «越中三大山城» があった。","lead":"守山城は、高岡市の二上山の一峰に築かれた山城です。戦国時代には神保氏の一族・神保氏張の城となり、のちに前田利長が入城しました。利長はここから越中西部を治めましたが、やがて富山城、さらに高岡城へと移り、守山城は役目を終えました。","story":["二上山は、奈良時代に越中国守だった大伴家持が «二上山の賦» をよんだ、万葉集ゆかりの山です。ふもとには国府（いまの伏木）があり、古くから越中の中心を見守る山でした。その峰の一つ、標高約250mの «城山» に守山城は築かれました。","城がいつ築かれたのかははっきりしません。南北朝時代に桃井直常が拠ったという伝承もあります。戦国時代になると、越中西部の神保氏の一族・神保氏張がこの城を本拠としました。«ここからなら、射水・砺波の平野も富山湾も一望できる»――見張りと守りにすぐれた場所でした。","1580年代、神保氏張は織田方の佐々成政と結びつきます。1585年、秀吉が越中に攻めこんで成政が降伏すると、守山城は前田家のものとなりました。越中西部を与えられた前田利長がこの城に入り、城を整えたといわれます。","その後、利長は富山城へ、さらに1609年には新しく築いた高岡城へと移ります。守山城は廃城となりました。«山の城から、平地の城と町へ»――守山城の歴史は、戦国の城が江戸時代の城下町へと移り変わる流れを物語っています。","いまも山頂付近には本丸などの曲輪や堀切、石垣の一部が残っています。本丸跡からは、高岡の町、富山湾、晴れた日には海の向こうの立山連峰まで見わたせます。«雨晴らし» の海岸越しに立山をのぞむ景色は、家持の時代から人びとを感動させてきました。"],"tl":[["奈良時代","大伴家持が二上山をよむ"],["南北朝時代","桃井直常が拠ったと伝わる（伝承）"],["戦国時代","神保氏張の本拠となる"],["1585年","富山の役のあと、前田利長が入城"],["1590年代","利長が富山城へ移る"],["1609年","利長が高岡城を築き、守山城は廃城に"]],"who":[["神保氏張","神保氏の一族。守山城を本拠とした"],["佐々成政","越中の大名。神保氏張と結んだ"],["前田利長","富山の役後に入城し、のちに高岡城を築いた"],["大伴家持","奈良時代の越中国守。二上山をよんだ"]],"deep":["«越中三大山城» の一つですが、ほかの二つ（増山城・松倉城）にくらべ、前田利長の時代に石垣が使われた可能性が指摘されています。","本丸・二の丸などの曲輪が尾根にそって並び、山頂近くには石垣の跡とされる石積みも見られます。","利長が守山城から富山城へ移った年は、資料によって違いがあります。","二上山は «ふたかみやま»。奈良の二上山と同じく、二つの峰をもつ山として名づけられました。","山には «二上山万葉ライン» という車道が通り、城跡の近くまで車で行くことができます。家持の銅像も山にあります。","神保氏張の妻は、織田信長の一族の女性だったといわれますが、その詳しい関係には諸説あります。"],"look":["本丸跡からの富山湾と立山連峰の眺め","尾根の堀切と曲輪","石垣の跡とされる石積み","二上山の大伴家持像"],"q":["守山城が築かれた二上山をよんだ、奈良時代の越中国守は？","大伴家持。『万葉集』に二上山の歌を残しています。"],"koji":[],"myth":"築城年・桃井直常の伝承・石垣の年代・利長の移転年は諸説です。","img":["二上山 (富山県)","神保氏張","前田利長"],"wp":"守山城","rel":{"ev":[],"grave":[]},"ph":[["c:0/00/Oyabe_River_and_Mt._Futagami_ac.jpg",5863,3899,"二上山 (富山県)"],["c:6/68/Maeda_Toshinaga.jpg",354,396,"前田利長"],["c:d/d7/Takaoka_Jokoji_Athletic_Stadium.jpg",1082,1007,"近く: 城光寺運動公園"],["c:a/a5/%E9%AB%98%E5%B2%A1%E5%B8%82%E5%96%B6%E5%9F%8E%E5%85%89%E5%AF%BA%E9%87%8E%E7%90%83%E5%A0%B4.jpg",1280,960,"近く: 高岡市営城光寺野球場"],["c:1/13/TAKAOKA-BUSSHARI-TOU.JPG",1920,1080,"近く: 鉢伏山 (高岡市)"],["c:5/53/TAKAOKA-JOUYAMA_Cherry-Blossom.JPG",1920,1080,"近く: 守山城 (越中国)"]]},{"id":"16_yasuda_jo","n":"安田城跡（秀吉の富山攻めの陣城）","yomi":"やすだじょうあと","cat":"城","rank":"A","y":1585,"era":["azuchi"],"sh":"国指定史跡","ad":"富山市婦中町安田","st":"JR高山本線の速星駅から歩いて約20分（車なら富山市街から約20分）","la":36.6583,"lo":137.1558,"hook":"秀吉が佐々成政を攻めた «富山の役»。その最前線に築かれた平城が、堀と土塁ごとよみがえった。","lead":"安田城は、1585年の «富山の役» のころ、豊臣秀吉方が佐々成政の富山城に備えて築いたとされる平城です。成政の降伏後は前田家の城となりました。堀と土塁で囲まれた3つの曲輪がほぼ昔の形で残り、国の史跡として整備され、資料館もあります。","story":["1585年、豊臣秀吉は10万ともいわれる大軍で越中へ攻めこみました。ねらいは、秀吉に従わない佐々成政の富山城です。秀吉は呉羽山の白鳥城に本陣をおいたと伝わり、そのまわりにはいくつもの «陣城» が築かれました。安田城も、そうした城の一つと考えられています。","安田城は、井田川のほとりの平らな土地に築かれた平城です。山城とちがい、守りの頼りは «水»。まわりを堀で囲み、土を盛り上げた土塁で守りを固めました。«平らな土地で、どう城を守るか»――その答えがこの堀と土塁です。","成政はまもなく降伏し、大きな戦いにはなりませんでした。その後、安田城は前田利家の家臣・岡嶋一吉が城主となったと伝わります。越中の西部を治めることになった前田家にとって、安田城は富山城ににらみをきかせる大事な城だったのでしょう。","やがて城は使われなくなり、跡地は田んぼになりました。ところが不思議なことに、田んぼの中には堀と土塁の形がそのまま残っていました。«なぜ田んぼにならずに残ったのか?»――城の土地を大切にする地元の人びとの思いがあったともいわれます。","調査のあと、城跡は国の史跡に指定され、堀に水をたたえた昔の姿に整えられました。本丸・二の丸・三の丸の3つの曲輪を歩くことができ、隣の資料館では発掘の成果や富山の役の歴史を学べます。平らな土地の城の姿がこれほどよくわかる場所は、全国でも多くありません。"],"tl":[["1585年","秀吉の «富山の役»。安田城が築かれたとされる"],["1585年","佐々成政が降伏"],["1580年代後半","前田家の家臣・岡嶋一吉が城主になったと伝わる"],["江戸時代","廃城となり、跡地は田んぼに"],["平成時代","国の史跡に指定され、史跡公園・資料館として整備"]],"who":[["豊臣秀吉","富山の役で佐々成政を攻めた"],["佐々成政","富山城主。秀吉に降伏した"],["岡嶋一吉","前田利家の家臣。安田城主と伝わる"],["前田利家","加賀藩の祖。富山の役で秀吉方として参戦"]],"deep":["安田城は «本丸»«二の丸»«三の丸» の3つの曲輪からなり、それぞれが堀で区切られています。土塁の高さや堀の幅は、発掘調査にもとづいて復元されています。","築城したのが秀吉方か前田方か、また富山の役の前からあったのかどうかには諸説があります。","平城の遺構がこれほど良い状態で残る例は北陸では貴重で、国の史跡に指定されました。","発掘では、城の出入り口（虎口）や、橋がかかっていたとみられる跡などが確認されています。","安田城と白鳥城、さらに大峪城などの城は、呉羽丘陵とその周辺で成政の富山城を囲む «包囲網» をつくっていたと考えられます。","資料館には、城跡から見つかった陶磁器や、富山の役の流れを示す展示があります。"],"look":["水をたたえた堀と土塁","本丸・二の丸・三の丸をつなぐ通路","安田城跡資料館","城跡から見る呉羽丘陵（白鳥城の方向）"],"q":["1585年、豊臣秀吉が佐々成政を攻めた戦いを何という？","«富山の役»。成政は大きな戦いをせずに降伏しました。"],"koji":[],"myth":"築城者・築城時期、岡嶋一吉の城主説には諸説があります。","img":["白鳥城","佐々成政","富山の役"],"wp":"安田城","rel":{"ev":[],"grave":[]},"ph":[["c:b/bd/Shiratorijou001.jpg",800,531,"白鳥城"],["c:3/38/Sassa_Narimasa.JPG",408,484,"佐々成政"],["c:2/2b/Hayahoshi_Station_2020.jpg",3456,2304,"近く: 速星駅"],["c:e/ec/Usaka-jinja_haiden.jpeg",3072,2304,"近く: 婦中町"],["c:7/7f/Future_City_Favore_2025-07-11_%28cropped%29.jpg",2535,1426,"近く: フューチャーシティ・ファボーレ"],["c:b/be/Toyama-nishi-high-school_toyama-pref_2018.jpg",1024,768,"近く: 富山県立富山西高等学校"],["c:5/52/Hayahoshi-junior-high-school_toyama-city_2018.jpg",1024,768,"近く: 富山市立速星中学校"],["c:7/73/Hayahoshi-elem-school_toyama-city_2018.jpg",1024,768,"近く: 富山市立速星小学校"]]},{"id":"16_hojozu_jo","n":"放生津城（越中公方・足利義材の御所）","yomi":"ほうじょうづじょう","cat":"城","rank":"A","y":1493,"era":["muromachi"],"sh":"","ad":"射水市八幡町（放生津小学校付近）","st":"万葉線の新湊地区の駅（中新湊・東新町など）から歩いて約5〜10分","la":36.776,"lo":137.106,"hook":"都を追われた将軍が、港町・放生津にやってきた。越中に «もう一つの幕府» があった5年間。","lead":"放生津城は、室町時代の越中の有力者・神保氏の城です。1493年、将軍の座を追われた足利義材（のちの義稙）がこの地に下り、神保長誠に迎えられて «越中御所» を開きました。人びとは義材を «越中公方» とよびました。今は城の遺構はほとんどなく、小学校の敷地に石碑が立っています。","story":["1493年、京都で大事件が起きました。管領の細川政元が、将軍・足利義材を追い出し、別の人物を将軍に立てたのです（«明応の政変»）。義材はとらえられ、閉じこめられてしまいました。«このままでは終われぬ»――義材はひそかに脱出し、北陸へ向かいました。","義材を迎えたのは、越中の放生津を本拠とする神保長誠でした。神保氏は畠山氏の家臣として越中を任されていた一族です。義材は放生津に御所をかまえ、ここから全国の大名に «自分こそ本当の将軍だ» と呼びかけました。地方に «もう一つの幕府» ができたようなものでした。","放生津は、富山湾に面した港町。海の道を使えば、北陸や日本海沿いの各地とすぐに連絡がとれます。«なぜ放生津だったのか?» それは、港の便利さと、神保氏という力強い味方がいたからだと考えられます。","しかし京都へ戻ることはなかなかできず、義材は1498年に越前の朝倉氏をたよって放生津を去りました。その後も各地を転々としたすえ、1508年、ついに将軍に返り咲きます。放生津での日々は、義材の «復活» への長い道のりの一歩だったのです。","神保氏はその後、越中の支配をめぐって越後の長尾氏と戦い、1520年には神保慶宗が長尾為景に敗れて滅びました。放生津城も戦国の争いのなかで姿を消していきます。今、城跡とされる放生津小学校には石碑が立ち、室町時代の «越中公方» の記憶を伝えています。"],"tl":[["室町時代","神保氏が放生津を本拠とする"],["1493年","明応の政変。足利義材が放生津に下り、神保長誠に迎えられる"],["1498年","義材が越前の朝倉氏のもとへ移る"],["1508年","義材（義尹）が将軍に返り咲く"],["1520年","神保慶宗が長尾為景に敗れる"]],"who":[["足利義材（義稙）","室町幕府10代将軍。追放後に放生津で «越中公方» とよばれた"],["神保長誠","越中の守護代。義材を迎えた"],["細川政元","管領。明応の政変で義材を追放した"],["神保慶宗","長誠の子。長尾為景に敗れた"],["長尾為景","越後の守護代。上杉謙信の父"]],"deep":["義材は放生津滞在中、たびたび名前を変えました。義材→義尹→義稙と改名しており、呼び方によって同じ人物だと気づきにくいので注意が必要です。","«越中御所» が置かれた場所は、放生津の正光寺とする説が知られていますが、確かな場所は諸説あります。","放生津には義材に従って幕府の役人たちも集まり、各地の大名に命令書（御内書）が出されたと考えられています。","放生津城の構造は、発掘調査でわずかに堀の跡などが確認されている程度で、詳しい姿はわかっていません。","«放生津» の地名は、生き物を放してその命を助ける仏教の儀式 «放生会» に由来するといわれます。","神保慶宗と長尾為景の戦い（新庄の戦い）は、越中の戦国時代の大きな転機となり、のちの上杉謙信の越中進出にもつながっていきます。"],"look":["放生津小学校の城跡の石碑","放生津八幡宮","内川沿いの港町の風景","新湊の町並み"],"q":["明応の政変で京都を追われ、放生津で «越中公方» とよばれた将軍は？","足利義材（のちの義稙）。1508年に将軍に返り咲きました。"],"koji":[],"myth":"越中御所の場所、城の規模・構造には諸説があります。","img":["足利義稙","明応の政変","神保長誠"],"wp":"放生津城","rel":{"ev":[],"grave":[]},"ph":[["c:1/13/Houjyouzu_castle.jpg",1984,1488,"放生津城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:6/64/Ashikaga_Yoshitane.jpg",1729,1984,"足利義稙"],["c:c/ca/Jinnbo_Naganobu.jpg",336,482,"神保長誠"]]},{"id":"16_kifune_jo","n":"木舟城（天正地震で埋もれた城）","yomi":"きふねじょう","cat":"城","rank":"A","y":1586,"era":["heian","azuchi"],"sh":"","ad":"高岡市福岡町木舟","st":"あいの風とやま鉄道の福岡駅から車で約5分（歩いて約25分）","la":36.702,"lo":136.963,"hook":"真冬の夜、大地が大きくゆれ、城は地の底へ沈んだ――。城主夫妻が命を落とした、天正地震の悲劇の城。","lead":"木舟城は、砺波平野の北にあった平城です。平安時代の末から石黒氏の城と伝わり、戦国時代の終わりには前田利家の弟・前田秀継が城主になりました。ところが1586年1月（旧暦では天正13年11月）の «天正地震» で城は崩れ、秀継夫妻が亡くなりました。今は石碑と土塁の一部が残る «城跡» です。","story":["木舟城のあたりは、昔は沼や湿地が多い土地でした。«木の舟» で行き来したことが名前の由来ともいわれます。平安時代の終わりには、この地の武士・石黒氏が城をかまえたと伝わります。石黒氏は、倶利伽羅峠の戦いで木曽義仲に味方したともいわれる古い一族です。","戦国時代の終わり、越中は佐々成政の支配を経て、1585年の «富山の役» のあと前田家のものになりました。木舟城には、前田利家の弟・前田秀継が入ります。«兄上のために、越中の守りを固めねば»――秀継は城と城下を整えていきました。","ところが、城主となってまもない冬の夜のことです。天正13年11月29日（1586年1月18日）、中部地方から近畿にかけて巨大な地震がおそいました。これが «天正地震» です。やわらかい湿地の上に建っていた木舟城は、ひとたまりもありませんでした。","城は崩れ、地面が沈みこみ、城主の秀継と妻、多くの家臣たちが亡くなったと伝わります。«城が一夜にして地の中に沈んだ» ――そんな話も語り継がれました。生きのびた秀継の子・利秀は、城を今石動（いまの小矢部市）に移しました。","今、城跡には石碑が建ち、土塁の一部が残っています。平らな田園の中にある小さな城跡ですが、地震の恐ろしさと、亡くなった人びとへの思いを静かに伝えています。天正地震では、飛騨の帰雲城も山崩れに埋もれるなど、各地で大きな被害が出ました。"],"tl":[["平安時代末","石黒氏が城をかまえたと伝わる"],["戦国時代","石黒氏の城として続く"],["1585年","富山の役のあと、前田秀継が城主となる"],["1586年1月18日（天正13年11月29日）","天正地震で城が倒壊。秀継夫妻らが亡くなる"],["1586年以降","前田利秀が今石動城に移り、木舟城は廃城に"]],"who":[["石黒氏","砺波地方の武士。木舟城を本拠としたと伝わる"],["前田秀継","前田利家の弟。木舟城主。天正地震で亡くなった"],["前田利秀","秀継の子。地震後、今石動に城を移した"],["前田利家","加賀藩の祖。弟の秀継に木舟城を任せた"]],"deep":["天正地震は、震源や規模に諸説がある巨大地震で、複数の断層が連動したとする見方もあります。越中・飛騨・美濃・近江など広い範囲に被害が出ました。","木舟城がやわらかい湿地の上にあったことが、大きな被害につながったと考えられます。地盤の «液状化» が起きた可能性も指摘されています。","天正地震では、飛騨の帰雲城が山崩れで城主一族ごと埋まったことが知られ、今もその場所ははっきりわかっていません。","«石黒氏» と倶利伽羅峠の戦いのかかわりは、軍記物語などに見える話で、細かいことは確かめられていません。","城跡の周辺では発掘調査が行われ、地震による地割れの跡や、陶磁器などが見つかっていると報告されています。","前田秀継の墓は、今石動の寺にあると伝わります。"],"look":["木舟城跡の石碑","残された土塁の一部","城跡周辺の平らな田園（昔の湿地）","説明板の城の推定図"],"q":["1586年1月、木舟城を崩した大地震は何とよばれる？","天正地震。城主の前田秀継夫妻が亡くなりました。"],"koji":[],"myth":"城名の由来、石黒氏の築城、«城が地の中に沈んだ» という話は伝承を含みます。","img":["天正地震","前田秀継","帰雲城"],"wp":"木舟城","rel":{"ev":[],"grave":[]},"ph":[["c:7/7b/Kihune_castle.jpg",4000,3000,"木舟城"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:6/66/Monument_of_Kaerikumo_Castle_Ruins_001.JPG",3648,2736,"帰雲城"]]},{"id":"16_tenjinyama_jo","n":"天神山城（謙信の魚津攻めの城）","yomi":"てんじんやまじょう","cat":"城","rank":"B","y":1582,"era":["muromachi","azuchi"],"sh":"","ad":"魚津市（市街地東方の天神山）","st":"あいの風とやま鉄道の魚津駅から車で約10分（天神山の公園から散策）","la":36.808,"lo":137.435,"hook":"あの山の向こうに、囲まれた味方がいる――。上杉景勝が魚津城を見下ろしながら、助けに行けなかった城。","lead":"天神山城は、魚津市の東、標高約150mの天神山に築かれた山城です。上杉謙信の越中攻めのころに使われたとされ、1582年には上杉景勝が魚津城を救うためにここに陣をしきました。しかし景勝は、本国越後の危機のため兵を引き返しました。","story":["天神山は、魚津の町と海を見下ろす小さな山です。ここからは、ふもとの魚津城や、少し奥の松倉城をよく見わたすことができました。上杉謙信が越中を攻めていたころ、この山は上杉軍の陣地として使われたと伝わります。","1582年、魚津城は柴田勝家らの織田軍に囲まれていました。城を守る上杉の将たちからは «早く助けに来てほしい» という知らせが届きます。上杉景勝は、越後から兵を率いてこの天神山まで進みました。","天神山から見下ろすと、魚津城を取り囲む織田の大軍が見えたことでしょう。«あと少しで助けられるのに»――景勝は攻めるきっかけを探しました。しかしそのとき、信濃の方面から織田軍が越後に迫っているという知らせが入ります。本国が危ない。景勝はやむなく天神山から兵を引き返しました。","援軍を失った魚津城は、6月3日に落城します。その前日、京都では本能寺の変が起きていました。«もし景勝がもう数日とどまっていたら»――天神山は、そんな «歴史のもしも» を思わせる場所です。","今、天神山のあたりは公園や墓地などになっていて、城の遺構はあまりはっきりしません。それでも山の上から魚津の町を見下ろすと、景勝の苦しい決断の場面が目に浮かぶようです。"],"tl":[["1560〜70年代","上杉謙信の越中攻めで陣地として使われたと伝わる"],["1582年3月ごろ","織田軍が魚津城を包囲"],["1582年5月","上杉景勝が天神山に着陣"],["1582年5月末ごろ","景勝が越後へ撤退"],["1582年6月3日","魚津城が落城"]],"who":[["上杉景勝","謙信の後継者。魚津城救援のため天神山に陣をしいた"],["上杉謙信","越中攻めでこの山を使ったと伝わる"],["柴田勝家","織田軍の総大将。魚津城を包囲した"],["魚津城の守将たち","援軍を待ちながら籠城を続けた"]],"deep":["天神山城は、合戦のときの一時的な «陣城» としての性格が強かったと考えられ、恒久的な城の建物があったかどうかはわかっていません。","景勝が着陣・撤退した日付は、史料によって数日のずれがあります。","景勝が撤退した理由は、信濃の森長可らの織田軍が越後に迫ったためとされます。上杉家は四方を織田方に囲まれ、存亡の危機にありました。","天神山という名前は、山に天神（菅原道真）がまつられていたことにちなむといわれます。","魚津城・松倉城・天神山城をあわせて歩くと、上杉と織田の攻防の地理がよくわかります。","本能寺の変のあと、上杉家は滅亡をまぬがれ、景勝はのちに豊臣政権の五大老の一人となりました。","山城には、敵を見張る «物見» の役目もありました。天神山は魚津城と松倉城の中間にあたり、両方の城と連絡をとるのに便利な位置だったと考えられます。こうした小さな陣城の働きは、記録に残りにくく、地形の観察が大切な手がかりになります。"],"look":["天神山から見下ろす魚津の町と富山湾","魚津城跡の方向","松倉城のある山並み","山中に残る平らな曲輪状の地形"],"q":["1582年、魚津城を救うために天神山に陣をしいた上杉家の当主は？","上杉景勝。本国の危機のため引き返しました。"],"koji":[],"myth":"謙信の使用、城の規模、着陣・撤退の日付は諸説があります。","img":["上杉景勝","魚津城","松倉城 (越中国)"],"wp":"天神山城 (越中国)","rel":{"ev":[],"grave":[]},"ph":[["c:8/87/Tenjinyama01.jpg",1600,1200,"天神山城 (越中国)"],["c:b/b2/Tenjinyamaue.jpg",1600,1200],["c:d/da/Kogakubo_KoboDaishi_Do.jpg",1600,1200],["c:1/13/Tenjinyama00.jpg",1599,1200],["c:3/3a/Tenjinyama_top.jpg",1200,1200],["c:8/8a/Tenjinyama02.jpg",1200,900],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:3/3b/Kyoukaizyou.jpg",900,675]]},{"id":"16_shirotori_jo","n":"白鳥城（呉羽山・富山の役の陣）","yomi":"しろとりじょう","cat":"城","rank":"B","y":1585,"era":["muromachi","azuchi"],"sh":"","ad":"富山市吉作（呉羽山）","st":"富山駅からバスで呉羽山方面へ、そこから歩いて登る（車なら呉羽山公園の駐車場から歩く）","la":36.696,"lo":137.164,"hook":"秀吉は呉羽山から富山城を見下ろした。佐々成政に降伏を決意させた «にらみの城»。","lead":"白鳥城は、富山市の西にある呉羽山の峰に築かれた山城です。1585年、豊臣秀吉が佐々成政を攻めた «富山の役» のとき、秀吉方の本陣が置かれたと伝わります。成政の降伏後は前田家の城となり、やがて廃城となりました。今も曲輪や堀切が残っています。","story":["呉羽山は、富山平野を東西に分けるように横たわる丘陵です。頂上からは富山の町と、はるか向こうの立山連峰が一望できます。この山の峰に、白鳥城は築かれました。いつ誰が築いたかははっきりしませんが、戦国時代には神保氏や佐々氏の城だったともいわれます。","1585年の夏、豊臣秀吉は大軍を率いて越中に攻めこみました。«富山の役» です。秀吉は呉羽山の白鳥城に本陣を置いたと伝わります。山の上から、成政のこもる富山城がよく見えました。«これだけの大軍を見れば、成政も観念するであろう»――秀吉の軍勢は、呉羽丘陵とそのふもとをうめつくしました。","まわりには安田城などの陣城も築かれ、富山城は囲まれていきました。成政は大きな戦いをせずに、頭を丸めて秀吉に降伏します。秀吉にとって白鳥城は、戦わずに勝つための «にらみの城» だったのです。","その後、白鳥城は前田家の城となり、家臣が守ったといわれます。しかし江戸時代になると役目を終えて廃城となりました。山の中には、本丸や二の丸の曲輪、敵の侵入をはばむ堀切の跡が今も残っています。","呉羽山は今、公園や散策路が整えられ、市民の憩いの場になっています。展望台からの景色はすばらしく、秀吉が見たであろう富山城の方向を眺めると、戦国の終わりの緊張感を想像することができます。"],"tl":[["戦国時代","白鳥城が築かれたとされる（築城者は諸説）"],["1585年8月","富山の役。秀吉方の本陣が置かれたと伝わる"],["1585年","佐々成政が降伏"],["1580年代後半","前田家の城となる"],["江戸時代初め","廃城"]],"who":[["豊臣秀吉","富山の役で本陣を置いたと伝わる"],["佐々成政","富山城主。秀吉に降伏した"],["前田利家","秀吉方として富山の役に参加"],["前田利長","戦後、越中西部を与えられた"]],"deep":["秀吉の本陣が白鳥城に置かれたかどうかは、史料によって書き方が違い、呉羽山周辺の別の場所とする説もあります。","城跡には本丸・二の丸などの曲輪と、尾根を切る堀切が残ります。山城としては規模は大きくありませんが、眺めのよさが特徴です。","白鳥城・安田城・大峪城など、呉羽丘陵とその周辺には富山の役にかかわる城がいくつもあり、あわせて «富山城包囲網» と考えられています。","«白鳥» という名前の由来ははっきりしていませんが、白い鳥の伝説と結びつける話もあります。","呉羽山は «呉羽丘陵» の一部で、富山市の «呉東»«呉西» という地域の分け方の基準にもなっています。","呉羽山の展望台からは、天気がよければ立山連峰が一望でき、富山城の模擬天守の方向もわかります。","富山の役で成政が戦わずに降伏した背景には、前年の «さらさら越え» で家康をたよったものの、家康がすでに秀吉と和解していたことがあります。味方を失った成政に、大軍に立ち向かう力は残っていませんでした。"],"look":["本丸跡の曲輪","尾根を切る堀切","呉羽山展望台からの富山市街と立山連峰","近くの安田城跡とのつながり"],"q":["1585年、秀吉方の本陣が置かれたと伝わる呉羽山の城は？","白鳥城。富山城の佐々成政ににらみをきかせました。"],"koji":[],"myth":"築城者、秀吉本陣の場所、城名の由来は諸説です。","img":["呉羽山","富山の役","安田城"],"wp":"白鳥城","rel":{"ev":[],"grave":[]},"ph":[["c:b/bd/Shiratorijou001.jpg",800,531,"白鳥城"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:2/2b/%E5%AF%8C%E5%B1%B1%E7%9C%8C%E7%99%BD%E9%B3%A5%E5%9F%8E%E8%B7%A11.jpg",1728,2304],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:6/61/%E4%B8%AD%E5%A4%AE%E3%82%B5%E3%82%A4%E3%82%AF%E3%83%AA%E3%83%B3%E3%82%B0%E3%83%AD%E3%83%BC%E3%83%89_%E5%AF%8C%E5%B1%B1%E5%B8%82%E5%AF%BA%E7%94%BA%E4%BB%98%E8%BF%912.jpg",2816,1584,"呉羽山"]]},{"id":"16_kitadai","n":"北代縄文広場（北代遺跡）","yomi":"きただいじょうもんひろば","cat":"遺跡","rank":"A","y":-2500,"era":["jomon"],"sh":"国指定史跡","ad":"富山市北代","st":"富山駅からバスで北代方面へ、そこから歩いて約5分（車なら富山駅から約20分）","la":36.716,"lo":137.162,"hook":"4000年以上前、呉羽山のふもとにあった «縄文のムラ»。70棟をこえる竪穴住居のあとが、ここで見つかった。","lead":"北代遺跡は、呉羽丘陵の北のはしにある縄文時代中期（約4500〜4000年前）のムラの跡です。竪穴住居のあとが70棟以上見つかり、国の史跡に指定されています。«北代縄文広場» では竪穴住居や高床建物が復元され、隣の縄文館で出土品を見ることができます。","story":["今から4000年以上前、呉羽丘陵のふもとの台地に、縄文人のムラがありました。台地の下には川や湿地が広がり、森にはクリやトチの木がしげっていました。«ここなら水も食べものも手に入る»――縄文人にとって、とても住みやすい場所だったのでしょう。","発掘調査では、地面を掘りくぼめてつくった «竪穴住居» のあとが70棟以上見つかりました。もちろん全部が同じ時期にあったわけではなく、何百年もの間に建てかえられてきたものです。住居の中には、煮たきや暖房に使った «炉» のあとも残っていました。","住居のほかに、柱の穴が規則正しく並んだ «掘立柱建物» のあとも見つかりました。«これは倉庫だろうか? それともみんなが集まる建物?»――研究者たちは、食べものをたくわえる高床の倉庫だったのではないかと考え、広場に復元しました。","出土品には、土器や石の道具のほか、土偶などもあります。縄文人は、ただ生きるために食べものを集めるだけでなく、祈りや祭りも大切にしていました。土器にほどこされた力強い文様からは、彼らの豊かな感性が伝わってきます。","北代縄文広場では、復元された竪穴住居の中に入ることができます。中はうす暗く、ひんやりしています。«ここで家族が火を囲んで暮らしていたんだ»――4000年前の暮らしを体で感じられる場所です。縄文館では、土器づくりなどの体験イベントも行われています。"],"tl":[["約4500〜4000年前","縄文時代中期、ムラが営まれる"],["昭和時代","遺跡の存在が知られ、発掘調査が行われる"],["平成時代","国の史跡に指定"],["平成時代","北代縄文広場として整備。竪穴住居・高床建物を復元"]],"who":[["北代に暮らした縄文人","竪穴住居に住み、森や川の恵みで暮らした"],["発掘・復元にかかわった人びと","ムラの跡を調べ、広場として復元した"]],"deep":["竪穴住居の数は70棟以上とされますが、同時に建っていたのはその一部と考えられます。縄文のムラは、建てかえをくり返しながら長く続きました。","復元された高床建物は、柱の穴の並びから推定されたもので、屋根や床の形は研究者の考えにもとづく復元です。","遺跡のある台地は呉羽丘陵の北のはしで、海に近い位置です。縄文時代は今より海が内陸まで入りこんでいた時期もあり、海の幸も利用していたと考えられます。","北代遺跡では、中期の土器が多く出土しています。北陸の縄文中期の土器は、立体的で大きな文様をもつものが特徴です。","富山県内には、同じ縄文時代中期の遺跡として、朝日町の不動堂遺跡などがあり、あわせて見ると北陸の縄文文化の広がりがわかります。","縄文館は入館無料で、復元住居の中に入ったり、出土品を見たりできます（休館日に注意）。"],"look":["復元された竪穴住居（中に入れる）","復元された高床建物","北代縄文館の土器・石器","台地から見る富山平野"],"q":["北代遺跡で70棟以上見つかった、地面を掘りくぼめてつくった縄文時代の家を何という？","«竪穴住居»。中央には炉のあとが残っていました。"],"koji":[],"myth":"住居の棟数・年代、高床建物の復元形は推定を含みます。史跡指定年は確かめていません。","img":["竪穴住居","縄文時代","呉羽山"],"wp":"北代遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:3/31/Kitadai_Site.jpg",1200,802,"北代遺跡"],["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:5/5a/Yoshinogari-iseki_tateanashiki-juukyo.JPG",6016,4000,"竪穴住居"],["c:6/61/%E4%B8%AD%E5%A4%AE%E3%82%B5%E3%82%A4%E3%82%AF%E3%83%AA%E3%83%B3%E3%82%B0%E3%83%AD%E3%83%BC%E3%83%89_%E5%AF%8C%E5%B1%B1%E5%B8%82%E5%AF%BA%E7%94%BA%E4%BB%98%E8%BF%912.jpg",2816,1584,"呉羽山"]]},{"id":"16_fudodo","n":"不動堂遺跡（巨大な縄文の長屋）","yomi":"ふどうどういせき","cat":"遺跡","rank":"A","y":-2500,"era":["jomon"],"sh":"国指定史跡","ad":"下新川郡朝日町不動堂","st":"あいの風とやま鉄道の泊駅から車で約10分","la":36.934,"lo":137.57,"hook":"長さ17m、炉が4つ。まるで «縄文のアパート»!? 田んぼの下から現れた、巨大な竪穴住居。","lead":"不動堂遺跡は、朝日町にある縄文時代中期（約4500年前）のムラの跡です。1973年、田んぼの整備工事中に見つかり、長さ約17m、幅約8mの小判の形をした巨大な竪穴住居が発見されました。その重要さから翌年、国の史跡に指定され、住居が復元されています。","story":["1973年、朝日町の不動堂で、田んぼを広く整える工事が行われていました。すると、土の中から縄文土器や、住居のあとが次々と現れます。«これはただの遺跡ではないぞ»――調査を進めると、今までに見たことのない大きさの竪穴住居が姿を現しました。","その住居は、長さ約17m、幅約8m。ふつうの竪穴住居の何倍もの広さです。しかも中には、火を燃やした «炉» が4つも並んでいました。«こんなに大きな家で、何をしていたのだろう?»――発見は大きなニュースになりました。","研究者たちはいろいろな説を考えました。いくつもの家族がいっしょに住む «長屋» だったのではないか。冬のあいだ、ムラの人たちがみんなで集まって作業をした «共同の作業場» だったのではないか。祭りや集会の場だったのではないか。答えは今もはっきりとは出ていません。","北陸や東北の日本海側には、こうした大型の竪穴住居が見つかる例があります。雪が深い地域で、冬をみんなで乗りこえるためのくふうだったのでは、と考える研究者もいます。不動堂遺跡は、その代表的な例として知られています。","発見の翌年、1974年に国の史跡に指定され、巨大住居は実物大で復元されました。中に入ると、その広さに驚かされます。«4つの炉に火が燃え、たくさんの人の声が響いていたのかもしれない»――4500年前のにぎわいを想像してみましょう。"],"tl":[["約4500年前","縄文時代中期、ムラが営まれる"],["1973年","田んぼの整備工事中に遺跡が見つかる"],["1973年","長さ約17mの巨大竪穴住居が発見される"],["1974年","国の史跡に指定"],["その後","巨大竪穴住居が復元される"]],"who":[["不動堂に暮らした縄文人","巨大な竪穴住居をつくり、雪国で暮らした"],["発掘調査にあたった人びと","工事中の発見から、巨大住居を明らかにした"]],"deep":["巨大住居は «第2号住居» とよばれ、長径約17m・短径約8mの小判形。中央に4つの炉が一列に並んでいました。","大型の竪穴住居は、秋田県・新潟県など日本海側の雪の多い地域でも見つかっていて、«ロングハウス» とよぶ研究者もいます。","巨大住居の使われ方には、共同住居説・作業場説・集会所説などがあり、決め手はありません。","遺跡からは縄文中期の土器や石器がたくさん見つかっています。北陸の中期の土器の特徴がよくわかる資料です。","見つかったきっかけは、田んぼを大きく整える «ほ場整備» の工事でした。工事の途中で見つかった遺跡が、すぐに国の史跡になったのはめずらしい例です。","復元住居は、柱の穴の位置などをもとに建てられたもので、屋根の形などは推定を含みます。"],"look":["実物大で復元された巨大竪穴住居","住居の中の4つの炉の位置","遺跡のまわりの田園風景","朝日町の埋蔵文化財の展示"],"q":["不動堂遺跡の巨大竪穴住居の中には、炉がいくつあった？","4つ。長さ約17mの住居の中に一列に並んでいました。"],"koji":[],"myth":"巨大住居の用途は諸説、復元の屋根の形は推定です。","img":["竪穴住居","縄文時代","朝日町 (富山県)"],"wp":"不動堂遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:1/19/Fudodo_Site.jpg",1200,865,"不動堂遺跡"],["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:5/5a/Yoshinogari-iseki_tateanashiki-juukyo.JPG",6016,4000,"竪穴住居"],["c:0/05/%E8%88%9F%E5%B7%9D%E3%81%B9%E3%82%8A_01.jpg",6178,4119,"朝日町 (富山県)"]]},{"id":"16_otake","n":"小竹貝塚（縄文人骨が多数出た貝塚）","yomi":"おだけかいづか","cat":"遺跡","rank":"A","y":-4000,"era":["jomon"],"sh":"","ad":"富山市呉羽町北","st":"あいの風とやま鉄道 呉羽駅が最寄り。遺跡は整備公園ではなく、現地で見られるものはほとんどない。出土品は県の埋蔵文化財センターなどの展示で見るのが確実","la":36.7225,"lo":137.17,"hook":"新幹線の工事現場から、6000年前の人びと90体あまりが «目をさました»。日本海側最大級の縄文貝塚。","lead":"小竹貝塚は、縄文時代の前期（今からおよそ6000〜5500年前）に人びとが暮らし、貝がらや骨を捨て、亡くなった人をほうむった場所です。北陸新幹線の工事にともなう発掘で、たくさんの人骨が見つかり、全国の研究者をおどろかせました。当時ここは海水と川の水がまじる入り江（潟）のほとりでした。","story":["富山駅から西へ、呉羽の丘がなだらかに北へ下っていくあたり。今は田んぼと住宅と新幹線の高架が見えるだけの場所ですが、6000年前の景色はまるでちがいました。地球が今より暖かく、海面が高かった «縄文海進» の時代。富山湾の水は内陸まで入りこみ、丘のすそには波の静かな潟が広がっていたと考えられています。","«ここなら、シジミがいくらでもとれるぞ»。そんな声が聞こえてきそうです。貝塚から出た貝の多くは、海水と淡水がまじる水辺にすむシジミのなかまでした。人びとは潟で貝をとり、魚をつり、丘の森でシカやイノシシを追い、木の実を集めました。食べ終わった貝がらを同じ場所に捨てつづけるうちに、厚い «貝の層» ができあがったのです。","なぜ、貝塚からはこんなに人骨がよく出るのでしょう? ふつう日本の土は酸性で、骨は長い年月のうちにとけて消えてしまいます。ところが貝がらのカルシウムが土の酸をやわらげるため、貝塚の中では骨が残りやすいのです。小竹貝塚ではこの «天然の保存庫» のおかげで、90体をこえる縄文人の骨が見つかりました。縄文時代前期の人骨がこれほどまとまって出た例は、全国でもめずらしいといわれます。","見つかったのは、北陸新幹線の建設に先立つ発掘調査のときでした。工事で消えてしまう遺跡は、ていねいに掘って記録に残す «記録保存» が行われます。調査員たちは、土の中から一体、また一体と骨を取り上げ、そのたびに位置や向き、いっしょに出た道具を図面に書きこみました。石器や土器、骨や角でつくった道具、飾りなども数多く出ています。","骨は «その人が生きた証» でもあります。背の高さ、年齢、けがや病気のあと、そして骨にのこる遺伝子(DNA)。研究では、小竹の人びとの遺伝子にいろいろな系統がまじっていることがわかり、縄文人が一つの集団ではなかった可能性を考える手がかりになっています。名もない6000年前の人びとが、今も私たちに «日本人はどこから来たのか» という問いを投げかけているのです。"],"tl":[["約6000〜5500年前","縄文時代前期。潟のほとりに集落と貝塚がいとなまれる"],["縄文時代前期","海面が高い «縄文海進» のころ。富山湾が内陸まで入りこむ"],["昭和時代","呉羽丘陵のふもとの貝塚として知られるようになる"],["2009〜2010年ごろ","北陸新幹線の建設にともなう本格的な発掘調査"],["調査後","90体をこえる人骨や多くの道具が出土し、分析・研究が進む"],["2015年","北陸新幹線（長野〜金沢）開業。遺跡の上を列車が走る"]],"who":[["縄文時代前期の人びと","この地で暮らし、貝塚に眠っていた人たち。名前は伝わらない"],["発掘調査の担当者たち","新幹線工事の前に遺跡を掘り、記録保存した"],["人類学・遺伝学の研究者","人骨やDNAを分析し、縄文人の姿を明らかにしようとしている"]],"deep":["人骨の数は «91体» と紹介されることが多く、縄文時代前期の人骨の出土数としては国内最多クラスとされます。一つの遺跡でこれだけの数がそろうと、背の高さや寿命などを «集団» として比べられるのが大きな価値です。","貝の主体は汽水域（海水と淡水がまじる水辺）のシジミ類とされます。これは当時この付近に潟湖（せきこ）が広がっていた証拠で、呉羽丘陵周辺の古い地形を復元する手がかりにもなっています。","貝塚は «ごみ捨て場» であると同時に «お墓» でもありました。ごみと死者を同じ場所に置くことを、縄文人がどう考えていたのか。«ものも人も自然に返す場所» だったとみる考え方もあり、議論が続いています。","DNA分析では、母から子へ伝わるミトコンドリアDNAの系統がいくつも見つかったと報告されています。縄文人の起源が一つではない可能性を示す例として、学術書や報道でたびたび取り上げられました。","呉羽丘陵の周辺には、ほかにも縄文時代の貝塚や集落跡が点在します。富山市北部の北代遺跡（国指定史跡）では縄文中期のたて穴住居が復元されていて、小竹の人びとの «その後» の暮らしを想像するのに役立ちます。","遺跡の多くは工事にともなって掘りあげられ、現地は新幹線の高架や周辺の土地になっています。«見られない遺跡» だからこそ、報告書や展示で出土品に会うことが大切です。"],"look":["現地は案内板が中心。周辺の地形（呉羽丘陵のすそと平野の境目）を見て、かつての潟の広がりを想像する","出土した人骨や土器・骨角器は、富山県埋蔵文化財センターなどの展示で公開されることがある","あわせて北代縄文広場（北代遺跡）の復元住居を訪ねると、縄文の暮らしがイメージしやすい"],"q":["貝塚から人の骨がよく見つかるのはなぜ?","貝がらのカルシウムが土の酸性をやわらげ、骨がとけにくくなるからです。"],"myth":"人骨の数や系統の解釈は、分析の進み方で変わる可能性がある。","img":["貝塚","縄文時代","縄文海進","呉羽丘陵"],"wp":"小竹貝塚","rel":{"ev":[],"grave":[]},"ph":[["c:8/83/Conchero_Arguin.jpg",2048,1536,"貝塚"],["c:1/1d/Post-Glacial_Sea_Level.png",1813,1088,"縄文海進"],["c:6/61/%E4%B8%AD%E5%A4%AE%E3%82%B5%E3%82%A4%E3%82%AF%E3%83%AA%E3%83%B3%E3%82%B0%E3%83%AD%E3%83%BC%E3%83%89_%E5%AF%8C%E5%B1%B1%E5%B8%82%E5%AF%BA%E7%94%BA%E4%BB%98%E8%BF%912.jpg",2816,1584,"呉羽丘陵"]]},{"id":"16_otsuka","n":"王塚・千坊山遺跡群（弥生の四隅突出墓）","yomi":"おおつか・せんぼうやまいせきぐん","cat":"遺跡","rank":"A","y":200,"era":["yayoi","kofun"],"sh":"国指定史跡","ad":"富山市婦中町富崎・千坊山ほか（羽根丘陵）","st":"JR高山本線 速星駅からタクシーで約10分。北陸自動車道 富山西ICから車で約10分。車が便利","la":36.6606,"lo":137.1169,"hook":"ヒトデのように四すみが突き出た «王のお墓»。出雲の風が、弥生時代の富山にも吹いていた。","lead":"富山市婦中町の羽根丘陵には、弥生時代の終わりから古墳時代のはじめにかけての村の跡とお墓がまとまって残っています。四すみが突き出た «四隅突出型墳丘墓» から、大きな前方後方墳の王塚古墳へ。ムラのリーダーが «王» になっていく流れを、一つの丘でたどれる珍しい場所です。","story":["富山平野を見下ろす羽根丘陵。尾根の上に立つと、東に神通川と富山の町、晴れた日にはその向こうに立山連峰まで見わたせます。およそ1800年前、この丘の上に人びとは村をつくりました。それが千坊山遺跡です。見晴らしのよい高い場所に村をかまえたのは、なぜでしょう? 田んぼの見回りのため、あるいは争いにそなえるためだったとも考えられています。","やがて丘の上に、ふしぎな形のお墓がつくられます。四角い土の盛り上がりの四すみが、ヒトデの腕のように外へ突き出した «四隅突出型墳丘墓»。富崎墳墓群や六治古塚墳墓がそれです。«この形、どこかで見たことがある»——考古学者たちがそう思ったのも当然で、この形は出雲（島根県）を中心とする山陰地方で特にさかんにつくられたお墓でした。","遠い出雲と、越中の丘。日本海の海の道で、人やものや «お墓のつくり方» までが行き来していたのです。«われらも出雲の王たちと同じ墓に眠ろう»。そんな思いがあったのかどうか。少なくとも、ここのリーダーが日本海ぞいの広いネットワークの一員だったことは、この墓の形がはっきり物語っています。","時代が古墳時代へ移ると、丘の上にはさらに大きな墓があらわれます。前が四角、後ろも四角の «前方後方墳»、王塚古墳と勅使塚古墳です。王塚古墳は全長58メートル。弥生の墓よりずっと大きく、ムラのまとめ役が、もっと広い地域を治める «王» へと成長していったようすがうかがえます。","一つの丘の上で、ムラの暮らし、弥生の特別な墓、そして古墳へ。日本の国のかたちができあがっていく時代の «変わり目» が、ぎゅっと詰まっているのがこの遺跡群の魅力です。今は公園として整えられた場所もあり、お墓の上に立って、1800年前の王が見たのと同じ富山平野をながめることができます。"],"tl":[["弥生時代後期","羽根丘陵の上に千坊山遺跡の集落がいとなまれる"],["弥生時代後期〜終末期","富崎墳墓群・六治古塚墳墓など四隅突出型墳丘墓がつくられる"],["古墳時代前期","勅使塚古墳・王塚古墳（前方後方墳）が築かれる"],["1948年","王塚古墳が単独で国の史跡に指定される"],["2004年","周辺の遺跡をまとめて «王塚・千坊山遺跡群» として国史跡に指定がえ"]],"who":[["千坊山のムラの人びと","丘の上に暮らし、墓をきずいた。名前は伝わらない"],["四隅突出墓に葬られたリーダー","弥生時代の終わりにこの地域をまとめた有力者と考えられる"],["王塚古墳の被葬者","古墳時代前期に婦負（ねい）の地を治めた首長とみられる。名は不明"]],"deep":["四隅突出型墳丘墓は、山陰（特に出雲）に大型のものが集まり、北陸では富山県と福井県などで見つかっています。富山の例は分布の東のはしにあたり、日本海ルートの交流を示す証拠として重視されています。","弥生の四隅突出墓 → 古墳時代の前方後方墳、という順番が一つの丘で追えるのがこの史跡の最大の特徴です。首長の墓が «地域の流行» から «全国共通のかたち» に変わっていく過程を考える材料になります。","王塚古墳のデータは、全長58メートル、後方部の高さ7.6メートルとされ、富山県内でも上位の規模です。前方後円墳ではなく «前方後方墳» である点が、北陸の古墳時代前期らしい特徴といわれます。","北陸の古墳時代前期には前方後方墳が目立ちます。氷見市の柳田布尾山古墳（全長107.5メートル）もその一つで、富山湾の東西に大型の前方後方墳が並ぶことになります。","千坊山遺跡のように丘の上につくられた弥生の村は «高地性集落» と呼ばれることがあり、争いの時代の備えとする説、見張りや交易の拠点とする説などがあります。","史跡名の «王塚» の読みは «おおつか»。地元の人が大きな塚を呼んだ名が伝わったものと考えられます。"],"look":["王塚古墳の墳丘：前方後方墳の «四角い後ろ» の形を歩いて確かめる","四隅突出型墳丘墓の突出部（ヒトデの腕のような張り出し）","尾根の上からの富山平野と立山連峰のながめ","勅使塚古墳など周辺の古墳との位置関係"],"q":["四隅突出型墳丘墓が特にたくさんつくられたのは、どこの地方?","出雲（島根県）を中心とする山陰地方です。富山の例は日本海の交流を物語ります。"],"myth":"集落の性格（高地性集落の目的）や、墓に葬られた人物像は諸説。","img":["四隅突出型墳丘墓","前方後方墳","王塚古墳 (富山県)"],"wp":"王塚・千坊山遺跡群","rel":{"ev":[],"grave":[]},"ph":[["c:8/88/Nishidani_Graves-2%2C_funkyu.jpg",5568,3712,"四隅突出型墳丘墓"],["c:0/0b/Shimosamuraizuka_Kofun_2.jpg",4608,3456,"前方後方墳"],["c:b/b0/Nagasawa_Western_Castle%28%E9%95%B7%E6%B2%A2%E8%A5%BF%E5%9F%8E%E8%B7%A1%29.jpg",4032,3024,"近く: 長沢西城"],["c:d/d9/Toyamashi_tenmondai.jpg",5232,3488,"近く: 富山市天文台"],["c:9/9e/Shiratori-shien-school_toyama-pref_2018.jpg",1024,768,"近く: 富山県立しらとり支援学校"],["c:5/57/Kureha_Country_Club%2C_Toyama_Toyama_Aerial_photograph.2009.jpg",3706,2779,"近く: 呉羽カントリークラブ"],["c:5/56/Furusato-elem-school_toyama-city_2018.jpg",1024,768,"近く: 富山市立古里小学校"],["c:3/39/Toyama_Hospital.jpg",4404,3031,"近く: 国立病院機構富山病院"]]},{"id":"16_fuoyama","n":"柳田布尾山古墳（日本海側最大の前方後方墳）","yomi":"やないだぬのおやまこふん","cat":"遺跡","rank":"A","y":300,"era":["kofun"],"sh":"国指定史跡","ad":"氷見市柳田（柳田布尾山古墳公園）","st":"JR氷見線 氷見駅から車・タクシーで10〜15分ほど。駅から歩くとかなり遠い","la":36.8232,"lo":136.9915,"hook":"1998年まで «ただの山» だと思われていた丘が、じつは日本海側でいちばん大きな前方後方墳だった。","lead":"柳田布尾山古墳は、3世紀の終わりから4世紀のはじめごろにつくられた、全長107.5メートルの前方後方墳です。前方後方墳としては日本海側で最大、富山県でもいちばん大きな古墳です。富山湾と、かつてあった «布勢の水海» を見下ろす丘の上に、海の王が眠っていたと考えられています。","story":["1998年6月のある日。氷見市の歴史をまとめる本（市史）をつくるため、調査員たちが丘や畑を一つずつ歩いて調べていました。柳田の丘にさしかかったとき、ひとりが足を止めます。«この斜面、自然の山にしては形がととのいすぎていないか?»。測ってみると、それは長さ100メートルをこえる、人がつくった墳丘でした。","見つかったのは、前も後ろも四角い «前方後方墳»。全長107.5メートルは、前方後方墳としては日本海側で最大、全国でも十本の指に入る大きさです。こんな巨大な古墳が、なぜ20世紀の終わりまで気づかれなかったのでしょう? 木や草におおわれ、地元では «布尾山» という山として親しまれていたからです。大きすぎて、かえって古墳だとわからなかったのです。","丘のふもとには、かつて «布勢の水海（ふせのみずうみ）» と呼ばれる大きな潟が入りこんでいました。奈良時代、越中国守の大伴家持が舟遊びを楽しみ、歌によんだあの湖です。古墳はその湖と富山湾に向かって横腹を見せ、軸は二上山のほうを向いています。«海から来る人に、わが力を見せつけよ»。そんな意図を読みとる研究者もいます。","発掘では、後方部の真ん中に、粘土で棺をつつむ «粘土槨（ねんどかく）» がつくられていたことがわかりました。ところが、ずっと昔に盗掘にあっていて、中の副葬品はほとんど失われていました。王の名も、どんな宝を持っていたのかも、今は謎のままです。","それでも、この古墳の場所と大きさが語ることはあります。日本海の海の道をおさえ、富山湾をゆきかう舟を見守った有力者——«海の王» の姿です。今は古墳公園として整えられ、墳丘の上まで歩いて登れます。頂上に立ち、潟のあった低地と海の方角をながめれば、1700年前の王の気分を少しだけ味わえるでしょう。"],"tl":[["3世紀末〜4世紀初め","古墳時代前期。前方後方墳が築かれる"],["奈良時代","ふもとの «布勢の水海» で大伴家持が舟遊びをし、歌をよむ"],["1998年6月","氷見市史の編さんにともなう分布調査で発見"],["1998〜2000年度","氷見市教育委員会が3次にわたって発掘調査"],["2001年1月","国の史跡に指定"],["2006年4月","柳田布尾山古墳公園が開園"]],"who":[["被葬者（名は不明）","富山湾と日本海の交通をおさえた有力者と考えられる"],["大伴家持","奈良時代の越中国守。古墳のふもとの布勢の水海で遊び、歌を残した"],["氷見市史の調査員","1998年の分布調査で古墳を発見した"]],"deep":["墳丘データ：全長107.5メートル、後方部は長さ約54メートル・高さ約10メートル、前方部は長さ約53.5メートル・高さ約6メートル。2段につくられ、葺石や埴輪は見つかっていません。","つくり方にも特徴があり、もとの丘を前方後方形にけずり出してから土を盛っています。盛り土は古墳全体の体積の約6割とされます。自然地形をうまく使い、少ない労力で巨大に見せる工夫です。","前方部のすそには不定形の周濠（堀）がめぐり、幅は5〜18メートルほど。前方部の東の角には、堀をわたる «陸橋» がついていたと推定されています。","後方部の東どなりには、直径25メートルの円墳（2号墳）があります。堀の形の関係から、2号墳のほうが先につくられた可能性が指摘されています。","古墳が築かれる前、この丘には弥生時代の集落があったとされ、弥生土器のかけらも出ています。","氷見市では翌1999年にも、同じ市史の調査で県内最大の前方後円墳・阿尾島田A1号墳が見つかっています。«歩いて探す» 地道な分布調査の力を示す例です。"],"look":["墳丘の上へ登り、前方部と後方部の «四角と四角» の形を体で感じる","丘から見下ろす旧十二町潟（布勢の水海）の低地と富山湾の方角","前方部のすその周濠のあと","となりの古墳館で出土品や発掘のようすを学ぶ"],"q":["柳田布尾山古墳が見つかったのは、何年?","1998年。市史をつくるための分布調査で、ようやく古墳だとわかりました。"],"myth":"被葬者を «海上交通をおさえた首長» とみるのは研究上の推定。","img":["前方後方墳","布勢水海","大伴家持"],"wp":"柳田布尾山古墳","rel":{"ev":[],"grave":[]},"ph":[["c:5/5e/Nunoo_zenkei.jpg",1530,1024,"柳田布尾山古墳"],["c:9/9a/Yanaida_Nunooyama_Kofun-2%2C_zenkei.jpg",6016,4000],["c:8/8a/Yanaida_Nunooyama_Kofun%2C_zenpoubu.jpg",6016,4000],["c:c/c2/Yanaida_Nunooyama_Kofun%2C_zenkei-1.jpg",6016,4000],["c:d/df/Yanaida_Nunooyama_Kofun%2C_rikkyo.jpg",6016,4000],["c:2/25/Yanaida_Nunooyama_Kofun%2C_kouhoubu.jpg",6016,4000],["c:1/16/Yanaida_Nunooyama_Kofun%2C_funcho.jpg",6016,4000],["c:0/0b/Shimosamuraizuka_Kofun_2.jpg",4608,3456,"前方後方墳"]]},{"id":"16_ozakai","n":"大境洞窟住居跡（日本初の洞窟遺跡調査）","yomi":"おおざかいどうくつじゅうきょあと","cat":"遺跡","rank":"A","y":-2500,"era":["jomon","yayoi","taisho"],"sh":"国指定史跡","ad":"氷見市大境（大境漁港近く・白山社）","st":"JR氷見線 氷見駅から海ぞいに北へ車で約20分。路線バスもあるが本数は少ない","la":36.9228,"lo":137.0302,"hook":"神社を建てかえようとしたら、洞窟の床から骨と土器が出てきた——日本の考古学が «地層を読む» ことを覚えた場所。","lead":"大境洞窟住居跡は、氷見市の海ぞいにある洞窟の遺跡です。1918年（大正7年）に神社の工事で見つかり、縄文時代から中世まで、6つの時代の層が重なっていることがわかりました。日本で初めて本格的に発掘された洞窟遺跡で、地層ごとに時代を調べる方法の出発点になりました。","story":["能登半島のつけ根、氷見の海岸を北へ。小さな漁港のそばの岩山に、ぽっかりと大きな口をあけた洞窟があります。中には白山社という神社がまつられていて、洞窟そのものがお宮のようです。1918年、この社殿を建てかえようと地面を掘ったとき、村人たちは手を止めました。«骨だ……それに、焼き物のかけらがたくさん出てくるぞ»。","知らせは東京に届き、東京帝国大学の人類学の研究者、柴田常恵らがやってきて本格的な調査が始まりました。彼らがしたことは、当時としては画期的でした。ただ宝探しのように掘るのではなく、土の色や質のちがいで «層» を一枚ずつ分け、それぞれの層から何が出たかを記録していったのです。","すると、洞窟の床はまるで «歴史のミルフィーユ» でした。いちばん下に縄文時代中期の層、その上に縄文後期・晩期、弥生、古墳時代、そして中世……と、6つの文化の層が重なっていたのです。«下にあるほど古い»——あたりまえに聞こえるこの原則を、実際の発掘で確かめ、時代の順番を組み立てる。それが日本で本格的に行われた最初期の例となりました。","なぜ人びとは何千年もこの洞窟を使いつづけたのでしょう? 海に近く、魚や貝がとれ、雨風をしのげる。岩の天井は、冬の日本海の荒れた風から家族を守ってくれたはずです。縄文の人、弥生の人、中世の人と、時代の違う人びとが、同じ «屋根» の下で火をたいていたのです。","見つかった遺物には、土器や陶磁器のほか、人の骨やけものの骨もありました。今も洞窟の中には白山社がまつられ、地元の人が手を合わせています。何千年分の暮らしと祈りが、同じ一つの岩屋に積み重なっている——それが大境洞窟のいちばんの不思議さかもしれません。"],"tl":[["縄文時代中期","洞窟が住まいとして使われはじめる（最下層）"],["縄文後期〜弥生・古墳時代","時代ごとに人びとが洞窟を利用し、層が重なる"],["中世","最上部の文化層が形成される"],["1918年（大正7年）","白山社の社殿改築の工事中に骨や土器が出土"],["大正時代","柴田常恵らによる調査。6つの文化層を確認"],["その後","国の史跡に指定され、保護される"]],"who":[["柴田常恵","東京帝国大学の人類学の研究者。層ごとに記録する調査を行った"],["大境の村人たち","社殿改築のときに遺物を見つけ、知らせた"],["洞窟に暮らした人びと","縄文から中世まで、時代の違う人たちがここで火をたいた"]],"deep":["大境洞窟の調査は «日本初の洞窟遺跡の発掘» であるとともに、層位（地層の上下関係）にもとづく発掘の «嚆矢（こうし＝はじまり）» と評価されています。日本考古学史の教科書に出てくる重要な場所です。","6つの文化層は、縄文時代中期から中世にわたります。一つの場所で数千年分の土器の変化を上下関係で確認できたことは、土器の «編年（年代の順番づけ）» を考えるうえで大きな意味がありました。","洞窟は海岸の岩が波にけずられてできた «海食洞» と考えられています。今は海岸線から少し離れていますが、かつては今より海に近かったとみられます。","洞窟の中に神社がまつられているのは、岩屋そのものを神聖な場所とみる古い信仰の形ともいえます。遺跡と信仰の場が重なっている点も、この史跡の特徴です。","氷見の海岸には、ほかにも岩陰や洞窟を利用した遺跡があり、能登半島の東側は古くから人が住みやすい海辺だったことがうかがえます。"],"look":["洞窟の大きな入口と、中にまつられた白山社","洞窟の天井や壁の岩はだ（波にけずられたあと）","史跡の説明板（層の重なりの図）","すぐ近くの大境漁港と富山湾のながめ"],"q":["大境洞窟で見つかった文化の層はいくつ?","6つ。縄文時代中期から中世までの層が重なっていました。"],"myth":"","img":["洞窟","柴田常恵","氷見市"],"wp":"大境洞窟住居跡","rel":{"ev":[],"grave":[]},"ph":[["c:3/3f/Oozakai_Cave.jpg",4820,3213,"大境洞窟住居跡"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:7/76/Ozakai_cave.jpg",2100,1499],["c:8/80/Cuevas_de_Acsibi%2C_Salta_%28Argentina%29.jpg",1024,768,"洞窟"],["c:4/49/Himi_port.jpg",6000,4000,"氷見市"]]},{"id":"16_kokubunji","n":"越中国分寺跡","yomi":"えっちゅうこくぶんじあと","cat":"寺社","rank":"A","y":750,"era":["nara","heian"],"sh":"県指定史跡","ad":"高岡市伏木一宮1丁目","st":"JR氷見線 越中国分駅から歩いて約14分。高岡駅から加越能バス «伏木一の宮» 下車、歩いて約3分","la":36.7979,"lo":137.0494,"hook":"大伴家持が国守として暮らした町に、聖武天皇の «国を守る寺» があった。いまは小さな薬師堂が、その記憶を守っている。","lead":"奈良時代、聖武天皇は国ごとに «国分寺» を建てるよう命じました。越中国の国分寺は、国府（今の県庁のような役所）があった高岡市伏木に建てられたと考えられています。建物は残っていませんが、今の薬師堂のあたりに土の壇や礎石と思われる石が残り、寺の跡とされています。","story":["741年、奈良の都。疫病や天災、反乱が続き、聖武天皇は心を痛めていました。«仏の力で国を守りたい»。そこで出されたのが、国ごとに僧の寺と尼の寺を建てよという «国分寺建立の詔（みことのり）» です。越中国でも、国府のあった伏木の台地に国分寺がつくられることになりました。","そのころ越中の国守として赴任していたのが、のちに『万葉集』の編者の一人とされる大伴家持です。家持は746年から約5年間、伏木の国守館で暮らし、200首をこえる歌をよみました。その歌のなかに、宴に招かれた僧 «玄勝»、«清見»、«恵行» といった人たちが出てきます。«この僧たちは、国分寺のお坊さんだったのでは?» と考える研究者もいます。","でも本当に家持のころ、国分寺はもう建っていたのでしょうか? 『万葉集』には «国分寺» という言葉そのものは出てきません。そこで、僧たちは近くの別の古い寺の僧だったとする説や、国分寺ができたのはもう少しあと（756年ごろ）とする説もあります。越中国分寺の始まりは、今も «諸説» のなかにあります。","寺の跡がどこかも、長いあいだ謎でした。«海の近くにあった»«いや海の中に沈んだ» という説まであったのです。昭和の調査で、今の薬師堂のまわりにある土の壇と、礎石らしい石が注目され、ここが国分寺の跡と考えられるようになりました。ただし伏木の台地では近代に瓦の原料の粘土が大量に掘られ、多くの遺構がけずられてしまいました。伽藍の並び方は、よくわかっていません。","今、境内には小さな薬師堂が立ち、地元では «国分堂» とも呼ばれています。ここには、明治の神仏分離のとき近くの気多神社から移された仏像なども大切にまつられています。華やかな七重塔はもうありませんが、台地の上に立てば、家持も見た富山湾と立山の景色が広がっています。"],"tl":[["741年","聖武天皇が国分寺建立の詔を出す"],["746〜751年","大伴家持が越中国守として伏木に在任"],["759年","砺波郡の田の地図に «国分金光明寺田» の記載"],["927年","『延喜式』で国分寺の運営費として稲3万束が定められる"],["1936〜1937年","堀井三友・上田三平らの調査で薬師堂付近が注目される"],["1965年","«越中国分寺跡» として富山県の史跡に指定"]],"who":[["聖武天皇","国分寺建立の詔を出した天皇"],["大伴家持","越中国守。伏木の国守館で多くの歌をよんだ"],["玄勝・清見・恵行","『万葉集』に出てくる僧。国分寺の僧だった可能性がいわれる"]],"deep":["国分寺の寺域は、薬師堂を中心に一辺2町（約216メートル）と推定されています。周辺には国分寺にちなむ地名が今も残っています。","薬師堂の境内には、土をつき固めた «版築» の土壇と、礎石と推定される石が6個残り、金堂の跡ではないかとみられています。","出土した瓦には、遠く三河国（愛知県）の国分寺・国分尼寺の瓦と似た特徴があり、瓦をつくる職人が国をこえて移動した可能性が指摘されています。","越中国分尼寺の場所はわかっていません。伏木台地の上で古い瓦が出る地点が候補とされています。","薬師堂には、南北朝時代ごろの木造文殊菩薩坐像（県指定文化財）など、もとは気多神社の本地仏だった仏像が移されています。明治の神仏分離の «ゆくえ» を物語る貴重な例です。","近くには越中国府の推定地とされる勝興寺、越中一宮の気多神社、北陸でも古いころの寺院跡とされる御亭角廃寺跡があり、伏木が古代越中の中心だったことがよくわかります。"],"look":["薬師堂（国分堂）の境内に残る土壇","礎石と推定される石","台地から見下ろす伏木の港と富山湾","近くの気多神社・勝興寺・高岡市万葉歴史館とあわせて歩く"],"q":["国分寺を国ごとに建てるよう命じた天皇は?","聖武天皇です。741年に詔を出しました。"],"myth":"『万葉集』の僧を国分寺の僧とみるか、創建年代をいつとするかは諸説。","img":["国分寺","大伴家持","勝興寺"],"wp":"越中国分寺","rel":{"ev":[],"grave":[]},"ph":[["c:3/38/Etchu_Kokubunji%2C_Yakushi-dou.jpg",6002,3978,"越中国分寺"],["c:3/3f/Emperor_Shomu.jpg",1876,3132],["c:3/3e/Sanj%C5%ABrokkasen-gaku_-_5_-_Kan%C5%8D_Tan%E2%80%99y%C5%AB_-_Ch%C5%ABnagon_Yakamochi.jpg",1000,1450],["c:a/a0/Bitchu_Kokubunji%2C_zenkei.jpg",6010,3990,"国分寺"],["c:5/5a/Fushiki_Shokoji_main_hall_ac.jpg",5863,3899,"勝興寺"]]},{"id":"16_keta","n":"気多神社（越中一之宮・高岡）","yomi":"けたじんじゃ","cat":"寺社","rank":"A","y":757,"era":["nara","muromachi"],"sh":"国の重要文化財（本殿）","ad":"高岡市伏木一宮1丁目","st":"JR氷見線 越中国分駅から歩いて約15分。高岡駅から加越能バス «伏木一の宮» 下車、歩いて約8分","la":36.8002,"lo":137.0443,"hook":"«一宮» はどちらだ? 射水神社との千年の «一宮争い» の片方の主役が、伏木の森に静かに立っている。","lead":"気多神社は、越中国の国府があった高岡市伏木にある神社で、越中国の «一宮（いちのみや＝その国でいちばん格式の高い神社）» の一つとされます。能登の気多大社から神さまを分けてまつったと考えられ、室町時代の特徴を残す本殿は国の重要文化財です。","story":["伏木の台地の上、こんもりとした森の中に、気多神社の本殿は立っています。正面の柱と柱の間が三つある «三間社流造（さんげんしゃながれづくり）»。太い木組みや、梁の先の «拳鼻（こぶしばな）» の形に、室町時代の職人の手わざが残っています。戦国の戦火をくぐりぬけて、ここまで残ったのは奇跡に近いことです。","この神社の始まりには謎があります。奈良時代、能登国はいったん越中国にふくまれ、そのあとまた分かれました。«能登の気多大社は、国府からは遠すぎる。国府の近くにお分けしておまつりしよう»——そうして757年ごろ、国府の近くに «新しい気多» がむかえられた、という説が有力です。","平安時代の終わりごろに書かれたとされる『白山之記』には、ドキッとする話がのっています。もともと越中の一宮は二上山の神（射水神社）だったのに、«新気多» ができると一宮争いがおこり、射水の神が力を失っているあいだに気多が一宮になった、というのです。国府のすぐそばにあったことが、気多神社に有利にはたらいたのかもしれません。","ところがふしぎなことに、奈良・平安の国の歴史書（六国史）には、射水神社や高瀬神社の名は何度も出てくるのに、気多神社は一度も出てきません。«まだ新しい神社だったからでは?»。延喜式（927年）の格付けをめぐっても、写本によって記述がちがい、どちらが本来の «名神大社» だったのか、学者の議論は今も続いています。","戦国時代には上杉謙信の兵火で焼けたと伝わりますが、本殿は難をのがれたとも記録されています。江戸時代には加賀藩の前田家が社殿を修理しました。境内には大伴家持をまつる大伴神社もあり、万葉の国守と一宮の神さまが、今もとなりあって伏木の町を見守っています。"],"tl":[["757年ごろ","能登が越中から分かれるころ、気多大社の神を分けてまつったとする説が有力"],["927年","『延喜式神名帳』に記載される"],["1532〜1555年（天文年間）","上杉勢の兵火にあうが、本殿は難をのがれたと伝わる"],["1645年","加賀藩主・前田利常が社殿を修復"],["1868年","神仏分離。別当寺の慶高寺は廃絶し、仏像は国分寺跡の薬師堂へ"],["1931年","本殿が旧国宝（のちの重要文化財）に指定"]],"who":[["大己貴命（おおなむちのみこと）","主祭神。大国主命の別名"],["大伴家持","越中国守。境内の大伴神社にまつられる"],["前田利常","加賀藩3代藩主。社殿を修復した"],["上杉謙信","戦国時代、その兵火で社が焼けたと伝わる"]],"deep":["越中国には «一宮» を名のる神社が4つ（射水神社・気多神社・高瀬神社・雄山神社）あります。時代や国府の移動によって一宮が入れかわった可能性があり、どれか一つに決めきれないのが越中の特徴です。","延喜式神名帳の写本のうち «九条本» などでは気多神社が名神大社、«出雲本» では射水神社が名神大社と書かれています。一般には前者が有力とされますが、射水神社こそ本来の名神大社とみる研究者もいます。","本殿は三間社流造で、木割（部材の太さ）が大きく、虹梁・拳鼻・手挟（たばさみ）の手法に室町時代の特質が残るとして、1931年に指定されました。","神仏習合の時代、気多神社の «本地仏» は仏像としてまつられていました。明治の神仏分離でそれらは国分寺跡の薬師堂に移され、木造文殊菩薩坐像などが今も残ります。","境内には «越中総社跡» と伝わる場所があります。総社は国司が国内の神々をまとめて拝むための神社で、国府の近くに置かれました。","毎年4月の春季例大祭では、高岡市の無形民俗文化財 «にらみ獅子» が奉納されます。"],"look":["室町時代の特徴を残す本殿（三間社流造）","大伴家持をまつる大伴神社","越中総社跡の伝承地","近くの越中国分寺跡（薬師堂）とあわせて歩く"],"q":["越中国で «一宮» を名のる神社はいくつある?","4つ。射水神社・気多神社・高瀬神社・雄山神社です。"],"myth":"創建年代（養老年間説など）や一宮争いの話は伝承・諸説をふくむ。","img":["気多大社","一宮","大伴家持","越中国分寺"],"wp":"気多神社 (高岡市)","rel":{"ev":[],"grave":[]},"ph":[["c:7/7c/Keta-taisha_keidai.JPG",3648,2736,"気多大社"],["c:6/6d/Zenkoku-ichinomiya.jpg",600,800,"一宮"],["c:3/3e/Sanj%C5%ABrokkasen-gaku_-_5_-_Kan%C5%8D_Tan%E2%80%99y%C5%AB_-_Ch%C5%ABnagon_Yakamochi.jpg",1000,1450,"大伴家持"],["c:3/38/Etchu_Kokubunji%2C_Yakushi-dou.jpg",6002,3978,"越中国分寺"]]},{"id":"16_takase","n":"高瀬神社（越中一之宮・南砺）","yomi":"たかせじんじゃ","cat":"寺社","rank":"A","y":780,"era":["nara","heian","edo"],"sh":"市指定史跡","ad":"南砺市高瀬","st":"JR城端線 福野駅から車で約10分。車が便利","la":36.5719,"lo":136.9483,"hook":"国の歴史書に6度も名が出る «高瀬神»。砺波平野の散居村のまん中で、越中いちばんの位を射水の神と分けあった。","lead":"高瀬神社は、南砺市にある越中国一宮の一つです。奈良・平安時代の国の歴史書に «高瀬神» として何度も登場し、位（神階）を上げられました。戦国時代に荒れましたが、江戸時代に加賀藩の前田家に守られ、今も砺波地方の人びとの心のよりどころになっています。","story":["砺波平野は、田んぼの中に家がぽつりぽつりと散らばる «散居村» で知られています。その平野の東のはし、大きな鳥居の先に高瀬神社の森があります。まつられているのは大己貴命（大国主命）。伝説では、北陸を平定した大己貴命が出雲へ帰るとき、«この地を守れ» と自分の魂をここにしずめていったのが始まりといわれます。","780年、奈良の朝廷の記録『続日本紀』に «越中国礪波郡の高瀬神を従五位下に叙す» と書かれました。これが高瀬神社が歴史に初めてはっきり登場した記事です。その後も795年、840年、854年、859年と位が上がり、ついには正三位に。そのたびに射水神社（二上神）と同じ日に同じ位を受けています。","«越中でいちばん位の高い神さまは、二人いた»。つまり高瀬の神と二上の神は、ライバルであり、ならんで越中を守るパートナーでもあったのです。854年には、高瀬神の神職が笏（しゃく）を持つことを許されました。これは伊勢神宮や大きな神社の神職にしか許されない名誉だったといいます。","平安時代のおわり、越中の国府が一時砺波郡に移ったため、そこから高瀬神社が一宮とされるようになったと考えられています。けれど戦国時代、越中は一向一揆と戦国大名の争いにまきこまれ、神社も荒れてしまいました。一部の神職は、ほかの神社へ移ったとも伝わります。","江戸時代、加賀藩主の前田家が高瀬神社をあつく敬い、手厚く保護しました。今の本殿・拝殿は、戦後に地元の人びとの寄付で建てられたものです。国の予算での再建が終戦で止まってしまったとき、«自分たちの一宮は自分たちで» と崇敬者が立ち上がったのです。社殿の新しさの裏には、そんな物語があります。"],"tl":[["780年","『続日本紀』に高瀬神が従五位下に叙されたと記される"],["859年","正三位に。射水神社と同時・同じ位"],["927年","『延喜式神名帳』で砺波郡の式内社7座の筆頭に"],["平安時代末","国府が一時砺波郡に移り、一宮とされるようになったと考えられる"],["戦国時代","戦乱で荒廃"],["江戸時代","加賀藩前田家の保護を受ける"],["1947〜1948年","崇敬者の手で本殿・拝殿が再建される"]],"who":[["大己貴命（大国主命）","主祭神。北陸平定の伝説をもつ"],["前田家（加賀藩）","江戸時代に神社をあつく保護した"],["崇敬者の人びと","戦後、寄付で社殿を再建した"]],"deep":["高瀬神の神階は780年・795年・840年・854年・859年と上がり、いずれも射水神社（二上神）と同時・同階でした。越中で二つの神が並び立っていたことを示すめずらしい記録です。","『延喜式』（927年）では «小社» ですが、砺波郡の式内社7座の筆頭に記されています。","神社の宝物として、出土地は不明ながら明治以前から伝わる «御物石器（ごぶつせっき）» があります。縄文時代晩期のもので長さ42.6センチ、御物石器としては日本最大級とされ、南砺市の文化財です。","境内の «なでうさぎ» は、大国主命と «因幡の白うさぎ» の神話にちなむもの。病んでいるところと同じ場所をなでると、ご利益があるといわれます。","戦前、国費による社殿再建が始まりましたが、1945年の終戦で工事は止まりました。1947年に本殿（流造）、1948年に拝殿（入母屋造）が崇敬者の手で完成しています。","近くには、高瀬の神が川舟をおりて足を洗ったという伝説の «御旅所跡» があり、市の史跡になっています。"],"look":["大きな鳥居と長い参道","本殿・拝殿と、唐破風の向拝殿","なでうさぎ","宝物殿（公開日を確認）","まわりに広がる砺波平野の散居村の景色"],"q":["高瀬神社と、いつも同じ日に同じ位を受けた越中の神社は?","射水神社（二上神）です。越中で最高位を分けあいました。"],"myth":"大己貴命が魂をしずめたという創建伝承、国府移転と一宮の関係は伝承・推定。","img":["砺波平野","散居村","大国主","射水神社"],"wp":"高瀬神社","rel":{"ev":[],"grave":[]},"ph":[["c:d/d4/Takase_Shrine_haiden.jpeg",1730,1127,"高瀬神社"],["c:7/71/Takase_Shrine_Torii_Haiden.jpg",3264,2448],["c:7/71/Takase_Shrine_Koreiden.jpg",3264,2448],["c:d/d4/Takase_Shrine_Big_Torii.jpg",3264,2448],["c:1/12/Takase_Shrine_Ema02.jpg",2791,2093],["c:c/ca/Takase_Shrine_torii.jpeg",2592,1944],["c:e/ed/Takase_Shrine_Ema01.jpg",2435,1826],["c:e/ee/Takase_Shrine_rabbit.jpg",2172,1628]]},{"id":"16_imizu","n":"射水神社（越中一之宮・高岡古城公園）","yomi":"いみずじんじゃ","cat":"寺社","rank":"A","y":1875,"era":["nara","heian","meiji"],"sh":"","ad":"高岡市古城（高岡古城公園内）","st":"JR・あいの風とやま鉄道 高岡駅から歩いて約15分","la":36.7485,"lo":137.0213,"hook":"二上山のふもとから、明治に «お城のあと» へお引っこし。泣いて神輿にすがった村人たちがいた。","lead":"射水神社は、越中国の一宮の一つで、もとは二上山のふもとにまつられた «二上神（ふたがみのかみ）» の社でした。明治8年（1875年）に、高岡城の本丸跡（今の高岡古城公園）へうつされました。奈良・平安時代には越中で最高の位を受けた、由緒ある神社です。","story":["高岡の町の北西にそびえる二上山。二つの峰をもつこの山は、古くから神の宿る山とされ、ふもとに «二上神» がまつられていました。奈良時代、越中国守の大伴家持も二上山をたたえる長い歌をよんでいます。国の歴史書には、二上神が高瀬の神と同じ日に同じ位を受けたことが何度も記され、越中でもっとも位の高い神の一柱でした。","中世から江戸時代にかけて、二上山には神と仏をいっしょにまつる寺（別当寺の養老寺）が栄え、山伏たちが大きな力をもちました。江戸時代、加賀藩の許しで山伏たちは越中の家々から «知識米» を集めて回ります。袋をかついだ姿は «ガンマンブロ» と呼ばれ、«泣く子もだまる» ほどおそれられたと伝わります。","明治になり、神と仏を分ける «神仏分離» が行われます。神社の神職は、長年つづいた社僧の支配から離れようと考えました。«二上の社地はせまく、町からも遠い。高岡城の本丸跡に社を移したい»。願いは国に認められ、明治8年（1875年）9月16日、遷座（せんざ＝神さまの引っこし）の日がやってきました。","その日、二上村の人びとは神輿にとりすがって号泣したといいます。先祖代々の «うちの神さま» が町へ行ってしまうのです。ご神体や宝物を天井裏や民家にかくしたという話まで伝わっています。のちに村人たちの願いで、もとの場所にも分社（二上射水神社）がおかれ、古い神事や獅子舞は今もそちらで受けつがれています。","高岡古城公園に移った射水神社は、明治33年（1900年）の高岡大火で社殿を焼失し、1902年に今の神明造の社殿が建てられました。城の堀と森にかこまれた境内は、いまや高岡の人びとの初詣やお宮参りの場。お城の神社となった越中の古い神さまは、町の人と山の人、両方の思いを受けとめてきたのです。"],"tl":[["780年","『続日本紀』に二上神が従五位下に叙されたと記される"],["859年","正三位に。高瀬神と同時・同階"],["927年","『延喜式神名帳』に記載される"],["1610年","加賀藩主前田利長が御供田を寄進"],["1875年9月16日","二上山麓から高岡城本丸跡へ遷座"],["1877年","二上山麓の旧社地に分社（二上射水神社）が置かれる"],["1900年","高岡大火で社殿焼失。1902年に再建"]],"who":[["瓊瓊杵尊（ににぎのみこと）","現在の祭神。神紋の «稲穂» はこの神にちなむ"],["大伴家持","越中国守。二上山をたたえる歌をよんだ"],["関守一","明治初めの権宮司。高岡城本丸跡への遷座を進めた"],["前田利長","加賀藩主。神社に田を寄進した"]],"deep":["祭神は今は瓊瓊杵尊とされますが、歴史的には射水の地をおさめた «伊彌頭国造（いみづのくにのみやつこ）» の祖神である二上神だったとされます。","延喜式神名帳の写本のうち «出雲本» では射水神社を名神大社と記しています。一般には誤記とされますが、こちらが古い形を残すとして、射水神社こそ本来の名神大社だったとみる説もあります。","平安時代末ごろ成立とされる『白山之記』には、射水の神と «新気多（気多神社）» の «一宮争い» の話が見えます。越中の一宮が一つに決まらない背景の一つです。","遷座の背景には、神仏分離をきっかけとする社僧と神職の対立があったとみられ、『高岡市史』もこの一件を廃仏毀釈の流れの中の出来事と考えています。","境内のある高岡古城公園は、前田利長が1609年に築いた高岡城の跡で、国の史跡です。堀の水面の割合が大きい «水濠の城» の姿がよく残っています。","『日本書紀』の天武天皇3年（674年）の記事を根拠に、1975年に «鎮座千三百年» の大祭が行われました。"],"look":["高岡古城公園（高岡城跡）の本丸跡に立つ神明造の社殿","神紋の «稲穂»","城跡の水濠と石垣","二上山麓の二上射水神社とあわせて訪ねると、遷座の物語がよくわかる"],"q":["射水神社は明治8年に、どこへうつされた?","高岡城の本丸跡（高岡古城公園）です。"],"myth":"養老元年（717年）の行基による別当寺開基は伝承で、疑問視する説が多い。遷座の日の «隠した» 話は伝承。","img":["高岡城","二上山 (富山県)","高瀬神社","気多神社"],"wp":"射水神社","rel":{"ev":[],"grave":[]},"ph":[["c:e/ec/Imizu-jinja_haiden.JPG",2352,1568,"射水神社"],["c:d/db/Precincts_of_Imizu_jinja.JPG",2352,1568],["c:2/24/Imizu_jinja_Gate.JPG",2352,1568],["c:6/61/TAKAOKA-FUTAGAMIYAMA-HIE-SHRINE.JPG",1920,1080],["c:a/af/Takaoka_Castle.jpg",4608,3456,"高岡城"],["c:0/00/Oyabe_River_and_Mt._Futagami_ac.jpg",5863,3899,"二上山 (富山県)"],["c:d/d4/Takase_Shrine_haiden.jpeg",1730,1127,"高瀬神社"],["c:b/b3/Keta-jinja_%28Takaoka%29%2C_shaden.jpg",5988,3956,"気多神社"]]},{"id":"16_nissekiji","n":"大岩山日石寺（磨崖不動明王）","yomi":"おおいわさんにっせきじ","cat":"寺社","rank":"A","y":1100,"era":["nara","heian"],"sh":"国指定史跡・国の重要文化財","ad":"中新川郡上市町大岩","st":"富山地方鉄道 上市駅から町営バス «大岩» 行きで約20分、終点下車すぐ（便は少ない）。北陸自動車道 滑川ICから車で約10分","la":36.6621,"lo":137.3911,"hook":"お堂の中にあるのは、仏像ではなく «岩そのもの»。高さ約3メートルの不動明王が、巨岩からぬっと姿をあらわす。","lead":"日石寺は «大岩不動» の名で親しまれる真言密宗の寺です。本尊は、大きな岩に直接ほりつけた «磨崖仏（まがいぶつ）» の不動明王で、平安時代後期の作と考えられ、国の重要文化財。寺伝では奈良時代に行基が開いたといいます。","story":["上市の町から山あいへ入ると、参道にそうめんの店が並ぶ門前町が見えてきます。石段を上って本堂に入ると、薄暗い堂内の奥に、巨大な岩の壁。そこに、怒りの表情の不動明王がほられています。«仏像をお堂に入れた» のではなく、«岩の仏をお堂でおおった»——それが日石寺の不思議なつくりです。","寺の言い伝えでは、奈良時代の725年、行基がこの地を訪れて岩に仏をほったのが始まりとされます。けれど美術の研究では、不動明王と二人の童子の像は、平安時代の後期につくられたと考えられています。«行基ほり» という伝説と、実際の年代。どちらもこの寺の歴史の一部です。","不動明王の像の高さは約2.8メートル。左右には矜羯羅童子（こんがらどうじ）と制吒迦童子（せいたかどうじ）がひかえ、さらに阿弥陀如来と、行基と伝わる僧の姿もほられています。やわらかい凝灰岩（ぎょうかいがん）の巨岩に、体の半分を浮き出させる «半肉彫り» で刻まれました。","この寺は何度も災難にあいました。南北朝時代には大風でお堂がたおれて仏も傷つき、修理されました。室町時代には戦火も受けています。そして1967年、本堂が火事で焼けてしまいます。«仏さまはご無事か!»——かけつけた人びとが見たのは、炎をくぐりぬけ、ほとんど傷のない不動明王の姿でした。岩の仏だからこそ、生きのびたのです。","境内には、六つの龍の口から水が落ちる «六本瀧» があり、大寒のころには白い装束の人びとが滝に打たれる寒修行が行われます。壁のない、中が丸見えのめずらしい三重塔も見どころ。修行を終えた人も観光客も、帰りには名物のそうめんをすする——千年の祈りと町のにぎわいが、同じ参道でつながっています。"],"tl":[["725年","寺伝で行基が開いたとされる"],["平安時代後期","不動明王二童子像が岩に刻まれる（推定）"],["1335年","不動堂が大風で倒れ、磨崖仏が大破"],["1342年","磨崖仏が修理される"],["1930年","«大岩日石寺石仏» として国の史跡に指定"],["1967年","本堂などが火災で焼失。磨崖仏はほとんど無事"],["1970年","不動堂が再建される"]],"who":[["行基","奈良時代の僧。寺伝で開基とされる"],["磨崖仏をほった仏師","平安時代後期の人とみられるが、名は伝わらない"],["寒修行の人びと","大寒に六本瀧で滝行をする信者たち"]],"deep":["磨崖仏は不動明王二童子・阿弥陀如来坐像・僧形坐像の計5体。不動明王と二童子は平安後期、阿弥陀と僧形像はのちに追加でほられたと考えられています。","«磨崖仏を覆う形で本堂が建つ» ため、雨風にさらされず保存状態が良いのが特徴です。屋外にある多くの磨崖仏と比べても、表情や彩色の痕跡が見やすいといわれます。","1930年に史跡、磨崖仏は国の重要文化財。史跡と重要文化財の «二重の指定» を受けている点も、この仏の価値の高さを示しています。","三重塔は壁がなく、中の柱や組物が丸見えです。建てるときにお金が足りず壁を省いたからだといわれ、それがかえってこの塔の個性になりました。","映画『劔岳 点の記』の撮影にも協力しており、立山・剱岳へ向かう山岳信仰の入口の一つとしての歴史も感じられます。","境内には町指定天然記念物のチャンチン（センダン科の木）もあります。"],"look":["本堂内の磨崖不動明王（岩に直接ほられた姿）","六本瀧（6つの龍頭から落ちる滝）","壁のない三重塔","門前のそうめん店が並ぶ参道"],"q":["日石寺の本尊の不動明王は、何にほられている?","大きな岩（凝灰岩）です。岩にほった仏を «磨崖仏» といいます。"],"myth":"行基開基は寺伝。三重塔の壁を省いた理由は伝承。","img":["磨崖仏","不動明王","行基","上市町"],"wp":"日石寺","rel":{"ev":[],"grave":[]},"ph":[["c:4/40/%E5%A4%A7%E5%B2%A9%E5%B1%B1.jpg",1973,1329,"日石寺"],["c:6/66/Usuki_sekibutsu_furuzono_dainichi_1.jpg",1600,1200,"磨崖仏"],["c:a/a1/Fud%C5%8D_My%C5%8D%C5%8D.jpg",3433,5046,"不動明王"],["c:8/8d/Gyouki_1.jpg",400,300,"行基"],["c:d/da/Tsurugidake_20100127.jpg",2200,1800,"上市町"]]},{"id":"16_ashikuraji","n":"芦峅寺（立山信仰の宿坊村）","yomi":"あしくらじ","cat":"寺社","rank":"A","y":1700,"era":["heian","edo"],"sh":"","ad":"中新川郡立山町芦峅寺","st":"富山地方鉄道 立山線 千垣駅から歩いて約30分、または車。富山県［立山博物館］が拠点","la":36.5831,"lo":137.3925,"hook":"女性は立山に登れなかった時代、白い布の橋を目かくしで渡り、«あの世» を通って生まれ変わった村がある。","lead":"芦峅寺は、立山のふもとにある村で、江戸時代には立山に登る人たちが泊まる宿坊がたくさん並んでいました。ここの人たちは «御師（おし）» として全国をまわり、立山の絵を見せながら信仰を広めました。女性のための «布橋灌頂会（ぬのばしかんじょうえ）» という儀式でも知られています。","story":["常願寺川に沿って山あいへ入った静かな村、芦峅寺。ここはかつて、神と仏をいっしょにまつる «立山中宮» の門前でした。江戸時代、夏になると全国から «立山禅定（ぜんじょう）» と呼ばれる登拝の人びとが集まり、宿坊に泊まってから、地獄と極楽がある霊山・立山をめざしたのです。","冬、雪にとざされると、宿坊の衆徒たちは «御師» となって全国へ旅立ちました。背負っていたのは «立山曼荼羅»。燃える地獄、針の山、血の池、そして山の上の極楽浄土が描かれた大きな絵です。«このまま悪いことをすれば、立山の地獄に落ちますぞ。だが、お山に登れば救われる»。絵ときをしながらお札を配り、次の夏の参拝者をさそったのです。","けれど立山は女人禁制。女性は登ることができませんでした。«それならば、わたしたちはどうやって救われるの?»。その答えが «布橋灌頂会» です。女性たちは白装束で目かくしをし、閻魔堂で罪をざんげしたあと、白い布をしいた朱ぬりの布橋をゆっくり渡りました。橋はこの世とあの世の境。板の数は煩悩と同じ108枚とされます。","橋を渡った先の «姥堂（うばどう）»。暗い堂内でお経を聞き、やがて目かくしをとると、前の扉が開き、光の中に立山の峰々があらわれた——そんなしかけだったと伝わります。いったん «死んで» 生まれ変わる «擬死再生» の儀式でした。明治の廃仏毀釈で途絶えましたが、布橋は1970年に復元され、1996年に儀式が復活、今は地元の人たちが受けついでいます。","芦峅寺の住民の名字は «佐伯» と «志鷹（したか）» がほとんど。立山を開いたと伝わる佐伯有頼と、白い鷹の伝説にちなむといわれます。近代になると、この村から立山ガイドが次々に生まれ、«剱の文蔵» とよばれた佐伯文蔵のように山の達人として名を残した人もいます。祈りの村は、山を守る人びとの村でもあったのです。"],"tl":[["701年","佐伯有頼が立山を開いたと伝わる（開山伝説）"],["江戸時代","宿坊が並び、衆徒が御師として全国に立山信仰を広める"],["江戸時代後期","布橋灌頂会がさかんに行われる"],["1868年〜","神仏分離・廃仏毀釈で中宮寺は雄山神社となり、布橋灌頂会は途絶える"],["1872年","立山の女人禁制がとかれる"],["1970年","布橋が復元される"],["1996年","国民文化祭で布橋灌頂会が復活"]],"who":[["佐伯有頼（慈興上人）","立山を開いたと伝わる人物。村の «佐伯» 姓の由来とされる"],["芦峅寺の衆徒（御師）","立山曼荼羅を背負い、全国で絵ときをした"],["佐伯文蔵","«剱の文蔵» と呼ばれた近代の名ガイド"],["布橋を渡った女性たち","立山に登れない代わりに、儀式で極楽往生を願った"]],"deep":["«芦峅寺» はもともと雄山神社 中宮祈願殿の寺名で、 «中宮寺» とも呼ばれました。今は地名として残り、雄山神社（祈願殿）、閻魔堂、姥堂跡などが集まっています。","立山曼荼羅は現在40点以上が確認されているともいわれ、地獄・極楽・開山伝説などを1枚に描いた «絵ときの道具» です。富山県［立山博物館］で実物を見ることができます。","布橋灌頂会は、閻魔堂 → 布橋 → 姥堂という順路で、この世からあの世へ行き、また戻る構成です。2014年には、儀式を再現した実行委員会がサントリー地域文化賞を受けました。","姥堂にまつられた «姥尊（うばそん／おんばさま）» は、立山の山の神・女神的な存在として、女性たちの信仰を集めたとされます。","芦峅寺と並んで、常願寺川下流側の岩峅寺（いわくらじ）も立山信仰の拠点でした。両者は立山の支配権をめぐって争ったこともあります。","映画『劔岳 点の記』では、立山ガイド協会の会員が撮影を支えました。明治の測量隊を案内した山の男たちの系譜が、今も続いています。"],"look":["布橋（朱ぬりの欄干の橋）","閻魔堂","姥堂跡と遙望館","雄山神社 中宮祈願殿","富山県［立山博物館］の立山曼荼羅"],"q":["布橋の板の枚数108枚は、何の数と同じとされる?","人の «煩悩» の数です。"],"myth":"佐伯有頼の開山や、名字の由来は伝承。","img":["立山修験","雄山神社","立山"],"wp":"芦峅寺","rel":{"ev":[],"grave":[]},"ph":[["c:a/a9/Chuuguu-kiganden_Haiden.JPG",2352,1568,"芦峅寺"],["c:f/f0/20_Tateyama_from_Mikurigaike_1998-7-17.jpg",1280,854,"立山修験"],["c:c/cf/Mount_Tate_viewed_from_Midorigaike.jpg",6016,4000,"立山"]]},{"id":"16_tateyama","n":"立山（地獄谷と禅定登山）","yomi":"たてやま","cat":"伝承","rank":"A","y":701,"era":["asuka","heian","edo"],"sh":"","ad":"中新川郡立山町芦峅寺（室堂・雄山）","st":"立山黒部アルペンルートの室堂ターミナルが入口。雄山山頂へは一ノ越経由で歩いて片道2時間ほど（本格的な登山装備が必要）","la":36.5758,"lo":137.6197,"hook":"«越中の立山には地獄がある»——平安時代の人びとがおそれ、あこがれた、日本三霊山の一つ。","lead":"立山は、雄山・大汝山・富士ノ折立の3つの峰からなる標高3000メートル級の山で、富士山・白山とともに «日本三霊山» と呼ばれます。山の中に地獄と極楽があると信じられ、江戸時代には多くの人が «禅定登山» に訪れました。今も室堂の近くでは、火山のガスが噴き出す «地獄谷» が見られます。","story":["立山の開山には、こんな伝説があります。飛鳥時代の701年、越中国司・佐伯有若の子、有頼が、父の大切な白い鷹を追って山へ入りました。鷹をさがすうち、一頭の熊に出会い、矢を放ちます。手負いの熊を追って岩屋に入ると、そこにいたのは熊ではなく、胸に矢を受けた阿弥陀如来でした。«この山を開き、人びとを救え»——有頼は出家して慈興と名のり、立山を開いたといわれます。","平安時代になると、«立山には地獄がある» という話が都にまで広まりました。『今昔物語集』には、立山の地獄に落ちた女性が修行僧にめぐり会い、«父母に供養をたのんでほしい» と願う話がのっています。湯気がふき上がり、硫黄のにおいがたちこめ、何も生えない谷。そんな景色を見た人びとは、ここを本当に «あの世» の入口だと感じたのでしょう。","江戸時代、立山はたくさんの人が登る信仰の山になりました。ふもとの芦峅寺や岩峅寺で身を清め、地獄谷を見て罪をおそれ、頂上の雄山神社で極楽を願う——これが «立山禅定» です。加賀藩は室堂に参拝者のための小屋を置き、それが今の室堂小屋の前身になりました。室堂小屋は、山小屋として使われた建物としては日本最古とされ、国の重要文化財です。","«なぜ女性は登れなかったの?»。立山は長く女人禁制で、女性が行けるのは芦峅寺の姥堂までと定められていました。この決まりがとかれたのは明治5年（1872年）のこと。今では誰もがケーブルカーとバスで標高2450メートルの室堂まで行けますが、それはほんの50年ほど前（1971年のアルペンルート全通）からの景色なのです。","立山は «自然の力» の山でもあります。1858年の安政飛越地震では、立山カルデラの鳶山がくずれ、大量の土砂が常願寺川に流れこみました。その土砂をとめる砂防工事は今も続いています。そして山の上には、日本では数少ない現存する氷河も。地獄と極楽、災害と恵み。立山は昔も今も、人間の小ささを教えてくれる山です。"],"tl":[["701年","佐伯有頼（慈興）が立山を開いたと伝わる"],["平安時代","『今昔物語集』などに «立山地獄» の話が記される"],["1695年","加賀藩が室堂に参拝者の参籠所を置く"],["1858年","安政飛越地震で鳶山が崩れ、立山カルデラに大量の土砂"],["1872年","女人禁制がとかれる"],["1971年","立山黒部アルペンルート全通"],["1995年","室堂小屋が国の重要文化財に"]],"who":[["佐伯有頼（慈興上人）","白鷹と熊の伝説で知られる開山者"],["佐伯有若","有頼の父とされる越中国司。伝説の登場人物"],["芦峅寺・岩峅寺の衆徒","登拝者を案内し、立山曼荼羅で信仰を広めた"],["加賀藩","室堂に参籠所を置き、立山信仰を保護した"]],"deep":["山頂部の標高は、雄山3003メートル、大汝山3015メートル。雄山山頂には雄山神社の峰本社がまつられています。一般に «立山に登る» とは雄山に登ることを指すことが多いです。","地獄谷は現在の火山活動の中心で、噴気や温泉が見られます。火山ガスの濃度が高いため、遊歩道が立入規制されることがあり、訪れる前に最新の情報を確認する必要があります。","立山曼荼羅には、剱岳が «針の山» として描かれることが多く、険しい岩峰が地獄のイメージと結びついていました。その剱岳に明治40年、陸地測量部が登頂したときの話が『劔岳 点の記』です。","雄山の東側には御前沢氷河があり、2012年に日本雪氷学会などによって «現存する氷河» と確認されました。日本の氷河の存在が認められたのは、このころが初めてです。","«日本三霊山» は立山・富士山・白山。いずれも山岳信仰の中心で、立山は開山伝説と地獄信仰がとくに有名です。","室堂周辺には雷鳥（国の特別天然記念物）がすみ、ミクリガ池・ミドリガ池は古い火口に水がたまった火口湖です。"],"look":["室堂平の室堂小屋（日本最古の山小屋建築）","地獄谷の噴気（規制情報を確認のうえ展望地から）","ミクリガ池（火口湖）","雄山山頂の雄山神社峰本社","夏の雪渓と高山植物、雷鳥"],"q":["立山とともに «日本三霊山» と呼ばれる二つの山は?","富士山と白山です。"],"myth":"佐伯有頼の開山、白鷹と熊の話は伝説。開山年701年も伝承。","img":["立山修験","雄山神社","室堂","立山黒部アルペンルート"],"wp":"立山","rel":{"ev":[],"grave":[]},"ph":[["c:c/cf/Mount_Tate_viewed_from_Midorigaike.jpg",6016,4000,"立山"],["c:6/64/Tateyama_from_Raicho-zawa.JPG",4128,3096],["c:5/53/NDL-DC_1307351_Utagawa_Hiroshige_%E5%B1%B1%E6%B5%B7%E8%A6%8B%E7%AB%8B%E7%9B%B8%E6%92%B2%E8%B6%8A%E4%B8%AD%E7%AB%8B%E5%B1%B1_crd.jpg",4445,2878],["c:3/3e/Geum_pentapetalum_07.jpg",3244,2374],["c:f/f0/Tateyama-midagahara.JPG",3072,2304],["c:4/42/Tateyama-keshiki-kurobeko.JPG",3072,2304],["c:d/da/Oonanji-tsurugi-tateyama.jpg",3072,2304],["c:a/a6/Tsurugi-toyama_16-9_name.jpg",3872,2176]]},{"id":"16_zentokuji","n":"城端別院善徳寺","yomi":"じょうはなべついんぜんとくじ","cat":"寺社","rank":"A","y":1559,"era":["muromachi","azuchi","edo"],"sh":"","ad":"南砺市城端","st":"JR城端線 城端駅から歩いて約10分","la":36.5157,"lo":136.902,"hook":"寺が引っこしてきたら、町ができた。城端は、一つのお寺の «門前町» として生まれた。","lead":"城端別院善徳寺は、浄土真宗（真宗大谷派）の大きな寺院です。蓮如上人を開祖とあおぎ、いくつかの場所をへて戦国時代に城端へうつりました。城端の町はこの寺の門前町として発展し、今も祭りや行事の中心になっています。","story":["室町時代の中ごろ、浄土真宗の蓮如上人は越前の吉崎を拠点に北陸で教えを広め、門徒の数は爆発的に増えました。善徳寺の寺伝によれば、蓮如は加賀と越中の境の砂子坂（すなござか）に道場をつくるよう手配し、一族の蓮真にまかせました。これが善徳寺の始まりとされます。","けれど時代は戦国。加賀では守護と門徒が対立し、蓮真たちは越中へ移らざるを得なくなります。法林寺、山本、福光……。善徳寺は何度も場所を変えました。そして永禄2年（1559年）ごろ、城ヶ端の城主・荒木大膳の願いで城端へうつったというのが定説です。五箇山や飛騨の白川へつながる山の道の入口——城端は、門徒たちにとって大事な «交通の要» だったのです。","やがて織田信長と石山本願寺の «石山合戦»。本願寺が二つの派に分かれかけたとき、善徳寺は信長と最後まで戦おうとした教如（のちの東本願寺の祖）の側につきました。1582年、教如は善徳寺をたよって越中の山あいにも来たと考えられています。«この寺は、わしを見すてなかった»。のちの東西本願寺の分裂で、善徳寺は越中の «東» の代表となりました。","戦国がおわると、加賀藩の前田利長と良い関係をきずきます。1604年、利長は狩りの途中に善徳寺に2泊し、屋敷地を寄進したと伝わります。江戸時代中ごろには大きな本堂が建てられ（1759年完成）、寺の名声はますます高まりました。お寺に人が集まれば、門前に店や宿がならび、町がにぎわいます。こうして城端の町は育っていきました。","江戸時代の終わり、加賀藩主・前田斉泰の子、亮麿（すけまろ）が幼くしてこの寺の住職として入り、わずか4歳で亡くなりました。町の人びとは «すけまるさま» と呼んで長くしのんだといいます。毎年夏の «虫干法会» では寺宝が公開され、多くの参拝者でにぎわいます。寺と町が、何百年も一つの家族のようにくらしてきたのです。"],"tl":[["15世紀後半","蓮如の手配で砂子坂に道場がおかれ、蓮真が入ったと伝わる"],["16世紀前半","法林寺・山本・福光へと移転をくり返す"],["1559年","城ヶ端城主・荒木大膳の願いで城端へ移ったとされる（定説）"],["1580年","石山合戦の終わりに教如を支持する"],["1604年","前田利長が善徳寺に2泊し、屋敷地を寄進したと伝わる"],["1759年","本堂の再建が完成"],["1849年","前田斉泰の子・亮麿が入寺（1851年に4歳で死去）"]],"who":[["蓮如","本願寺8代。善徳寺が開祖とあおぐ"],["蓮真・実円","初期の善徳寺をささえた一族"],["教如","本願寺12代で東本願寺の祖。善徳寺をたよった"],["前田利長","加賀藩2代藩主。寺と交流し土地を寄進した"],["亮麿（達亮）","前田斉泰の子。幼くして住職となり早世"]],"deep":["善徳寺は蓮如を初代、蓮真を2代とかぞえますが、蓮真は «照護寺蓮真» と名のりつづけたため、実質的な初代は子の実円だったとみる見方もあります。","城端への移転時期には諸説があり、『城端善徳寺由緒略書』にもとづく1559年説が定説とされています。背景には、加賀・越前の国境封鎖で、北陸の門徒が五箇山〜飛騨白川を通らなければ畿内へ出られなかった事情があったと指摘されます。","善徳寺には前田利長からの礼状が12通伝わり、加賀藩との関係の深さを示しています。","1649年、越中で西本願寺派の中心だった井波の瑞泉寺が東本願寺派に転じると、善徳寺と瑞泉寺は同格として越中の東派寺院をまとめる体制になりました。","江戸時代中期、近江から来た住職・真応は俳句や絵にすぐれ、この時期に城端から多くの文化人が出たと評されます。","城端の町では、5月の城端曳山祭が有名で、ユネスコ無形文化遺産 «山・鉾・屋台行事» の一つに含まれています。寺の門前町としての町の力を今に伝える祭りです。"],"look":["大きな本堂（江戸時代中期に完成）","山門と境内の広さ","夏の虫干法会での寺宝公開","門前に続く城端の町並みと坂道"],"q":["善徳寺は本願寺が東西に分かれたとき、どちらの側についた?","東（のちの真宗大谷派・東本願寺）側。教如を支持しました。"],"myth":"蓮如による道場開設、利長の宿泊の話は寺伝・伝承。移転年は諸説。","img":["蓮如","教如","城端曳山祭","真宗大谷派井波別院瑞泉寺"],"wp":"善徳寺 (南砺市)","rel":{"ev":[],"grave":[]},"ph":[["c:6/68/Johana_zentokuji%28%E5%9F%8E%E7%AB%AF%E5%88%A5%E9%99%A2%E5%96%84%E5%BE%B3%E5%AF%BA%29.jpg",3264,2448,"善徳寺 (南砺市)"],["c:3/3c/Yamamoto_zentoku-ji%28%E5%B1%B1%E6%9C%AC%E5%96%84%E5%BE%B3%E5%AF%BA%E8%B7%A1%29.jpg",4032,3024],["c:8/83/Sunakozaka_zentokuji%28%E7%A0%82%E5%AD%90%E5%9D%82%E5%96%84%E5%BE%B3%E5%AF%BA%E8%B7%A1%29.jpg",3024,4032],["c:0/03/Kotoku-ji%28%E5%85%89%E5%BE%B3%E5%AF%BA%29.jpg",4032,3024],["c:3/30/Chigenji%28%E7%A6%8F%E5%85%89%E7%9F%A5%E6%BA%90%E5%AF%BA%29.jpg",4032,3024],["c:6/62/Zentokuji_in_Johana_Mugiya_Festival%28%E3%82%80%E3%81%8E%E3%82%84%E7%A5%AD%E6%99%82%E3%81%AE%E5%96%84%E5%BE%B3%E5%AF%BA%29.jpg",3901,2760],["c:c/cf/Zentokuji_hondo%28%E5%96%84%E5%BE%B3%E5%AF%BA%E6%9C%AC%E5%A0%82%29.jpg",3002,2252],["c:c/c7/Manpukuji_sanmon.JPG",2816,2112]]},{"id":"16_gokoku_hachiman","n":"埴生護国八幡宮（義仲の戦勝祈願）","yomi":"はにゅうごこくはちまんぐう","cat":"寺社","rank":"A","y":1183,"era":["heian","azuchi","edo"],"sh":"国の重要文化財（本殿・釣殿・拝殿及び幣殿）","ad":"小矢部市埴生","st":"あいの風とやま鉄道 石動駅から車で約10分","la":36.6668,"lo":136.852,"hook":"«平家を討つ力をお与えください»——倶利伽羅峠の決戦を前に、木曾義仲が願書をささげた八幡宮。","lead":"埴生護国八幡宮は、小矢部市の倶利伽羅峠のふもとにある神社です。1183年、源氏の木曾義仲が平家との決戦の前にここで戦勝を祈ったと伝わります。江戸時代はじめに建てられた本殿などは、国の重要文化財です。","story":["寿永2年（1183年）の春。信濃で兵をあげた木曾義仲は、北陸へ攻め上ってきた平家の大軍と向き合っていました。平家の総大将は平維盛。その数、10万騎ともいわれます。越中と加賀の国境、砺波山の倶利伽羅峠が、決戦の舞台となろうとしていました。","義仲は峠のふもと、埴生の八幡宮に陣をかまえます。«ここは八幡さま、源氏の守り神の社ではないか。なんと心強い»。『平家物語』は、義仲が書記役の覚明（かくめい）に願書を書かせ、八幡さまにささげたと語ります。すると、どこからか3羽の山鳩が飛んできて、源氏の白旗の上を舞った——八幡の使いの鳩があらわれた、と兵たちは奮い立ったといいます。","5月11日の夜、義仲軍は平家軍を倶利伽羅の谷へ追い落とし、大勝利をおさめました。«角に松明をつけた牛の群れを敵陣に放った» という «火牛の計» の話は有名ですが、これは『源平盛衰記』などに出てくる話で、本当にあったかどうかは疑う説もあります。いずれにせよ、この勝利で義仲は京へ攻め上る道を開いたのです。","境内の入口には、馬にまたがる義仲の像と、源氏の兵が鳩の案内で見つけたと伝わる湧き水 «鳩清水（はとしみず）» があります。のどをうるおした兵たちの姿が目にうかぶようです。石段をのぼると、朱色のあざやかな社殿が見えてきます。","その後も八幡宮は武将たちに大切にされました。佐々成政や前田利長が土地を寄進し、武田信玄の書状も社宝として伝わるといいます。今の本殿は慶長5年（1600年）、拝殿や釣殿は正保3年（1646年）の建築で、いずれも国の重要文化財。源平の決戦から江戸時代まで、武士たちの祈りがここに重なっています。"],"tl":[["718年","伝承による創建"],["1181年","源頼政の縁者・埴生弥太郎盛兼が平家方に追いつめられ自害したと史料にみえる"],["1183年5月","木曾義仲が倶利伽羅峠の戦いの前に戦勝を祈願したと伝わる"],["1183年5月11日","倶利伽羅峠の戦いで義仲が平家軍に大勝"],["1600年","本殿が建てられる"],["1646年","釣殿・拝殿及び幣殿が建てられる"]],"who":[["木曾義仲（源義仲）","戦勝を祈願し、倶利伽羅峠で平家を破った"],["覚明（大夫房覚明）","義仲の書記役。願書を書いたと『平家物語』が語る"],["平維盛","倶利伽羅峠で敗れた平家の総大将"],["佐々成政・前田利長","戦国〜江戸初めに社領を寄進した武将"]],"deep":["«義仲戦勝祈願書» は社宝として伝わります。『平家物語』の «木曾願書» の場面と結びつけて語られ、源平合戦の舞台を実感させる資料です。","«火牛の計» は『源平盛衰記』などにみえる話で、『平家物語』諸本には見えないものもあります。古代中国の田単の戦法をまねた後世の脚色とみる説もあります。","創建については、源頼政に近い埴生氏が京都（山城国）の石清水八幡宮から八幡神を勧請したのではないか、という説があります。","重要文化財の社殿は、本殿（1600年）、釣殿・拝殿及び幣殿（1646年）。拝殿と本殿を «釣殿» でつなぐ構成は、この地方の神社建築を考えるうえで貴重です。","境内の石段は、蓮沼城主・遊佐慶親の寄進と伝わります。戦国時代の越中の武将の信仰も刻まれています。","近くの倶利伽羅峠には、源平の古戦場として «火牛の像» や猿ケ馬場の平家本陣跡などが残り、あわせて歩くと戦いの地理がよくわかります。"],"look":["木曾義仲の騎馬像","鳩清水（名水）","長い石段と朱色の社殿（重要文化財）","近くの倶利伽羅峠古戦場"],"q":["義仲が願書をささげたとき、飛んできて白旗の上を舞ったと伝わる鳥は?","山鳩（3羽）です。八幡神の使いとされます。"],"koji":[{"w":"火牛の計","m":"牛の角に松明をつけて敵陣に放つ作戦。倶利伽羅峠の話として有名だが、史実かどうかは疑問視されている"}],"myth":"義仲の祈願と山鳩の話は軍記物語による。火牛の計は史実性に疑問。718年創建は伝承。","img":["倶利伽羅峠の戦い","源義仲","倶利伽羅峠"],"wp":"護国八幡宮","rel":{"ev":[],"grave":[]},"ph":[["c:8/82/Hanyu_Gokoku_Hachiman-gu_Shrine.jpg",3417,2026,"護国八幡宮"],["c:c/c6/Hanyu_Gokoku_Hachiman-gu_Shrine_Hatoshimizu.jpg",3090,2073],["c:c/c6/Battle_of_Kurikaradani_Kassen_Zu.jpg",8498,4293,"倶利伽羅峠の戦い"],["c:2/27/Minamoto_no_Yoshinaka.jpg",843,767,"源義仲"]]},{"id":"16_toshinaga_bo","n":"前田利長墓所（高岡）","yomi":"まえだとしながぼしょ","cat":"墓所","rank":"A","y":1646,"era":["edo"],"sh":"国指定史跡（加賀藩主前田家墓所）","ad":"高岡市関町","st":"JR・あいの風とやま鉄道 高岡駅（瑞龍寺口）から歩いて約20分。瑞龍寺から八丁道を歩いて東へ約870メートル","la":36.7378,"lo":137.023,"hook":"高さ11メートルをこえる巨大な墓標。弟が兄のためにつくった、戦国武将の墓としては全国でも最大級の墓所。","lead":"前田利長は加賀藩の2代藩主で、高岡の町を開いた人です。利長が亡くなって33年目の1646年、あとをついだ弟の利常が、兄の冥福を祈ってこの墓所をつくりました。堀にかこまれた豪壮な墓は武将の墓として全国的にもめずらしく、国の史跡になっています。","story":["慶長14年（1609年）、前田利長は富山城が火事で焼けたのをきっかけに、関野と呼ばれた野原に新しい城と町をつくりました。これが高岡です。しかしそのわずか5年後の1614年、利長は病に苦しんだすえ、53歳（数え年）で亡くなりました。その死を深く悲しんだのが、腹ちがいの弟で養子として家をついだ3代藩主・利常でした。","利長には子がありませんでした。兄から加賀百万石をたくされた利常は、兄への恩を生涯忘れなかったといわれます。兄の33回忌にあたる正保3年（1646年）、利常は高岡に壮大な墓所を築きました。さらに菩提寺として瑞龍寺（今の国宝）を整え、二つを «八丁道» というまっすぐな道で結びました。","墓所の中心にあるのは、戸室石（とむろいし）でつくった三段の壇と、その上に立つ花崗岩の «笠塔婆（かさとうば）» 型の墓標です。墓全体の高さは約11.75メートル、墓標だけでも約8メートル。«なぜこんなに大きいの?» と思わずにはいられません。そこには、兄への感謝と、前田家の力を天下に示すという思いがこめられていたと考えられています。","じつはこの墓所、ただのお墓ではなかったともいわれます。江戸時代の古い絵図には、墓のまわりに二重の堀がめぐらされたようすが描かれ、いざというときには高岡を守る砦としての役割も考えられていたとみられます。2007年の調査では、つくられた当初の墓所の広さが約3万3000平方メートルもあったことがわかりました。今残る広さのおよそ3倍です。","ふだん、墓標のある内側の区域には入れません。けれど利長が高岡に入城したと伝わる9月13日には «前田利長公顕彰祭» が行われ、特別に内側が公開されます。また6月には、利長の恩をしのぶ金屋町の «御印祭» にあわせ、子どもたちが墓前で «弥栄節（やがえふ）» を踊ります。400年以上たった今も、高岡の人びとは «町の生みの親» を忘れていないのです。"],"tl":[["1609年","前田利長が高岡城を築き、高岡の町を開く"],["1614年","利長が高岡で死去"],["1646年","利常が利長の33回忌に墓所を造営"],["1965年","富山県の史跡に指定"],["2007年","発掘・レーダー探査で当初の規模や外堀を確認"],["2009年","金沢・野田山の墓所とともに «加賀藩主前田家墓所» として国史跡に"],["2015年","日本遺産の構成文化財に"]],"who":[["前田利長","加賀藩2代藩主。高岡の町を開き、ここに眠る"],["前田利常","3代藩主。利長の異母弟で養子。墓所と瑞龍寺を整えた"],["前田利家","利長の父。加賀藩の祖"],["金屋町の人びと","御印祭で利長の遺徳をしのび、墓前で踊りを奉納する"]],"deep":["墓所の諸元：墓碑全体の高さ約11.75メートル、墓碑の一辺15.5メートル、笠塔婆型墓標の高さ約8.0メートル、三重の墓壇は約250平方メートル、大灯籠の高さ約6.8メートル。","造営当初の約3万3000平方メートルという面積は、前田家の古文書にある «1万坪» という記述とも合います。今残るのは約1万平方メートルで、外郭の多くは中学校のグラウンドやテニスコートになっています。","2007年の調査で、墓碑の土台の規模が金沢市の野田山にある前田家歴代墓所と同じ «造墓原理» でつくられていることがわかりました。","墓所の正面口は南西にあり、八丁道で約870メートル先の菩提寺・瑞龍寺と向かい合っています。墓所と寺を一直線で結ぶ «都市の軸» をつくったところに、利常の演出力がうかがえます。","墓標の台座に使われた戸室石は、金沢城の石垣にも使われた金沢近郊の石です。","瑞龍寺の仏殿・法堂・山門は国宝で、利長の菩提を弔う寺として利常が整えました。墓所と瑞龍寺はセットで訪れたい場所です。"],"look":["笠塔婆型の巨大な墓標と三段の墓壇（外から見学）","まわりの石柵と堀","瑞龍寺へまっすぐのびる八丁道","9月13日の顕彰祭の日は内側の公開あり"],"q":["前田利長墓所をつくったのは誰?","弟で3代藩主の前田利常です。兄の33回忌（1646年）につくりました。"],"myth":"砦としての役割は古図からの推定。","img":["前田利長","前田利常","瑞龍寺 (高岡市)","高岡城"],"wp":"前田利長墓所","rel":{"ev":[],"grave":[]},"ph":[["c:d/df/Maedatoshinagakoubosho2.jpg",2272,1704,"前田利長墓所"],["c:0/03/Maedatoshinagakoubosho.JPG",2272,1704],["c:6/68/Maeda_Toshinaga.jpg",354,396,"前田利長"],["c:b/b9/Maeda_Toshitsune.png",1294,1725,"前田利常"],["c:7/77/Zuiryuji_Temple_2010-08-29_01.jpg",4320,3240,"瑞龍寺 (高岡市)"],["c:a/af/Takaoka_Castle.jpg",4608,3456,"高岡城"]]},{"id":"16_yamachosuji","n":"山町筋（高岡の土蔵造りの町並み）","yomi":"やまちょうすじ","cat":"町","rank":"A","y":1900,"era":["edo","meiji"],"sh":"国の重要伝統的建造物群保存地区","ad":"高岡市木舟町・小馬出町・守山町ほか","st":"万葉線 片原町停留場・坂下町停留場から歩いてすぐ。高岡駅から歩いて約10分","la":36.7476,"lo":137.0121,"hook":"火事で町の6割が焼けた高岡。商人たちは «もう燃えない家を» と、黒い土蔵の町をつくりあげた。","lead":"山町筋は、高岡の中心にある、明治時代の土蔵造りの家が並ぶ通りです。«山町» とは、高岡御車山祭の山車（やま）をもつ10の町のこと。1900年の大火のあと、燃えにくい土蔵造りで町が建て直され、今は国の重要伝統的建造物群保存地区になっています。","story":["1609年、前田利長は高岡の町を開き、北陸道の道筋を城下の中に引きこみました。人が通れば商売が生まれます。利長は町に «御車山（みくるまやま）» をあたえたと伝わり、それを持つ町が «山町» と呼ばれるようになりました。今も5月1日の御車山祭では、豪華な7基の山車がこの通りを練り歩きます。","ところが1614年に利長が亡くなり、翌年には幕府の «一国一城令» で高岡城は廃城に。家臣たちは金沢へ引きあげ、町はさびれかけました。«このままでは高岡は消えてしまう»。3代藩主・利常は町の人が出ていくのを禁じ、米や塩の蔵を置き、布の検査を高岡で行わせるなど、商人の町として生まれ変わらせたのです。","明治33年（1900年）6月、大火事が高岡をおそいました。町の約6割が焼け、山町筋の家もほとんどが焼けてしまいます。そのなかで、もともと土蔵造りだった2軒だけが焼け残りました。«見ろ、土蔵なら燃えないのだ»。商人たちは、県が出していた建築のきまりにしたがい、分厚い土かべの土蔵造りで家を建て直しました。","できあがった町並みは、ただの «和風» ではありません。黒い漆喰のかべ、観音開きの土の扉、そして軒をささえる柱には、高岡の鋳物でつくった西洋風の鉄柱。葉の模様（アカンサス）がついたものもあります。となりとの間には赤レンガの防火壁。明治の商人たちの «最新の防火技術» と «おしゃれ» が合わさった町なのです。","昭和の終わりごろ、古い土蔵がこわされはじめると、住民たちが立ち上がり «土蔵造りのある山町筋まちづくり協議会» をつくりました。2000年には国の重要伝統的建造物群保存地区に選ばれ、電線の地中化も進みました。重要文化財の菅野家住宅や、土蔵造りのまち資料館では、家の中まで見ることができます。"],"tl":[["1609年","前田利長が高岡を開き、北陸道を城下に通す"],["1615年","一国一城令で高岡城が廃城"],["1620年","前田利常が町人の転出を禁じ、商工業の町へ"],["1900年6月","高岡大火。町の約6割、山町筋の多くが焼ける"],["明治後期〜昭和初期","土蔵造りの家が建て並ぶ"],["2000年12月","国の重要伝統的建造物群保存地区に選定"],["2015年","日本遺産の構成文化財に"]],"who":[["前田利長","高岡を開き、御車山を町にあたえたと伝わる"],["前田利常","廃城後の高岡を商人の町として育てた"],["菅野家","山町筋を代表する商家。住宅は国の重要文化財"],["まちづくり協議会の住民たち","町並みの保存に取り組んだ"]],"deep":["重要伝統的建造物群保存地区は、小馬出町・守山町の全域、木舟町のほぼ全域などの約5.5ヘクタール。伝統的建造物として建築物96棟などが特定されています。","土蔵造りの家は2階建ての切妻造り・黒瓦葺きが基本。2階の観音開きの土扉を全部開くと、となりの家の扉とぴったり重なるように作られた家もあります。","軒の鋳物の鉄柱や、庇の天井の鏝絵（こてえ）の飾りなど、細部に «鋳物の町・高岡» らしさが出ています。","御車山は、豊臣秀吉が使った御所車を前田利長が町民にあたえ、各町が手を加えたものと伝わります。高岡御車山祭はユネスコ無形文化遺産 «山・鉾・屋台行事» の一つです。","通りには、赤レンガ造りの銀行建築など、洋風の建物もまじり、明治から昭和初期の商業都市・高岡の豊かさがうかがえます。","1889年の市制施行で、高岡は全国31の最初の «市» の一つになりました。北陸でも有数の商工業都市だった証拠です。"],"look":["黒漆喰の土蔵造りの家並み","軒をささえる鋳物の鉄柱","赤レンガの防火壁","菅野家住宅（重要文化財・有料公開）","高岡市土蔵造りのまち資料館（旧室崎家住宅）"],"q":["1900年の大火で焼け残ったのは、どんな造りの家だった?","もともと土蔵造りだった2軒でした。これが土蔵の町づくりのきっかけになりました。"],"myth":"御車山が秀吉の御所車に由来するという話は伝承。","img":["高岡御車山祭","高岡城","重要伝統的建造物群保存地区","高岡市"],"wp":"山町筋","rel":{"ev":[],"grave":[]},"ph":[["c:6/6e/Town_Of_Storehouse_Making_%E5%9C%9F%E8%94%B5%E9%80%A0%E3%82%8A%E3%81%AE%E7%94%BA%E4%B8%A6%E3%81%BF_%E9%AB%98%E5%B2%A1%E5%B8%82%E6%9C%A8%E8%88%9F%E7%94%BA_-_panoramio.jpg",2832,2128,"山町筋"],["c:e/e4/%E5%9C%9F%E8%94%B5%E9%80%A0%E3%82%8A%E3%81%AE%E7%94%BA%E4%B8%A6%E3%81%BF_-_panoramio_%284%29.jpg",4752,3168],["c:4/41/%E5%9C%9F%E8%94%B5%E9%80%A0%E3%82%8A%E3%81%AE%E7%94%BA%E4%B8%A6%E3%81%BF_-_panoramio_%282%29.jpg",4752,3168],["c:7/77/Dozodukuri_no_Machi_Museum.JPG",3648,2736],["c:8/84/Yamacho-Suji_at_Kommadashi.jpg",2304,1728],["c:0/07/Sugano_House_1-1.jpg",2272,1704],["c:0/05/Toyama_Bank_Head_Office.jpg",1455,1080],["c:b/b2/%E9%AB%98%E5%B2%A1%E5%B8%82%E8%A1%97%E3%81%AE%E9%A2%A8%E6%99%AF_-_panoramio.jpg",4752,3168,"高岡御車山祭"]]},{"id":"16_kanayamachi","n":"金屋町（高岡鋳物発祥の町）","yomi":"かなやまち","cat":"産業","rank":"A","y":1611,"era":["edo","meiji"],"sh":"国の重要伝統的建造物群保存地区","ad":"高岡市金屋町","st":"JR・あいの風とやま鉄道 高岡駅から歩いて約20分。万葉線 片原町停留場から歩いて約10分","la":36.7515,"lo":137.0075,"hook":"7人の鋳物師から始まった町。石だたみには銅がちりばめられ、千本格子の «さまのこ» の奥から、今も金属の音が聞こえる。","lead":"金屋町は、加賀藩2代藩主・前田利長が1611年に7人の鋳物師（いもじ）を呼びよせて開いた町で、高岡の鋳物（銅器）づくりの発祥地です。千本格子の家と石だたみの通りが残り、«鋳物師町» として初めて国の重要伝統的建造物群保存地区に選ばれました。","story":["1611年、高岡の町を開いたばかりの前田利長は考えました。«町を栄えさせるには、ものづくりが要る»。そこで砺波郡の西部金屋村から、金森弥右衛門ら7人の鋳物師を呼びよせ、千保川をはさんで城下の向かい側に土地をあたえました。鋳物は火を使います。火事の心配がある仕事場を、川の向こうに置いたのです。","鋳物師たちがあたえられた土地は約5000坪。ひとりひとりの敷地は、通りから奥へ細長くのびる «短冊形» でした。表に住まい、中庭をはさんで土蔵、いちばん奥に作業場。«作業場から火が出ても、母屋まで燃え広がらないように» という工夫です。鋳物師たちは税の免除や関所の自由通行などの特権も認められ、利長への恩を代々語りついできました。","はじめに作ったのは、鍋や釜などの暮らしの道具でした。やがて江戸時代の終わりごろから、銅器づくりがさかんになります。仏具、花びん、置物……。高岡の銅器は全国に知られるようになり、江戸時代中期には鋳物師の数が日本一になったともいわれます。明治以降は大きなニシン釜、各地の銅像や梵鐘、そして高岡大仏まで、この町の技が生み出しました。","金屋町を歩くと、家々の表には細かい縦格子がびっしり。地元では «さまのこ» と呼ばれる千本格子です。足もとの石だたみをよく見てください。ところどころに銅の板がうめこまれ、光っています。«ここは鋳物の町だよ» と、道そのものが語っているのです。","毎年6月19日・20日には、利長の恩をしのぶ «御印祭（ごいんさい）» が行われ、町の人びとが «弥栄節（やがえふ）» を踊りながら町を流します。秋には «金屋町楽市inさまのこ» が開かれ、町家に工芸作品が並びます。400年の職人の町は、今も新しい作り手たちを迎え入れながら生きているのです。"],"tl":[["1609年","前田利長が高岡を開く"],["1611年","利長が7人の鋳物師を金屋町に呼びよせる"],["江戸時代中期","鋳物師の数が日本一になったといわれる"],["天保・弘化のころ","銅器の生産が始まったとされる"],["明治時代","ニシン釜・銅像・梵鐘などを製作"],["1989〜1991年度","銅をちりばめた石だたみの道が整備される"],["2012年12月","鋳物師町として初の国の重要伝統的建造物群保存地区に"]],"who":[["前田利長","金屋町を開き、鋳物師を保護した"],["金森弥右衛門","呼びよせられた7人の鋳物師の一人"],["高岡の鋳物職人たち","鍋釜から銅器・銅像まで、技をつないできた"]],"deep":["鋳物師たちの宅地は «拝領地» «御印地» と呼ばれ、東西50間・南北100間（約5000坪）の土地があたえられました。","鋳物師たちは «御綸旨（ごりんじ）» を代々受けつぐ、諸役を免除される、関所の通行が自由などの特権を、明治維新まで持っていたとされます。","重要伝統的建造物群保存地区は金屋町と金屋本町の一部、約6.4ヘクタール。伝統的建造物は113棟とされています。","町の中の «高岡市鋳物資料館» には、鋳物の道具や製品が集められ、1561点が «高岡鋳物の製作用具及び製品» として国の登録有形民俗文化財になっています。","2014年には保存地区内で火事があり、伝統的建造物を含む家が焼けました。石だたみ沿いの千本格子の家への延焼はまぬがれましたが、«火とともに生きる町» の防災の大切さを改めて示しました。","高岡銅器は国の伝統的工芸品で、全国の銅像や梵鐘の多くを手がけてきたといわれます。"],"look":["千本格子 «さまのこ» の家並み","銅がちりばめられた石だたみ","高岡市鋳物資料館","千保川沿いの金屋緑地公園（鋳物工場の跡）"],"q":["金屋町を開いたとき、前田利長が呼びよせた鋳物師は何人?","7人です。1611年、砺波郡西部金屋村から呼びよせました。"],"myth":"«鋳物師の数が日本一» はいわれている話。","img":["高岡銅器","鋳物","前田利長","重要伝統的建造物群保存地区"],"wp":"金屋町 (高岡市)","rel":{"ev":[],"grave":[]},"ph":[["c:4/4b/Takaoka-shi_Kanayamachi%2C_Toyama%2C_historic_industrial_town%28metal%29.JPG",6016,4016,"金屋町 (高岡市)"],["c:d/dc/Takaoka_Daibutsu_2011-07-15_01.jpg",3240,4320,"高岡銅器"],["c:6/68/Maeda_Toshinaga.jpg",354,396,"前田利長"]]},{"id":"16_takaoka_daibutsu","n":"高岡大仏","yomi":"たかおかだいぶつ","cat":"寺社","rank":"A","y":1933,"era":["kamakura","edo","showa"],"sh":"高岡市指定有形文化財","ad":"高岡市大手町（大佛寺）","st":"万葉線 坂下町停留場（高岡大仏口）から歩いて数分。高岡駅から歩いて約10分","la":36.7456,"lo":137.0172,"hook":"3度も焼けた大仏が、4度目に選んだのは «燃えない体»。鋳物の町の職人たちが、青銅で守り神をつくりあげた。","lead":"高岡大仏は、高岡市の大佛寺にある銅製の阿弥陀如来の坐像です。昔は木の大仏でしたが、何度も火事で焼けたため、1907年から高岡銅器の職人たちが力を合わせて銅でつくり直し、1933年に完成しました。奈良・鎌倉と並ぶ «日本三大仏» を名のっています。","story":["大仏の歴史は、鎌倉時代にさかのぼるといわれます。1221年、源義勝という人が二上山のふもとに高さ約4.8メートルの木の大仏を建てたと伝わります。1609年、前田利長が高岡の町を開くと、大仏も城下にうつされました。けれど、その大仏はのちに焼けてしまいます。","江戸時代の1745年、極楽寺の住職・等誉上人の手で、高さ約9.7メートルの金色の木造大仏が再建されました。ところが1821年にまた焼失。1841年に再び建てられますが、明治33年（1900年）、町の6割を焼いた高岡大火で三たび灰になってしまいました。«なぜ、うちの大仏さまばかり焼けるのか»。町の人びとの嘆きが聞こえてきそうです。","«もう木ではだめだ。燃えない大仏をつくろう»。そう願い出たのが松木宗左衛門でした。高岡は、金屋町の鋳物師以来300年の «鋳物の町»。その職人たちの技を集めれば、銅の大仏がつくれるはずです。1907年、工事が始まりました。とはいえ巨大な仏像を銅で鋳るのは簡単ではありません。部分ごとに鋳造し、組み上げる作業が長い年月をかけて続けられました。","26年後の1933年5月、ついに銅の大仏が完成し、開眼供養が行われました。同じころ高岡を訪れた歌人の与謝野晶子は、この大仏を «鎌倉の大仏より一段と美男» とほめたと伝わります。すっきりとした目鼻立ちは、今も «イケメン大仏» として親しまれています。","大仏の台座の中には回廊があり、地獄絵などが展示されています。そして中央の部屋には、1900年の大火で焼けた木造大仏の頭部がまつられています。焼けてしまった先代の大仏と、燃えない体で生まれ変わった今の大仏。二つが一つの場所で町を見守っているのです。"],"tl":[["1221年","源義勝が二上山のふもとに木造大仏を建てたと伝わる"],["1609年","高岡開町とともに大仏が城下へ移される"],["1745年","等誉上人が高さ約9.7メートルの木造大仏を再建"],["1821年","大仏が焼失（1841年再建）"],["1900年","高岡大火で木造大仏が焼失"],["1907年","松木宗左衛門の発願で銅造大仏の建立が始まる"],["1933年5月","銅造大仏が完成し開眼供養"],["1981年","高岡市指定有形文化財に"]],"who":[["源義勝","最初の木造大仏を建てたと伝わる人物"],["等誉上人","江戸時代に大仏を再建した極楽寺の住職"],["松木宗左衛門","銅造大仏の建立を発願した"],["与謝野晶子","大仏を «鎌倉大仏より美男» と評したと伝わる歌人"]],"deep":["«日本三大仏» は、江戸時代には奈良・鎌倉・京都の方広寺の大仏を指したとされます。方広寺の大仏が1973年の火事で失われたこともあり、今は高岡大仏がその一つを名のっています（ほかにも名のる大仏があります）。","高岡大仏は、小杉大仏・庄川大仏とともに «越中三大仏» の一つとされます。","大仏の後ろの円い光背は1958年に取りつけられました。1980年の補修のときには、大仏が今の場所へ約11メートル後ろに移されています。","建立には、高岡銅器の職人たちの技術が結集しました。明治以降、高岡では全国の銅像や梵鐘がつくられており、大仏はその技術の «見本» ともいえます。","最初の木造大仏の建立（1221年）については、伝承として語られている部分が多く、確かな史料は限られます。"],"look":["銅造の阿弥陀如来坐像と円い光背","台座の中の回廊と、焼けた木造大仏の頭部","端正な顔立ち（正面と横からくらべてみる）","万葉線の «高岡大仏口» の副駅名"],"q":["高岡大仏が木造から銅造になった理由は?","木造の大仏が何度も火事で焼けたからです。1900年の大火のあと、燃えない銅で再建されました。"],"myth":"1221年の創建、与謝野晶子の評は伝承。","img":["大仏","高岡銅器","与謝野晶子","阿弥陀如来"],"wp":"高岡大仏","rel":{"ev":[],"grave":[]},"ph":[["c:d/dc/Takaoka_Daibutsu_2011-07-15_01.jpg",3240,4320,"高岡大仏"],["c:7/74/Daibutsu_Temple_1-1.jpg",2272,1704],["c:e/e9/H%C5%8Dk%C5%8Dji_Daibutsu_Kaempfer.png",466,642,"大仏"],["c:7/72/Akiko_Yosano_younger.jpg",1449,2124,"与謝野晶子"],["c:5/5d/Kamakura_Budda_Daibutsu_front_1885.jpg",1536,2048,"阿弥陀如来"]]},{"id":"16_iwase","n":"岩瀬の廻船問屋森家（北前船の町）","yomi":"いわせのかいせんどいやもりけ","cat":"産業","rank":"A","y":1878,"era":["edo","meiji"],"sh":"国の重要文化財（旧森家住宅）","ad":"富山市東岩瀬町","st":"富山地方鉄道 富山港線 東岩瀬駅から歩いて約10分","la":36.757,"lo":137.228,"hook":"大阪から北海道まで、日本海を行き来した «動く総合商社» 北前船。その富で建てられた問屋の家が、港町に今も立つ。","lead":"岩瀬は富山港の近く、神通川の河口にひらけた港町です。江戸時代から明治にかけて «北前船» の寄港地として栄え、廻船問屋（船で商売する店）が立ち並びました。明治初めに建てられた森家は、その代表的な家として公開されています。","story":["春、大阪を出た船が、瀬戸内海をぬけ、下関をまわって日本海を北へ。途中の港で米や塩、酒、紙などを積み、北海道（蝦夷地）でニシンの肥料や昆布を積んで帰ってくる。これが «北前船» です。船主は運び賃をもらうのではなく、自分で品物を買って別の港で売る «買積み»。一航海で大もうけすることもあり、«動く総合商社» とも呼ばれました。","岩瀬の港にも、そんな船主や問屋たちが集まりました。«今年はニシンの値がいいぞ»«昆布を多めに積んでおけ»。問屋の店先では、船頭と商人の声がとびかったことでしょう。北前船で運ばれた北海道の昆布は、富山の食卓にも広がりました。富山の人が昆布をよく食べるのは、このころからの歴史があるからだといわれます。","大町通りに面して立つ森家は、明治11年（1878年）ごろに建てられた廻船問屋の家です。通りから見ると、細かい格子の落ち着いた表がまえ。でも一歩中に入ると、高い吹き抜けに太い梁がわたり、つやつやとした木の床や柱に、北前船でもうけた問屋の «本気» が見えてきます。","«なぜ見えにくいところにこそ、お金をかけたの?»。それは、ぜいたくをひけらかさない北陸の商人の心意気ともいわれます。表は質素に、中は立派に。土蔵や船の道具が残り、案内の人が家のつくりや北前船の商売の話をしてくれます。","明治の終わりになると、鉄道や蒸気船の時代が来て、北前船はしだいに姿を消しました。けれど岩瀬の町には問屋の家並みがよく残り、今は酒蔵やギャラリーもあるおしゃれな通りになっています。すぐ近くには、昭和に富山の町と港を結んだ富岩運河も。港町の «海の道» の記憶を、歩いてたどれる町です。"],"tl":[["江戸時代","北前船の寄港地として岩瀬の港がにぎわう"],["江戸時代後期〜明治前期","北前船の商売が最もさかんになる"],["1878年ごろ","廻船問屋森家の家屋が建てられる"],["明治後期","鉄道・汽船の発達で北前船がおとろえる"],["1935年","富岩運河が完成し、富山の町と港が水路で結ばれる"],["現在","旧森家住宅が国の重要文化財として公開されている"]],"who":[["森家","岩瀬の廻船問屋。北前船の商売で栄えた"],["北前船の船頭・水主（かこ）たち","日本海を行き来し、品物を運んだ"],["岩瀬の問屋・商人たち","港に集まる品物を売り買いした"]],"deep":["北前船は «西廻り航路» を使って大阪と北海道を結びました。18世紀に河村瑞賢が西廻り航路を整えたことが、日本海側の港町の発展につながりました。","北前船の最大の特徴は «買積み» 方式です。運賃をもらう «運賃積み» とちがい、品物の値段の差がもうけになるため、うまくいけば大きな利益、失敗や遭難で大損もある «ハイリスク・ハイリターン» の商売でした。","北前船が運んだ北海道の昆布は、富山の売薬商人の手で薩摩へ、さらに琉球を通じて中国へ渡ったという «昆布ロード» の話が知られます。売薬と昆布の結びつきについては研究者の議論もあります。","北前船でよく使われた大型の和船は «弁才船（べざいせん）» で、一本の大きな帆をもつのが特徴です。«千石船» とも呼ばれました。","岩瀬の町並みには、東岩瀬の «廻船問屋型町家» の特徴を残す家が多く、富山市が町並みの修景を進めてきました。"],"look":["旧森家住宅の吹き抜けと太い梁","通りに面した格子の表がまえ","大町・新川町通りの町並み","近くの岩瀬浜・富山港と富岩運河"],"q":["品物を自分で買って別の港で売る、北前船の商売のやり方を何という?","«買積み（かいづみ）» です。"],"myth":"«昆布ロード» の話は通説として語られるが、細部には議論がある。","img":["弁才船","富岩運河","西廻海運"],"wp":"北前船","rel":{"ev":[],"grave":[]},"ph":[["c:7/71/Kitamaebune_by_Iida_Yonezo_2.jpg",1024,768,"北前船"],["c:b/bf/Img%E8%BE%B0%E6%82%A6%E4%B8%B8.jpg",5170,3516],["c:f/fc/Kitamaekan01s3900.jpg",2500,3900],["c:c/c1/A_Kai-sen_ship%2C_Engaku-ji_temple_%28Kamakura%29%2C_1633.jpg",1103,713],["c:6/6a/%E5%8C%97%E5%89%8D%E8%88%B9%E4%B8%BB%E4%B9%85%E4%BF%9D%E9%82%B8.jpg",800,600],["c:1/18/Michinoku_Maru_01.jpg",533,800],["c:f/fa/Ueno_junks.jpg",2560,1980,"弁才船"],["c:9/96/Fugan_unga.JPG",1600,1066,"富岩運河"]]},{"id":"16_suganuma","n":"菅沼合掌造り集落（五箇山）","yomi":"すがぬまがっしょうづくりしゅうらく","cat":"町","rank":"A","y":1800,"era":["edo","meiji"],"sh":"国指定史跡（越中五箇山菅沼集落）・世界文化遺産","ad":"南砺市菅沼","st":"JR城端線 城端駅などから世界遺産バスで約40分、«菅沼» 下車","la":36.4035,"lo":136.8865,"hook":"川がぐるりと回りこむ小さな台地に、茅葺きの大屋根が9つ。雪の山里は、世界が認めた «手を合わせた家» の村。","lead":"菅沼集落は、南砺市五箇山にある合掌造りの村です。庄川が大きく曲がる内側の平らな土地に、急な茅葺き屋根の家が9棟ならびます。1995年、白川郷・相倉とともに «白川郷・五箇山の合掌造り集落» として世界文化遺産に登録されました。","story":["富山県のいちばん南西、岐阜県との境に近い五箇山。深い谷を庄川が流れ、冬には2メートルをこえる雪が積もります。その庄川が大きく «U» の字に曲がった内側、三方を川に守られた小さな台地に、菅沼集落はあります。まわりを山と川にかこまれた、まるで «かくれ里» のような場所です。","家々の屋根は、両手を合わせたような急な三角形。«合掌造り» と呼ばれます。なぜこんなに急な屋根なのでしょう? ひとつは、重い雪をすべり落とすため。もうひとつは、屋根裏を何層にも使うためです。広い屋根裏では蚕を飼い、糸をとりました。和紙づくり、そして火薬の原料となる «塩硝（えんしょう）» づくりも、この山里の大事な仕事でした。","五箇山は、交通が不便なため、加賀藩の流刑地にもされた土地です。けれど、閉ざされた山里だからこそ、古い暮らしや民謡が残りました。«こきりこ節» や «麦屋節» など、五箇山の民謡は今も歌いつがれています。平家の落人が住みついたという伝説も、この地には伝わっています。","合掌造りの屋根は、数十年に一度、ふきかえが必要です。一軒だけの力ではとてもできません。そこで村人総出で茅を運び、屋根にのぼってふく «結（ゆい）» の助け合いが行われてきました。«今年はあの家、次はうちの番»。集落の家並みは、人のつながりそのものなのです。","菅沼には、五箇山民俗館と塩硝の館があり、山の暮らしの道具や塩硝づくりの方法を知ることができます。夏の緑、秋の紅葉、そして冬の雪景色とライトアップ。茅の屋根に雪が積もった夜、窓からもれる灯りを見ていると、百年、二百年前の冬の夜にタイムスリップしたような気持ちになります。"],"tl":[["江戸時代","加賀藩領。養蚕・和紙・塩硝づくりが営まれる"],["江戸時代","五箇山が加賀藩の流刑地とされる"],["江戸時代末〜明治","現在残る合掌造りの家の多くが建てられたとされる"],["1970年","«越中五箇山菅沼集落» として国の史跡に指定"],["1994年","国の重要伝統的建造物群保存地区に選定"],["1995年","«白川郷・五箇山の合掌造り集落» として世界文化遺産に登録"]],"who":[["菅沼の人びと","合掌造りの家に住み、結で屋根を守ってきた"],["加賀藩","五箇山を治め、塩硝を買い上げ、流刑地とした"],["平家の落人","五箇山に住みついたという伝説の人びと"]],"deep":["世界遺産の構成は、岐阜県白川村の荻町、富山県南砺市の相倉と菅沼の3集落です。菅沼は3つの中でいちばん小さく、合掌造りは9棟とされます。","合掌造りは、太い «合掌» 材を三角形に組み、釘を使わず縄やネソ（マンサクなどの木の枝）でしばって組み上げるのが特徴です。しなやかに動いて雪の重みや風の力を逃がします。","屋根裏は2〜4層に分かれ、養蚕の場として使われました。囲炉裏の煙が屋根裏にのぼることで、茅や木材の防虫・防腐にも役立ったといわれます。","五箇山の «塩硝» は加賀藩の大切な軍需品で、床下の土と蚕のふんや草を使う «培養法» で作られました。菅沼の «塩硝の館» で詳しく学べます。","集落の上の展望広場からは、庄川の曲がりの内側に家々が並ぶ全景を見下ろせます。車は集落の外の駐車場にとめ、エレベーターやトンネルで下りる仕組みです。","合掌造りの家は今も人が住む私有の住まいです。見学は公開施設や外観にとどめ、敷地に勝手に入らないことが大切です。"],"look":["展望広場から見る集落の全景","合掌造りの大屋根と、茅のふきかえの跡","五箇山民俗館","塩硝の館","冬の雪景色とライトアップ（開催日を確認）"],"q":["合掌造りの屋根が急な角度になっている理由の一つは?","重い雪をすべり落とすためです。屋根裏を養蚕などに広く使うためでもあります。"],"koji":[{"w":"結（ゆい）","m":"村人どうしが労働を出しあって助け合うしくみ。屋根のふきかえなどで行われる"}],"myth":"平家落人伝説は伝承。","img":["合掌造り","白川郷・五箇山の合掌造り集落","白川郷"],"wp":"五箇山","rel":{"ev":[],"grave":[]},"ph":[["c:9/99/%E4%B8%96%E7%95%8C%E9%81%BA%E7%94%A3%E8%8F%85%E6%B2%BC%E5%90%88%E6%8E%8C%E9%9B%86%E8%90%BD.jpg",5184,3456,"五箇山"],["c:9/9e/%E8%8F%85%E6%B2%BC%E4%B8%96%E7%95%8C%E9%81%BA%E7%94%A3%E5%90%88%E6%8E%8C%E9%9B%86%E8%90%BD.jpg",5184,3456],["c:3/3c/Gokayama_20070822.jpg",3072,2304],["c:1/18/%E4%BA%94%E7%AE%87%E5%B1%B1%E7%9B%B8%E5%80%89%E5%90%88%E6%8E%8C%E9%9B%86%E8%90%BD02.jpg",2048,1536],["c:e/e9/Gokayama_ainokura_gassho_shuraku_20050504_5.jpg",1600,1200],["c:2/27/%E8%8F%85%E6%B2%BC%E5%90%88%E6%8E%8C%E9%80%A0%E3%82%8A%E9%9B%86%E8%90%BD20221105-IMG_4849.jpg",1600,1067],["c:d/db/Gokayama_Japanese_Old_Village_002.jpg",800,600],["c:2/25/Gokayama_Japanese_Old_Village_001.jpg",800,600]]},{"id":"16_ensho","n":"五箇山の塩硝の館（加賀藩の火薬づくり）","yomi":"ごかやまのえんしょうのやかた","cat":"産業","rank":"A","y":1650,"era":["azuchi","edo"],"sh":"","ad":"南砺市菅沼（菅沼集落内）","st":"JR城端線 城端駅などから世界遺産バスで約40分、«菅沼» 下車","la":36.4041,"lo":136.887,"hook":"合掌造りの床下で、4〜5年かけて «火薬のもと» を育てていた。雪深い山里は、加賀百万石のひみつの兵器工場だった。","lead":"塩硝（えんしょう）は、鉄砲の火薬（黒色火薬）に欠かせない硝石のことです。雨の多い日本では天然の硝石がとれないため、五箇山では家の床下で土を «育てて» 塩硝をつくりました。菅沼集落の «塩硝の館» では、そのふしぎな技術と、加賀藩をささえた山里の歴史を知ることができます。","story":["戦国時代、鉄砲が日本に伝わると、火薬の原料が大問題になりました。黒色火薬は、硝石・硫黄・木炭をまぜてつくります。硫黄は火山の国・日本でいくらでもとれます。木炭も簡単。けれど硝石だけは、雨の多い日本では天然にはほとんどできず、外国から買うしかありませんでした。«硝石を国の中でつくれないものか»。","その答えの一つが、五箇山にありました。合掌造りの家の囲炉裏のそばの床下に穴を掘り、土と草、そして蚕のふんなどを何層にも重ねて入れておくのです。囲炉裏のぬくもりの中で、土の中の小さな生き物（微生物）が少しずつ硝酸という成分を作り出します。4〜5年たった «育った土» に水をかけて成分をとかし出し、灰汁をまぜて煮つめると、白い結晶——塩硝ができあがりました。","«なぜ五箇山だったの?»。答えは、この土地の暮らしにあります。養蚕がさかんで蚕のふんがたくさん手に入り、山の草も豊富。冬は長く、囲炉裏の火を一日中たやさない。そして深い山にかこまれ、ひみつを守りやすい。五箇山の暮らしそのものが、塩硝づくりにぴったりだったのです。","戦国時代には、五箇山の塩硝が一向一揆を通じて石山本願寺に送られたとも伝わります。江戸時代になると、加賀藩は五箇山の塩硝をまとめて買い上げ、金沢の «土清水（つちしみず）塩硝蔵» へ運ばせました。重い荷を背負って山道を運ぶ人びとの行列が、雪の少ない季節に峠をこえていったのです。加賀藩が «百万石» の武力を保てたかげには、この山里の手仕事がありました。","けれど明治になると、南米のチリなどから安い硝石が大量に輸入されるようになり、五箇山の塩硝づくりは終わりをむかえます。塩硝の館では、床下の穴の模型や道具、煮つめる作業の再現などで、何百年も続いた «土を育てる» 技術を見ることができます。のどかな合掌造りの床下に、そんな歴史がねむっているのです。"],"tl":[["16世紀","鉄砲の普及で火薬の原料・硝石の需要が高まる"],["戦国時代","五箇山の塩硝が石山本願寺に送られたと伝わる"],["江戸時代","加賀藩が五箇山の塩硝を買い上げ、金沢の土清水塩硝蔵へ運ばせる"],["江戸時代","五箇山・白川郷など限られた地域で «培養法» による生産が続く"],["明治時代","輸入硝石におされ、五箇山の塩硝づくりが終わる"],["現在","菅沼集落の «塩硝の館» で製法や歴史を展示"]],"who":[["五箇山の人びと","床下で土を育て、塩硝を煮つめてつくった"],["加賀藩（前田家）","塩硝を独占的に買い上げ、藩の軍事力をささえた"],["運び手たち","塩硝を背負って山道をこえ、金沢へ運んだ"]],"deep":["加賀藩では、五箇山でつくられた硝石を «塩硝» と呼びました。一般に «煙硝» «焔硝» と書くと、硫黄や炭をまぜた黒色火薬そのものを指すことが多いため、区別されます。","日本の硝石づくりには、床下の古い土を使う «古土法»、草や蚕ふんを床下で数年かけて発酵させる «培養法» などがありました。培養法は加賀藩の五箇山や飛騨の白川郷など、ごく限られた地域の技術とされます。","化学的には、土の中の硝化細菌がアンモニアを硝酸に変え、灰汁のカリウムと反応させることで硝酸カリウム（硝石）を得ます。江戸時代の人びとは、経験だけでこの仕組みを使いこなしていました。","«硝石» の英語 niter が «窒素（nitrogen）» の語源になりました。火薬と肥料は、窒素というつながりで兄弟のような関係です。","五箇山の塩硝が石山本願寺に送られたという話は、一向一揆と五箇山の深い関係から語られるもので、伝承の要素も含みます。","明治以降、チリ硝石の輸入、さらにはアンモニアの工業的な合成法の登場で、世界中の «手づくり硝石» は姿を消していきました。"],"look":["床下の塩硝づくりの穴の再現展示","灰汁をまぜて煮つめる道具","合掌造りの家そのもの（囲炉裏と床下の関係に注目）","菅沼集落の全景とあわせて見学"],"q":["黒色火薬の3つの原料は?","硝石（塩硝）・硫黄・木炭です。日本で手に入りにくかったのは硝石でした。"],"myth":"石山本願寺への供給は伝承をふくむ。","img":["黒色火薬","五箇山","合掌造り"],"wp":"硝石","rel":{"ev":[],"grave":[]},"ph":[["c:5/5c/Niter_from_Tarapaca%2C_Chile_%28cropped%29.jpg",1438,1219,"硝石"],["c:e/ee/Black_Powder-1.JPG",2048,1536,"黒色火薬"],["c:9/99/%E4%B8%96%E7%95%8C%E9%81%BA%E7%94%A3%E8%8F%85%E6%B2%BC%E5%90%88%E6%8E%8C%E9%9B%86%E8%90%BD.jpg",5184,3456,"五箇山"],["c:7/78/Japanese_traditional_architecture_Gassh%C5%8D-zukuri.jpg",2048,1536,"合掌造り"]]},{"id":"16_inami","n":"井波の町並み（井波彫刻）","yomi":"いなみのまちなみ","cat":"産業","rank":"A","y":1763,"era":["muromachi","edo"],"sh":"","ad":"南砺市井波（八日町通り）","st":"JR城端線 砺波駅などから路線バスで約25分、«井波» 周辺で下車","la":36.5586,"lo":136.9722,"hook":"町を歩くと、どこからか «コン、コン» とノミの音。日本の音風景100選に選ばれた、木彫りの町。","lead":"井波は、瑞泉寺というお寺の門前町として栄えた町です。何度も焼けた瑞泉寺を建て直すなかで、井波の大工たちは京都から来た彫刻師に学び、すばらしい木彫りの技を身につけました。これが «井波彫刻» で、国の伝統的工芸品になっています。","story":["1390年、本願寺5代の綽如（しゃくにょ）が井波に瑞泉寺を開きました。北陸の浄土真宗の中心の一つとなった瑞泉寺には多くの門徒が集まり、そのまわりに町ができていきます。戦国時代には一向一揆の拠点となり、戦火で焼かれたこともありました。瑞泉寺はそのたびに、井波の宮大工たちの手で建て直されてきたのです。","江戸時代の中ごろ、瑞泉寺の大規模な再建が始まりました。このとき京都の本願寺から、御用彫刻師の前川三四郎が派遣されてきます。«これが都の彫りか……»。井波の大工たちは、三四郎のノミさばきに目を見はり、弟子入りするように技を学びました。この出会いが、井波彫刻の始まりといわれています。","寺社の彫刻で身につけた技は、やがて家の «欄間（らんま）»、獅子頭、天神様の像など、暮らしの中の美術品へと広がっていきました。一枚の板の表と裏から深く彫りこみ、花や鳥、雲や龍を立体的に浮かび上がらせる «透かし彫り» は、井波彫刻の真骨頂です。","瑞泉寺へ続く八日町通りを歩くと、石だたみの両側に彫刻の工房がずらりと並んでいます。看板も表札も、木彫り。通りのあちこちから «コン、コン» とノミをたたく音が聞こえ、この音は «日本の音風景100選» にも選ばれました。今も200人をこえる職人がこの町で働いているといわれ、これほど彫刻師が一か所に集まる町は世界的にもめずらしいのです。","井波の職人たちの腕は、富山県内の曳山祭の山車や、全国の祭り屋台の彫刻でも発揮されてきました。2018年に復元された名古屋城本丸御殿でも、井波の職人が欄間を彫っています。一つのお寺の再建から生まれた技が、300年かけて日本中の «美» をささえるまでになったのです。"],"tl":[["1390年","綽如が瑞泉寺を開く"],["戦国時代","瑞泉寺が一向一揆の拠点となり、戦火で焼かれる"],["1763〜1774年ごろ","瑞泉寺再建に京都の彫刻師・前川三四郎が派遣され、井波の大工が学ぶ"],["1947年","木彫刻の技能者養成所（のちの訓練校）が設立される"],["1975年","井波彫刻が国の伝統的工芸品に指定"],["2018年","«宮大工の鑿一丁から生まれた木彫刻美術館・井波» が日本遺産に"]],"who":[["綽如","本願寺5代。瑞泉寺を開いた"],["前川三四郎","京都の本願寺の御用彫刻師。井波の大工に技を伝えた"],["井波の宮大工・彫刻師たち","瑞泉寺を建て直し、井波彫刻を育てた"]],"deep":["井波彫刻の作品には欄間、獅子頭、衝立、天神様（菅原道真）像などがあり、日用品より «美術工芸品» が中心なのが特徴です。","富山県内の放生津・城端・八尾・伏木・出町などの曳山や、各地のだんじり・祭り屋台の彫刻の制作や修理にも、江戸時代から井波の職人が関わってきました。","2018年に復元された名古屋城本丸御殿・上洛殿の欄間7枚は、井波の彫刻師が透かし彫りで彫り、京都の職人が極彩色で仕上げたものです。","井波では1991年から4年に一度、世界の木彫作家が集まる «いなみ国際木彫刻キャンプ» が開かれ、町に作品が残されています。","瑞泉寺の山門や本堂にも、井波の職人の手による彫刻が数多く見られます。寺そのものが «木彫刻の美術館» です。","職人を育ててきた井波木彫刻工芸高等職業訓練校は、生徒の減少で2022年度末に休校となり、その後は «井波彫刻塾» という形で技術の伝承が続けられています。"],"look":["八日町通りの工房と木彫りの看板","瑞泉寺の山門・本堂の彫刻","井波彫刻総合会館の作品展示","町のあちこちに置かれた木彫りの作品"],"q":["井波の木彫りの音は、何に選ばれている?","«日本の音風景100選» です。"],"myth":"職人の人数は時期によって変わる。","img":["真宗大谷派井波別院瑞泉寺","欄間","綽如","井波町"],"wp":"井波彫刻","rel":{"ev":[],"grave":[]},"ph":[["c:d/d4/Michinoeki_Inami.021.jpg",3296,2472],["c:3/30/InamibetsuinZuisenji.JPG",3865,2572,"真宗大谷派井波別院瑞泉寺"],["c:d/dc/Wooden-panel-used-as-a-decorative-transom-above-paper-covered-sliding-doors%2Cranma%2Ckatori-city%2Cjapan.JPG",1600,1200,"欄間"]]},{"id":"16_yatsuo","n":"越中八尾の町並み（おわらの町）","yomi":"えっちゅうやつおのまちなみ","cat":"町","rank":"A","y":1636,"era":["edo","meiji"],"sh":"","ad":"富山市八尾町（東町・諏訪町ほか）","st":"JR高山本線 越中八尾駅から歩いて約15〜20分","la":36.578,"lo":137.138,"hook":"胡弓の音が夜の坂道にしみこむ。9月の3日間、編笠の人びとが無言で踊りながら町を流していく。","lead":"越中八尾は、富山市南部の山あいにある坂の町です。江戸時代に町ができ、養蚕や和紙で栄えました。毎年9月1日から3日まで行われる «おわら風の盆» は、胡弓と三味線にあわせて静かに踊る祭りとして全国に知られています。","story":["井田川の河岸段丘の上、高い石垣の上に家々が並ぶ八尾の町。«八尾» という名は、八つの尾根が集まるところだから、といわれます。坂を上り下りする細い道、格子戸の町家、白い土蔵。浄土真宗の聞名寺の門前町として人が集まり、1636年に加賀藩から «町» としての許しを受けました。","山あいの町が豊かになったのは、養蚕と紙のおかげでした。八尾は飛騨との行き来の要所で、蚕の卵（蚕種）や生糸、そして和紙の取引でにぎわいました。八尾の和紙は、富山の売薬の袋や包み紙にも使われたといわれます。お金持ちの商人たちは、5月の曳山祭で豪華な曳山を町に引き出しました。","おわら風の盆の始まりには、こんな言い伝えがあります。江戸時代の元禄のころ、町の外に出てしまっていた大切な «町建ての文書» を取りもどしたお祝いに、町の人びとが三日三晩、歌い踊りながら町を練り歩いた。«それがおわらの始まりだ» というのです。やがて、稲の実りのころにふく強い風（二百十日の風）がおさまるよう願う祭りとも結びついたと考えられています。","«なぜ、こんなに静かで、さびしげな踊りなの?»。おわらを初めて見た人は、たいていそう感じます。深くかぶった編笠で顔をかくし、胡弓のすすり泣くような音にあわせ、しなやかに手足をのばす。見物人は «静かに» と声をかけあい、ぼんぼりの灯りの下、坂の町に歌声だけがひびきます。この雰囲気は小説にもえがかれ、全国から大勢の人が訪れるようになりました。","風の盆の3日間、八尾の町は人口の何倍もの人でうまります。けれど本当のおわらは、夜がふけて観光客がへったあとの «町流し» だという人もいます。石畳の諏訪町本通りを、ひと組の踊り手と地方（じかた＝演奏する人）が、ゆっくりと坂を上っていく。400年近い町の歴史が、一夜の踊りに流れこんでいくようです。"],"tl":[["1636年","加賀藩から町立ての許しが出て八尾町が開かれる"],["元禄のころ","町建て文書を取りもどした祝いに三日三晩踊ったと伝わる（おわらの起源伝承）"],["江戸時代","養蚕・和紙の取引で町が栄え、曳山祭が始まる"],["明治〜昭和","おわらに胡弓が加わるなど、今の姿に洗練されていく"],["1980年代","小説などで «おわら風の盆» が全国的に知られる"],["2005年","八尾町が富山市と合併"]],"who":[["八尾の町人たち","町を開き、おわらと曳山祭を守ってきた"],["おわらの踊り手と地方","唄・三味線・胡弓で風の盆をつくる"],["聞名寺","町の成り立ちに関わった浄土真宗の寺"]],"deep":["«おわら» の語源には、«大笑い（おおわらい）» から来たという説、豊年を願う «大藁（おおわら）» から来たという説などがあり、はっきりしません。","«風の盆» は、立春から数えて210日目ごろ（9月初め）に来る台風の «風» の被害をしずめ、豊作を願う行事と結びついたと考えられています。","おわらは旧町ごとに «支部» があり、それぞれ町流し・輪踊り・舞台踊りを行います。男踊りは農作業、女踊りは蚕の仕事などをかたどったともいわれます。","諏訪町本通りは «日本の道100選» に選ばれた石畳の道で、両側の格子戸の町家とあわせて八尾らしい景色を見せてくれます。","八尾の曳山祭（5月）では、江戸時代から伝わる豪華な曳山が町を巡行します。曳山の彫刻などには井波の職人も関わったとされます。","八尾和紙の工房（桂樹舎など）では、紙すきや型染めの作品に触れることができます。"],"look":["井田川から見上げる石垣の上の町並み","諏訪町本通り（日本の道100選）","聞名寺","おわら風の盆（9月1〜3日）の町流し","曳山展示館の曳山"],"q":["おわら風の盆は毎年何月何日から?","9月1日から3日までの3日間です。"],"myth":"おわらの起源（町建て文書の話）や語源は伝承・諸説。","img":["越中おわら節","胡弓","聞名寺"],"wp":"八尾町","rel":{"ev":[],"grave":[]},"ph":[["c:d/dd/Kazenobon01.jpg",800,600,"八尾町"],["c:0/05/Yatsuo_district_Toyama_city_Aerial_photograph.1975.jpg",4125,3489],["c:e/e3/Yatsuo_-machi_Ida_river_terrace_stone_wall.A.jpg",4000,3000],["c:a/a4/Owara_Kaze_no_Bon.Suwa-Machi_street_in_the_middle_of_the_night_on_September_3%2C_2017.jpg",6000,4000],["c:1/1f/Kazenobon03.jpg",800,600,"越中おわら節"]]},{"id":"16_aimoto","n":"愛本橋（日本三奇橋の刎橋）","yomi":"あいもとばし","cat":"街道","rank":"A","y":1663,"era":["edo","showa"],"sh":"","ad":"黒部市宇奈月町下立・中ノ口","st":"富山地方鉄道本線 愛本駅から歩いて約15分。車が便利","la":36.8602,"lo":137.5537,"hook":"«国の安全は、山や川の険しさで守るものではない»——18歳の藩主が家臣の反対をおしきって架けた、暴れ川の奇橋。","lead":"愛本橋は、黒部川にかかる橋です。江戸時代、ここには橋脚のない «刎橋（はねばし）» がかけられ、山口の錦帯橋、山梨の猿橋とならんで «日本三奇橋» と呼ばれました。今の橋は昭和47年（1972年）にかけられたアーチ形の鉄の橋です。","story":["黒部川は «黒部四十八ヶ瀬» と呼ばれた暴れ川でした。川の流れはいくつにも分かれ、大雨のたびに道を変えます。北陸道を行く旅人も、参勤交代の大名行列も、この川をわたるのに命がけでした。1661年、18歳の加賀藩主・前田綱紀は、藩主になって初めて国入りしたとき、この難所をわたって金沢に着きました。","«山ぞいに新しい道を開き、黒部川の狭いところに橋をかけよう»。綱紀のことばに、家臣たちは反対しました。«黒部川は国を守る天然の堀。橋をかければ、敵が攻めこみやすくなります»。しかし綱紀は «国の安危は得失にあり。山河の険阻によるべきにあらず（国の安全は政治のよしあしで決まる。山や川の険しさにたよるものではない）» と答え、架橋を決めたと伝わります。","とはいえ、橋をかけるのは簡単ではありません。愛本の両岸は岩山で、川幅はいちばんせまいところでも、洪水のときには大量の土石と水がおしよせます。川の中に橋脚を立てても、1年ももたずに流されてしまうのです。«ならば、川の中に脚を立てなければよい»。職人たちが選んだのは、両岸から太い木を何段も重ねて突き出し、その先をつないで橋にする «刎橋» でした。","1663年に完成した刎橋は、長さ約61メートル、幅約3.6メートル。空中にはね出すような独特の姿は、旅人たちをおどろかせ、«日本三奇橋» の一つと呼ばれるようになりました。幕末の儒学者・頼三樹三郎（らいみきさぶろう）もこの橋をたたえる詩を残し、その詩碑が近くに立っています。刎橋は、江戸時代の終わりまで何度もかけかえられながら使われました。","明治になると木のアーチ橋、大正には鉄の橋にかわりました。けれど1969年8月の豪雨で、その鉄橋も濁流にのまれて流されてしまいます。今の橋は、流された橋の少し下流に、川の中に脚を立てないアーチ橋としてかけられました。«川に脚を立てない» という江戸の知恵は、形をかえて今も生きているのです。"],"tl":[["1626年","この地に打渡橋がかけられる"],["1661年","前田綱紀が初めて国入りし、架橋を決めたと伝わる"],["1663年","刎橋の愛本橋が完成（以後1862年までに8回かけかえ）"],["1678年","富山藩が橋番人を置く"],["1891年","木造アーチ橋になる"],["1920年","鋼鉄のトラス橋になる"],["1969年8月","豪雨でトラス橋が流失"],["1972年","今の橋（ニールセンローゼ橋）が完成"]],"who":[["前田綱紀","加賀藩5代藩主。家臣の反対をおさえて架橋を決めた"],["頼三樹三郎","幕末の儒学者。愛本橋をたたえる詩を残した"],["橋をかけた職人たち","刎橋の技術で暴れ川に橋をかけた"]],"deep":["«日本三奇橋» は、錦帯橋（山口）・猿橋（山梨）と、愛本橋または木曽の桟（かけはし）などを数えるなど、数え方にいくつかの説があります。","刎橋は、両岸の岩に «刎木（はねぎ）» と呼ばれる大木を斜めに差しこみ、少しずつ前へ突き出して重ね、その上に橋板をわたす構造です。猿橋と同じ形式でした。","刎橋の規模は «橋長33間、幅10尺» と記録され、メートルに直すと長さ約61メートル、幅約3.6メートルになります。","今の橋は1972年完成で、橋長130メートル。橋脚を置かない «ニールセンローゼ橋» という形式で、バスケットの持ち手のように内側に傾いたアーチをもち、日本で2番目にかけられた例とされます。","1969年に流された鉄橋の一部は、1998年に約150メートル下流の川底から見つかり、うなづき友学館の前庭に展示されています。","うなづき友学館（黒部市歴史民俗資料館）には、刎橋の一部を2分の1で復元した模型があり、構造がよくわかります。"],"look":["今のアーチ形の愛本橋と黒部川の峡谷","旧橋の場所に近い頼三樹三郎の詩碑","うなづき友学館の刎橋の復元模型","黒部川扇状地のはじまり（扇頂）の地形"],"q":["川の中に橋脚を立てず、両岸から木を突き出してかける橋を何という?","«刎橋（はねばし）» です。"],"koji":[{"w":"国の安危は得失にあり。山河の険阻によるべきにあらず","m":"国の安全は政治のよしあしで決まるもので、山や川の険しさにたよるものではない。前田綱紀のことばと伝わる"}],"myth":"綱紀のことばや家臣の反対の話は伝承として語られる。","img":["刎橋","錦帯橋","前田綱紀","黒部川"],"wp":"愛本橋","rel":{"ev":[],"grave":[]},"ph":[["c:8/8a/Aimoto_Bridge.jpg",1200,900,"愛本橋"],["c:2/2c/American_engineer_and_railroad_journal_%281893%29_%2814572885609%29.jpg",2832,1968],["c:6/66/20100724_Iwakuni_5235.jpg",4288,2848,"錦帯橋"],["c:2/29/Maeda_Tsunanori.jpg",3309,5203,"前田綱紀"],["c:4/4b/Kurobe_River.jpg",800,600,"黒部川"]]},{"id":"16_sakai_seki","n":"境関所跡（加賀藩の東の関）","yomi":"さかいせきしょあと","cat":"街道","rank":"A","y":1614,"era":["edo"],"sh":"県指定史跡","ad":"下新川郡朝日町境","st":"あいの風とやま鉄道 越中宮崎駅から車で約5分","la":36.9765,"lo":137.625,"hook":"箱根の関所の2倍の武器をそなえた、加賀百万石の «東の玄関»。その先には、親不知の荒波が待っていた。","lead":"境関所は、越中と越後の国境、境川のそばに加賀藩が置いた関所です。1614年に正式な関所となり、明治2年（1869年）まで国境を守りました。箱根の関所の2倍の規模の武器や人員をそなえ、全国でも最大級の関所だったといわれます。今は跡地に «関の館» が建っています。","story":["北陸道を東へ、越中から越後へ向かう旅人がいちばん緊張したのが、この境の関所でした。«どこから来た。どこへ行く。手形を見せよ»。役人の声がひびき、荷物が調べられます。関所を通りぬけると、すぐ先には、断崖と荒波のあいだを波が引いたすきに走りぬける難所 «親不知（おやしらず）» が待っていました。","加賀藩はもともと、ここに口留番所（くちどめばんしょ）を置いていましたが、1614年に正式な関所として整えました。境川をはさんだ向こう、越後側には幕府の市振（いちぶり）関所があり、二つの関所の間はおよそ一里（約4キロ）。«百万石の国の入口» は、隣国と幕府の両方に向き合う最前線でもあったのです。","関所には、陸の道を調べる関所だけでなく、海辺や海の上を調べる «浜関所»、海や山から勝手に国境をこえる者を見張る «御亭（おちん）»、藩主が泊まる «御旅屋（おたや）»、鉄砲の練習場、牢屋、役人の長屋までありました。寛文6年（1666年）以降は、奉行・与力・足軽など約30人、鉄砲70・槍70・弓30などがそなえられていたといいます。これは箱根の関所の2倍の規模でした。","«なぜ、そこまで厳しく守ったの?»。加賀藩は外様の大藩として、幕府に疑われないよう気を配りつつ、自分の国を守る必要がありました。人の出入りを厳しく見張ることで、藩の秘密（塩硝など軍事の品）を守り、逃亡者や密輸を防いだのです。境は塩づくりもさかんで、関所の奉行が塩の奉行を兼ねた時期もありました。","1689年、奥の細道の旅の途中の松尾芭蕉も、市振の宿に泊まったあとこの国境をこえて越中に入りました。明治2年（1869年）、関所は廃止されます。跡地は小学校をへて、今は «関の館» という施設になり、敷地には関所跡の碑が立っています。旅人たちの緊張と安堵が行きかった国境の記憶が、静かに残されています。"],"tl":[["江戸時代初め","加賀藩が境に口留番所を置く"],["1614年","正式な関所として整備される"],["1666年以降","奉行以下約30人と多数の武器がそなえられる"],["1689年","松尾芭蕉が市振から越中へ国境をこえる（奥の細道）"],["1869年2月","関所が廃止される"],["1965年","«境関所跡» として富山県の史跡に指定"],["1998年","跡地に «関の館» が完成"]],"who":[["加賀藩（前田家）","境関所を置き、東の国境を守った"],["関所の奉行・役人たち","2〜3年交代で国境の警備にあたった"],["松尾芭蕉","奥の細道の旅でこの国境をこえた俳人"]],"deep":["関所の奉行は2〜3年の交代制で、5000石から1500石クラスの家臣がつとめたとされます。加賀藩がこの関所をどれほど重視したかがわかります。","境は製塩がさかんで、関所の奉行は寛政8年（1796年）まで «御塩奉行» も兼ねていました。","関係資料として «境関所御囲絵図»（2枚）と «類従旧例古格»（3冊）が朝日町の文化財に指定されています。","越後側の市振関所は幕府が設け、高田藩が預かりました。二つの関所が一里の距離で向き合う国境は、全国でもめずらしい例です。","芭蕉は市振の宿で «一つ家に遊女も寝たり萩と月» の句をよみ、翌日、越中へ入りました。","«入り鉄砲に出女» は幕府の関所の有名な方針ですが、境関所のような藩の関所でも、女性の出入りや武器・軍需品の出入りは厳しく調べられました。"],"look":["関所跡の碑と «関の館»","境川と国境の地形（越後側の市振方面を望む）","近くの海岸の景色（親不知へ続く海岸線）"],"q":["境関所の武器や人員の規模は、有名な箱根関所のおよそ何倍?","約2倍とされます。"],"myth":"","img":["関所","松尾芭蕉","親不知"],"wp":"北陸道","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:7/7f/Ishibe_shukubanosato02s3200.jpg",3200,1800,"関所"],["c:c/ca/Basho_by_Morikawa_Kyoriku_%281656-1715%29.jpg",512,854,"松尾芭蕉"]]},{"id":"16_fugan","n":"富岩運河と中島閘門","yomi":"ふがんうんがとなかじまこうもん","cat":"近代","rank":"A","y":1934,"era":["showa","heisei"],"sh":"国の重要文化財（富岩運河水閘施設）","ad":"富山市中島・興人町付近","st":"富山駅北口から北へ歩いて約30分。富岩運河環水公園から富岩水上ラインの船で行くこともできる（運航期間を確認）","la":36.7256,"lo":137.2197,"hook":"水位差2.5メートルを、水の力だけで船ごと上げ下げ。パナマ運河と同じしくみの閘門が、昭和の富山に生まれた。","lead":"富岩運河は、富山の町と岩瀬の港（富山港）を結ぶために昭和のはじめにつくられた、長さ約5.1キロの運河です。途中の中島閘門は、水位のちがう水面のあいだで船を上げ下げする «パナマ運河方式» の施設で、昭和の土木建造物として全国で初めて国の重要文化財になりました。","story":["江戸時代から、岩瀬の港は北前船でにぎわっていました。けれど、港から富山の町の中心までは遠く、荷物を運ぶのはひと苦労。«港と町を水の道でつなげられないか»。明治・大正と、その願いは強くなっていきました。","昭和3年（1928年）、内務省の技師・赤司貫一が画期的な計画を立てます。運河を掘り、その土で曲がりくねっていた神通川の旧河道を埋め立て、新しい町と道路と公園をいっしょにつくる——当時はばらばらに行うのがふつうだった工事を、まとめて行う計画でした。«これは日本初の試みだ» と、内務省の幹部も感心したといいます。","工事は1930年、不況で仕事を失った人びとの «失業対策» としても始まりました。掘り出された土は約130万立方メートル。運河は1935年に完成しました。途中の中島閘門は、上流と下流で約2.5メートルある水位の差を調整する施設です。船が閘室に入ると後ろの扉がしまり、水を出し入れして水面を上げ下げ。«ポンプを使わず、水の高低差だけで動かす» しくみでした。","運河ぞいには工場が立ち並び、富山の工業を大きく育てました。けれど戦後、トラック輸送の時代になると運河を使う船はへり、水はよごれ、木材の皮がヘドロになって «じゃま者» 扱いされるようになります。1979年、県は運河の半分を埋め立てて道路にする計画を発表しました。«このまま消えてしまうのか»——。","ところが1984年、県は方針を大きく変えます。«運河を埋めるのではなく、水辺をいかした町づくりをしよう»。中島閘門は昔の姿に復元修理され、1998年に国の重要文化財に。運河のいちばん上流の船だまりは «富岩運河環水公園» に生まれかわりました。今では遊覧船が閘門を通り、昭和の «水のエレベーター» を体験できます。"],"tl":[["1918年","東岩瀬町と富山市の有志が運河の実現をめざし協議を始める"],["1928年","赤司貫一の計画をもとに都市計画事業が決まる"],["1930年","失業対策事業として着工"],["1934年8月","中島閘門が完成"],["1935年","富岩運河が完成し、運航開始"],["1979年","運河の半分を埋め立てる計画が発表される"],["1984年","埋め立てをやめ、運河をいかす方針に転換"],["1998年","中島閘門などが国の重要文化財に指定"]],"who":[["赤司貫一","内務省の技師。運河・区画整理・道路・公園を一体で計画した"],["工事で働いた人びと","不況の時代に失業対策事業で運河を掘った"],["閘門の操作員","24時間体制で閘門と治水を管理した"]],"deep":["中島閘門は長さ86メートル。閘室は長さ60.6メートル・幅9.09メートルで、200トン級までの船が通れます。","基礎には直径21センチ・長さ5.3メートルの松の丸太が約1700本使われています。閘室の底には、竿で船を進めやすいよう割り石が千鳥に並べられています。","扉は鋼製の «マイターゲート（合掌式ゲート）» で、約1万5000本のリベットで組み立てられています。復元修理でもリベット接合で昔の姿に戻され、扉の水が漏れないところには檜材が使われています。","指定の名称は «富岩運河水閘施設»。閘門、閘門操作所、放水路、中島橋、量水計が含まれます。昭和初期の土木建造物として国の重要文化財になった全国初の例です。","運河を掘った土は、神通川の «馳越（はせこし）工事» でできた旧河道の埋め立てや富山港の修築に使われました。今の富山県庁や富山市役所のあたりは、その埋立地に建っています。","富岩運河環水公園は1997年に開園し、公園内のスターバックスが «世界一美しいスタバ» として話題になったこともあります。"],"look":["中島閘門の閘室と鋼製の扉（リベットに注目）","洒落た外観の閘門操作所","遊覧船で体験する水位の上げ下げ","上流の富岩運河環水公園と天門橋"],"q":["中島閘門は、上流と下流の水位の差を何で調整する?","ポンプを使わず、水の高低差を利用した自然の流れで調整します。"],"myth":"","img":["富岩運河","閘門","富岩運河環水公園"],"wp":"中島閘門","rel":{"ev":[],"grave":[]},"ph":[["c:1/1a/2_K%C5%8Djinmachi%2C_Toyama-shi%2C_Toyama-ken_930-0809%2C_Japan_-_panoramio_%2825%29.jpg",4608,3456,"中島閘門"],["c:a/a1/2_K%C5%8Djinmachi%2C_Toyama-shi%2C_Toyama-ken_930-0809%2C_Japan_-_panoramio_%289%29.jpg",4608,3456],["c:a/a3/2_K%C5%8Djinmachi%2C_Toyama-shi%2C_Toyama-ken_930-0809%2C_Japan_-_panoramio_%2849%29.jpg",4608,3456],["c:c/ce/2_Chome_Nakajima%2C_Toyama-shi%2C_Toyama-ken_930-0801%2C_Japan_-_panoramio_%281%29.jpg",4608,3456],["c:9/96/Fugan_unga.JPG",1600,1066,"富岩運河"],["c:0/0c/Lock-2.jpg",600,800,"閘門"],["c:4/42/Starbucks_Toyama_Canal_Park.jpg",960,493,"富岩運河環水公園"]]},{"id":"16_kurobe_kyokoku","n":"黒部峡谷鉄道（電源開発の軌道）","yomi":"くろべきょうこくてつどう","cat":"近代","rank":"A","y":1926,"era":["taisho","showa"],"sh":"","ad":"黒部市黒部峡谷口（宇奈月駅）","st":"富山地方鉄道・宇奈月温泉駅から歩いて約5分で宇奈月駅","la":36.8148,"lo":137.5856,"hook":"観光客を乗せて走るかわいいトロッコ電車。そのレールは、もともと «ダムと発電所をつくるための資材運び» に敷かれたものだった。","lead":"黒部峡谷鉄道は、宇奈月から欅平まで約20kmを走るトロッコ電車です。大正時代、黒部川で電気をつくる工事のために資材を運ぶ線路として敷かれました。人を乗せる正式な営業が始まったのは、戦後の1953年になってからです。","story":["大正時代のはじめ、黒部川は «日本一の暴れ川» の一つとして知られていました。雪どけ水が多く、山から海までの落差がとても大きい。«この水の力で電気をつくれば、工場も町も動かせる»。そう考えた会社が、けわしい谷の奥へ発電所を建てようと計画します。けれども問題は、どうやって資材を運ぶかでした。","答えは、谷沿いの細い林道に小さなレールを敷くことでした。1923年に工事が始まり、1926年に宇奈月から猫又までの運転が始まります。レールの幅はわずか762mm。ふつうの鉄道よりずっと狭いのは、崖にへばりつくような場所に線路を通すためでした。その後、線路は少しずつ奥へのび、1937年に欅平までつながりました。","«乗せてほしい» と頼む人は、工事が始まったころから少なくありませんでした。山奥の温泉に行きたい人、登山をしたい人。会社は本来の仕事ではないので、«安全の保証はできません» という約束で、ついでに乗せることにしたといわれます。命がけの乗車だったのです。","戦争中から戦後にかけて、線路の持ち主は日本電力、日本発送電、関西電力と移り変わりました。そして1953年、関西電力が正式に旅客営業を始め、1971年には鉄道を専門にあつかう会社として «黒部峡谷鉄道» が生まれます。工事用の線路が、日本を代表する観光列車に生まれ変わった瞬間でした。","今もこの鉄道は、観光と同時に発電所の仕事も支えています。冬は雪崩の危険があるため運休し、春になると線路や鉄橋の点検から一年が始まります。窓のない車両から吹きこむ谷風を感じながら、«なぜこんな場所に線路を?» と考えてみると、百年前の人びとの苦労が見えてきます。"],"tl":[["1923年","日本電力が宇奈月〜猫又間の軌道工事に着手"],["1926年","宇奈月〜猫又間で運転開始"],["1937年","欅平まで線路がつながる"],["1941年","欅平から奥へ、関係者専用の上部軌道が仙人谷まで通じる"],["1953年","関西電力が宇奈月〜欅平間で旅客営業を開始"],["1971年","黒部峡谷鉄道株式会社が発足し、営業を引き継ぐ"],["1988年","宇奈月ダム建設にともない、新山彦橋を通る今のルートに変更"],["2024年","能登半島地震で鐘釣橋が落石を受け損傷。その後は一部区間での運行が続く"]],"who":[["日本電力","黒部川の電源開発を進めた会社。資材運搬用として線路を敷いた"],["関西電力","戦後に鉄道を受け継ぎ、1953年に旅客営業を始めた"],["黒部峡谷鉄道","1971年に関西電力の子会社として生まれた、今の運営会社"]],"deep":["軌間762mmの鉄道は、今の日本ではとても珍しい存在です。ほかは三重県の四日市あすなろう鉄道と三岐鉄道北勢線くらいで、«特殊狭軌» と呼ばれます。","欅平駅から先には、関西電力の関係者専用の «上部軌道» が続きます。高熱隧道を通って黒部川第四発電所方面へつながるルートで、一般の人は原則乗れませんでした。","この上部軌道を含むルートは «黒部宇奈月キャニオンルート» として一般に開く計画が進められていましたが、2024年の地震で本線が被災し、開放は延期されました。","宇奈月駅前の黒部川電気記念館の入口には、1925年から使われたEB形電気機関車（EB5）が、登場当時の姿に戻されて保存されています。","定期券の割引率がとても高く、利用者は関電関係者のほか、沿線の宿で働く人やガイドなどです。«生活の足» としての一面もあるのです。","2013年には台湾の阿里山森林鉄路と姉妹鉄道になりました。どちらも山の資源を運ぶために生まれた鉄道という共通点があります。"],"look":["宇奈月駅を出てすぐの赤い «新山彦橋» と、対岸に残る旧線の «山彦橋»","途中の駅から見える発電所やダム（出平・小屋平など）","窓のない普通客車で感じる谷風と水しぶきの音","宇奈月駅前の黒部川電気記念館と保存機関車"],"q":["黒部峡谷鉄道の線路は、もともと何のために敷かれた？","発電所やダムを建てるための資材を運ぶためです。人を乗せる正式な営業は戦後の1953年から。"],"koji":[],"myth":"工事時代の便乗客への «安全は保証しない» という条件は、伝えられる内容に細部の違いがある。運行区間は災害で変わることがあるので、最新の運行情報を確認のこと。","img":["黒部峡谷","宇奈月温泉","黒部川"],"wp":"黒部峡谷鉄道","rel":{"ev":[],"grave":[]},"ph":[["c:c/c8/Series_3100%2C_Kurobe_Gorge_Railway%2C_October_2020.jpg",4032,3024],["c:0/08/Shin_Yamabiko_bridge_and_Kurobe_Torokko_railway.jpg",4032,3024],["c:3/3b/Kurobe_Gorge_Railway_EDV34_and_EDV35.jpg",2961,3025],["c:b/b5/Kurobe_gorge_railway_EDR33_and_EDM29.JPG",4112,2945],["c:1/1e/Kurobe_gorge_railway_dashidaira_station.JPG",4402,2935],["c:a/a0/Kurobe_Gorge_Railway_1000_series_passenger_coach.jpg",3648,2736],["c:c/c2/Passenger_cars_at_Unazuki_Station_20180505.jpg",3264,2448],["c:9/9a/Kurobe_Gorge_Railway_class_3100_passenger_coaches_at_Unazuki_Station.jpg",3073,2305]]},{"id":"16_koonet","n":"高熱隧道（黒部川第三発電所の難工事）","yomi":"こうねつずいどう","cat":"昭和","rank":"A","y":1938,"era":["showa"],"sh":"","ad":"黒部市宇奈月町黒部奥山（欅平〜阿曽原〜仙人谷付近）","st":"一般の人は入れない。欅平駅から先は関係者専用の軌道。周辺の登山道は上級者向け","la":36.68,"lo":137.635,"hook":"岩の温度は最高166℃。触れればやけどするトンネルを、人の手で掘りぬいた工事があった。","lead":"«高熱隧道» は、黒部峡谷の奥で黒部川第三発電所をつくるときに掘られたトンネルの通称です。掘り進むと岩がどんどん熱くなり、最高で160℃をこえたと記録されています。雪崩の事故などで多くの人が亡くなった、とても厳しい工事でした。","story":["1936年、黒部峡谷の奥、欅平の上流で新しい発電所の工事が始まりました。上流にダムをつくり、水をトンネルで欅平近くの発電所まで落として電気をおこす計画です。人が歩くのもやっとの谷で、資材を運ぶだけでも転落する人が出るほどでした。","トンネルを掘り始めてすぐ、作業員たちは異変に気づきます。岩が熱いのです。奥へ進むほど温度は上がり、ついには温度計が160℃をこえました。この山の下には、熱い温泉の通り道があったのです。作業員は黒部川の冷たい水を浴びながら、交代で少しずつ掘り進めました。«なぜそこまでして?» と思うかもしれません。当時の日本は工場を動かす電気を、とても必要としていたのです。","熱はもう一つの危険を生みました。岩に仕掛けたダイナマイトが、熱のせいで予定より早く爆発してしまう事故が起きたのです。安全に爆破するための工夫を重ねながら、工事は続けられました。","冬には雪崩がおそいかかりました。とくに «泡雪崩» と呼ばれる、ものすごい風を伴う雪崩は、頑丈に建てたはずの宿舎を吹き飛ばし、多くの作業員の命をうばいました。工事全体で亡くなった人は300人をこえるともいわれます。","1940年、トンネルと発電所はついに完成しました。いまもこのトンネルは関西電力の専用軌道として使われていますが、一般の人が中に入ることはできません。のちに作家の吉村昭がこの工事を小説『高熱隧道』に描き、多くの人が黒部の奥で起きたことを知るようになりました。ここで働き、亡くなった人びとへの思いを胸に、この場所の話を読んでほしいと思います。"],"tl":[["1936年","黒部川第三発電所の工事が始まる"],["1936〜1940年","岩盤の温度が上がり続け、最高166℃に達したと記録される"],["1938年末","志合谷で泡雪崩が宿舎をおそい、多数の犠牲者が出る"],["1940年","トンネルと発電所の工事が完了"],["1941年","欅平から仙人谷までの上部軌道が開通"],["1967年","吉村昭が小説『高熱隧道』を発表"]],"who":[["日本電力","黒部川第三発電所の建設を進めた電力会社"],["佐藤工業","工事を担当した建設会社の一つ。小説の «佐川組» のモデル"],["吉村昭","この工事をもとに小説『高熱隧道』を書いた作家"]],"deep":["小説『高熱隧道』の登場人物はすべて架空で、実名の会社は «日本電力» だけ。建設会社 «佐川組» は佐藤工業がモデルとされます。小説の場面をそのまま史実と受け取らないよう注意が必要です。","岩盤温度 «166℃» は小説でも印象的に使われる数字ですが、工事記録にもとづく値として広く紹介されています。","作業員は切羽（掘っている最前線）に黒部川の水をホースでかけ続け、交代時間を短くしてしのいだといわれます。","«泡雪崩» は、雪煙と猛烈な爆風をともなう雪崩で、黒部の工事では鉄筋コンクリートの宿舎まで飛ばしたと伝えられます。","このトンネルは現在、関西電力黒部専用鉄道（上部軌道）の一部です。のちの黒部ダム（黒四）建設にも欠かせないルートになりました。","亡くなった人の数は資料によってちがい、正確な数ははっきりしていません。朝鮮半島から来た人も多く働いていたといわれます。"],"look":["欅平駅の周辺（上部軌道への入口や竪坑の建物を外から見られる）","欅平から見上げる峡谷のけわしさ","宇奈月の黒部川電気記念館で電源開発の歴史を学ぶ"],"q":["高熱隧道の岩盤は最高で何℃に達したと記録されている？","166℃です。作業員は川の水を浴びながら交代で掘り進みました。"],"koji":[],"myth":"犠牲者数（300人余りとされる）は資料で差がある。小説『高熱隧道』は事実をもとにした創作で、人物や会話は架空。","img":["黒部川第三発電所","吉村昭","泡雪崩"],"wp":"高熱隧道","rel":{"ev":[],"grave":[]},"ph":[["c:e/ef/Jobu_Kido_Kounetsu_Zuido2.jpg",1024,768,"高熱隧道"],["c:b/b8/Kounetu_Zuido.jpg",1600,1200]]},{"id":"16_komaki","n":"小牧ダム（庄川の流木争議）","yomi":"こまきだむ","cat":"昭和","rank":"A","y":1930,"era":["taisho","showa"],"sh":"国の登録有形文化財","ad":"砺波市庄川町小牧","st":"JR高岡駅・砺波駅から加越能バスで «小牧堰堤» 下車すぐ","la":36.569,"lo":136.977,"hook":"完成したとき «東洋一» の高さをほこったダム。その陰で、川で木を運ぶ人びととの長い争いがあった。","lead":"小牧ダムは庄川にある発電用のダムで、1930年に完成しました。当時は東洋一の高さといわれました。けれども川で丸太を流して運んでいた木材業者はダムに強く反対し、«庄川流木争議» と呼ばれる長い争いが起きました。","story":["むかしの庄川は、山の木を運ぶ «道» でした。飛騨の山で切った木を川に流し、下流の町まで運んでいたのです。これを «流木» といいます。ところが大正時代、この川に大きなダムをつくって電気をおこそうという計画が持ち上がりました。言い出したのは富山県出身の実業家・浅野総一郎です。","«川をせき止められたら、木が運べなくなる!» 木材業者たちは、はげしく反対しました。そこでダムには、木を運ぶための設備と、魚がのぼれる魚道をつけるように設計が変えられ、1925年にようやく工事が始まります。設計の一部はアメリカの会社に頼みました。当時の日本には、これほど大きなダムの経験がなかったからです。","それでも争いはおさまりません。有力な木材会社 «飛州木材» は裁判に訴え、ダムに水をためることを止めさせる決定まで勝ち取りました。けれどもその決定は取り消され、1930年、ダムに水がたまり始め、発電が始まります。","負けた側は、ダムの設備では木を流せないと主張して、たくさんの丸太を流し始めました。ダム湖は丸太でうまり、1933年1月には両者がぶつかって多くのけが人が出ます。«どうすれば、みんなが生きていけるのか?» 最後は国（内務省）の和解案を受け入れ、1933年8月、争いはようやく終わりました。","ダムができたことで、庄川峡には遊覧船が走り、新しい観光地が生まれました。今もダムは現役で電気をつくり、その姿は国の登録有形文化財になっています。静かな湖面の下に、川とともに生きた人たちの必死の思いが眠っているのです。"],"tl":[["1919年","浅野総一郎らが庄川水力電気を設立"],["1925年","ダムの工事が始まる。飛州木材が工事中止を求める"],["1926年","飛州木材が行政裁判所にダム認可の取り消しを訴える"],["1930年","湛水禁止の仮処分が出るが取り消され、11月に発電開始"],["1933年1月","電力側と木材側が衝突し、多くの負傷者が出る"],["1933年8月","内務省の和解案を受け入れ、争議が終わる"],["2001年","土木学会選奨土木遺産に認定"],["2002年","河川用ダムとして初めて登録有形文化財に"]],"who":[["浅野総一郎","富山県出身の実業家。庄川での発電を計画した"],["飛州木材","庄川で流木をしていた有力な木材会社。ダムに反対し裁判で争った"],["物部長穂","工学博士。彼の耐震設計の理論が初めて取り入れられたダムとされる"],["日本電力","資金難になった庄川水力電気を子会社にし、建設を進めた"]],"deep":["小牧ダムは、物部長穂の «貯水用重力式堰堤の特性並びに其合理的設計方法» という耐震設計理論を初めて取り入れたダムとされ、その後のダムづくりに大きく影響しました。","ダム右岸にはエレベーター式の魚道、左岸には木材運搬用のコンベアが設けられました。争議の «答え» がダムの形に残っているのです。","漁業補償として1932年に «庄川養魚場» が開かれ、サケやマスのふ化・放流が行われるようになりました。","岐阜県側の道路整備が電力会社の負担で行われ、費用から «百万円道路» と呼ばれました。今の国道156号の前身です。","争議は文学の題材にもなり、高見順の短編『流木』、三島由紀夫の短編『山の魂』などが知られます。","最近はダムの点検通路で日本酒やみそを熟成させる試みも行われ、産業遺産の新しい使い方として話題になっています。"],"look":["17門のゲートが並ぶ堤体の全景","右岸の魚道、左岸の木材運搬設備のあと","小牧港から出る庄川遊覧船（ダム湖を大牧温泉方面へ）","下流の展望広場から見上げるダム"],"q":["庄川流木争議で、ダムに反対したのはどんな人たち？","川に丸太を流して運んでいた木材業者です。ダムで川がせき止められると木が運べなくなるためでした。"],"koji":[],"myth":"«東洋一» は完成当時の高さについての表現。争議の経過は資料により細部の書き方が異なる。","img":["庄川","浅野総一郎","物部長穂"],"wp":"小牧ダム","rel":{"ev":[],"grave":[]},"ph":[["c:8/8a/Komaki_Dam_right_view.jpg",3240,4320,"小牧ダム"],["c:2/29/Komaki_power_station_penstock.jpg",3814,2862],["c:b/b4/Komaki_power_station.jpg",2559,1919],["c:0/02/Shogawa_Yuransen_Noriba.jpg",2048,1536],["c:6/6c/Komaki_Damsite.jpg",2048,1536],["c:3/3c/Komaki_Damsite-2.jpg",2048,1536],["c:1/1b/Sho_River_from_Shirakawago.jpg",1920,1280,"庄川"],["c:8/84/Asano_S%C5%8Dichir%C5%8D.jpg",1573,2368,"浅野総一郎"]]},{"id":"16_kushu","n":"富山大空襲の跡（城址公園と松川）","yomi":"とやまだいくうしゅうのあと","cat":"昭和","rank":"A","y":1945,"era":["showa"],"sh":"","ad":"富山市本丸（富山城址公園）","st":"JR富山駅から歩いて約10分。市内電車 «国際会議場前» からすぐ","la":36.6932,"lo":137.2098,"hook":"1945年8月2日の未明、爆撃の目印にされたのは、富山城跡の東南の角だった。","lead":"太平洋戦争の終わり近く、1945年8月1日の夜から2日の未明にかけて、アメリカ軍のB-29が富山市を焼夷弾で攻撃しました。町の中心部はほとんど焼け野原になり、2,000人をこえる人が亡くなりました。城址公園とそばを流れる松川は、その記憶をとどめる場所です。","story":["8月2日の午前0時すぎ、空襲警報が鳴りました。空は晴れていました。町は明かりを消していましたが、先頭の飛行機が照明弾を落とし、地上を明るく照らします。その目印の中心は、富山城跡の東南の角でした。«なぜお城が?» それは、町の真ん中を示すのにちょうどよい場所だったからです。","攻撃に来たB-29は170機をこえ、落とされた焼夷弾は数十万発にのぼると計算されています。火は «地をはい、空にくるった» と市の歴史書は書いています。消火を続けようとした人たちも、この火の勢いにはかないませんでした。","逃げ場を求めて、人びとは川や河原へ向かいました。城の堀の名残である松川にも、火をさけて身を沈めた人がいたと伝えられます。町なかで救助にあたった兵士たちも、松川の水に体をひたしながら行き来したと記録されています。","夜が明けると、町の中心で形を残していた建物は、県庁や電気ビル、百貨店など、ほんのわずかでした。亡くなった人の数は資料によって2,200人台から2,700人近くまで幅があり、名前がわかっていない人も少なくありません。","戦後、富山の町は広い道路を通して新しく生まれ変わりました。城址公園には1974年、平和と復興を願う «天女の像» が建てられました。公園を歩き、松川べりを歩くとき、この場所で起きたことと、亡くなった人びとのことを静かに思い出してほしいと思います。"],"tl":[["1945年8月1日","アメリカ軍が富山・長岡・水戸・八王子の4都市への攻撃を命令"],["1945年8月2日未明","B-29が富山市を焼夷弾で攻撃。市街地の大部分が焼失"],["1945年9〜10月","寺や学校で合同の追悼法会が行われる"],["1946年8月1日","第一回の復興祭。富山大橋から流し火で霊を慰める"],["1954年","城址公園で富山産業大博覧会。模擬天守が建てられる"],["1966年","戦災復興事業の完成式"],["1974年8月1日","城址公園に戦災復興記念像（天女の像）が建てられる"]],"who":[["富山の市民","空襲で家や家族を失い、焼け野原から町を立て直した"],["歩兵第514聯隊の兵士","空襲の中で消火や救助にあたり、戦死者も出た"],["第20航空軍（アメリカ軍）","B-29による日本の都市への攻撃を指揮した"]],"deep":["この夜、アメリカ軍は富山・長岡・水戸・八王子の4都市を同時に攻撃しました。4都市の中で、富山に来た機数が最も多かったとされます。","米軍は «目標地域の99.5%を破壊» と報告しました。これは米軍が決めた目標地域についての数字で、町全体の焼失率そのものではない、という指摘があります。","焼け残った数少ない建物の一つが富山電気ビル（1936年完成）です。戦後は進駐した米軍に一時接収されました。","市街地の外にあった工場の多くは、ほとんど被害を受けませんでした。焼かれたのは主に人びとが暮らす町だったのです。","毎年8月の北日本新聞納涼花火は、1946年に神通川の河原で行われた犠牲者の供養がもとになったといわれます。","氷見市の島尾海岸には犠牲者の遺体が流れ着き、地元の人びとが葬って、今も慰霊が続けられています。"],"look":["城址公園の戦災復興記念像（天女の像）","空襲の目印とされた城跡の東南の角あたり","松川べりの遊歩道（堀の名残の川）","焼け残った富山電気ビル（外観）"],"q":["富山大空襲で、爆撃の目印（中心点）にされたのはどこ？","富山城跡の東南の角です。町の中心を示す目印として使われました。"],"koji":[],"myth":"死者数は資料によって2,275人〜2,695人などの差があり、実際は3,000人近いという見方もある。松川で亡くなった人の話は証言として伝わるもの。","img":["富山城","焼夷弾","B-29 (航空機)"],"wp":"富山大空襲","rel":{"ev":[],"grave":[]},"ph":[["c:2/2e/Bombing_of_Toyama%2811%29.jpg",2477,2393,"富山大空襲"],["c:4/4a/THE_KITANIPPON_SHIMBUN%2821%29.jpg",3152,4304],["c:c/cf/THE_KITANIPPON_SHIMBUN%2813%29.jpg",3168,4312],["c:4/45/THE_KITANIPPON_SHIMBUN%2812%29.jpg",3152,4328],["c:1/1d/Memorial_Peace_monument_in_Toyama%2C_Toyama.jpg",3024,4032],["c:7/70/Bombing_of_Toyama%2818%29.jpg",2973,4225],["c:1/17/THE_KITANIPPON_SHIMBUN%282%29.jpg",2305,3156],["c:e/ed/THE_KITANIPPON_SHIMBUN%2811%29.jpg",2692,2548]]},{"id":"16_amaharashi","n":"雨晴海岸（義経岩の伝承）","yomi":"あまはらしかいがん","cat":"伝承","rank":"A","y":1187,"era":["nara","heian"],"sh":"","ad":"高岡市太田（雨晴）","st":"JR氷見線・雨晴駅から歩いて約5分","la":36.828,"lo":137.0187,"hook":"海の向こうに3000m級の立山連峰。その手前の小さな岩で、源義経が «雨の晴れるのを待った» と伝わる。","lead":"雨晴海岸は、富山湾ごしに立山連峰が見える、県を代表する景色の場所です。«雨晴» という名前は、源義経が奥州へ逃げる途中、岩かげでにわか雨がやむのを待ったという言い伝えから来ています。奈良時代には大伴家持がこの浜辺を歌に詠みました。","story":["兄の源頼朝と対立した源義経は、北陸道を通って奥州・平泉へ逃げたと伝えられています。山伏の姿に身をかえ、弁慶たちわずかな家来とともに旅をしていました。その一行がこの浜にさしかかったとき、急に雨が降り出しました。","«殿、しばしあの岩のかげへ»。弁慶は大きな岩を持ち上げ、その下で義経を雨宿りさせたといいます。やがて雨は晴れ、一行は旅を続けました。この話から、岩は «義経岩»、あたりは «雨晴» と呼ばれるようになったと伝わります。もちろん、史料で確かめられる話ではありません。","じつはこの浜辺は、義経よりずっと前から歌に詠まれていました。奈良時代、越中の国守として赴任した大伴家持は、このあたりの «渋谿（しぶたに）» の磯を愛し、«馬並めて いざ打ち行かな 渋谿の 清き磯廻に 寄する波見に» と詠みました。«みんなで馬を並べて、波を見に行こう» という、わくわくした歌です。","今、義経岩の上には小さな «義経社» がまつられています。岩のすぐそばをJR氷見線の列車が走り、海には «女岩» という松の生えた小島がぽつんと浮かびます。冬の晴れた朝には、海から湯気が立つ «けあらし» と、白い立山連峰がいっしょに見られることもあります。","«なぜ、義経の伝説がここに?» 北陸には義経の逃避行にまつわる伝承地がいくつもあり、近くの伏木には弁慶が義経を扇で打って関所を通った «如意の渡し» の話も残ります。人びとは、美しい景色と悲劇の英雄の物語を重ね合わせてきたのです。"],"tl":[["746年","大伴家持が越中守として赴任。のちに渋谿の磯を歌に詠む"],["1187年ごろ","義経一行が北陸道を通って奥州へ向かったと伝わる（伝承）"],["江戸時代","義経岩と «雨晴» の地名の由来が語り継がれる"],["明治〜大正時代","海岸沿いに鉄道（今の氷見線）が通り、景勝地として知られるようになる"],["2014年","雨晴海岸を含む富山湾が «世界で最も美しい湾クラブ» に加盟"]],"who":[["源義経","奥州へ逃げる途中、岩かげで雨宿りしたと伝わる"],["武蔵坊弁慶","義経の家来。岩を持ち上げて雨宿りさせたと伝わる"],["大伴家持","越中の国守。この浜辺（渋谿）を歌に詠んだ"]],"deep":["義経の北陸落ちは『義経記』などの軍記物に描かれますが、ルートや出来事の多くは物語としての性格が強く、史実として確かめるのは難しいとされます。","家持が詠んだ «渋谿» は、今の雨晴から太田にかけての海岸とされます。万葉集の越中の歌は、地名が今も特定できるものが多いのが特徴です。","沖の «女岩» と、手前の «男岩» など、小さな島や岩礁が多いのがこの海岸の景観の特徴です。","雨晴海岸は能登半島国定公園に含まれ、«日本の渚百選» にも選ばれています。","氷見線の越中国分〜雨晴間は海岸線ぎりぎりを走るため、鉄道写真の名所としても知られ、青春18きっぷのポスターにも使われました。"],"look":["義経岩と岩の上の義経社","沖に浮かぶ女岩と、背後の立山連峰（晴れた日）","冬の朝の «けあらし»","道の駅雨晴からの展望"],"q":["«雨晴» という地名は、だれの伝説から生まれた？","源義経です。岩かげでにわか雨が晴れるのを待ったと伝わります。"],"koji":[{"w":"判官びいき","m":"弱い立場の人や悲運の人に同情し、味方したくなる気持ち。義経（判官）への同情から生まれたことば"}],"myth":"義経の雨宿りと弁慶が岩を持ち上げた話は伝承で、史実としては確かめられない。","img":["源義経","大伴家持","氷見線"],"wp":"雨晴海岸","rel":{"ev":[],"grave":[]},"ph":[["c:8/8c/Himi-line-amaharashi.jpg",3884,2600,"雨晴海岸"],["c:c/c1/AmeharashiSeaside.JPG",4000,3000],["c:f/f5/Tateyama_Mountains_and_Onna-iwa_viewed_from_Amaharashi_Coast_20190309134344.jpg",10200,2274],["c:7/7d/Minamoto_no_Yoshitsune.jpg",1440,1724,"源義経"],["c:3/3e/Sanj%C5%ABrokkasen-gaku_-_5_-_Kan%C5%8D_Tan%E2%80%99y%C5%AB_-_Ch%C5%ABnagon_Yakamochi.jpg",1000,1450,"大伴家持"],["c:9/9d/JRW_Himi-line_Kiha47-1015.jpg",5472,3648,"氷見線"]]},{"id":"16_sanson","n":"砺波平野の散居村","yomi":"となみへいやのさんきょそん","cat":"町","rank":"A","y":1650,"era":["azuchi","edo"],"sh":"","ad":"砺波市・南砺市ほか（砺波平野一帯）","st":"JR城端線・砺波駅のまわりから広がる。全体を見わたすなら、南砺市の閑乗寺公園など高台の展望地へ車で","la":36.625,"lo":136.955,"hook":"田んぼの海に、森の «島» がぽつぽつ浮かぶ。一つひとつの森の中に、一軒ずつ家がある。","lead":"砺波平野では、家がかたまって村をつくるのではなく、田んぼの中に一軒ずつ離れて建っています。これを «散居村» といいます。約220平方キロメートルに7,000戸ほどが散らばり、日本最大の散居村とされます。","story":["高いところから砺波平野を見下ろすと、ふしぎな景色が広がります。水を張った田んぼの中に、こんもりした木立がいくつも浮かび、その中に大きな屋根がのぞいています。«なぜ、みんなばらばらに住んでいるの?» ふつうの村なら、家は道ぞいに寄り集まっているはずです。","答えの一つは、川にあります。庄川は江戸時代より前、何度もあふれて流れを変えました。人びとは平野の中でも少し高い場所を選んで家を建て、そのまわりを田んぼにしました。自分の家のまわりに自分の田があれば、毎日の見回りも水の管理もしやすい。とても合理的な暮らし方だったのです。","江戸時代、この地を治めた加賀藩は、田んぼを割り当て直す政策を行いました。それでも農民たちは田を交換したりして、できるだけ家のまわりに自分の田を集めようとしたといわれます。こうして16世紀末から17世紀ごろ、今の景色の形ができていったと考えられています。","家を囲む木立は «カイニョ» と呼ばれる屋敷林です。冬の吹雪や夏の日ざしから家を守り、落ちた枝は燃料に、木は家を直す材料になりました。女の子が生まれるとキリを植え、嫁入りのたんすにしたともいいます。«土地を売ってもカイニョは売るな» ということばが残るほど、大切にされてきました。","けれども今、カイニョの手入れは高齢の家族には大変な仕事です。地域の人たちは手入れを手伝う仲間をつくり、この景色を守ろうとしています。春、チューリップの花と水田とカイニョが織りなす景色は、何百年もの暮らしの工夫がつくった «生きた文化財» なのです。"],"tl":[["中世","散居の形のはじまりはこのころまでさかのぼるとも考えられる"],["16世紀末〜17世紀","今の散居村の景観ができたと考えられる"],["江戸時代","加賀藩の田地割のもとでも、農民が家のまわりに田を集めようとした"],["昭和初期","地理学者の研究で、砺波の散村が全国に知られる"],["1990年代以降","屋敷林を守る取り組みや、となみ散居村ミュージアムの整備が進む"]],"who":[["砺波平野の農民","自分の田の中に家を建て、カイニョを育てて暮らしてきた"],["加賀藩（前田家）","江戸時代にこの地を治め、田地割などの農政を行った"],["小川琢治","京都帝国大学の地質学者。砺波の散村に初めて学問的に注目したとされる"]],"deep":["地理の教科書では «散村»、富山県内では «散居村» ということばが定着しています。«散村» は «山村» と音が同じでまぎらわしい、という事情もあります。","散村は世界的には珍しくなく、イギリスの大部分やフランス西部、北イタリアのポー川流域などにも見られます。日本では出雲平野、讃岐平野、胆沢扇状地なども知られます。","伝統的な家の形には、切妻屋根の妻側を正面にした «アズマダチ» と、平入りの «マエナガレ» があります。白い壁と木組みの «アズマダチ» は砺波の顔です。","カイニョにはスギが多く、クリ・カキ・ウメなど実のなる木も植えられました。«塩なめてもカイニョを守れ» ともいわれました。","散居の成立理由には、洪水、水利、加賀藩の政策、開墾の進め方など複数の説があり、一つに決まっているわけではありません。"],"look":["高台（閑乗寺公園など）から見る散居村の全景","アズマダチの家とカイニョの組み合わせ","となみ散居村ミュージアムの展示と古民家","春のチューリップ畑と水田の季節"],"q":["散居村の家を囲む屋敷林を、砺波の方言で何という？","«カイニョ» です。風雪をふせぎ、燃料や建材にもなりました。"],"koji":[],"myth":"散居村の起こりには諸説あり、時期も中世説・近世説がある。","img":["砺波平野","屋敷林","アズマダチ"],"wp":"散居村","rel":{"ev":[],"grave":[]},"ph":[["c:6/6a/Frutighaeuser.jpg",3091,2000,"散居村"],["c:3/34/Sankyoson.JPG",3648,2736],["c:d/d7/Azumadachi_Takase_2026-04_ac.jpg",1321,880],["c:5/5a/TonamiHeiya_Kanjouji.jpg",800,528],["c:f/f8/Aerial_photograph_of_Dispersed_settlement_in_Tonami_plain.jpg",720,540],["c:c/c3/20081207%E7%A0%BA%E6%B3%A2%E5%B9%B3%E9%87%8E.jpg",1280,960,"砺波平野"],["c:b/be/2015-12-17_Old_hous_in_Haterumajima_%E6%B3%A2%E7%85%A7%E9%96%93%E5%B3%B6%E9%9B%86%E8%90%BD%E5%8F%A4%E6%B0%91%E5%AE%B6_DSCF3199.JPG",2304,1536,"屋敷林"]]},{"id":"16_manyo","n":"高岡市万葉歴史館（国守大伴家持）","yomi":"たかおかしまんようれきしかん","cat":"学び","rank":"A","y":746,"era":["nara"],"sh":"","ad":"高岡市伏木一宮","st":"JR氷見線・伏木駅から歩いて約25分。バスも利用できる","la":36.7925,"lo":137.052,"hook":"万葉集の歌の、およそ10首に1首はこの人の作。その歌人が5年間くらした町に、万葉集だけの博物館がある。","lead":"高岡市万葉歴史館は、万葉集と、越中の国守だった大伴家持をテーマにした博物館です。家持は奈良時代に約5年間この地にくらし、たくさんの歌を詠みました。館は1990年、越中国府があったとされる伏木に開かれました。","story":["746年、29歳ほどの若い貴族が、都から越中へやって来ました。大伴家持。越中国の «国守»、つまり今でいう県知事のような役人です。都育ちの彼にとって、雪深い北国はまったく知らない世界でした。","けれども家持は、この土地の自然に強く心を動かされます。海の向こうにそびえる雪の山を見て、«立山に 降り置ける雪を 常夏に 見れども飽かず 神からならし» と詠みました。夏になっても消えない雪、いくら見てもあきない、きっと神の山だからだろう、という意味です。","春には、«春の苑 紅にほふ 桃の花 下照る道に 出で立つ娘子» という、色あざやかな歌も生まれました。桃の花の赤に照らされた道に、少女が立っている。まるで一枚の絵のようです。«なぜ越中で、こんなに歌が生まれたの?» 都を離れたさびしさ、新しい景色への驚き、仲間との宴。それらが家持の歌を豊かにしたと考えられています。","家持は751年に都へもどりましたが、越中で詠んだ歌は220首をこえます。のちに家持は万葉集をまとめた中心人物の一人と考えられるようになり、越中の歌はその大切な一部になりました。","万葉歴史館では、こうした歌の世界を映像や模型でわかりやすく紹介しています。庭には万葉集に出てくる植物が約70種類植えられ、歌に出てくる花を実際に見ることができます。館を出て、家持が見たのと同じ海と山をながめてみてください。"],"tl":[["746年","大伴家持が越中守として赴任"],["747年","家持が «立山賦» を詠む"],["750年","«春の苑 紅にほふ…» の歌を詠む"],["751年","家持が少納言となって都へもどる"],["759年","万葉集の最後の歌を因幡で詠む"],["1990年","高岡市万葉歴史館が開館"]],"who":[["大伴家持","越中国守。越中で220首をこえる歌を詠み、万葉集の編者と考えられる"],["大伴池主","家持の部下で親族ともいわれる。越中で家持と多くの歌をやりとりした"],["大伴坂上大嬢","家持の妻。越中にも来たと考えられている"]],"deep":["万葉集の約4,500首のうち、家持の歌は約470首ともっとも多く、そのうち越中時代の歌が大きな割合を占めます。","越中国府は、伏木の勝興寺のあたりにあったと考えられています。歴史館は国府跡とされる場所に近い台地の上にあります。","越中の歌には «立山（たちやま）»«渋谿»«奈呉の海»«二上山» など今もわかる地名が多く、歌の舞台を歩く楽しみがあります。","«立山» の読みは万葉集では «たちやま» と考えられています。家持の «立山賦» は、立山を詠んだ最古の文学ともいわれます。","館は高岡市の市制百周年記念事業として1989年に着工、1990年10月に開館しました。"],"look":["家持の越中時代を紹介する常設展示と映像","万葉集の植物が植えられた «四季の庭»","屋上から見る伏木の町と二上山","近くの勝興寺（越中国府跡とされる）と組み合わせて歩く"],"q":["大伴家持が越中国守として過ごしたのは約何年間？","約5年間（746〜751年）です。その間に220首をこえる歌を詠みました。"],"koji":[{"w":"海ゆかば","m":"家持の長歌の一節。のちに曲がつけられ、戦時中に広く歌われた"}],"myth":"家持の越中での歌数は数え方により220〜223首などとされる。越中国府の正確な位置は発掘で確定しきっていない。","img":["大伴家持","万葉集","勝興寺"],"wp":"高岡市万葉歴史館","rel":{"ev":[],"grave":[]},"ph":[["c:3/3e/Sanj%C5%ABrokkasen-gaku_-_5_-_Kan%C5%8D_Tan%E2%80%99y%C5%AB_-_Ch%C5%ABnagon_Yakamochi.jpg",1000,1450,"大伴家持"],["c:a/ae/Genryaku_Manyosyu.JPG",1333,1000,"万葉集"],["c:5/5a/Fushiki_Shokoji_main_hall_ac.jpg",5863,3899,"勝興寺"]]},{"id":"16_tateyama_museum","n":"富山県［立山博物館］（立山曼荼羅）","yomi":"とやまけんたてやまはくぶつかん","cat":"学び","rank":"A","y":1700,"era":["edo"],"sh":"","ad":"中新川郡立山町芦峅寺","st":"富山地方鉄道立山線・千垣駅から歩いて約30分。車が便利","la":36.5827,"lo":137.3935,"hook":"地獄も極楽も、立山の中にある。江戸の人びとをひきつけた一枚の絵が、この村から全国へ運ばれた。","lead":"富山県［立山博物館］は、立山信仰の村・芦峅寺にある博物館です。地獄と極楽を描いた «立山曼荼羅» や、剱岳の山頂で見つかった錫杖の頭など、立山と人びとの関わりを伝える品々を見ることができます。","story":["むかしの人にとって、立山はただの高い山ではありませんでした。煙を上げる地獄谷は «地獄»、美しい弥陀ヶ原は «極楽»。死んだ人の魂が集まる、この世とあの世の境の山だと考えられていたのです。","伝承では、奈良時代の初めに佐伯有頼という若者が、白い鷹を追って山に入り、傷ついた熊を追ううちに阿弥陀如来に出会い、立山を開いたとされます。«熊だと思って射た矢が、仏さまの胸にささっていた» という、ふしぎな話です。","江戸時代、芦峅寺の村には30をこえる宿坊があり、衆徒と呼ばれる人びとが立山信仰を広めていました。冬になると衆徒たちは全国へ出かけ、お札を配りながら大きな絵を広げて語りました。これが «立山曼荼羅» です。«悪いことをすると、こんな地獄に落ちるぞ»。絵を指さしながらの話に、人びとは息をのんだことでしょう。","立山は長く女人禁制の山でした。そこで女性の救いのために行われたのが «布橋灌頂会» です。白い布を敷いた橋を、目かくしをした女性たちが渡り、あの世からこの世へ生まれ変わる体験をしたといいます。明治時代にとだえましたが、今は再現され、数年に一度行われています。","博物館は展示館のほか、閻魔堂、布橋、宿坊などが村の中に点在する «広域分散型»。村を歩くこと自体が見学になります。展示館の設計は建築家の磯崎新で、らせん階段は立山の «雪の大谷» をイメージしているといわれます。"],"tl":[["701年","佐伯有頼が立山を開いたと伝わる（伝承）"],["1230年","銅造帝釈天立像がつくられる（銘による）"],["江戸時代","芦峅寺の衆徒が立山曼荼羅を手に全国で布教"],["明治初め","神仏分離で立山の寺院組織が解体され、布橋灌頂会もとだえる"],["1907年","陸地測量部の柴崎芳太郎が剱岳山頂で銅錫杖頭を発見"],["1972年","立山風土記の丘として開館"],["1991年","富山県立山博物館として開館"]],"who":[["佐伯有頼","立山を開いたと伝わる人物（伝承）"],["芦峅寺の衆徒","宿坊を営み、立山曼荼羅の絵解きで全国に信仰を広めた"],["柴崎芳太郎","剱岳に登頂し、山頂で古い錫杖頭を見つけた測量官"],["磯崎新","展示館を設計した建築家"]],"deep":["館名は «とやまけんりつ・やまはくぶつかん» と読みまちがえられないよう、«富山県［立山博物館］» と角かっこをつけて書きます。","剱岳山頂の銅錫杖頭は国の重要文化財。«未踏峰» と思われた剱岳に、はるか昔に登った人がいたことを示しました。新田次郎の小説『劒岳 点の記』はこの登頂を題材にした作品です。","立山信仰用具1,243点が国の重要有形民俗文化財に指定されています。","閻魔堂の仏像群は富山県指定文化財。布橋の手前にある閻魔堂で罪を懺悔してから橋を渡る、という流れになっていました。","敷地内の旧嶋家住宅は、猪谷の関所近くにあった江戸時代の商家で、国の重要文化財です。","立山曼荼羅は芦峅寺系と岩峅寺系があり、描かれる場面や構図にちがいがあるとされます。"],"look":["展示館の立山曼荼羅（地獄と極楽の描き分け）","閻魔堂と、姥堂川にかかる朱色の布橋","宿坊・教算坊の建物","まんだら遊苑（曼荼羅の世界を体感する施設）"],"q":["立山曼荼羅は、何のために使われた？","衆徒が全国を回って、地獄や極楽の様子を絵解きし、立山信仰を広めるために使いました。"],"koji":[],"myth":"佐伯有頼の開山は伝承。布橋灌頂会の開催周期は近年3年に一度とされるが、変わることがある。","img":["立山曼荼羅","芦峅寺","布橋灌頂会"],"wp":"富山県立山博物館","rel":{"ev":[],"grave":[]},"ph":[["c:1/15/Tateyama-museum_toyama-pref.jpg",2803,2102,"富山県立山博物館"],["c:a/a9/Chuuguu-kiganden_Haiden.JPG",2352,1568,"芦峅寺"]]},{"id":"16_maibotsurin","n":"魚津埋没林博物館","yomi":"うおづまいぼつりんはくぶつかん","cat":"学び","rank":"B","y":0,"era":["yayoi"],"sh":"国の特別天然記念物（魚津埋没林）","ad":"魚津市釈迦堂","st":"富山地方鉄道・電鉄魚津駅から歩いて約20分。あいの風とやま鉄道・魚津駅からは車で約10分","la":36.8225,"lo":137.395,"hook":"海のすぐそばの地面の下から、約2000年前の森が根っこごと出てきた。","lead":"魚津の海岸の地下には、約2000年前のスギの森が埋もれています。これを «埋没林» といい、国の特別天然記念物です。博物館では、掘り出した巨大な根っこを、見つかった場所のまま水の中で見ることができます。","story":["1930年、魚津の港で海底の土砂をさらう工事をしていた人たちは、首をかしげました。«なんだ、この大きな木の根っこは?» 海のすぐそばの地面の下から、たくさんの切り株が出てきたのです。","調べてみると、それは約2000年前に生えていたスギの森でした。川がはこんできた土砂が森を埋め、その後、海面が上がったことで、森は海面より低いところに閉じこめられたと考えられています。水につかって空気にふれなかったため、木はくさらずに残りました。","1936年、この埋没林は国の天然記念物に指定されます。戦後の1952年には、博覧会にあわせて発掘が行われ、掘った場所をそのまま使って保存館がつくられました。いまの博物館は1992年に建て直されたものです。","水中展示館では、深さ2.5mのプールの中に、発掘された場所のまま樹根が沈んでいます。いちばん大きなものは、根の広がりが約10mもあり、樹齢500年以上の木だったといわれます。«弥生時代の森が、目の前にある»。上からも、地下の窓からものぞけます。","魚津は «蜃気楼の見える町» としても有名です。春、冷たい雪どけ水と暖かい空気がつくる条件がそろうと、海の向こうの町や船がのびたり、さかさまに見えたりします。博物館は蜃気楼の観測も続けていて、埋没林とあわせて «富山湾のふしぎ» を教えてくれます。"],"tl":[["約2000年前","スギの森が土砂に埋もれる"],["1930年","魚津港の工事中に大量の樹根が見つかる"],["1936年","«魚津の埋没林» として国の天然記念物に指定（のち特別天然記念物）"],["1952年","埋没林の発掘が行われる"],["1955年","魚津市立博物館として開館"],["1989年","指定地の発掘調査が行われる"],["1992年","今の魚津埋没林博物館が完成"],["2007年","魚津埋没林が «日本の地質百選» に選ばれる"]],"who":[["魚津港の工事の人びと","1930年、港の工事中に樹根を見つけた"],["博物館の学芸員","埋没林の保存と、毎年の蜃気楼観測を続けている"]],"deep":["水中展示館のプールは深さ2.5m、約240t。水は地下水をくみ上げていて、年末には水をぬいて清掃する «水のない埋没林» が公開されます。","ドーム館の壁には今の海面の高さが示され、2000年前の地面が今の海面より低いことを体感できます。","1990年につくられた «世界初の蜃気楼人工発生装置» を使ったシアターがありましたが、1997年に止められました。","博物館の学芸員は1990年代から毎年、蜃気楼の出現回数を記録し、見え方をA〜Eの5段階で評価して発表しています。","埋没林が残った理由（川の土砂・海面の上昇・地下水）の組み合わせについては、研究が続けられています。"],"look":["水中展示館の巨大な樹根（上と地下の窓の両方から）","乾燥展示館の、直接さわれる2000年前の木","ドーム館の «今の海面ライン»","春に海岸から見える蜃気楼（条件がそろった日）"],"q":["魚津の埋没林は、約何年前の森？","約2000年前のスギの森です。土砂に埋もれ、海面より低い場所に残りました。"],"koji":[],"myth":"森が埋もれた原因には複数の要因が考えられ、細かな過程は研究中。","img":["魚津埋没林","蜃気楼","魚津市"],"wp":"魚津埋没林博物館","rel":{"ev":[],"grave":[]},"ph":[["c:2/2d/Uozu_Buried_Forest_Museum_ac_%281%29.jpg",5839,3883,"魚津埋没林博物館"],["c:7/75/Uozu_Submerged_Forest.jpg",6000,4000],["c:d/d7/Uodu-maiboturin_mus_03.JPG",2592,1944],["c:d/d5/Uodu-maiboturin_mus_01.JPG",2592,1944],["c:c/c8/Great_Salt_Lake_Utah_USA3.jpg",3264,2448,"蜃気楼"],["c:5/52/Uozu_montage_2019.png",1184,2061,"魚津市"]]},{"id":"16_takase_iseki","n":"高瀬遺跡（東大寺領荘園の跡）","yomi":"たかせいせき","cat":"遺跡","rank":"A","y":800,"era":["nara","heian"],"sh":"国指定史跡","ad":"南砺市高瀬","st":"JR城端線・福野駅から車で約10分","la":36.542,"lo":136.925,"hook":"田んぼを整備していたら、1200年前の «役所のような建物» と、くねくね曲がる小川が出てきた。","lead":"高瀬遺跡は、平安時代の初めごろの建物のあとが見つかった遺跡です。荘園を管理した «荘所» のような建物と考えられ、奈良の東大寺がこの地方にもっていた荘園との関係が注目されています。今は史跡公園として整備されています。","story":["1970年、南砺市高瀬で田んぼの整備工事をしていたところ、土の中から古い柱のあとが見つかりました。翌年の発掘で、一辺10mほどの大きな建物のあとが3棟並んでいることがわかります。床を張った立派な建物でした。","まわりからは、土器のほか、文字を書いた木の札（木簡）、大きな硯、お坊さんが使う浄瓶、漆器、曲げ物などが出てきました。«こんな田舎に、なぜ役所のような建物が?» 手がかりは、奈良時代に砺波平野にあった東大寺の荘園です。","奈良時代、国は «開いた土地は自分のものにしてよい» という法を出しました。大きなお寺や貴族は、きそって新しい田を開きます。東大寺もその一つで、砺波の地にいくつもの荘園をもっていました。荘園には、米を集めたり働く人をまとめたりする管理所 «荘所» が置かれました。","高瀬の建物は、そうした荘所の一つではないかと考えられています。ただし、どの荘園のものかは決め手がなく、東大寺の «杵名蛭庄» の荘所だと認定するまでにはいたっていません。それでも、荘園の現場のようすを具体的に考えられる、とても貴重な遺跡です。","建物のまわりを曲がりくねって流れる小川も見つかりました。今、その流れにそって約4万株のハナショウブが植えられ、毎年6月には «菖蒲まつり» が開かれます。1200年前の役人も、この水辺をながめていたのかもしれません。"],"tl":[["743年","墾田永年私財法が出され、寺や貴族の開墾が進む"],["奈良時代","東大寺が砺波郡に荘園をもつ"],["平安時代初め","高瀬に床張りの大きな建物が建てられる"],["1970年","水田整備事業中に遺構が見つかる"],["1971年","発掘調査が行われる"],["1972年","国の史跡に指定"],["1973〜1974年","史跡公園として整備"],["2015年","公園内に南砺市埋蔵文化財センターがリニューアル開館"]],"who":[["東大寺","奈良の大寺。砺波郡に荘園をもっていた"],["荘園の役人・荘民","荘所で米や人の管理をし、田を耕した人びと"]],"deep":["建物は «5間×4間» の規模のものなど3棟が確認され、周囲の打ちこみ板の列や雨落ち溝から、役所風の建物だったことはほぼ確実とされます。","出土品には木簡、大型の硯、浄瓶、漆器、曲げ物のほか、焼き物の小さな塔（瓦塔）もあり、仏教的な要素もうかがえます。","建物群を囲むように蛇行する小川は «曲水» とも呼ばれ、ただの排水路か、景観を意識したものかが興味をひきます。","遺跡の東約300mでは、同じころの集落のあとも見つかっています。荘所と働く人びとの村の関係を考える手がかりです。","正倉院には越中の東大寺荘園の絵図が伝わっていて、文献と遺跡を組み合わせて荘園の姿を考えられる点が、この地域の研究の強みです。"],"look":["建物の柱の位置を示した史跡公園","くねくねと流れる小川（曲水）とハナショウブ（6月）","南砺市埋蔵文化財センターの出土品の展示","近くの越中一宮・高瀬神社"],"q":["高瀬遺跡の建物は、何のための施設と考えられている？","荘園を管理する «荘所» のような役所風の建物と考えられています。"],"koji":[{"w":"墾田永年私財法","m":"743年に出された法。新しく開いた田を永久に自分のものにしてよいとし、荘園が広がるきっかけになった"}],"myth":"東大寺のどの荘園の荘所かは確定していない（杵名蛭庄説などがある）。","img":["荘園","東大寺","高瀬神社"],"wp":"高瀬遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:5/58/Takase_iseki_Park.jpg",768,576,"高瀬遺跡"],["c:a/a7/%E6%9D%B1%E5%A4%A7%E5%AF%BA_%E5%A4%A7%E4%BB%8F%E6%AE%BF%EF%BC%882024%E5%B9%B4%EF%BC%89.jpg",4032,3024,"東大寺"],["c:d/d4/Takase_Shrine_haiden.jpeg",1730,1127,"高瀬神社"]]},{"id":"16_sakai_a","n":"境A遺跡（ヒスイと蛇紋岩の工房）","yomi":"さかいえーいせき","cat":"遺跡","rank":"A","y":-2500,"era":["jomon"],"sh":"出土品が国の重要文化財","ad":"下新川郡朝日町境","st":"あいの風とやま鉄道・越中宮崎駅から歩いて約45分。遺跡の上は高速道路で、現地に見学施設はない","la":36.9703,"lo":137.6144,"hook":"新潟との県境近く。縄文人はここで、海岸のヒスイをみがいて玉にし、石斧を大量につくっていた。","lead":"境A遺跡は、富山県の東のはし、新潟県との境近くにある縄文時代の遺跡です。ヒスイの玉や蛇紋岩の磨製石斧をつくった «工房» のあとが見つかり、出土品2,432点が国の重要文化財になっています。","story":["1984年と1985年、北陸自動車道をつくる前の発掘調査で、朝日町境の丘から驚くほどの量の出土品が見つかりました。縄文土器だけで平箱7,000箱分。あわせて約8,000箱という、とてつもない量です。","中でも注目されたのが、ヒスイと蛇紋岩です。すぐ東の新潟県糸魚川は、日本有数のヒスイの産地。川から海へ流れ出たヒスイは、この辺りの海岸でも拾うことができます。縄文人は、緑に光るかたい石を根気よくみがき、穴をあけて玉に仕上げました。«どうやって、あんなにかたい石に穴を?» 砂と水、そして長い時間をかけたと考えられています。","蛇紋岩からは、木を切るための磨製石斧がたくさんつくられました。作りかけのもの、失敗したもの、完成品。工程ごとの石が残っていたおかげで、石斧づくりの手順がくわしくわかりました。","ここでつくられた玉や石斧は、自分たちで使うだけでなく、遠くの村へも運ばれたと考えられています。縄文時代にも、人と物が行き来する «ネットワーク» があったのです。境A遺跡は、その出発点の一つでした。","遺跡には縄文時代中期から後期の建物のあと34棟や、1,500基もの穴のあとも見つかり、長いあいだ人が住み続けた村だったこともわかりました。今、遺跡の上には高速道路が通っています。けれども出土品が、この丘で石をみがき続けた人びとの姿を今に伝えています。"],"tl":[["縄文時代早期〜前期","このころの土器片も見つかり、人の活動が始まる"],["縄文時代中期〜晩期","ヒスイの玉や蛇紋岩の石斧づくりがさかんになる"],["平安時代〜中世","製塩のあとや掘立柱建物が営まれる"],["1984〜1985年","北陸自動車道の建設に先立って発掘調査"],["1999年","出土品2,432点が国の重要文化財に指定"]],"who":[["縄文の工人たち","ヒスイを玉に、蛇紋岩を石斧に加工した人びと"],["発掘調査の関係者","高速道路建設前の調査で、膨大な出土品を記録した"]],"deep":["重要文化財の内訳は、玉製作関係932点、磨製石斧製作関係583点、土器・土製品77点、石器・石製品833点です。","遺跡の範囲は約45,000㎡、そのうち約12,000㎡が調査されました。旧石器時代から中世・近世にまでおよぶ複合遺跡です。","クリ材の柱の根元が約10本見つかっているほか、焼けた鳥・獣・魚の骨やサメの歯も出土し、食べ物の手がかりになっています。","近くの宮崎・境海岸は «ヒスイ海岸» とも呼ばれ、今もヒスイが拾えることがあります。遺跡の立地と原料の近さがよくわかります。","蛇紋岩の磨製石斧は北陸から中部・関東方面でも見つかっていて、どこまで運ばれたかが研究のテーマになっています。"],"look":["出土品の展示（朝日町・富山県の施設で公開されることがある）","近くの宮崎・境海岸（ヒスイ海岸）の石の浜","遺跡のあった丘と大谷川のまわりの地形"],"q":["境A遺跡で縄文人が加工していた、緑色のかたい宝石は？","ヒスイです。近くの糸魚川方面が産地で、玉に加工されました。"],"koji":[],"myth":"製品がどこまで運ばれたかは研究が続いている。","img":["翡翠","宮崎・境海岸","磨製石器"],"wp":"境A遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:2/28/%E6%AD%B4%E5%8F%B2%E3%82%92%E5%A4%89%E3%81%88%E3%81%9F%E3%83%92%E3%82%B9%E3%82%A4.jpg",2639,2748,"翡翠"],["c:7/72/%E5%AE%AE%E5%B4%8E%E3%83%BB%E5%A2%83%E6%B5%B7%E5%B2%B8.jpg",960,720,"宮崎・境海岸"],["c:6/6b/N%C3%A9olithique_0001.jpg",2560,1704,"磨製石器"]]},{"id":"16_kurobe2","n":"黒部川第二発電所（宇奈月）","yomi":"くろべがわだいにはつでんしょ","cat":"近代","rank":"A","y":1936,"era":["taisho","showa"],"sh":"","ad":"黒部市宇奈月町黒部奥山（猫又付近）","st":"黒部峡谷鉄道のトロッコ電車の車窓から、猫又駅付近の対岸に見える。建物の中は非公開","la":36.775,"lo":137.622,"hook":"けわしい谷底に、まっ白な四角い建物。昭和のはじめ、峡谷に «モダン建築» が現れた。","lead":"黒部川第二発電所は、1936年に運転を始めた水力発電所です。上流の小屋平ダムから水を引いて電気をおこします。建物は建築家・山口文象の設計で、峡谷の景色にとけこむ白い姿が今も車窓から見られます。","story":["話は大正時代にさかのぼります。1919年、黒部川の水の力でアルミニウムをつくろうと «東洋アルミナム» という会社が生まれました。アルミをつくるには、ものすごい量の電気が必要だからです。会社は黒部川の水利権を手に入れ、海ぞいの三日市から山のほうへ鉄道をのばしていきました。","その後、開発は大手の電力会社 «日本電力» に引きつがれます。まず下流に柳河原発電所をつくり、次の目標が第二発電所でした。1929年にはトロッコの線路が小屋平までのびますが、ちょうどそのころ世の中は大不況。«電気が売れないなら、工事は止めるしかない»。工事はいったん中断されてしまいます。","1932年ごろから景気がもち直すと、今度は電気が足りなくなりました。1933年、工事は再開。ダムや取水口、トンネル、発電所の建物を4つの建設会社が分担し、すでにトロッコで資材を運べたこともあって、工事は順調に進みました。1936年10月、発電所は運転を始めます。","ダムの場所をめぐっては、こんな話もあります。もとは約1km上流につくる予定でしたが、それでは名勝 «猿飛峡» が水の底に沈んでしまう。専門家が現地を調べ、今の位置に変えたのです。電気と景色、どちらも大切にしようという判断でした。","白い4階建ての発電所は、四角い窓が並ぶシンプルなデザインで、ダムも同じ建築家が手がけました。«なぜ山奥の発電所に、ここまでデザインを?» 峡谷の景観との調和を考えたからだといわれます。2003年には、日本のモダン建築を代表する作品の一つに選ばれました。"],"tl":[["1919年","東洋アルミナムが設立される"],["1922年","東洋アルミナムが日本電力の傘下に入る"],["1927年","下流の柳河原発電所が完成"],["1929年","線路が小屋平までのびるが、不況で工事が中断"],["1933年","工事が再開される"],["1936年10月","黒部川第二発電所が運転を開始"],["1951年","戦後の電力再編で関西電力が引きつぐ"],["2003年","発電所と小屋平ダムがDOCOMOMO JAPANに選ばれる"]],"who":[["山口文象","発電所の建物と小屋平ダムのデザインを手がけた建築家"],["日本電力","黒部川の電源開発を進め、第二発電所を建設した"],["東洋アルミナム","アルミ生産のため黒部川開発を始めた会社。のち日本電力に合併"]],"deep":["発電所には3台のフランシス水車発電機があり、小屋平ダムからの水で最大7万2,000kWを発電します。","工事は大林組（ダム・取水口）、間組と鉄道工業（導水路トンネル）、大倉土木（水槽・発電所）の4社が分担しました。","小屋平ダムは土砂がたまる «堆砂» が深刻で、2000年度の調査では堆砂率95%。全国の大きなダムの中で2番目の高さでした。","少し上流には、黒部ダム完成後につくられた新黒部川第二発電所がありますが、設備は地下にあるため外からはほとんど見えません。","宇奈月温泉は、この電源開発と鉄道の建設とともに開かれた温泉町です。上流の温泉からお湯を引く管をめぐって起きた «宇奈月温泉事件» は、«権利の濫用» の判例として法律の教科書に必ず出てきます。","山口文象の設計した小屋平ダムのデザインは、のちの仙人谷ダムにも引きつがれました。"],"look":["トロッコ電車の車窓から見る白い発電所の外観（猫又駅付近）","小屋平駅付近で見える小屋平ダムの天端","宇奈月駅前の黒部川電気記念館で電源開発の歴史を学ぶ"],"q":["黒部川の電源開発を最初に始めた会社は、何をつくるために電気が必要だった？","アルミニウムです。アルミの生産には大量の電気が必要でした。"],"koji":[{"w":"権利の濫用","m":"形の上では権利があっても、他人を害するような使い方は許されないという考え方。宇奈月温泉事件の判決で知られる"}],"myth":"","img":["小屋平ダム","山口文象","宇奈月温泉"],"wp":"黒部川第二発電所","rel":{"ev":[],"grave":[]},"ph":[["c:9/95/KEPCO_Koyadaira_Dam.jpg",5472,3648,"小屋平ダム"],["c:e/e9/%E5%B1%B1%E5%8F%A3%E6%96%87%E8%B1%A1.jpg",380,380,"山口文象"],["c:e/e7/Unaduki_Onsens.jpg",1200,900,"宇奈月温泉"]]},{"id":"16_tateyama_caldera","n":"立山カルデラ（鳶山崩れ）","yomi":"たてやまかるでら","cat":"伝承","rank":"A","y":1858,"era":["edo","showa"],"sh":"国の重要文化財（白岩堰堤砂防施設）","ad":"中新川郡立山町芦峅寺（立山カルデラ内）","st":"一般の立ち入りは制限。立山駅近くの立山カルデラ砂防博物館が行う見学会（申込制）で入れる","la":36.555,"lo":137.545,"hook":"江戸時代の大地震で山がまるごと崩れた。その土砂は、今も富山平野の上に «ぶらさがって» いる。","lead":"立山カルデラは、立山の西側にある東西約6.5km、南北約5kmの大きなくぼ地です。1858年の飛越地震で鳶山が大きく崩れ、その土砂が下流に大災害をもたらしました。今も大量の土砂が残り、砂防工事が続けられています。","story":["1858年の春の夜、飛騨と越中の境あたりを震源とする大きな地震が起きました。«飛越地震» です。立山カルデラの南の «大鳶山»«小鳶山» は、この揺れで山ごと崩れ落ちました。これを «鳶山崩れ» といいます。","崩れた土砂はカルデラの中にあった立山温泉をのみこみ、湯治の客や働いていた人が亡くなりました。さらに土砂は常願寺川の上流をせき止め、大きな «天然のダム» をつくってしまいます。","加賀藩と富山藩は見張りを置き、住民を避難させる対策をとりました。«いつ切れるのか»。人びとはおびえながら山を見上げたことでしょう。そして地震から約2週間後と2か月後、天然ダムは2度にわたって決壊します。泥と岩の洪水が平野をおそい、多くの田畑や家が流され、たくさんの命が失われました。","明治以降も、常願寺川は土砂をはこびつづけました。富山県は1906年に砂防工事を始めますが、せっかくつくった堰堤も何度もこわされます。1926年からは国が直接工事を行うことになり、1939年に完成した白岩堰堤は、高さ63m、落差108mという日本一の規模をほこります。","«なぜ今も工事が続いているの?» それは、カルデラの中に約2億立方メートル、黒部ダムの貯水量ほどもの土砂が残っているからです。もし一度に流れ出せば、富山平野が1〜2mも埋まるといわれます。雪の少ない季節だけの工事が、今も毎年くり返されています。"],"tl":[["約22万年前","立山西側での火山活動が始まる"],["1858年4月9日","飛越地震が起き、鳶山崩れが起こる"],["1858年4月・6月","常願寺川の天然ダムが2度決壊し、下流に大被害"],["1906年","富山県が砂防工事に着手"],["1926年","国の直轄事業となる"],["1931年","砂防工事用のトロッコ軌道が開通"],["1939年","白岩堰堤が完成"],["2009年","白岩堰堤砂防施設が国の重要文化財に指定"]],"who":[["加賀藩・富山藩","天然ダムの見張りと住民の避難対策にあたった"],["立山温泉の人びと","鳶山崩れの土石流で命を落とした"],["幸田文","砂防の現場を訪れ、随筆『崩れ』に書いた作家"]],"deep":["以前は約10万年前の噴火でできた «陥没カルデラ» と考えられていましたが、今は崩壊と侵食でできた «侵食カルデラ» とする考えが有力です。«カルデラと呼びたくない» という研究者もいます。","白岩堰堤は7基の副堰堤と組み合わさった複合ダムで、高さ・落差ともに日本一とされます。近くの本宮砂防堰堤は «日本一の貯砂量» をもつとされ、国の登録有形文化財です。","砂防工事用のトロッコ（国土交通省の専用軌道）は、スイッチバックを何度もくり返して登る線路として鉄道ファンにも知られます。","冬は20mほども雪が積もるため、工事は4月〜10月に限られます。冬の前には工事事務所の建物やトロッコの橋の一部を撤去するほどです。","カルデラ内には幸田文の『崩れ』の文学碑が建てられています。","飛越地震の日付は旧暦では安政5年2月26日です。"],"look":["立山カルデラ砂防博物館の展示（カルデラの模型と災害の記録）","見学会で見られる白岩堰堤（落差108m）","砂防トロッコの線路（見学会や展示で）","立山駅周辺から見る常願寺川の荒々しい河原"],"q":["1858年の飛越地震で崩れた、カルデラ南側の山の名前は？","鳶山（大鳶山・小鳶山）です。この崩壊を «鳶山崩れ» といいます。"],"koji":[],"myth":"天然ダム決壊による死者数や被害の数字は資料によって差がある。","img":["飛越地震","白岩堰堤","常願寺川"],"wp":"立山カルデラ","rel":{"ev":[],"grave":[]},"ph":[["c:d/d5/20081003%E7%AB%8B%E5%B1%B1%E9%80%A3%E5%B3%B0Tagged.jpg",1280,960],["c:5/55/Tonbi.jpg",800,530],["c:8/85/Siraiwadam.jpg",800,530],["c:c/c3/Jyouganji_river.jpg",1644,2192,"常願寺川"]]},{"id":"16_shinjo_jo","n":"新庄城（佐々成政の支城）","yomi":"しんじょうじょう","cat":"城","rank":"B","y":1572,"era":["muromachi","azuchi"],"sh":"","ad":"富山市新庄町1丁目（富山市立新庄小学校）","st":"富山駅からバスで約15分。城跡は小学校なので、校内には入れない","la":36.7018,"lo":137.2528,"hook":"今は小学校。でも戦国時代、ここは上杉謙信も陣を置いた «越中の十字路» の城だった。","lead":"新庄城は、今の富山市新庄町にあった戦国時代の平城です。北陸街道の富山と水橋の間にあり、いくつもの道が分かれる交通の要所でした。上杉謙信や佐々成政の時代の戦いの舞台となり、1615年に廃城になりました。","story":["富山の町から東へ約4km。ここは北陸街道と、岩瀬の港や山あいの村へ向かう道が交わる場所でした。«ここをおさえれば、越中の東と西をつなぐ道を手に入れられる»。だからこそ、戦国の武将たちはこの城を奪い合いました。","1572年、越後の上杉謙信はこの新庄城に陣を置き、一向一揆勢がこもる富山城を攻めました。«尻垂坂の戦い» と呼ばれる戦いです。飛騨の武将・江馬輝盛も、ここへやって来て謙信にあいさつしたと伝えられます。","謙信が亡くなると、越中には織田信長の勢力がのびてきます。1578年には織田方と上杉方がこの近くでぶつかり、上杉方が敗れました（月岡野の戦い）。その後、織田方の佐々成政が越中を治めるようになると、新庄城は魚津城や松倉城など上杉方の城を攻めるための前線の城となりました。","けれども成政の越中支配も長くは続きません。1585年、豊臣秀吉の大軍に囲まれて降伏し、越中はやがて前田家のものになります。1615年の «一国一城令» で城は役目を終え、その後は加賀藩の陣屋や米蔵が置かれました。","明治時代、城跡には小学校が建てられ、今も子どもたちが通っています。2013年の体育館の建てかえで行われた発掘では、校舎の下から城のあとが見つかりました。«自分たちの学校の下に、戦国の城がある»。それだけで、歴史がぐっと身近に感じられます。"],"tl":[["1520年","長尾為景が神保慶宗と戦い、ここに陣城を築く（新庄城の戦い）"],["天文年間","三輪氏が城を築いたとされる"],["1572年","上杉謙信が新庄城に陣を置き、富山城を攻める（尻垂坂の戦い）"],["1578年","織田方と上杉方が近くで戦う（月岡野の戦い）"],["1580年ごろ","織田方の城となり、上杉方の城を攻める拠点になる"],["1585年","佐々成政が秀吉に降伏"],["1615年","一国一城令により廃城"],["2013年","新庄小学校の体育館改築前の発掘で城跡を確認"]],"who":[["上杉謙信","越後の大名。新庄城に陣を置いて富山城を攻めた"],["佐々成政","織田方の武将。富山城主として越中を治め、新庄城も支配下に置いた"],["長尾為景","謙信の父。1520年にこの地で神保慶宗と戦った"],["江馬輝盛","飛騨の武将。新庄城の謙信のもとを訪れたと伝わる"]],"deep":["江戸時代の記録では、本丸が東西約140m、南北約100〜127m、堀の幅が約11mと書かれ、平城としてはかなりの規模でした。","2013年の発掘では、城より前の飛鳥・白鳳時代や平安時代の集落のあと、室町時代の館のあとも見つかり、長く人が住み続けた場所だとわかりました。","城跡の遺構は、1895年の小学校建設やその後の拡張で削られたと考えられています。","1595年、前田利長が新川郡も加増され、上杉方の越中衆から城を受け取ったことで、上杉氏による越中支配は終わりました。","1583年には土肥政繁の配下に襲われて落城したとされ、成政の時代も決して安定した城ではありませんでした。"],"look":["新庄小学校の周辺に立つ城跡の案内（校内には入らない）","旧北陸街道の道筋","城跡の微高地（周囲より少し高い地形）"],"q":["1572年、上杉謙信が新庄城に陣を置いて攻めた城は？","富山城です。一向一揆勢がこもっていました（尻垂坂の戦い）。"],"koji":[{"w":"一国一城令","m":"1615年に江戸幕府が出した命令。大名の城を原則一つに限り、多くの城が廃城になった"}],"myth":"築城者や築城時期、佐々成政の時代の城の役割については諸説がある。","img":["佐々成政","上杉謙信","富山城"],"wp":"新庄城 (越中国)","rel":{"ev":[],"grave":[]},"ph":[["c:b/bd/Shinjo_castle%28%E6%96%B0%E5%BA%84%E5%9F%8E%E8%B7%A1%29.jpg",4032,3024,"新庄城 (越中国)"],["c:3/38/Sassa_Narimasa.JPG",408,484,"佐々成政"],["c:8/88/Uesugi_Kenshin_Portrait_from_Uesugi_Shrine.png",768,1164,"上杉謙信"],["c:a/a9/Toyama_Municipal_Folk_Museum_%28mock_keep_tower_of_the_Toyama_Castle%29_20180503.jpg",4288,2412,"富山城"]]},{"id":"16_imaisurugi_jo","n":"今石動城（前田利秀の城）","yomi":"いまいするぎじょう","cat":"城","rank":"B","y":1585,"era":["azuchi"],"sh":"小矢部市指定史跡","ad":"小矢部市城山町（城山公園）","st":"あいの風とやま鉄道・石動駅から歩いて約20分","la":36.6833,"lo":136.8585,"hook":"城主の父は地震で城ごと押しつぶされた。若い跡つぎは、この山の城を町の中心にえらんだ。","lead":"今石動城は、小矢部市の白馬山（標高186m）にあった山城です。1585年、前田利家が佐々成政と戦うために築き、弟の前田秀継と、その子の利秀が守りました。利秀は城下町をつくり、今の石動の町の土台を残しました。","story":["1585年、加賀の前田利家と越中の佐々成政は、はげしく対立していました。利家は越中攻めの足がかりとして、国境近くの白馬山に城を築きます。守りについたのは利家の末の弟・前田秀継と、その子の利秀でした。","同じ年の5月、成政方の武将たちが城に攻めよせ、城下に火を放ちました。けれども秀継・利秀親子はこれを追い返します。«今石動合戦» です。8月には豊臣秀吉が越中攻めのためこの城に立ち寄り、まもなく成政は降伏しました。","戦いのあと、秀継は砺波の木舟城4万石をまかされました。ところが11月、天正大地震が北陸をおそいます。木舟城はくずれ、秀継は城の下じきになって亡くなりました。父を失った利秀は、«ゆれでこわれた木舟の町は、もう立て直せない» と考え、本拠を今石動に移します。","利秀は山のふもとに町をつくり、職人や寺を呼び集めました。鍛冶町、紺屋町などの町名は今も残ります。北陸道の道すじも今石動を通るように変わり、小矢部川の水運とあわせて、町は大いににぎわいました。","しかし1593年、利秀は26歳の若さで病気で亡くなり、翌年、城は廃城となります。城はわずか10年ほどの命でしたが、利秀が開いた町は、その後も «石動» として続いていきました。今、城跡は城山公園になっていて、山の上から町を見下ろせます。"],"tl":[["1491年","『越後下向日記』に «ユスリギ山» の名が見える"],["1585年4月","前田利家が築城。前田秀継が入る"],["1585年5月","佐々方の攻撃を秀継・利秀が撃退（今石動合戦）"],["1585年8月","豊臣秀吉が越中攻めで滞在。成政が降伏"],["1585年11月","天正大地震で木舟城が倒れ、秀継が亡くなる"],["1586年","利秀が本拠を今石動に移し、城下町をつくる"],["1593年","利秀が26歳で病死"],["1594年","廃城"]],"who":[["前田利秀","秀継の子。今石動に城下町を開いた"],["前田秀継","利家の末弟。今石動城を守り、のち木舟城主。地震で死去"],["前田利家","加賀の大名。佐々成政と戦うため城を築いた"],["佐々成政","越中の大名。今石動城を攻めさせたが、秀吉に降伏"],["豊臣秀吉","越中攻めの途中、この城に滞在した"]],"deep":["名前の由来は、白馬山に能登の石動山（せきどうさん）の伊須流岐比古神社をまつったことから «新しい石動＝今石動» と呼ばれた、という説が有力です。","利家が石動山天平寺を攻めたとき人質として差し出された虚空蔵菩薩像を、城の守り本尊にしたという話もあり、この像は今、市内の聖泉寺にあります。","城域では250か所以上の平らな削平地が見つかっていて、県内でも有数の規模の山城です。本丸は東西約50m、南北約30mです。","利秀の死後、家臣の篠島清了が3千石を与えられて町を治め、その統治は5代・1710年まで続きました。","城山公園には1922年に建てられた神武天皇の銅像があり、2024年の能登半島地震で倒れましたが、同じ年に修復されました。"],"look":["山頂の本丸跡からの眺め（石動の町と小矢部川）","尾根にのこる曲輪跡と堀切","ふもとの旧町名（鍛冶町・紺屋町など）と寺町","城山公園の展望台"],"q":["前田秀継が亡くなった原因は？","1585年の天正大地震で木舟城がくずれ、その下じきになったためです。"],"koji":[],"myth":"«今石動» の名の由来には複数の説がある。本丸は私有地とされ、整備が行き届いていない所もある。","img":["前田利家","天正地震","木舟城"],"wp":"今石動城","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:9/96/Maeda_Toshiie.jpg",495,658,"前田利家"],["c:7/7b/Kihune_castle.jpg",4000,3000,"木舟城"]]},{"id":"16_inokuchi_jo","n":"井口城（井口氏の山城）","yomi":"いのくちじょう","cat":"城","rank":"B","y":1362,"era":["kamakura","muromachi"],"sh":"南砺市指定史跡","ad":"南砺市池尻","st":"JR城端線・福野駅から車で約10分","la":36.5446,"lo":136.9307,"hook":"『太平記』にも登場する平城。越中の有力武士・石黒氏のルーツとされる一族の城だった。","lead":"井口城は、南砺市池尻にあった平城で、鎌倉時代の終わりごろから豪族・井口氏の本拠だったと考えられています。石黒氏など越中の有力な武士の多くは井口氏の流れをくむともいわれます。南北朝時代には戦いの舞台となりました。","story":["砺波平野の南、田んぼの広がる池尻の地に、かつて四角い堀に囲まれた城がありました。井口城です。城の主・井口氏は、越中の砺波郡で力をもった一族で、江戸時代の書物『越登賀三州志』は、木舟城の石黒氏や野尻氏、宮崎氏なども井口氏の分かれだと書いています。","南北朝時代、日本は二つの朝廷に分かれて争いました。井口氏も戦いに巻きこまれ、やがて越中の有力者・桃井直常に従います。直常は庄川ぞいの城を本拠とし、井口城はその支えとなる城として使われました。","1362年、直常は信濃から越中に入り、兵を集めて加賀の富樫氏を攻めます。ところが敗れて、この井口城へ逃げ帰りました。この場面は軍記物語『太平記』に書かれています。«井口城へ引き退く»。いつもは静かな平野の城に、敗れた兵たちがなだれこんだ光景を想像してみてください。","1369年、直常の子・直和が再び富樫氏を攻めましたが失敗し、逆に能登の吉見氏に攻められて、9月24日、井口城は落城しました。井口氏はその後、県の東のはしの朝日町大家庄のほうへ拠点を移したと考えられていますが、いつ移ったのかははっきりしません。","今、主郭のあとは墓地になり、堀は田んぼに変わって、地面の上ではほとんど形がわかりません。けれども発掘では二重の堀が見つかり、城は南北朝時代と室町〜戦国時代前期の二つの時期に使われていたことがわかりました。石碑と案内板が、その記憶を伝えています。"],"tl":[["鎌倉時代後期","井口氏がこの地を拠点にしていたとされる"],["南北朝時代初め","井口氏が越中の争乱に加わる"],["1346〜1370年ごろ","桃井直常に従い、井口城がその支城となる"],["1362年","富樫氏に敗れた桃井直常が井口城へ逃げ帰る（『太平記』）"],["1369年9月24日","吉見氏に攻められて落城"],["1992年","南砺市（旧町）の史跡に指定"]],"who":[["井口氏","砺波郡の豪族。城の主。石黒氏などの祖とされる"],["桃井直常","南北朝時代の越中の有力者。井口城を支城とした"],["桃井直和","直常の子。1369年に富樫氏を攻めて敗れた"],["石黒氏","木舟城を本拠とした越中の武士。井口氏の流れをくむとされる"]],"deep":["城の規模は東西約135m、南北約99m。方形の主郭を堀で囲み、堀をはさんだ東側に出丸があったとされます。","井口氏の出自は、藤原利仁の子孫・斎藤氏の流れとする説（『越登賀三州志』『富樫家譜』）のほか、古代の豪族・利波臣の子孫とする説もあります。","1581〜1582年、佐々成政と一向一揆が戦った «窪城の戦い» の «窪城» は、この井口城のことではないかという見方もあります。","耕地整理のとき、城の周りから五輪塔など大量の石塔が見つかり、«池尻中世石塔群» として南砺市の文化財になっています。","朝日町大家庄にも «井口城» があり、同じ井口氏の城とされます。同じ名前の城が県の東西にあるのはこのためです。"],"look":["城跡の石碑と案内板","主郭のあとの区画と、周りの田んぼに残る堀のなごり","近くに展示されている池尻中世石塔群"],"q":["井口城が登場する、南北朝時代の戦いを描いた軍記物語は？","『太平記』です。1362年、桃井直常が井口城へ逃げ帰る場面があります。"],"koji":[],"myth":"題では «石黒氏の城» とされるが、城主は井口氏。石黒氏は井口氏の流れとする説による。井口氏の出自にも諸説ある。","img":["桃井直常","太平記","石黒氏"],"wp":"井口城","rel":{"ev":[],"grave":[]},"ph":[["c:5/5a/Inokuchi_Castle%28%E4%BA%95%E5%8F%A3%E5%9F%8E%E5%9D%80%29.jpg",1024,768,"井口城"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:6/6e/%E6%A1%83%E4%BA%95%E7%9B%B4%E5%B8%B8.jpg",712,954,"桃井直常"],["c:7/7c/Taiheiki_-_1698_-_1-5.jpg",2592,1728,"太平記"]]},{"id":"16_hasunuma_jo","n":"蓮沼城（遊佐氏の城と城下）","yomi":"はすぬまじょう","cat":"城","rank":"B","y":1585,"era":["muromachi","azuchi"],"sh":"","ad":"小矢部市蓮沼","st":"JR城端線・福野駅から加越能バスで «四日町» 下車、歩いて約15分","la":36.655,"lo":136.8575,"hook":"«蓮沼三千軒»。そう呼ばれたにぎやかな城下町は、一夜の焼き討ちで消えた。","lead":"蓮沼城は、今の小矢部市蓮沼にあった平城です。室町時代、越中守護・畠山氏の守護代だった遊佐氏が築き、砺波郡の政治の中心として栄えました。1585年、前田利家の焼き討ちで城と町は焼かれ、その役目は今石動へ移りました。","story":["室町時代、越中の守護は畠山氏でしたが、本人は都にいて、実際の政治は «守護代» にまかせていました。砺波郡をまかされたのが遊佐氏です。遊佐氏は小矢部川の近くの蓮沼に城を築き、ここを拠点にしました。","城のそばには北陸道が通り、川の舟も行き来しました。人と物が集まる蓮沼は «蓮沼三千軒» と呼ばれるほどにぎわったといいます。連歌師の宗祇も、越後へ向かう途中にたびたび城主・遊佐長滋の館に立ち寄り、連歌の会を開いたと伝えられます。","戦国時代になると、加賀の一向一揆の力が強まり、遊佐氏は越後へ逃れました。城は一揆勢の手に入り、上杉謙信に追われた椎名康胤も、ここに身を寄せたといわれます。1576年ごろ、謙信は蓮沼城を攻め落としました。","時代は進み、1585年。越中の佐々成政は、豊臣秀吉と前田利家を迎えうつため、蓮沼城に兵糧を集めていました。«ここをたたけば、成政の守りはくずれる»。利家は電光石火で蓮沼を襲い、城と町に火を放って、成政の援軍が来る前に引き上げました。","三千軒の町は灰になりました。翌年、城下の役目は近くに築かれた今石動へ移され、北陸道の道すじも変わります。蓮沼がふたたび栄えることはありませんでした。今は田んぼと散居村の中に石碑と案内板が立つだけです。碑の裏には、遊佐長滋の連歌が刻まれています。"],"tl":[["1429〜1441年ごろ","守護代・遊佐氏が城を築いたとされる"],["1469〜1486年ごろ","宗祇がたびたび遊佐長滋の館を訪れたと伝わる"],["1504〜1527年ごろ","遊佐慶親が埴生護国八幡宮に石段を寄進。のち越後へ亡命"],["1569年以降","椎名康胤が一向一揆勢と合流し、蓮沼に拠ったとされる"],["1576年ごろ","上杉謙信に攻められて落城"],["1585年","前田利家が蓮沼城と城下を焼き討ち"],["1586年","城下の役目が今石動へ移る"]],"who":[["遊佐長滋","蓮沼城主。宗祇と交流し、連歌を詠んだ"],["宗祇","室町時代の連歌師。蓮沼で千句の連歌を催したと伝わる"],["椎名康胤","謙信にそむいた武将。蓮沼で最期をむかえたともいわれる"],["前田利家","1585年に蓮沼を焼き討ちした"],["佐々成政","蓮沼城を守りの拠点とし、兵糧を集めた"]],"deep":["城の規模は東西26間、南北36間、堀の幅5間と伝えられています。","宗祇が編んだ連歌集『新撰菟玖波集』には、遊佐長滋の句が収められています。地方の武士が一流の文化人とつながっていた証拠です。","遊佐慶親は、埴生護国八幡宮に108段の石段を寄進したとされます。今も同社の石段を登ると、その縁を感じられます。","椎名康胤の最期の地には、蓮沼説のほか、氷見の朝日山で自害したという説などがあり、はっきりしません。","近くの柴田屋館（南砺市）には土塁の一部が残り、蓮沼城のまわりの支城・館のようすを想像する手がかりになります。"],"look":["水田の中に立つ «蓮沼城» の石碑と案内板","碑の裏に刻まれた遊佐長滋の連歌","近くの埴生護国八幡宮の石段（あわせて訪ねたい）"],"q":["蓮沼の町のにぎわいを表した、昔のことばは？","«蓮沼三千軒» です。1585年の焼き討ちで町は失われました。"],"koji":[],"myth":"築城者（遊佐徳盛か）、宗祇の訪問回数、椎名康胤の最期の地には諸説がある。","img":["宗祇","椎名康胤","埴生護国八幡宮"],"wp":"蓮沼城","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:5/56/S%C5%8Dgi.jpg",1595,3402,"宗祇"],["c:8/82/Hanyu_Gokoku_Hachiman-gu_Shrine.jpg",3417,2026,"埴生護国八幡宮"]]},{"id":"16_moridera_jo","n":"森寺城（湯山城・氷見の山城）","yomi":"もりでらじょう","cat":"城","rank":"B","y":1576,"era":["muromachi","azuchi"],"sh":"氷見市指定史跡","ad":"氷見市森寺","st":"JR氷見線・氷見駅から車で約20分。城跡は森林公園として整備","la":36.9089,"lo":136.9594,"hook":"能登と越中の境の尾根に、長さ1kmをこえる山城。発掘で見つかった石垣は、わざとこわされていた。","lead":"森寺城は、氷見市の標高160mの尾根にあった戦国時代の山城で、古い記録では «湯山城» と呼ばれます。能登の畠山氏、上杉謙信、佐々成政と城主が次々に変わり、1585年ごろ廃城になりました。氷見市でいちばん大きな城です。","story":["氷見の北西、能登との国境に近い山の中に、南北1,100m、東西400mにもおよぶ大きな城がありました。尾根にそって本丸、二の丸、そして «寺坂屋敷»«サイダ屋敷» などと呼ばれる曲輪がいくつも並びます。国境を守る、大切な城でした。","城を築いたのは、16世紀前半の能登の守護・畠山氏だと考えられています。ところが1576年、越後の上杉謙信が越中から能登へ進んでくると、城は上杉方のものになり、長沢光国が守りにつきました。","1578年、謙信が急に亡くなります。«謙信公がいなくなった»。上杉の力が弱まったすきに、織田信長の勢力が越中へ入ってきて、城は織田方に奪われました。やがて越中を治めた佐々成政の城となります。","発掘調査では、二の丸へ登る坂から石垣と、石を敷いた道、側溝が見つかりました。«大手道» と考えられるものです。1581年ごろに成政が整えたとみられています。ところが、その石垣はわざとこわされていました。1585年、成政が秀吉に降伏したあと、前田利家が城を使えなくする «破城» をしたと考えられています。","«なぜ石垣をこわしたの?» 城は、使われなくなっても敵に利用されればまた戦いの拠点になります。だから勝った側は、石垣や堀をくずして、二度と城として使えないようにしたのです。今、城跡は森林公園になっていて、土塁や堀切が戦国の緊張を伝えています。"],"tl":[["16世紀前半","能登守護・畠山氏が築いたとされる"],["1576年","上杉謙信方の城となり、長沢光国が入る"],["1578年","謙信の死後、織田方に奪われ、のち佐々成政の城に"],["1581年ごろ","成政が大手の石垣や石敷道を整えたと推定"],["1585年ごろ","成政の降伏後、前田利家による破城を受け廃城"],["1973年","氷見市の史跡に指定"],["2004年","試掘調査で大手道の石垣と石敷道が見つかる"]],"who":[["畠山氏（能登）","能登の守護大名。城を築いたと考えられる"],["上杉謙信","越後の大名。1576年に城を配下に入れた"],["長沢光国","上杉方として城を守った武将"],["佐々成政","織田方の武将。大手道を整えたと推定される"],["前田利家","成政降伏後、城をこわしたと推定される"]],"deep":["城の縄張りは南北1,100m×東西400mで、氷見市内最大級です。","1996・1997・2001年の調査では、V字形の空堀や、土どめの石組みをもつ土塁が見つかりました。","出土品は陶磁器やかわらけが中心で、城の名が史料に出る前の15世紀の珠洲焼も見つかっています。ただし多くは16世紀末の攻防の時期のものです。","大手道の石垣は安土城ほどの規模ではないものの、この地域の山城としては先進的なつくりだったと考えられます。","築いたのが畠山義総の時代かどうかは、はっきりしていません。"],"look":["本丸・二の丸の平らな曲輪","尾根を断ち切る堀切と土塁","二の丸へ登る大手道（石垣・石敷道が見つかった場所）","尾根から見下ろす阿尾川の谷"],"q":["森寺城が古い記録で呼ばれていた別の名前は？","«湯山城» です。"],"koji":[],"myth":"築城者（畠山義総の代か）や、石垣を整えた人物・破城した人物は発掘成果からの推定。","img":["佐々成政","上杉謙信","能登畠山氏"],"wp":"森寺城","rel":{"ev":[],"grave":[]},"ph":[["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:3/38/Sassa_Narimasa.JPG",408,484,"佐々成政"],["c:8/88/Uesugi_Kenshin_Portrait_from_Uesugi_Shrine.png",768,1164,"上杉謙信"]]},{"id":"16_ao_jo","n":"阿尾城（菊池氏の海の城）","yomi":"あおじょう","cat":"城","rank":"B","y":1585,"era":["azuchi"],"sh":"県指定史跡","ad":"氷見市阿尾","st":"JR氷見線・氷見駅から車で約10分","la":36.8793,"lo":136.9924,"hook":"三方を海に囲まれた岬の城。九州・肥後の名門の子孫を名のる一族が守り、あの傾奇者・前田慶次郎も入った。","lead":"阿尾城は、氷見市の富山湾につき出た岬 «城ケ崎» にあった戦国時代の城です。九州の菊池氏の子孫とされる菊池武勝・安信親子が城主として知られます。1585年には前田方の武将として、前田慶次郎も入ったといわれます。","story":["氷見の北、富山湾に小さくつき出た岬があります。三方を海に囲まれ、陸からは細い道でしか近づけない。能登へ向かう道と海の道の両方をおさえる、まさに «海の城» でした。","戦国時代の終わりにここを治めていたのは、菊池武勝です。遠い九州・肥後の名門、菊池氏の子孫だといわれます。武勝は最初、上杉謙信に従い、その後は織田信長と結び、越中に入ってきた佐々成政の配下として活躍しました。","ところが信長が亡くなると、成政と前田利家は対立します。«どちらにつくべきか»。武勝は悩んだすえ、利家の側につきました。怒った成政は阿尾城に攻めよせますが、前田勢の加勢もあって、城は持ちこたえました。","このとき、前田方の武将として阿尾城に入ったのが、前田慶次郎です。派手なふるまいで知られる «傾奇者» で、のちに小説や漫画で大人気になりました。ただし、実際に城にいたのは5月から7月ごろまでの3か月ほどと考えられています。","菊池氏は前田家の家臣となり、城と1万石の領地を認められました。けれども1596年に当主が亡くなると、城はまもなく使われなくなります。今、岬の上には榊葉乎布神社があり、2012年には武勝から数えて16代目の子孫がこの神社の春祭りに参加しました。"],"tl":[["15世紀ごろ","岬の上が城として使われ始めたと考えられる（出土品から）"],["戦国時代後期","菊池武勝が城主となり、上杉謙信に従う"],["1580年ごろ","織田方につき、佐々成政の配下となる"],["1585年","前田方につき、成政の攻撃を退ける。前田慶次郎が入城"],["1596年","当主が亡くなり、まもなく廃城"],["1989〜1992年","氷見市教育委員会が発掘調査"],["2012年","菊池武勝の16代目の子孫が城跡の神社の祭りに参加"]],"who":[["菊池武勝","阿尾城主。肥後菊池氏の子孫とされる。上杉・織田・前田と主をかえた"],["菊池安信","武勝の子。父とともに城を守った"],["前田慶次郎","傾奇者として知られる武将。1585年に阿尾城に入った"],["佐々成政","前田方についた菊池氏を攻めた"],["前田利家","菊池氏に加勢し、城を守らせた"]],"deep":["1989〜1992年の発掘では、はっきりした城の建物のあとは見つかりませんでした。ただし «伝二の丸»«伝三の丸» で15〜16世紀の遺物が出ていて、そこが城の中心だったと考えられています。","前田慶次郎が «城主» だったという見方もありますが、実際の在城は3か月ほどと考えられています。","菊池氏が肥後菊池氏の末裔という話は家の伝えによるもので、どのような経緯で越中に来たかははっきりしません。","菊池氏は前田方についたあとも、城と知行1万石を安堵されました。地方の小さな武士が、大名の争いの中で生き残った例です。","岬の上の榊葉乎布神社は、城跡とともに地域の人びとに守られています。"],"look":["海につき出た城ケ崎の地形（遠くから全体を見るとよくわかる）","岬の上の榊葉乎布神社","岬から見る富山湾と、晴れた日の立山連峰"],"q":["1585年、前田方の武将として阿尾城に入った «傾奇者» はだれ？","前田慶次郎です。ただし実際にいたのは3か月ほどと考えられています。"],"koji":[],"myth":"菊池氏の肥後菊池氏末裔説は家伝。前田慶次郎の在城期間・役割には諸説ある。","img":["前田利益","菊池氏","氷見市"],"wp":"阿尾城","rel":{"ev":[],"grave":[]},"ph":[["c:3/39/Jyogasaki.jpg",5184,3456,"阿尾城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:f/f8/Maeda_Keijir%C5%8D.jpg",557,785,"前田利益"],["c:4/49/Himi_port.jpg",6000,4000,"氷見市"]]},{"id":"16_miyazaki_jo","n":"宮崎城（越後との境の城）","yomi":"みやざきじょう","cat":"城","rank":"B","y":1584,"era":["kamakura","azuchi"],"sh":"県指定史跡","ad":"下新川郡朝日町宮崎・境（城山公園）","st":"あいの風とやま鉄道・泊駅から車で約20分。城山に無料駐車場あり","la":36.963,"lo":137.5856,"hook":"すぐ東は難所・親不知。越中の «玄関» を守るこの城は、源平の時代から戦国まで、何度も戦場になった。","lead":"宮崎城は、朝日町の城山（標高249m）にあった山城で、別名を境城といいます。越中と越後の国境にあり、東に親不知の難所をひかえる交通の要所でした。承久の乱や戦国時代の戦いの舞台となり、今は城山公園として整備されています。","story":["越後から越中へ入るには、海ぞいのけわしい崖 «親不知» を越えなければなりません。その出口をにらむ山の上に、宮崎城はありました。«ここを通さなければ、越中には入れない»。この城は、いわば越中の玄関の門番でした。","言い伝えでは、平安時代の終わり、1183年ごろ、木曾義仲が北陸へ進んだとき、この地の武士・宮崎太郎が以仁王の皇子 «北陸宮» をむかえ、御所をつくったといわれます。けれども、このころすでに城があったという確かな証拠はありません。","確かな記録に城が現れるのは、1221年の承久の乱です。京都の朝廷と鎌倉幕府が戦ったこの乱で、北条朝時が率いる幕府軍が北陸道を進み、5月30日にこの城を攻め落としたことが、北条義時の命令書からわかります。","戦国時代、城は越中の佐々成政のものとなり、家臣の丹羽権平が守っていました。1584年10月、越後の上杉景勝がせめよせます。城兵300人が27人にまで減るほどのはげしい戦いの末、城は6日目に開きました。«最後の一人まで»。そんな覚悟の籠城だったのかもしれません。","その後、越中は前田家のものとなり、国境には «境関所» が置かれて、城は役目を終えたといわれます。今、城山公園には空堀や土塁、堀切、石垣の一部が残り、北陸宮の墓と伝わる塚もあります。山頂からは、日本海と越後へ続く海岸線が見わたせます。"],"tl":[["1183年ごろ","宮崎太郎が北陸宮をむかえたと伝わる（伝承）"],["1221年5月30日","承久の乱で北条朝時の幕府軍に攻め落とされる"],["戦国時代","椎名康胤が上杉氏にそむいた際、戦いの最前線となる"],["1580年代","佐々成政の支城となる"],["1584年10月","上杉景勝の攻撃を受け、籠城6日目に開城"],["1595年","新川郡が前田利長の領地となり、上杉方の越中支配が終わる"],["江戸時代初め","境関所が置かれ、廃城になったといわれる"],["1965年","本丸跡の保護工事が完成"]],"who":[["宮崎太郎","『平家物語』長門本などに登場する越中の武士。北陸宮をむかえたと伝わる"],["北陸宮","以仁王の皇子。木曾義仲に奉じられた"],["北条朝時","承久の乱で北陸道を進んだ幕府軍の大将"],["丹羽権平","佐々成政の家臣。上杉勢の攻撃に籠城した"],["上杉景勝","越後の大名。1584年に宮崎城を攻め落とした"]],"deep":["宮崎太郎の名は «長康» とも «重頼» とも伝わり、はっきりしません。","承久の乱での落城は、北条義時の承久3年6月6日付けの御教書で確認でき、«確実に城だった» といえる最初の記録です。","成政が秀吉に降伏したあとも、宮崎城には上杉景勝の城将が成政に備えて置かれていました。越中の東のはしは、しばらく上杉の支配が続いたのです。","城山公園には大堀切と石橋、三の丸の石塁、二の丸の土塁と石垣、本丸の石垣などが残ります。«明治天皇宮崎御小休所址» の碑もあります。","とやま城郭カードの «No.1» はこの宮崎城。県の東の玄関にある城だからといえるでしょう。"],"look":["本丸跡からの日本海と親不知方面の眺め","大堀切と石橋","二の丸の土塁と石垣","北陸宮御墳墓と伝わる塚"],"q":["承久の乱で宮崎城を攻め落とした幕府軍の大将はだれ？","北条朝時です。1221年5月30日に攻め落としました。"],"koji":[],"myth":"宮崎太郎が北陸宮をむかえ御所を置いた話、北陸宮の墓は伝承で、学問的な裏づけはない。","img":["北陸宮","承久の乱","親不知"],"wp":"宮崎城 (越中国)","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:5/5c/Setagawa%EF%BC%88Yodogawa%EF%BC%89_Karahashi.jpg",800,600,"承久の乱"]]},{"id":"16_futagami","n":"二上射水神社と二上山","yomi":"ふたがみいみずじんじゃとふたがみやま","cat":"寺社","rank":"B","y":747,"era":["nara","meiji"],"sh":"","ad":"高岡市二上（二上山の南のふもと）","st":"JR高岡駅から車で約20分","la":36.7775,"lo":137.011,"hook":"天狗が斧をふり上げ、わら人形の四天王が並ぶ。1年に1度だけ組まれる «築山» は、祭りが終わるとすぐにこわされる。","lead":"二上射水神社は、高岡市の二上山のふもとにある神社です。二上山そのものを神とあがめ、かつては越中一宮・射水神社がここにありました。明治時代に射水神社が高岡城跡へ移ったあとも、地元の人びとがこの地で祭りを守ってきました。","story":["高岡の北にそびえる二上山は、二つの峰をもつ山です。古くから神の山とされ、ふもとにはこの山をまつる射水神社がありました。越中国の一宮、つまり越中でいちばん格の高い神社です。","奈良時代、越中の国守・大伴家持もこの山を愛し、«二上山の賦» という長い歌を詠みました。国府のある伏木から毎日のようにながめた山だったのでしょう。二上山は万葉の歌のふるさとでもあります。","長いあいだ、射水神社は二上山の寺と深く結びつき、お坊さんたちが神社のことも取りしきっていました。明治時代、神と仏を分ける政策が進むと、1875年、射水神社は高岡の町の中心、高岡城の本丸跡へ移されます。«神さまを、ふもとから持っていかれてしまうのか»。二上の人たちは反対し、もとの場所には分社が残されました。これが今の二上射水神社です。","この神社には、ふしぎな祭りが伝わっています。4月23日の例祭の «築山行事» です。境内の三本杉の前に高さ約4mの壇を組み、上には斧をふり上げた天狗の姿の神さま、下には持国天・増長天・広目天・多聞天のわら人形を並べます。神さまをおろして祭りをしたあと、«ぐずぐずしていると山の悪い神があばれる» と、壇は大急ぎでこわされます。","神輿が進む途中で、一つの神輿だけがわりこむ «院内わりこみ» という不思議な作法もありますが、その意味は伝わっていません。この築山は、高岡御車山祭の山車のもとになったとも考えられています。"],"tl":[["奈良時代","二上山のふもとに射水神社がまつられていたとされる"],["747年","大伴家持が «二上山の賦» を詠む"],["927年","『延喜式』神名帳に射水神社が名神大社として記される"],["1875年","射水神社が高岡城跡へ移り、旧地に分社が残る"],["1956年","明治期に途絶えていた築山行事が復活"],["1968年","木造男神坐像が国の重要文化財に指定"],["1982年","築山行事が富山県の無形民俗文化財に指定"]],"who":[["大伴家持","越中国守。二上山を歌に詠んだ"],["二上の氏子","射水神社の移転に反対し、旧地の分社と祭りを守った"],["二上大神","二上山を神体とする神。築山では天狗の姿であらわされる"]],"deep":["築山は、放生津八幡宮（射水市）でも行われ、石動山でもかつて行われていました。主神の姿から、放生津の «足なし»、二上山の «手なし»、石動山の «口なし» と呼ばれてきました。","わら人形には昔、古い面が付けられていましたが、1950年に台風で祭りが中止になって以来、付けられていません。今は3Dスキャンで古面の複製をつくる取り組みが進められています。","社宝の木造男神坐像は国の重要文化財です。","境内には二上山養老寺の寺院の一つ、慈尊院も併設されていて、神仏習合のなごりを感じられます。","戦後、二上射水神社は射水神社から独立し、正式名を «越中総社射水神社» としました。"],"look":["境内の三本杉（築山が組まれる場所）","4月23日の例祭の築山行事","神社の背後にそびえる二上山と、山上の万葉ラインからの眺め","併設の慈尊院"],"q":["築山行事で、壇の上にまつられる神さまはどんな姿？","斧をふり上げた天狗の姿です。下段には四天王のわら人形が並びます。"],"koji":[],"myth":"築山行事が高岡御車山のもとになったという説は «考えられている» 段階。院内わりこみの意味は伝わっていない。","img":["射水神社","大伴家持","高岡御車山祭"],"wp":"二上射水神社","rel":{"ev":[],"grave":[]},"ph":[["c:9/99/Futagami-imizu-jinja_haiden.jpeg",2048,1536,"二上射水神社"],["c:1/1d/Futagami-imizu-jinja_entrance.jpeg",2048,1536],["c:e/ec/Imizu-jinja_haiden.JPG",2352,1568,"射水神社"],["c:3/3e/Sanj%C5%ABrokkasen-gaku_-_5_-_Kan%C5%8D_Tan%E2%80%99y%C5%AB_-_Ch%C5%ABnagon_Yakamochi.jpg",1000,1450,"大伴家持"],["c:b/b2/%E9%AB%98%E5%B2%A1%E5%B8%82%E8%A1%97%E3%81%AE%E9%A2%A8%E6%99%AF_-_panoramio.jpg",4752,3168,"高岡御車山祭"]]},{"id":"16_iwakuraji","n":"岩峅寺（立山の麓の衆徒の村）","yomi":"いわくらじ","cat":"寺社","rank":"B","y":1600,"era":["heian","edo"],"sh":"国の重要文化財（雄山神社前立社壇本殿）","ad":"中新川郡立山町岩峅寺","st":"富山地方鉄道立山線・上滝線の岩峅寺駅から歩いて約10分","la":36.6185,"lo":137.344,"hook":"«峅» は神さまが降り立つ場所。立山へ登る人は、まずこの村で身を清めた。","lead":"岩峅寺は、常願寺川のほとりにある立山信仰の村です。立山の神をまつる雄山神社の «前立社壇» があり、かつては立山寺（岩峅寺）という寺でした。江戸時代には宿坊が並び、衆徒たちが立山へ向かう人びとをむかえました。","story":["立山は、富士山・白山とならぶ «日本三霊山» の一つです。むかし立山へお参りする人は、ふもとの村で身を清めてから山に入りました。その入り口にあたるのが岩峅寺です。«峅» という字には、神さまが降り立つ場所という意味があるといわれます。","伝承では、立山を開いた佐伯有頼が、白い鷹に導かれてたどり着いた岩屋の正面が、この地だとされます。ここに建てられた立山寺が、今の雄山神社前立社壇のはじまりです。山頂の本社は冬には参れないため、一年中の祭りはこのふもとで行われてきました。","村には宿坊が並び、«衆徒» と呼ばれる人びとが立山信仰をささえました。山に入る人のけがれや罪を、湯を使った神事で清め、道中の無事を祈ったといいます。宿坊には今も立山曼荼羅が残り、全国の信者に立山の教えを広めたことを伝えています。","岩峅寺と、さらに山寄りの芦峅寺は、どちらも立山信仰の村でしたが、それぞれ役割がちがったといわれます。«山の上のことは岩峅寺、ふもとと全国回りは芦峅寺»。二つの村はときに競い合いながら、立山の信仰を守り続けました。","明治時代の神仏分離で、寺としての岩峅寺はなくなり、雄山神社の一部となりました。けれども、北陸でいちばん大きいといわれる本殿や、旧登山道、石仏は今も残っています。岩峅寺駅から歩いて、立山へ向かった昔の人びとの気持ちを想像してみてください。"],"tl":[["701年","佐伯有頼が立山を開いたと伝わる（伝承）"],["平安時代初め","立山寺（岩峅寺）が建てられたとされる"],["1190年代","源頼朝が前立社壇本殿を再建したと伝わる"],["1492年","足利義稙（義材）が本殿を改修したとされる"],["1583年","佐々成政が本殿を改修したとされる"],["江戸時代","宿坊が並び、衆徒が立山登拝の人びとを迎える"],["明治初め","神仏分離で寺院としての岩峅寺がなくなる"]],"who":[["佐伯有頼","立山を開いたと伝わる人物。のちの慈興上人"],["岩峅寺の衆徒","宿坊を営み、立山登拝の人びとを清め、導いた"],["源頼朝","前立社壇の本殿を再建したと伝わる"],["佐々成政","越中を治めていたころ本殿を改修したとされる"]],"deep":["前立社壇本殿は檜皮葺き、五間社流造で、本殿としては北陸最大の規模とされ、国の重要文化財です。","木造慈興上人（佐伯有頼）坐像も国の重要文化財に指定されています。","本殿をはさんで両側に鳥居と神門（表と東）がある珍しいつくりは、立山信仰の入り口という性格からといわれます。","すぐ横を流れる常願寺川はたびたび大水を起こし、ここから流された神体が下流の神社の神体になった、という話もあります。","江戸時代、岩峅寺と芦峅寺の衆徒は、山での権利や布教の範囲をめぐって争ったこともあったといわれます。","境内には探湯（くがたち）の釜などが伝わり、湯を使った清めの神事のなごりをとどめています。"],"look":["雄山神社前立社壇の本殿（北陸最大級の流造）","表と東、二つの鳥居と神門","村に残る宿坊や旧登山道の石仏","岩峅寺駅から見る常願寺川の広い河原"],"q":["岩峅寺の «峅» という字には、どんな意味があるといわれる？","神さまが降り立つ場所、という意味があるといわれます。"],"koji":[],"myth":"佐伯有頼の開山、頼朝の再建は伝承。岩峅寺と芦峅寺の役割分担の細部は時代や資料で異なる。","img":["雄山神社","立山","芦峅寺"],"wp":"岩峅寺","rel":{"ev":[],"grave":[]},"ph":[["c:f/f0/20_Tateyama_from_Mikurigaike_1998-7-17.jpg",1280,854,"雄山神社"],["c:c/cf/Mount_Tate_viewed_from_Midorigaike.jpg",6016,4000,"立山"],["c:a/a9/Chuuguu-kiganden_Haiden.JPG",2352,1568,"芦峅寺"]]},{"id":"16_choukeiji","n":"長慶寺の五百羅漢","yomi":"ちょうけいじのごひゃくらかん","cat":"寺社","rank":"B","y":1799,"era":["edo"],"sh":"","ad":"富山市五艘（呉羽丘陵の東斜面）","st":"富山駅から車で約15分。寺から羅漢の並ぶ斜面へは坂道を歩く","la":36.7115,"lo":137.1904,"hook":"山の斜面に、535人の羅漢さんがひな壇のように並んで、みんなで立山の方角を見ている。","lead":"長慶寺は、富山市の呉羽丘陵の中腹にある曹洞宗のお寺です。境内の斜面には、江戸時代後期に富山の廻船問屋が寄進した535体の石の羅漢像が並びます。完成までに約50年かかったといわれます。","story":["呉羽山の東の斜面を登っていくと、木々の間から、たくさんの石の顔がこちらを見ています。笑っている顔、考えこんでいる顔、あくびをしているような顔。長慶寺の五百羅漢です。羅漢とは、お釈迦さまの教えを受けて悟りをひらいた弟子たちのことです。","この羅漢像を寄進したのは、江戸時代後期の富山の商人、廻船問屋の黒牧善次郎でした。北前船などで日本海を行き来した廻船問屋は、大きな富をたくわえていました。«商いで得た富を、仏さまにおかえししたい»。そんな思いがあったのかもしれません。","善次郎は、佐渡の石工に羅漢像を彫らせ、船で運ばせたといわれます。1799年に始まった寄進は、1849年まで約50年も続いたと伝わります。善次郎一人の代では終わらない、長い長い仕事でした。","羅漢たちは東向きに、ひな壇のように並んでいます。東には富山平野、その向こうには立山連峰。«なぜ東向きなの?» はっきりした理由は伝わっていませんが、朝日と立山をあおぐ向きに並ぶ姿は、見る人の心をしずかにしてくれます。","お寺には、もう一つ悲しい歴史があります。本尊はかつて «桜谷大仏» と呼ばれる大きな仏さまでしたが、明治のはじめ、富山藩の厳しい廃仏政策のなかで失われ、今は仏頭だけが残っています。石の羅漢たちは、そんな時代もこの斜面で生きのびてきたのです。"],"tl":[["1786年","日輪禅師が曹洞宗の寺として開山"],["1799年","黒牧善次郎による羅漢像の寄進が始まったとされる"],["1849年","約50年かけて羅漢像がそろったとされる"],["1870年ごろ","廃仏毀釈のなかで本尊の桜谷大仏が失われ、仏頭だけが残る"]],"who":[["黒牧善次郎","富山の廻船問屋。五百羅漢を寄進した"],["日輪禅師","長慶寺を曹洞宗の寺として開いた僧"],["佐渡の石工","羅漢像を彫ったと伝わる職人たち"],["白仙院","富山藩6代藩主・前田利與の妻。柿本人麻呂像を寄進した"]],"deep":["長慶寺はもとは新川郡塩野にあった真言宗の寺で、1786年に曹洞宗の寺として開かれ、商人・河上屋市郎左衛門の願いで今の場所に移ったとされます。","山号は «法羅陀山»。本尊は釈迦如来です。","羅漢像の数は «五百羅漢» といいながら、実際には535体とされます。数えてみるのも楽しみの一つです。","富山藩は明治3年（1870年）ごろ、寺をまとめて減らす厳しい政策をとり、多くの仏像や寺が失われました。桜谷大仏もその犠牲になったと考えられます。","寺には富山藩の奥方・白仙院が寄進した柿本人麻呂像が伝わります。藩の上層ともつながりのある寺でした。","羅漢像は一体ずつ顔やしぐさがちがい、«自分に似た羅漢さんが必ずいる» という言い方は各地の五百羅漢で親しまれています。長慶寺でも、お気に入りの一体を探しながら歩く人が多くいます。"],"look":["ひな壇状に並ぶ535体の羅漢像と、一体ずつちがう表情","羅漢の間に立つ石灯籠","境内から見える富山平野と立山連峰","本堂の仏頭（桜谷大仏のなごり）","呉羽山の散策路（寺からそのまま丘陵を歩ける）"],"q":["長慶寺の羅漢像を寄進した黒牧善次郎は、どんな仕事をしていた？","廻船問屋です。船で物を運んで商いをする商人でした。"],"koji":[],"myth":"寄進の期間（約50年）や佐渡の石工が彫ったという話は «といわれる» 伝え。","img":["五百羅漢","呉羽丘陵","廃仏毀釈"],"wp":"長慶寺 (富山市)","rel":{"ev":[],"grave":[]},"ph":[["c:3/30/Chokei-ji%2C_Toyama.jpg",4032,2757,"長慶寺 (富山市)"],["c:1/15/GOHYAKURAKAN_CHOUKEIJI.JPG",800,1200],["c:6/61/%E4%B8%AD%E5%A4%AE%E3%82%B5%E3%82%A4%E3%82%AF%E3%83%AA%E3%83%B3%E3%82%B0%E3%83%AD%E3%83%BC%E3%83%89_%E5%AF%8C%E5%B1%B1%E5%B8%82%E5%AF%BA%E7%94%BA%E4%BB%98%E8%BF%912.jpg",2816,1584,"呉羽丘陵"]]},{"id":"16_monmyoji","n":"聞名寺（八尾の町の起こり）","yomi":"もんみょうじ","cat":"寺社","rank":"B","y":1551,"era":["muromachi","edo"],"sh":"","ad":"富山市八尾町","st":"JR高山本線・越中八尾駅から歩いて約20分","la":36.5803,"lo":137.1388,"hook":"«おわら風の盆» で知られる坂の町・八尾。その町は、飛騨から旅してきた一つのお寺の門前から始まった。","lead":"聞名寺は、富山市八尾町にある浄土真宗本願寺派のお寺です。鎌倉時代の終わりに美濃で始まり、飛騨を転々としたのち、戦国時代の1551年に今の場所へ移りました。その門前に人が集まってできたのが、今の八尾の町です。","story":["お寺が «引っこし» をくり返した、と聞くとふしぎに思うかもしれません。聞名寺のはじまりは1290年。浄土真宗を開いた親鸞のひ孫・覚如の弟子が、美濃国で小さな道場を開いたのが最初だといわれます。","その後、お寺は飛騨の山の中へ移り、さらに飛騨の中で場所を変えます。15世紀の後半には越中に入り、いったん飛騨にもどったあと、1524年に八尾の乗嶺という所へ移りました。«なぜこんなに移ったの?» 信者の多い場所を求めたり、戦乱をさけたりと、理由はさまざまだったと考えられます。","そして1551年、お寺は井田川の河岸段丘の上、今の場所に落ち着きました。浄土真宗のお寺には多くの門徒が集まります。お寺のまわりに家が建ち、店が開き、やがて町ができていきました。聞名寺が «門前町・八尾の礎» と呼ばれるのはこのためです。","江戸時代、八尾は飛騨と富山を結ぶ道の中継地として、また養蚕や和紙の町として栄えました。坂にそって並ぶ家並みと石垣は、今も «坂の町» の風情を残しています。","町が大きくなると、八尾の人びとはお寺を中心に祭りや行事をととのえていきました。お寺の鐘が時を告げ、門徒が集まって話し合う。聞名寺は、祈りの場であると同時に、町の人びとが集まる «広場» のような役目も果たしていたのです。","毎年9月1日から3日には、胡弓の音にあわせて静かに踊る «おわら風の盆» が行われます。その始まりは、江戸時代に町の «町建て御墨付» を取りもどした祝いに、三日三晩踊り明かしたことだと伝えられます。聞名寺の境内も、踊りの舞台の一つになっています。"],"tl":[["1290年","覚如の弟子・願智坊永承（覚淳）が美濃国で道場を開く"],["1314年","飛騨国益田郡に移り、福応寺を建てる"],["1323年","飛騨国吉城郡吉田村へ移る"],["1468年","越中国に入る"],["1492年","いったん飛騨にもどる"],["1524年","八尾の乗嶺に寺を移す"],["1551年","今の場所に移り、門前町八尾が育ち始める"]],"who":[["願智坊永承（覚淳）","覚如の直弟子。美濃で道場を開いた聞名寺の始まりの僧"],["覚如","親鸞のひ孫。本願寺の基礎を築いた"],["八尾の門徒・町衆","お寺のまわりに住み、門前町をつくりあげた"]],"deep":["寺宝の «聞名寺文書» は富山県の文化財、«椿図浅彫欄間» は富山市の文化財に指定されています。","山号は «桐野山»、本尊は阿弥陀如来です。","飛騨の吉田村の草庵はのちに常蓮寺となったとされ、飛騨と八尾の信仰のつながりを物語っています。","おわら風の盆の起こりを元禄時代の «町建て御墨付» 取りもどしとする話は伝承で、年代や細部には諸説があります。","八尾は越中と飛騨を結ぶ道の «入り口» にあたり、お寺の移動の道すじが、そのまま人と物の道すじだったと考えると面白くなります。"],"look":["聞名寺の山門と本堂","寺の周りの坂道と石垣の家並み（諏訪町・東町など）","9月1〜3日のおわら風の盆（境内での踊り）","井田川の河岸段丘の地形"],"q":["聞名寺が今の八尾の地に移ったのは何年？","1551年（天文20年）です。その門前から八尾の町が育ちました。"],"koji":[],"myth":"寺の移転の理由や、おわら風の盆の起源は伝承・諸説がある。","img":["八尾町","おわら風の盆","覚如"],"wp":"聞名寺","rel":{"ev":[],"grave":[]},"ph":[["c:d/dd/Kazenobon01.jpg",800,600,"八尾町"],["c:f/f5/Etchu-Yatsuo_Station_2020.jpg",3456,2304,"近く: 越中八尾駅"],["c:c/ca/Yatsuo-high-school_toyama-pref_2018.jpg",1024,768,"近く: 富山県立八尾高等学校"],["c:2/22/%E8%B6%8A%E4%B8%AD%E5%85%AB%E5%B0%BE%E9%83%B5%E4%BE%BF%E5%B1%80.jpg",4272,2848,"近く: 越中八尾郵便局"],["c:c/c5/Yatsuo-elem-school_toyama-city_2018.jpg",1024,768,"近く: 富山市立八尾小学校"],["c:b/b5/Monmyo-ji_in_Yatsuo%2C_Toyama.jpg",6000,3376,"近く: 聞名寺 (富山市)"]]},{"id":"16_jonichiji","n":"上日寺（氷見の大イチョウ）","yomi":"じょうにちじ","cat":"寺社","rank":"B","y":1680,"era":["asuka","edo"],"sh":"国の天然記念物（上日寺のイチョウ）","ad":"氷見市朝日本町","st":"JR氷見線・氷見駅から歩いて約15分","la":36.8585,"lo":136.9775,"hook":"寺の火事も、長い年月も生きのびた一本のイチョウ。秋、境内は黄金色にそまる。","lead":"上日寺は、氷見市の朝日山のふもとにある高野山真言宗のお寺です。飛鳥時代の創建と伝わり、江戸時代には前田家の祈願所でした。境内の大イチョウは、1926年に国の天然記念物に指定されています。","story":["氷見の町を見下ろす朝日山。そのふもとの上日寺には、見上げるほど大きなイチョウの木があります。太い幹から枝が四方に広がり、秋には黄色い葉が空をおおいます。«この木は、いったい何年ここに立っているのだろう?» 地元では千年をこえるともいわれます。","お寺の歴史も古く、白鳳時代（飛鳥時代の後半）に開かれたと伝えられています。本尊は千手観音。南北朝時代の1346年には七堂伽藍が再建されたといい、大きなお寺だったことがうかがえます。","江戸時代のはじめ、1614年には加賀藩の前田利長から山屋敷が寄進され、明治になるまで前田家の «祈願所» として大切にされました。藩の殿さまが、国の平和や家の繁栄を祈らせたお寺です。","ところが1639年、火事でお堂が焼けてしまいます。お寺の人びとは力を合わせ、1680年に九間の大きな本堂を建て直しました。正面には、なだらかな曲線をえがく唐破風の向拝がつけられ、今もその姿を見ることができます。火事のあとも、イチョウは変わらずそこに立ち続けていました。","イチョウは «生きた化石» と呼ばれる古い植物で、火に強いともいわれ、寺や神社によく植えられてきました。上日寺の大イチョウも、お寺が燃えたときに焼け残ったのかもしれません。ただしそれを確かめる記録はなく、想像をふくらませる楽しみとして味わいたいところです。","お寺のそばには、縄文時代の朝日貝塚もあります。何千年も前から人が暮らし、千年も前から祈りの場がある。上日寺の大イチョウは、その長い時間を見守ってきた «生き証人» なのかもしれません。"],"tl":[["白鳳時代","上日寺が開かれたと伝わる"],["1346年","七堂伽藍が再建されたとされる"],["1614年","前田利長から山屋敷が寄進される。以後、前田家の祈願所に"],["1639年","火事でお堂が焼ける"],["1680年","九間の本堂を再建"],["1926年","上日寺のイチョウが国の天然記念物に指定"]],"who":[["前田利長","加賀藩2代藩主。上日寺に山屋敷を寄進した"],["前田家","江戸時代を通じて上日寺を祈願所とした"],["法道仙人","上日寺を開いたと伝わる伝説の僧"]],"deep":["本堂は延宝8年（1680年）の再建で、向唐破風造・銅板葺きの向拝が付いています。","イチョウの天然記念物指定は1926年と早く、日本の天然記念物制度（1919年の法律）が始まってまもないころのものです。","寺は北陸三十三ヵ所観音霊場の一つで、観音さまをめぐる巡礼の人も訪れます。","境内には本堂のほか、開山堂・観音堂・鐘楼・閻魔堂・薬師堂があり、それぞれに祈りの歴史があります。","近くの朝日貝塚は縄文時代の貝塚で、氷見の海と人のつながりの古さを示します。氷見市立博物館もあわせて訪ねたい場所です。","寺の山号 «朝日山» は、背後の山の名前と同じです。寺のある «朝日本町» という地名とあわせ、東の海から朝日がのぼる氷見の地形をよく表しています。"],"look":["国の天然記念物の大イチョウ（秋の黄葉が見ごろ）","1680年再建の本堂と唐破風の向拝","朝日山公園から見る氷見の町と富山湾","近くの朝日貝塚"],"q":["上日寺のイチョウが国の天然記念物に指定されたのは何年？","1926年（大正15年）です。"],"koji":[],"myth":"白鳳時代の創建、法道仙人の開基、イチョウの樹齢（千年以上）は伝承。","img":["朝日貝塚","氷見市","イチョウ"],"wp":"上日寺","rel":{"ev":[],"grave":[]},"ph":[["c:e/ef/Ginkgo_at_Jyonichiji_temple.JPG",3456,5184],["c:6/60/Asahi_kaizuka_himi.jpg",6000,4000,"朝日貝塚"],["c:4/49/Himi_port.jpg",6000,4000,"氷見市"],["c:2/22/Ginkgo_2024.jpg",3264,2448,"イチョウ"]]},{"id":"16_ankyoji","n":"安居寺（南砺の古観音）","yomi":"あんごじ","cat":"寺社","rank":"B","y":1200,"era":["heian","edo"],"sh":"","ad":"南砺市安居","st":"JR城端線 福野駅から車で約10分（歩くと遠いので車・タクシーが便利）","la":36.577,"lo":136.88,"hook":"砺波平野のはずれ、杉木立の丘の上で、平安の観音さまが千年近く里を見守ってきた。","lead":"安居寺は、南砺市の小さな丘にある真言宗の古いお寺です。本尊の観音さまは平安時代に作られたとされる木の仏像で、国の重要文化財に指定されています。«越中の古観音» として、昔から近くの村々の人がお参りに通ってきました。","story":["砺波平野を西へ進むと、田んぼの向こうに、こんもりとした森が見えてきます。その森の中にあるのが安居寺です。«安居（あんご）» とは、お坊さんが雨の季節に一か所にこもって修行することを表すことば。静かな山の中で修行する場所、という意味がこめられているのかもしれません。","寺では、その始まりをずっと昔、奈良時代にまでさかのぼる、と伝えています。ただし、それを確かめられる古い記録は残っていません。«本当にそんなに古いの?» と思ったら、手がかりになるのが本尊の観音さまです。仏像の作りや木の彫り方から、平安時代の作と考えられていて、少なくともそのころには、ここに大切にまつられる仏さまがいたことがわかります。","観音さまは、困っている人の声を聞いて救ってくれる仏さまです。昔の砺波の村々では、日照りや大水、はやり病があるたびに、人びとが «どうか助けてください» と丘をのぼってきたことでしょう。農家にとって、お天気や作物の出来は命に関わる大問題でした。お寺は、村の暮らしの不安を受けとめる場所だったのです。","江戸時代、越中は加賀藩の領地になりました。藩の殿さまや家臣も、古いお寺や神社を大切にしました。安居寺にも、藩とのつながりを伝える話が残っているといわれます。また、越中の観音霊場めぐりの札所のひとつとしても知られ、巡礼の人たちがここから旅を始めた、とも伝わります。","いま、境内は春には桜、秋には紅葉がきれいで、近くは公園として整えられています。ふだんは静かな寺ですが、長い年月、村人たちの祈りをたくわえてきた場所です。石段をのぼりながら、«千年前、この道を誰が歩いたのだろう?» と想像してみてください。"],"tl":[["奈良時代","寺伝では、このころに寺が開かれたとされる（確かな記録はない）"],["平安時代","本尊の木造聖観音立像が作られたと考えられる"],["戦国時代","越中は一向一揆や戦国大名の争いの舞台に"],["江戸時代","加賀藩の領地となり、地域の祈りの寺として続く"],["近代以降","本尊の観音像が国の重要文化財に指定される"],["現在","越中の観音霊場めぐりの札所として参拝者が訪れる"]],"who":[["地元の村人たち","雨乞い・病よけなど、暮らしの願いを観音にたくした"],["歴代の住職","古い本尊と寺を守り伝えてきた"],["加賀藩","越中を治めた藩。領内の古い寺社を保護した"]],"deep":["本尊は «聖観音（しょうかんのん）» の立像。腕が多い千手観音などと違い、もっとも基本の姿の観音です。一本の木から彫り出す作り方など、平安時代の特徴が見られるとされます。","«奈良時代に始まった» という話は寺の言い伝え（寺伝）で、その時代の文書は残っていません。北陸の古寺には、よく似た «奈良時代開創» の伝承が多く、比べて読むとおもしろいテーマです。","安居寺は真言宗の寺です。越中の西部、とくに砺波地方は浄土真宗がとても盛んな土地で、真言宗の古い寺がこうして残っているのは貴重だといえます。","本尊は秘仏として、ふだんは公開されないことがあります。拝観できる時期は限られるといわれるので、行く前に寺や市の観光案内で確かめるのが安心です。","砺波平野は家々が田んぼの中に点々と建つ «散居村（さんきょそん）» で有名です。安居寺の丘の周りからも、屋敷林に囲まれた家が散らばる景色が見え、寺と村の関係を感じられます。"],"look":["本尊をまつる本堂（公開の有無は事前確認を）","境内の古い石仏や石灯籠","参道の杉木立","周りの散居村の風景"],"q":["安居寺の «安居（あんご）» とはもともと何を表すことば？","お坊さんが雨の季節などに一か所にこもって修行することです。"],"koji":[],"myth":"開創を奈良時代とするのは寺伝で、確かな史料では確かめられない。本尊の制作年代も研究上の推定。","img":["南砺市","砺波平野"],"wp":"安居寺","rel":{"ev":[],"grave":[]},"ph":[["c:8/83/IOX-AROSA_%286984536175%29.jpg",4592,3448,"南砺市"],["c:c/c3/20081207%E7%A0%BA%E6%B3%A2%E5%B9%B3%E9%87%8E.jpg",1280,960,"砺波平野"],["c:8/83/Higashi-Ishiguro_Station_2020-1.jpg",3456,2304,"近く: 東石黒駅"],["c:2/27/Fukumitsu_Station_2020.jpg",3456,2304,"近く: 福光駅"],["c:8/82/R304-2019-165.jpg",1600,898,"近く: 道の駅福光"],["c:d/d6/Fukumitsu_Post_Office_2026-06-27.jpg",5712,3213,"近く: 福光郵便局"]]},{"id":"16_ryuzenji","n":"眼目山立山寺","yomi":"がんもくざんりゅうせんじ","cat":"寺社","rank":"B","y":1400,"era":["muromachi","edo"],"sh":"","ad":"中新川郡上市町眼目","st":"富山地方鉄道 上市駅から車で約10分","la":36.683,"lo":137.392,"hook":"立山を見上げる丘に、杉並木がまっすぐ続く。その先に、室町時代から続く禅寺が静かに建っている。","lead":"眼目山立山寺（がんもくざん りゅうせんじ）は、上市町にある曹洞宗の禅寺です。室町時代のはじめに開かれたと伝わり、北陸での曹洞宗の広がりを語るうえで大事なお寺のひとつです。長い杉並木の参道が有名です。","story":["上市の町から山のほうへ向かうと、背の高い杉がずらりと並ぶ道があらわれます。これが立山寺の参道です。昼間でも少しうす暗く、足音だけが響く道を歩いていると、«なぜこんなに長い並木が作られたんだろう?» と思わずにいられません。","立山寺は、曹洞宗の禅寺です。曹洞宗は、鎌倉時代に道元が中国から伝えた禅の教えで、«ただひたすら座る（只管打坐）» ことを大切にします。その教えは、室町時代になると北陸の各地に広まっていきました。能登の總持寺から出た禅僧たちが、越中や加賀に次々とお寺を開いていったのです。","寺の始まりは、室町時代のはじめごろと伝わります。開いたのは大徹宗令（だいてつそうれい）という禅僧とされます。寺には、立山の神さまが老人の姿であらわれ、この地に寺を開くよう告げた、という言い伝えもあるといわれます。«立山寺» という名前も、立山の信仰とのつながりを感じさせます。","禅寺は、ただお祈りする場所ではありませんでした。修行僧が集まって座禅をし、食事もそうじもすべて修行として行う «道場» です。立山寺も、多くの僧が学んだ寺として知られ、ここから各地に教えが広がったといわれます。戦国時代には戦乱に巻きこまれたとも伝わりますが、江戸時代には加賀藩のもとで寺が続きました。","いまも参道の杉並木は、町の人たちに大切にされています。春の新緑、夏の蝉しぐれ、冬の雪景色。季節ごとに表情を変える並木道を歩き、本堂の前で立山の方角を振り返ると、昔の禅僧たちが見ていた景色に少しだけ近づける気がします。"],"tl":[["鎌倉時代","道元が曹洞宗を伝える"],["室町時代初め","大徹宗令によって寺が開かれたと伝わる"],["室町時代","北陸に曹洞宗の寺が広がる。立山寺も修行の寺として知られる"],["戦国時代","戦乱に巻きこまれたと伝わる"],["江戸時代","加賀藩の領内の禅寺として続く"],["現在","杉並木の参道とともに、地域の寺として親しまれる"]],"who":[["大徹宗令","立山寺を開いたと伝わる室町時代の禅僧"],["道元","曹洞宗を日本に伝えた鎌倉時代の僧"],["立山の神（伝承）","老人の姿であらわれ寺を開くよう告げたという言い伝え"]],"deep":["«眼目山» という山号は、所在地の地名 «眼目（さっか）» からきています。地名は «さっか» と読むことが多く、寺の山号は «がんもくざん» と読むのがふつうです。読み方のちがいに注意。","北陸の曹洞宗は、能登の總持寺を中心に大きな勢力を持ちました。總持寺の二代目とされる峨山韶碩の門下から多くの弟子が出て、各地に寺を開いたといわれます。立山寺もその流れの中に位置づけられます。","寺に «立山» の名がついていることは、立山信仰と禅寺の関係を考える手がかりになります。ただし、立山の神が寺を開かせたという話は伝承で、史料で確かめられるものではありません。","参道の杉並木は、寺を訪れた人を長い距離歩かせることで、心を落ち着かせる «結界» の役目を持っていたと考える人もいます。杉の本数や樹齢については、いろいろな数字が語られています。","上市町は、立山連峰の剱岳のふもとの町でもあります。寺の近くから見える山なみは、禅僧たちにとって修行の心を引きしめる存在だったのかもしれません。"],"look":["杉並木の参道（ゆっくり歩いて）","本堂と山門","境内から見る立山連峰の方角","季節ごとの境内の木々"],"q":["曹洞宗で大切にされる «只管打坐（しかんたざ）» とはどういう意味？","«ただひたすら座禅をする» という意味。座ること自体を修行と考えます。"],"koji":[{"w":"只管打坐","m":"ほかのことを考えず、ただひたすら座禅すること。曹洞宗の教えの中心"}],"myth":"開山の年代や、立山の神が寺を開かせた話は寺伝・伝承で、細部は確かめられない。","img":["立山寺","曹洞宗","總持寺"],"wp":"上市町","rel":{"ev":[],"grave":[]},"ph":[["c:d/da/Tsurugidake_20100127.jpg",2200,1800,"上市町"],["c:1/1e/Kamiichi_Town_Office.jpg",2240,1680],["c:8/84/%E5%A4%A7%E5%B2%A9%E5%B1%B1%E6%97%A5%E7%9F%B3%E5%AF%BA20230801-P1029117.jpg",1600,1200],["c:4/42/%E3%81%9D%E3%81%86%E3%82%81%E3%82%93%EF%BC%88%E3%81%9D%E3%81%86%E3%82%81%E3%82%93%E9%87%91%E9%BE%8D%EF%BC%8920230801-P1029181.jpg",1600,1200],["c:2/2f/Hayatuki_IoriBri.jpg",1600,1200],["c:d/d5/Kamiichi-machi.jpg",1076,774],["c:b/be/Nakamura_no_%C5%8Csugi_20120730_A_-_panoramio.jpg",1024,768],["c:8/80/Kamiichi-station_2018.jpg",1024,768]]},{"id":"16_gokoku_toyama","n":"富山県護国神社","yomi":"とやまけんごこくじんじゃ","cat":"寺社","rank":"B","y":1913,"era":["taisho","showa"],"sh":"","ad":"富山市磯部町","st":"富山市内電車 安野屋電停から歩いて約10分","la":36.692,"lo":137.206,"hook":"神通川のほとり、戦いで命を落とした富山の人びとの名が、静かにまつられている。","lead":"富山県護国神社は、戊辰戦争から太平洋戦争までの戦いで亡くなった、富山県ゆかりの人びとをまつる神社です。大正時代に «招魂社（しょうこんしゃ）» として始まり、昭和の初めに今の名前になりました。神通川の近くの静かな森の中にあります。","story":["富山の町を流れる神通川。その川岸に近い磯部の森に、富山県護国神社があります。鳥居をくぐると、町の音が遠くなり、背の高い木々の間から静かな拝殿が見えてきます。ここでまつられているのは、神話の神さまではなく、実際にこの国の戦いで命を落とした人たちです。","明治時代、国のために亡くなった人の魂をまつるため、各地に «招魂社» がつくられました。東京の招魂社は、のちに靖国神社になります。富山でも大正のはじめに招魂社が建てられ、戊辰戦争や日清・日露戦争で亡くなった県ゆかりの人たちがまつられました。","昭和に入ると、戦争は大きく、長くなっていきます。1939年、全国の招魂社は名前を «護国神社» に改めました。富山の招魂社も富山県護国神社となり、日中戦争、そして太平洋戦争で亡くなった多くの人が合わせてまつられていきました。その数は数万人にのぼるといわれます。","1945年8月、富山の町は大空襲を受け、ほとんどが焼けてしまいました。戦争が終わると、軍に関わる神社のあり方も問われ、全国の護国神社はきびしい時代をむかえます。それでも、家族や友を亡くした人たちがここに通い、祈りを続けました。«どうか、安らかに» ―― その思いが、神社を支えてきたのです。","いま、神社の境内には、戦いの記録や遺族の思いを伝える碑がいくつも立っています。訪れるときは、ここが悲しみと祈りの場所であることを心にとめて、静かにお参りしたいものです。そして、«なぜ多くの人が戦場に行かなければならなかったのか?» と考えることが、平和への一歩になるのかもしれません。"],"tl":[["1868年","戊辰戦争が始まる"],["1904年","日露戦争。県ゆかりの多くの兵士が戦地へ"],["大正時代初め","富山に招魂社がつくられる"],["1939年","全国の招魂社が «護国神社» に改称。富山県護国神社となる"],["1945年8月","富山大空襲。市街地の大部分が焼ける"],["戦後","遺族や県民の祈りの場として続く"]],"who":[["県ゆかりの戦没者","戊辰戦争から太平洋戦争までの戦いで亡くなり、まつられている人びと"],["遺族","戦後も祭りや慰霊を続け、神社を支えてきた人たち"],["歩兵第35連隊の兵士","富山に置かれた連隊。多くの県出身者が属した"]],"deep":["«招魂社» から «護国神社» への改称は、1939年の法令による全国一斉のものでした。各県に «指定護国神社» が置かれ、富山県護国神社もそのひとつとされました。","戦後、占領期には軍国主義との関わりが問題とされ、全国の護国神社の中には、一時的に名前を変えたところもあります。神社の歴史を調べるときは、こうした時代の変化にも注目すると深く理解できます。","まつられている人の数は «数万柱» といわれます。神社では亡くなった人を «柱（はしら）» と数えます。正確な数は、神社の案内などで確かめてください。","境内の近くには、かつて陸軍の歩兵第35連隊が富山市五福に置かれていました。連隊と神社は、戦前の富山の人びとにとって «兵士を送り出し、帰らぬ人をまつる» 一続きの場所でした。","神通川の流れはもともと今とは違い、明治から大正にかけての河川の付け替え工事で大きく変わりました。神社のあたりの地形も、その工事と関わっているといわれます。"],"look":["拝殿と、その奥の本殿（外から拝む）","境内の慰霊碑・記念碑","神通川に近い森の雰囲気","お参りは静かに。祭典の日は特にマナーに注意"],"q":["全国の «招魂社» がいっせいに «護国神社» と名前を変えたのは何年？","1939年（昭和14年）です。富山の招魂社もこのとき富山県護国神社になりました。"],"koji":[],"myth":"創建年は大正初めとされる。まつられる人数は資料により幅があり、細部は神社の案内で確認を。","img":["護国神社","富山大空襲"],"wp":"富山縣護國神社","rel":{"ev":[],"grave":[]},"ph":[["c:8/87/Toyamaken-gokoku-jinja_haiden.jpeg",3072,2304,"富山縣護國神社"],["c:c/cd/Toyamaken-chinrei-jinja.jpeg",3072,2304],["c:2/2e/Bombing_of_Toyama%2811%29.jpg",2477,2393,"富山大空襲"]]},{"id":"16_toyama_maeda_bo","n":"富山藩主前田家墓所（長岡御廟所）","yomi":"とやまはんしゅまえだけぼしょ（ながおかごびょうしょ）","cat":"墓所","rank":"B","y":1674,"era":["edo"],"sh":"富山市指定史跡","ad":"富山市長岡新","st":"JR富山駅からバスで約20分、下車後歩く。車が便利","la":36.683,"lo":137.1775,"hook":"«くすりの富山» を育てた殿さまたちが、呉羽の丘のふもとで静かに眠っている。","lead":"長岡御廟所（ながおかごびょうしょ）は、江戸時代に富山を治めた富山藩の、歴代の殿さま（前田家）とその家族のお墓です。初代の殿さまが亡くなったあとに作られ、大きな石の墓や灯籠が森の中に並んでいます。","story":["富山の西にある呉羽丘陵。そのふもとの長岡の森に入ると、ずらりと並ぶ石灯籠と、苔むした大きな墓石があらわれます。ここは、富山藩主の前田家の人びとが葬られた «御廟所（ごびょうしょ）»。江戸時代、ふつうの町人は近づくことさえできない、特別な場所でした。","富山藩は、加賀百万石の前田家から分かれて生まれた藩です。加賀藩の三代目・前田利常が、次男の利次（としつぐ）に領地を分けたことから始まりました。利次は、はじめ別の場所に城を作ろうとしましたが、やがて富山城に入って町を整えます。そして利次が亡くなると、この長岡の地に葬られました。これが御廟所の始まりです。","二代目の殿さま・前田正甫（まさとし）には、有名な話が伝わっています。江戸城で、ある大名が急に腹痛で苦しみだしたとき、正甫が持っていた薬 «反魂丹（はんごんたん）» を飲ませると、たちまち治ったというのです。«その薬をうちの国でも売ってほしい» と頼まれたことが、«越中富山の薬売り» の始まりになった、といわれます。","富山の薬売りは、家々に薬箱を預け、使った分だけあとでお金をもらう «先用後利（せんようこうり）» というしくみで全国に広がりました。藩もこの商売を守り育て、富山の大事な収入になりました。長岡に眠る殿さまたちは、今の «くすりの富山» の土台をつくった人たちでもあるのです。","明治になって藩がなくなると、御廟所もしだいに静かな森に戻っていきました。いまは市の史跡として守られています。墓石の前に立ち、«300年前、この殿さまたちは何を考えて国を治めたのだろう?» と思いをめぐらせてみてください。"],"tl":[["1639年","加賀藩から分かれて富山藩ができる。初代藩主は前田利次"],["1661年ごろ","利次が富山城に入り、城下町を整える"],["1674年","利次が亡くなり、長岡に葬られる（御廟所の始まり）"],["1690年","江戸城で反魂丹が評判になったと伝わる（伝承）"],["江戸時代","歴代藩主や一族が葬られ、御廟所が整えられる"],["1871年","廃藩置県で富山藩がなくなる"],["現在","富山市の史跡として保存"]],"who":[["前田利次","富山藩の初代藩主。長岡御廟所に最初に葬られた"],["前田正甫","二代藩主。反魂丹の伝説で知られ、売薬を育てたとされる"],["前田利常","加賀藩三代藩主。富山藩・大聖寺藩を分けて作った"],["前田利同","富山藩最後の藩主"]],"deep":["加賀藩は1639年、利常の隠居に合わせて、次男の利次に富山10万石、三男の利治に大聖寺7万石を分けました。本家を守るための «支藩» づくりで、万一のときの予備の家という意味もありました。","利次ははじめ、富山の西の «百塚（ひゃくづか）» に新しい城を築く計画を立てたといわれます。しかし加賀藩の領地と交換する形で富山城を得て、そちらを本拠にしました。","«江戸城腹痛事件» の話は、1690年の出来事として語られることが多いものの、同じ時代の確かな記録では確かめられていません。売薬の始まりを説明する «伝説» として楽しむのがよいでしょう。","«先用後利» は、今でいう «置き薬» のしくみです。薬売りが持ち歩いた «懸場帳（かけばちょう）» という顧客台帳は、とても大事な財産として受けつがれました。","御廟所には、藩主の墓のほか、奥方や子どもたちの墓もあるとされます。墓石の形や大きさの違いから、身分の違いや時代の変化を読みとることができます。","富山藩の最後の藩主・前田利同（としあつ）は明治以降も生き、華族として東京で暮らしました。そのため、藩主すべてがここに眠っているわけではありません。"],"look":["並んだ石灯籠と大きな墓石","初代・利次の墓（案内板で確認を）","呉羽丘陵のふもとの森の雰囲気","あわせて富山城址公園や売薬資料館をめぐると理解が深まる"],"q":["富山の薬売りの «先用後利» とはどんなしくみ？","先に薬を家に預けて使ってもらい、使った分の代金をあとで受け取るしくみです。"],"koji":[{"w":"先用後利","m":"用いることを先に、利益はあとに。富山の売薬の基本の考え方"}],"myth":"«江戸城腹痛事件» は伝承で、同時代史料では確認されていない。どの藩主の墓があるかは現地の案内で確認を。","img":["前田利次","前田正甫","富山の売薬"],"wp":"富山藩","rel":{"ev":[],"grave":[]},"ph":[["c:a/a9/Toyama_Municipal_Folk_Museum_%28mock_keep_tower_of_the_Toyama_Castle%29_20180503.jpg",4288,2412,"富山藩"],["c:c/ce/Toyama_Commercial_High_School.JPG",3648,2736,"近く: 富山県立富山商業高等学校"],["c:3/38/Fuchu-Usaka_Station_2020.jpg",3456,2304,"近く: 婦中鵜坂駅"],["c:2/2a/Toyama_Prefectural_General_Education_Center.JPG",3648,2736,"近く: 富山県総合教育センター"],["c:0/0f/Shinmei-elem-school_toyama-city_2018.jpg",1024,768,"近く: 富山市立神明小学校"],["c:c/c2/Toyama-sogo-shien-school_toyama-pref_2018.jpg",1024,768,"近く: 富山県立富山総合支援学校"]]},{"id":"16_sassa","n":"佐々成政のさらさら越え（厳冬の立山越え）","yomi":"さっさなりまさのさらさらごえ","cat":"伝承","rank":"B","y":1584,"era":["azuchi"],"sh":"","ad":"富山市・立山町境（ザラ峠付近、北アルプスの山中）","st":"本格的な登山でしか行けない。室堂から五色ヶ原経由で長時間の山行","la":36.556,"lo":137.615,"hook":"真冬の北アルプスを越えて、家康に会いに行く。戦国武将・佐々成政の «無茶» は、本当にあったのか?","lead":"1584年の冬、富山城の城主・佐々成政は、雪の立山連峰を越えて浜松の徳川家康に会いに行ったと伝わります。これを «さらさら越え» と呼びます。どこをどう越えたのか、本当に冬だったのか、今も議論が続く戦国の大冒険です。","story":["1584年、天下は豊臣秀吉のものになろうとしていました。これに対抗したのが徳川家康と織田信雄です。小牧・長久手の戦いで、越中の佐々成政は家康の側につきました。ところが、信雄が秀吉と勝手に仲直りしてしまい、家康も戦いをやめてしまいます。越中の成政は、秀吉方の前田利家に囲まれ、ひとり取り残されました。","«このままでは終われない。家康どのにもう一度立ち上がってもらわねば!» 成政はそう考えたといわれます。しかし、浜松へ向かう道はどこも敵の領地。残された道は、雪に閉ざされた北アルプスを越えることだけでした。季節は、真冬の12月（旧暦）です。","成政はわずかな家来とともに富山を出発し、立山の山中に入ったと伝わります。ザラ峠を越え、黒部川の谷へ下り、さらに針ノ木峠を越えて信濃の大町へ出た、というのが有名な説です。雪の中、凍える手で岩をつかみ、道なき道を進む ―― 想像するだけで、身ぶるいがします。«さらさら» の名は、このザラ峠からきたともいわれます。","命がけの旅の末、成政は浜松にたどり着き、家康に会いました。しかし家康の答えは «もう戦わない» というものだったといわれます。成政の苦労は報われませんでした。翌年、秀吉は大軍で越中に攻め入り、成政は降伏します。のちに肥後（熊本）の大名になりましたが、一揆が起こった責任を問われて、切腹させられました。","«本当に冬のアルプスを越えられたのか?» という疑問は、昔から多くの人がいだいてきました。道すじについても別の説があります。それでも、ザラ峠の名前とともに語られる成政の話は、富山の人たちにとって、負けても最後まであきらめなかった武将の物語として、今も語りつがれています。"],"tl":[["1580年ごろ","佐々成政が織田信長から越中を任される"],["1582年","本能寺の変。信長が亡くなる"],["1584年","小牧・長久手の戦い。成政は家康方につく"],["1584年冬（旧暦12月）","雪の立山を越えて浜松へ向かったと伝わる（さらさら越え）"],["1585年","秀吉の大軍が越中へ。成政は降伏する"],["1587年","肥後の大名になる"],["1588年","肥後国人一揆の責任を問われ切腹"]],"who":[["佐々成政","越中の大名。さらさら越えの主人公"],["徳川家康","成政が助けを求めた相手。再戦には応じなかったといわれる"],["豊臣秀吉","天下統一を進めた。1585年に越中を攻めた"],["前田利家","加賀の大名。秀吉方として成政と戦った"],["織田信雄","家康と組んだが秀吉と和睦した"]],"deep":["«さらさら越え» の道すじは、ザラ峠〜黒部川〜針ノ木峠のルートが有名ですが、確かな記録は乏しく、別の峠を通った説や、季節についての異論もあります。","成政が浜松に着いたことは、同時代の記録からもうかがえるとされます。一方で、途中の山中のようすを具体的に書いた確かな史料はなく、物語の多くは後の時代の書物にもとづいています。","ザラ峠は標高2300mを超える峠で、今も夏の登山道になっています。現代の装備でも冬に越えるのはきわめて危険で、そのことが «本当にできたのか» という議論を生んでいます。","成政には «黒百合伝説» も伝わります。側室の早百合を疑って殺したため、その恨みで佐々家が滅んだ、というこわい話です。これは後の時代に作られた話と考えられています。","立山山麓の «立山カルデラ» の周辺は、江戸時代の大地震で大きく崩れた地域でもあります。成政の時代の山道と今の地形は、同じではないことに注意が必要です。"],"look":["（登山者向け）ザラ峠と五色ヶ原の風景","室堂から見る立山連峰（成政が越えた方角を想像して）","富山市の富山城址公園（成政の居城があった場所）","立山カルデラ砂防博物館などで地形を学ぶ"],"q":["佐々成政が真冬の山を越えて会いに行った相手は？","浜松の徳川家康です。秀吉との戦いを続けるよう頼みに行きましたが、家康は応じなかったといわれます。"],"koji":[],"myth":"道すじ・季節・同行者の数などは諸説あり、後世の書物による部分が多い。黒百合伝説は後世の創作と考えられる。","img":["ザラ峠","針ノ木峠","富山城"],"wp":"佐々成政","rel":{"ev":[],"grave":[]},"ph":[["c:3/38/Sassa_Narimasa.JPG",408,484,"佐々成政"],["c:7/7c/Hira_Castle_site_ac_%281%29.jpg",5887,3914],["c:6/64/Sassa_Narimasa%27s_Tonsure_Monument.jpg",1280,960],["c:5/5f/Isobe_no_Ippon_Enoki.jpg",1280,960],["c:e/e1/Sasaragoe.jpg",1606,752],["c:f/f1/Toyama_20230717_105650.jpg",4608,3072,"ザラ峠"],["c:e/ed/Harinoki_Pass.jpg",6000,4000,"針ノ木峠"],["c:a/a9/Toyama_Municipal_Folk_Museum_%28mock_keep_tower_of_the_Toyama_Castle%29_20180503.jpg",4288,2412,"富山城"]]},{"id":"16_sugano_house","n":"菅野家住宅（高岡の土蔵造り）","yomi":"すがのけじゅうたく","cat":"町","rank":"B","y":1901,"era":["meiji"],"sh":"国の重要文化財","ad":"高岡市木舟町","st":"万葉線 片原町電停から歩いて約5分／JR高岡駅から歩いて約15分","la":36.7515,"lo":137.0205,"hook":"大火で町が焼けた翌年、商人たちは «二度と燃えない家» を建てた。黒く光る壁が、その決意を今に伝える。","lead":"菅野家住宅は、高岡の «山町筋（やまちょうすじ）» に建つ、明治時代の大きな商家です。1900年の大火のあとに、火に強い «土蔵造り» で建てられました。黒い漆喰の重々しい壁が特徴で、国の重要文化財に指定されています。","story":["1900年（明治33年）、高岡の町を大きな火事がおそいました。木造の家が並ぶ町は、あっという間に炎に包まれ、商人たちの店や蔵の多くが焼けてしまいました。«このままでは、また同じことが起きる。燃えない町をつくろう!» ―― 焼け跡に立った人びとは、そう決意したのです。","そこで選ばれたのが «土蔵造り» でした。家の柱や壁を厚い土でおおい、その上を漆喰で塗り固める作り方です。まるで家そのものを大きな蔵にしてしまうような方法で、火が燃え移りにくくなります。菅野家住宅は、大火の翌年ごろに建てられた、この土蔵造りの代表的な家です。","菅野家は、高岡で綿や糸などをあつかう大きな商家でした。高岡は江戸時代から、加賀藩の保護を受けた商工業の町として栄えていました。明治になると、商人たちは銀行や電力会社など新しい事業にも乗り出します。菅野家もそうした地元の有力な家のひとつだったといわれます。","家の正面に立つと、まず目に入るのが黒くつややかな壁です。漆喰に墨などをまぜて黒く仕上げ、何度も磨いて光らせたといわれます。屋根の上の «箱棟（はこむね）»、窓の重い扉、そして内部の吹き抜けや豪華な座敷。«商売が大成功していることを、町の人に見せたかったのかな?» と想像がふくらみます。","いまの山町筋には、同じような土蔵造りの家が並び、国の重要伝統的建造物群保存地区になっています。毎年5月1日には «御車山（みくるまやま）» がこの通りを進みます。明治の商人たちが «燃えない町» にかけた思いが、祭りの日も静かに町を守っているのです。"],"tl":[["1609年","前田利長が高岡の町を開く"],["江戸時代","加賀藩の保護のもと、商工業の町として栄える"],["1900年","高岡大火。町の中心部が大きく焼ける"],["1901年ごろ","菅野家住宅が土蔵造りで建てられる"],["昭和後期","国の重要文化財に指定される"],["2000年","山町筋が重要伝統的建造物群保存地区に選ばれる"]],"who":[["菅野家","高岡の有力な商家。住宅の持ち主"],["前田利長","加賀藩二代藩主。高岡の町を開いた"],["高岡の町人たち","大火のあと、土蔵造りの町並みをつくりあげた人びと"]],"deep":["土蔵造りは、関東では «店蔵（みせぐら）» と呼ばれ、埼玉県の川越が有名です。高岡の土蔵造りは、雪の多い北陸の気候に合わせた工夫があり、比べてみるとおもしろいテーマです。","黒い漆喰は、白い漆喰よりも手間がかかるといわれ、商家の «財力の見せどころ» でもありました。壁の黒光りは、職人の技術の高さを示しています。","山町筋の町並みには、明治の土蔵造りだけでなく、大正・昭和の洋風建築も混じっています。赤いレンガの防火壁が見られる建物もあり、防火への工夫が一つではなかったことがわかります。","菅野家住宅は、今も人が暮らす家でもあるといわれます。公開される部分や時間は限られることがあるので、見学の前に確認しましょう。","高岡では明治以前にも何度か大火がありました。1900年の大火は特に被害が大きく、町のつくりを大きく変えるきっかけになりました。"],"look":["黒漆喰の正面の壁（光り方に注目）","屋根の箱棟と鬼瓦","公開時は内部の吹き抜けと座敷","周りの山町筋の町並み（土蔵造りや洋館）"],"q":["菅野家住宅のような、家全体を厚い土壁でおおって火に強くした作り方を何という？","«土蔵造り（どぞうづくり）» です。1900年の大火のあと、高岡で多く建てられました。"],"koji":[],"myth":"建築年は大火の翌年ごろとされる。公開範囲・時間は変わることがあるので要確認。","img":["山町筋","高岡市","土蔵造り"],"wp":"菅野家住宅","rel":{"ev":[],"grave":[]},"ph":[["c:6/6e/Town_Of_Storehouse_Making_%E5%9C%9F%E8%94%B5%E9%80%A0%E3%82%8A%E3%81%AE%E7%94%BA%E4%B8%A6%E3%81%BF_%E9%AB%98%E5%B2%A1%E5%B8%82%E6%9C%A8%E8%88%9F%E7%94%BA_-_panoramio.jpg",2832,2128,"山町筋"],["c:c/c4/Takaoka_montage.JPG",3600,5085,"高岡市"],["c:f/f0/Kurayoshi_Utsubuki-Tamagawa02n4592.jpg",4592,3056,"土蔵造り"]]},{"id":"16_inotani_seki","n":"猪谷関所跡（飛騨街道の関）","yomi":"いのたにせきしょあと","cat":"街道","rank":"B","y":1700,"era":["edo"],"sh":"","ad":"富山市猪谷","st":"JR高山本線 猪谷駅から歩いて約5〜10分","la":36.444,"lo":137.252,"hook":"越中のブリは、この関所を通って飛騨の山奥へ。山と川にはさまれた小さな関に、人と物の行き来がぎゅっと詰まっていた。","lead":"猪谷（いのたに）は、富山と飛騨（岐阜県）をむすぶ飛騨街道の、越中側の出入り口です。江戸時代には関所が置かれ、人や荷物を調べていました。建物は残っていませんが、近くに «猪谷関所館» という資料館があり、当時のようすを学べます。","story":["神通川をさかのぼっていくと、両側から山がせまり、谷がぐっと細くなります。その先にあるのが猪谷です。ここから先は飛騨の国。江戸時代、この国境の村に、越中側の関所が置かれていました。","関所は、人や物の出入りを見張る «国の門» です。とくに厳しく調べたのは、武器が持ちこまれること、そして女の人が国の外へ出ていくこと。«入り鉄砲に出女（でおんな）» ということばがあるように、関所は国の安全を守る大切な場所でした。猪谷の関所でも、旅人は «手形» という通行証を見せなければなりませんでした。","猪谷を通った荷物で有名なのが、富山湾でとれた «ブリ» です。塩でしめたブリは、この飛騨街道を通って飛騨の高山へ運ばれ、さらに信州の松本方面まで届けられました。山国の人たちにとって、ブリは年越しに欠かせないごちそう。飛騨から信州へ届いたブリは «飛騨ブリ» と呼ばれたといいます。","反対に、飛騨からは木材や山の産物が越中へ運ばれてきました。険しい山道を、重い荷物を背負って歩いた «ボッカ（歩荷）» と呼ばれる人たちもいました。«この荷物を背負って、あの山を越えるの?» と驚くほどの重さを運んだといわれます。","明治になると関所は廃止され、やがて鉄道の高山本線が通りました。いま猪谷駅は、JR西日本とJR東海の境の駅です。昔も今も、ここは «越中と飛騨の境目»。関所館の展示を見たあと、駅のホームから谷を見わたせば、人と物が行きかった街道の姿が浮かんでくるでしょう。"],"tl":[["江戸時代初め","加賀藩・富山藩のもとで、飛騨街道の越中側に関所が置かれる"],["江戸時代","ブリや塩が越中から飛騨・信州へ、木材などが飛騨から越中へ運ばれる"],["明治初め","全国の関所が廃止される"],["1934年","高山本線が全線開通する"],["現在","猪谷関所館で関所の歴史を紹介"]],"who":[["関所の役人","手形を調べ、人と荷物を見張った"],["ボッカ（歩荷）","重い荷物を背負って山道を運んだ人びと"],["ブリを運んだ商人","富山湾のブリを飛騨・信州へ届けた"]],"deep":["«飛騨街道» には、神通川沿いの道と、その支流沿いの道など、複数のルートがありました。猪谷はそれらが越中から飛騨へ抜ける大事な地点でした。","富山と飛騨・信州をむすぶ道は、ブリが運ばれたことから «ぶり街道» とも呼ばれます。富山湾のブリが、遠く松本の年取り魚になったという話は、流通の歴史としてよく知られています。","関所の «手形» は、旅の目的や身元を書いた書類です。村の役人やお寺が発行することが多く、手形がないと関所を通れませんでした。","猪谷の関所は、富山藩が管理した «口留番所（くちどめばんしょ）» の一つといわれます。大きな街道の関所と比べると規模は小さく、荷物の出入りを調べる役割が大きかったと考えられます。","猪谷駅は、JR西日本とJR東海の境界駅です。江戸時代の国境が、今の鉄道会社の境になっているのは、偶然ではない «地理の力» を感じさせます。"],"look":["猪谷関所館の展示（手形や関所の模型など）","神通川の谷の地形（国境らしさ）","猪谷駅のホーム（JR2社の境の駅）","周辺の旧街道の雰囲気"],"q":["富山湾でとれて、飛騨街道を通って信州まで運ばれた魚は？","ブリです。飛騨を通って届いたことから «飛騨ブリ» とも呼ばれました。"],"koji":[{"w":"入り鉄砲に出女","m":"江戸時代の関所で、武器の持ちこみと女性が出ていくことをとくに厳しく調べたこと"}],"myth":"関所の設置年や規模の細部は資料による。建物は現存せず、関所館は後に建てられた資料館。","img":["猪谷駅","ぶり街道","関所"],"wp":"飛騨街道","rel":{"ev":[],"grave":[]},"ph":[["c:1/16/Inotani-station-building2019.jpg",4032,3024,"猪谷駅"],["c:7/7f/Ishibe_shukubanosato02s3200.jpg",3200,1800,"関所"],["c:8/8a/Hida-nakayama_sta.jpg",1280,960,"近く: 飛驒中山駅"],["c:b/b2/Mozumi_sta.jpg",1280,960,"近く: 茂住駅"],["c:5/54/Hosoiri_post-office.jpg",1555,1166,"近く: 細入郵便局"],["c:b/bb/Kinry%C5%AB-ji_temple%2C_Hida%2C_2017.jpg",4608,3456,"近く: 金龍寺 (飛騨市)"]]},{"id":"16_fushiki","n":"伏木北前船資料館（旧秋元家）","yomi":"ふしききたまえぶねしりょうかん","cat":"産業","rank":"B","y":1880,"era":["edo","meiji"],"sh":"","ad":"高岡市伏木古国府","st":"JR氷見線 伏木駅から歩いて約10分","la":36.791,"lo":137.056,"hook":"屋根の上の小さな «見張り台» から、船主は海の向こうに帰ってくる自分の船を探した。","lead":"伏木北前船資料館は、江戸時代から明治にかけて «北前船» の商売をしていた廻船問屋・秋元家の家を使った資料館です。屋根の上には港を見わたす «望楼（ぼうろう）» があり、北前船でにぎわった伏木港のようすを伝えています。","story":["伏木は、小矢部川が富山湾に注ぐ河口にある港町です。奈良時代には越中の国府が置かれ、大伴家持が国司として暮らした場所でもあります。そして江戸時代、この港は «北前船（きたまえぶね）» でおおいににぎわいました。","北前船は、大阪と北海道を、日本海まわりで行き来した商船です。大阪から北へ向かうときは塩や砂糖、着物などを積み、北海道からはニシンや昆布を積んで戻ってきました。港に立ち寄るたびに荷物を売り買いするので、«一航海で千両かせぐ» といわれるほどもうかる商売でした。","秋元家は、そうした船の荷物をあつかう廻船問屋でした。家の屋根の上には、小さな部屋がちょこんとのっています。これが «望楼»。船が帰ってくる季節になると、主人はここにのぼり、遠めがねで海を見つめたといいます。«あの帆は、うちの船だろうか?» 胸が高鳴る瞬間だったことでしょう。","しかし北前船の時代は、明治の後半に終わりをむかえます。蒸気船や鉄道、電信が広まり、港ごとの値段の違いでもうける商売が難しくなったのです。伏木港は、その後、近代的な港として生まれ変わっていきます。港の近代化に力をつくした人物として、地元の商人・藤井能三（のうぞう）の名がよく知られています。","資料館では、北前船の模型や、船の道具、商いの記録などが展示されています。望楼にのぼると、今の伏木港と、晴れた日には立山連峰も見えるといわれます。«海と山にはさまれた港» から、世界とつながる商売が生まれた ―― そのことを実感できる場所です。"],"tl":[["奈良時代","伏木に越中国府が置かれる。大伴家持が国司として赴任"],["江戸時代中期〜","北前船の寄港地として伏木がにぎわう"],["明治時代","秋元家の建物と望楼が港を見守る"],["明治後期","蒸気船・鉄道の発達で北前船がおとろえる"],["1899年","伏木港が外国貿易のできる港（開港）になる"],["現在","旧秋元家が伏木北前船資料館として公開される"]],"who":[["秋元家","伏木の廻船問屋。資料館の建物の持ち主"],["藤井能三","伏木の商人。伏木港の近代化に力をつくした"],["大伴家持","奈良時代の越中国司。伏木の国府で多くの歌をよんだ"]],"deep":["北前船の «北前» は、大阪など上方の人が日本海側の地方を指したことばから、ともいわれます。語源には諸説あります。","北前船のもうけの基本は、港ごとの値段の差です。ある港で安く買い、別の港で高く売る «買積み（かいづみ）» という方法で、船主自身が商人でもありました。","北海道のニシンは、肥料（しめかす）として北陸や西日本の田畑に運ばれました。北前船は、食べ物だけでなく、農業のしくみまで変えたのです。","富山の «昆布の消費量が多い» 食文化も、北前船で北海道の昆布が大量に運ばれてきたことと関係があるといわれます。","望楼のある商家は、北前船の港町に見られる特徴的な建物です。伏木の望楼は、港町の景観を伝える貴重な例とされます。建物の建築年は資料館の案内で確かめてください。"],"look":["屋根の上の望楼（のぼって港を見わたす）","北前船の模型や船道具の展示","商いの記録や引札（広告）","近くの伏木港と、越中国府ゆかりの勝興寺"],"q":["北前船が北海道から運んできたもので、肥料にも使われた魚は？","ニシンです。しめかすにして田畑の肥料として使われました。"],"koji":[],"myth":"北前船の «一航海千両» はよく使われる言い回しで、実際のもうけは年や船によって違う。建物の建築年は要確認。","img":["北前船","藤井能三","勝興寺"],"wp":"伏木港","rel":{"ev":[],"grave":[]},"ph":[["c:8/8b/Toyama_New_Port_002.JPG",1600,1200,"伏木港"],["c:c/cd/Port_of_Fushiki_Toyama_West_side_area_Aerial_photograph.2021.jpg",14999,8912],["c:8/85/Kaiwo-maru-001.jpg",1600,1200],["c:7/71/Kitamaebune_by_Iida_Yonezo_2.jpg",1024,768,"北前船"],["c:5/5a/Fushiki_Shokoji_main_hall_ac.jpg",5863,3899,"勝興寺"]]},{"id":"16_tachimi","n":"立美遺跡（旧石器の石器群）","yomi":"たつみいせき","cat":"遺跡","rank":"B","y":-20000,"era":["kyuseki"],"sh":"","ad":"南砺市（旧福光町）","st":"車でないと行きにくい。現地に案内施設はないとされる","la":36.54,"lo":136.87,"hook":"2万年以上前、氷河期の砺波に、ナイフのような石器をつくる人びとがいた。","lead":"立美遺跡（たつみいせき）は、南砺市にある旧石器時代の遺跡です。土器がまだなかった氷河期のころの石器がたくさん見つかりました。とくに、瀬戸内地方と同じ作り方の石器が出たことで、研究者の注目を集めました。","story":["いまから2万年以上前、地球は «氷河期» でした。今よりずっと寒く、海の水面は低く、日本列島は大陸と近い形をしていたと考えられています。そんな時代、砺波の丘の上にも、人びとが暮らしていました。土器も田んぼもない時代。人びとは、石を打ち割って道具をつくり、動物をかり、木の実を集めていました。","立美遺跡は、その旧石器時代の人びとが残した石器が見つかった場所です。見つかったのは、先のとがったナイフのような石器や、石を割ったときに出るかけら。«これが本当に人がつくった道具なの?» と思うかもしれませんが、割れ口をよく見ると、何度も計算して打ち割った跡がわかるのです。","研究者を驚かせたのは、石器の作り方でした。石の塊から、横長の薄い «はへん（剥片）» を同じ形で次々にはがしとり、それをナイフ形の石器に仕上げる方法。これは «瀬戸内技法» と呼ばれ、大阪府の国府（こう）遺跡などで知られる、瀬戸内地方に特徴的な作り方だと考えられていました。それが、はるか北陸の砺波で見つかったのです。","«瀬戸内の人びとがここまで旅してきたのか?» «技術だけが伝わったのか?» ―― 答えはまだはっきりしていません。けれども、氷河期の人びとが、思っていたよりずっと広い範囲で行き来し、知識を分かち合っていたことを示す手がかりとして、立美遺跡は重要だとされています。","いま、現地は丘陵地の中にあり、目立つ建物や展示があるわけではありません。見つかった石器は、研究機関などで保管されているといわれます。遺跡そのものより、«ここで氷河期の人が石を割っていた» と想像することが、一番の見どころかもしれません。"],"tl":[["約3万年前ごろ","日本列島で旧石器時代の人びとの活動が広がる"],["約2万年前ごろ","立美遺跡で石器がつくられたと考えられる（推定）"],["約1万6千年前ごろ","土器が使われはじめ、縄文時代へ向かう"],["昭和時代","発掘調査で旧石器時代の石器群が見つかる"],["現在","北陸の旧石器研究で重要な遺跡として知られる"]],"who":[["旧石器時代の人びと","石を打ち割って道具をつくり、狩りや採集で暮らした"],["発掘した研究者","石器の作り方から、瀬戸内とのつながりを指摘した"]],"deep":["«瀬戸内技法» は、大阪府藤井寺市の国府遺跡などの研究から名づけられた石器の作り方です。横長の剥片（翼のような形から «翼状剥片» と呼ばれる）を連続してとるのが特徴です。","瀬戸内技法でつくられるナイフ形石器は «国府型ナイフ形石器» と呼ばれます。北陸・東北など瀬戸内から遠い地域で見つかる例は、人の移動や技術の伝わり方を考える手がかりになります。","旧石器時代の年代は、地層にはさまれた火山灰などを手がかりに推定されます。ここでの «約2万年前» はおおよその目安で、遺跡ごとに研究者の見方が分かれることもあります。","旧石器時代の遺跡は、土器や建物の跡がほとんど残らないため、石器とそのかけらの分布が主な資料になります。かけらをつなぎ合わせる «接合» という作業で、石を割った順番まで復元できます。","日本の旧石器研究は、2000年に発覚した «旧石器ねつ造事件» で大きな打撃を受けました。その後、各地の遺跡は資料を慎重に見直されています。遺跡の話を読むときは、どの報告にもとづくかを意識すると良いでしょう。"],"look":["現地の丘陵の地形（氷河期の暮らしを想像）","南砺市や県の埋蔵文化財の展示（公開されていれば）","周辺の砺波平野を見下ろす景色"],"q":["横長の薄いかけらを次々にとってナイフ形石器をつくる方法で、瀬戸内地方の名がついたものは？","«瀬戸内技法» です。立美遺跡でもこの作り方の石器が見つかったとされます。"],"koji":[],"myth":"遺跡の正確な位置・年代・出土点数は報告書による。見学施設はなく、所在地の表示は大まかなもの。","img":["瀬戸内技法","ナイフ形石器","旧石器時代"],"wp":"南砺市","rel":{"ev":[],"grave":[]},"ph":[["c:8/83/IOX-AROSA_%286984536175%29.jpg",4592,3448,"南砺市"],["c:3/3d/%E8%B5%A4%E7%A5%96%E7%88%B6%E6%BA%9C%E6%B1%A0%E5%86%86%E7%AD%92%E5%88%86%E6%B0%B4.jpg",4000,3000],["c:0/08/%E5%9F%8E%E7%AB%AF%E7%94%BA_%E6%9B%B3%E5%B1%B1%E7%A5%AD%E3%82%8A_SLKY20180505_0000057.jpg",6657,4443],["c:9/99/%E4%B8%96%E7%95%8C%E9%81%BA%E7%94%A3%E8%8F%85%E6%B2%BC%E5%90%88%E6%8E%8C%E9%9B%86%E8%90%BD.jpg",5184,3456],["c:1/18/Fukumitsu_Branch.jpg",3648,2736],["c:5/5c/Kainyo.JPG",3872,2592],["c:3/30/InamibetsuinZuisenji.JPG",3865,2572],["c:a/ac/ZuisenjiTaishido.JPG",3300,2201]]},{"id":"16_asahi_kaizuka","n":"朝日貝塚（氷見）","yomi":"あさひかいづか","cat":"遺跡","rank":"B","y":-4000,"era":["jomon"],"sh":"国指定史跡","ad":"氷見市朝日丘","st":"JR氷見線 氷見駅から歩いて約15分","la":36.854,"lo":136.986,"hook":"縄文人が食べた貝がらの山から、5000年前の «台所» と «家» の姿が見えてきた。","lead":"朝日貝塚は、氷見の町を見下ろす丘の上にある縄文時代の貝塚です。大正時代に見つかり、貝がらや土器、住居の跡などが調べられました。早くから学者に注目された遺跡で、国の史跡に指定されています。","story":["氷見の町の背後にある朝日山の丘。いまは住宅や公園がありますが、何千年も前、この丘の下はもっと海に近かったと考えられています。縄文時代は今よりあたたかい時期があり、海が陸の奥まで入りこんでいたのです。丘の上の縄文人にとって、海はすぐ目の前の «食べ物の宝庫» でした。","貝塚とは、縄文人が食べた貝のからや、魚や動物の骨、こわれた土器などを捨てた場所のことです。«ごみ捨て場?» と思うかもしれません。けれども、そのごみこそが、当時の人びとが何を食べ、どんな道具を使っていたかを教えてくれる、何よりの手がかりなのです。","朝日貝塚が見つかったのは大正時代のことです。工事のときに貝がらや土器が出てきたのがきっかけでした。その後、研究者たちが調査に訪れ、貝塚の下から、縄文人の住まいの跡や、火をたいた炉の跡が見つかったといわれます。«貝塚のそばに、人びとの家があった» ―― 縄文人の暮らしが、まるごと浮かび上がってきたのです。","貝塚からは、いろいろな貝や魚の骨、石の道具、土器などが出てきました。土器の形や模様から、縄文時代の中ごろを中心とする時期のものと考えられています。人びとは、海で貝をとり、魚をつり、山で木の実を拾い、この丘で火を囲んでいたのでしょう。","いま、史跡のある場所は、朝日山公園の近くです。すぐそばの上日寺（じょうにちじ）には、国の天然記念物の大イチョウもあります。丘の上から氷見の海と、晴れた日には海の向こうの立山連峰を眺めてみてください。縄文人も、同じ山なみを見ていたかもしれません。"],"tl":[["約6000年前ごろ","縄文時代の海が今より陸の奥まで入りこむ（縄文海進）"],["縄文時代中ごろ","朝日の丘で人びとが暮らし、貝塚が形づくられる"],["大正時代","工事をきっかけに貝塚が見つかり、調査が行われる"],["大正〜昭和初め","国の史跡に指定される"],["現在","公園の近くに史跡として保存されている"]],"who":[["縄文時代の人びと","貝や魚、木の実をとって丘の上で暮らした"],["大正時代の研究者","貝塚を調査し、住居の跡などを明らかにした"],["地元の人びと","史跡として貝塚を守ってきた"]],"deep":["«縄文海進» は、約6000年前ごろをピークに海面が今より高くなった現象です。多くの貝塚が今の海岸線より内陸にあるのは、このためです。","朝日貝塚では、貝塚にともなって住居の跡や炉の跡が見つかったとされ、日本の考古学の早い時期に «貝塚と住まいの関係» を示した例として語られます。","貝の種類の割合からは、当時の海の環境（岩場か砂浜か、塩分の濃さなど）が推定できます。貝塚は «過去の海の記録簿» でもあります。","富山湾沿いには、氷見の大境洞窟など、ほかにも注目される縄文時代の遺跡があります。朝日貝塚とあわせて見ると、富山湾の縄文文化の広がりがわかります。","近くの上日寺の大イチョウは国の天然記念物で、雨乞いの伝説でも知られます。遺跡と寺をセットで歩くと、丘の長い歴史を感じられます。"],"look":["史跡の標柱と説明板","丘から見える氷見の町と海","近くの上日寺の大イチョウ","氷見市の博物館の縄文の展示（公開時）"],"q":["縄文人が食べた貝のからや骨、こわれた土器などが積み重なった場所を何という？","«貝塚» です。当時の食べ物や道具を知る大切な手がかりになります。"],"koji":[],"myth":"発見・指定の年や、住居跡の «初めての発見» などの評価は資料によって書き方が異なる。","img":["氷見市","貝塚","上日寺"],"wp":"朝日貝塚","rel":{"ev":[],"grave":[]},"ph":[["c:6/60/Asahi_kaizuka_himi.jpg",6000,4000,"朝日貝塚"],["c:2/21/Asahi_Shell_Mound_2019-12-08_%281%29_sa.jpg",6240,4160],["c:4/49/Himi_port.jpg",6000,4000,"氷見市"],["c:8/83/Conchero_Arguin.jpg",2048,1536,"貝塚"]]},{"id":"16_sakuradani","n":"桜谷古墳","yomi":"さくらだにこふん","cat":"遺跡","rank":"B","y":350,"era":["kofun"],"sh":"国指定史跡","ad":"高岡市太田","st":"JR氷見線 越中国分駅から歩いて約10〜15分","la":36.807,"lo":137.033,"hook":"富山湾を見下ろす丘の上。1600年前、海を支配した «王» がここに眠った。","lead":"桜谷古墳は、高岡市の二上山のふもと、富山湾に近い丘の上にある古墳時代の古墳群です。前方後円墳などがあり、昔からこの地域の有力者のお墓と考えられてきました。昭和のはじめに国の史跡に指定されています。","story":["雨晴海岸の近く、富山湾を見わたす小高い丘。そこに、こんもりとした木々におおわれた古墳があります。これが桜谷古墳です。«なぜこんな海の見える場所にお墓をつくったのだろう?» ―― その問いが、この古墳を読み解くカギになります。","古墳時代、各地には «王» や «豪族» と呼ばれる有力者がいて、自分の力を示すために大きなお墓をつくりました。とくに、鍵穴のような形の «前方後円墳» は、ヤマト王権（のちの朝廷）とつながりのある有力者だけがつくれた特別な形だと考えられています。桜谷古墳群にも、この前方後円墳がふくまれています。","海の近くの丘にお墓をつくったのは、海から見上げたときに、よく目立つようにするためだった、という考え方があります。富山湾を行き来する船の人たちに «ここには力のある王がいるぞ» と示す、目印のような役割です。この地域の王は、海の交通をおさえることで力を得ていたのかもしれません。","古墳からは、玉や石の腕輪の形をした飾りなどが見つかったといわれます。こうした品は、遠くの地域から運ばれてきた貴重なもので、王が広い範囲の人びととつながっていたことを示しています。","やがて奈良時代になると、すぐ近くの伏木に越中の国府が置かれます。古墳の王の時代から国府の時代へ ―― このあたりは、ずっと越中の «中心地» だったのです。古墳の上に立ち、目の前の海と、遠くの立山連峰をながめながら、1600年前の王の気持ちを想像してみてください。"],"tl":[["3世紀後半ごろ","各地で前方後円墳がつくられはじめる"],["4〜5世紀ごろ","桜谷古墳群がつくられたと考えられる（推定）"],["奈良時代","近くの伏木に越中国府が置かれる"],["昭和初め","国の史跡に指定される"],["現在","丘の上に古墳が保存され、見学できる"]],"who":[["古墳に葬られた有力者","富山湾沿いの地域を治めたと考えられる «王»"],["ヤマト王権","前方後円墳を通じて各地の有力者とつながった"],["大伴家持","のちに近くの国府で暮らした奈良時代の国司"]],"deep":["桜谷古墳群は、前方後円墳の1号墳を中心に複数の古墳からなるとされます。墳丘の大きさや形の細部は、調査の報告書や現地の説明板で確かめてください。","前方後円墳の分布は、ヤマト王権とのつながりの地図ともいえます。北陸の日本海側に前方後円墳があることは、日本海の交通が重要だったことを示しています。","古墳の年代は、埴輪や副葬品、墳丘の形から推定されます。桜谷古墳の年代については、古墳時代の前期から中期ごろとする見方があります。","富山県内には、氷見や射水、婦中など、ほかにも古墳が集まる地域があります。桜谷古墳は、海に面した立地で特に印象的な例です。","古墳のある二上山は、万葉集にもよまれた山です。大伴家持は二上山を題材にした歌を残しており、古墳の丘と万葉の風景が重なり合っています。"],"look":["前方後円墳の形（前と後ろの高さの違い）","丘の上から見る富山湾","近くの雨晴海岸と女岩","説明板で古墳群の配置を確認"],"q":["鍵穴のような形をした古墳を何という？","«前方後円墳» です。ヤマト王権とつながりのある有力者のお墓と考えられています。"],"koji":[],"myth":"年代・墳丘の規模・出土品の細部は報告書による。«海の目印» とする説は解釈の一つ。","img":["前方後円墳","二上山 (富山県)","雨晴海岸"],"wp":"桜谷古墳","rel":{"ev":[],"grave":[]},"ph":[["c:0/06/Sakuradani_Kofun_Group_%28Takaoka%29-1%2C_funkyu.jpg",6016,4000,"桜谷古墳"],["c:5/59/Sakuradani_Kofun_Group_%28Takaoka%29-2%2C_funkyu.jpg",6016,4000],["c:c/c3/NintokuTomb_Aerial_photograph_2007.jpg",1000,982,"前方後円墳"],["c:0/00/Oyabe_River_and_Mt._Futagami_ac.jpg",5863,3899,"二上山 (富山県)"],["c:8/8c/Himi-line-amaharashi.jpg",3884,2600,"雨晴海岸"]]},{"id":"16_rentai35","n":"歩兵第35連隊の跡（富山・五福）","yomi":"ほへいだいさんじゅうごれんたいのあと","cat":"昭和","rank":"B","y":1900,"era":["meiji","taisho","showa"],"sh":"","ad":"富山市五福（富山大学五福キャンパス周辺）","st":"富山市内電車 富山大学前電停からすぐ","la":36.699,"lo":137.187,"hook":"若者が学ぶキャンパスは、かつて若者が兵士として出発していった場所だった。","lead":"富山大学の五福キャンパスのあたりには、明治から昭和の戦争が終わるまで、陸軍の «歩兵第35連隊» が置かれていました。富山県から多くの若者がこの連隊に入り、日露戦争やその後の戦争に向かいました。今は大学となり、当時の建物はほとんど残っていません。","story":["富山大学の五福キャンパス。学生たちが自転車で行き来し、図書館で本を読む、にぎやかな学びの場です。けれども、ほんの80年ほど前まで、ここは陸軍の «兵営（へいえい）» でした。ラッパの音が響き、若い兵士たちが行進の訓練をしていた場所なのです。","明治時代、日本は全国に «師団» と «連隊» を置いて軍隊をととのえました。北陸には金沢に第9師団が置かれ、その中の一つとして生まれたのが歩兵第35連隊です。連隊はやがて富山の五福に移り、富山県出身の若者たちが兵士として集められるようになりました。","第9師団は、日露戦争で旅順（りょじゅん）の要塞を攻める激しい戦いに加わりました。多くの兵士が命を落とし、ふるさとには悲しい知らせが届きました。«おらの村の○○さんも、帰ってこなんだ» ―― そんな声が、県内の村々で聞かれたことでしょう。","昭和になると、戦争はさらに広がっていきます。連隊の兵士たちは中国大陸や南方の戦場へ送られ、多くが帰ってきませんでした。1945年8月には富山の町そのものが空襲で焼かれ、戦争は兵士だけでなく、ふるさとの家族の命もうばいました。","戦争が終わり、軍隊はなくなりました。兵営の跡地には大学がつくられ、«戦う場所» は «学ぶ場所» に生まれ変わりました。キャンパスを歩きながら、«ここから出ていった若者たちは、どんな思いで門を出たのだろう?» と考えてみてください。その問いを忘れないことが、この場所の歴史を受けつぐことなのだと思います。"],"tl":[["1897年ごろ","第9師団のもとで歩兵第35連隊が編成される"],["明治30年代初め","連隊が富山の五福に置かれる"],["1904〜1905年","日露戦争。第9師団は旅順の攻撃に加わる"],["1937年〜","日中戦争・太平洋戦争で各地の戦場へ"],["1945年","富山大空襲。敗戦により陸軍は解体される"],["1949年","新制の富山大学が発足。跡地がキャンパスとなる"]],"who":[["連隊の兵士たち","富山県出身の若者が多く、各地の戦場へ送られた"],["兵士の家族","出征を見送り、帰らぬ人を待った"],["第9師団","金沢に司令部を置いた陸軍の師団。第35連隊はその一部"]],"deep":["陸軍の歩兵連隊は、多くの場合、その地方の出身者で編成されました。このため、ひとつの戦いで連隊が大きな損害を受けると、同じ地方の村々が同時に悲しみに包まれることになりました。","日露戦争の旅順攻囲戦では、第9師団などが大きな損害を出しました。富山からも多くの兵士が加わったと考えられます。","戦後、全国の軍用地の多くは、学校や公園、官公庁の用地になりました。富山大学の五福キャンパスも、そうした «軍都から学都へ» の転換の一例です。","富山市内では、神通川のそばの富山県護国神社が、連隊ゆかりの戦没者をまつる場所になっています。両方をめぐると、戦前の富山の姿が立体的に見えてきます。","連隊が各時期にどの戦場に送られたかは、部隊ごとに複雑です。くわしく調べるときは、防衛省の資料や地元の戦史資料を確かめるのが確実です。"],"look":["富山大学五福キャンパス（大学の敷地。見学はマナーを守って）","キャンパス周辺に残る記念碑などがあれば確認","近くの富山県護国神社","呉羽丘陵から見た五福の町並み"],"q":["歩兵第35連隊が属していた、金沢に司令部をおいた陸軍の師団は？","第9師団です。北陸の各県の連隊がまとまって編成されていました。"],"koji":[],"myth":"編成・移駐の年、各時期の派遣先は資料で細部が異なる。跡地の遺構や記念碑の有無は現地で確認を。","img":["第9師団 (日本軍)","富山大学","旅順攻囲戦"],"wp":"歩兵第35連隊","rel":{"ev":[],"grave":[]},"ph":[["c:3/35/%E6%AD%A9%E5%85%B5%E7%AC%AC%E4%B8%89%E5%8D%81%E4%BA%94%E8%81%AF%E9%9A%8A%E6%AD%A3%E9%96%80%E5%89%8D.jpg",1628,916,"歩兵第35連隊"],["c:d/db/Ishikawa-ken_History_Museum03s3s4272b.jpg",4272,2848,"第9師団 (日本軍)"],["c:c/ce/203_Meter_Hill.jpg",1600,1109,"旅順攻囲戦"]]},{"id":"16_denki_bldg","n":"富山電気ビルデイング（空襲を耐えた建物）","yomi":"とやまでんきびるでぃんぐ","cat":"昭和","rank":"B","y":1936,"era":["showa"],"sh":"国の登録有形文化財","ad":"富山市桜橋通り","st":"富山市内電車 桜橋電停からすぐ／JR富山駅から歩いて約10分","la":36.6925,"lo":137.217,"hook":"1945年8月2日の朝、焼け野原になった富山の町に、このビルだけがぽつんと立っていた。","lead":"富山電気ビルデイングは、1936年に建てられた鉄筋コンクリートのビルです。1945年の富山大空襲で町のほとんどが焼けたとき、焼け残った数少ない建物の一つでした。今もホテルやレストランとして使われ、国の登録有形文化財になっています。","story":["富山駅から南へ、路面電車の走る大通りを歩いていくと、どっしりとしたクリーム色のビルが見えてきます。丸みのある角、縦に長い窓。昭和のはじめの «モダン» な香りが漂うこの建物が、富山電気ビルデイングです。富山の人たちからは «電気ビル» と呼ばれて親しまれています。","このビルは、1936年、電力会社の本社として建てられました。当時、富山は立山の雪どけ水を利用した水力発電がさかんで、«電気の県» として発展していました。ビルには事務所だけでなく、ホールや食堂などもあり、町の人たちが集まる社交の場でもあったといわれます。","1945年8月1日の夜から2日の未明にかけて、アメリカ軍の爆撃機の大編隊が富山の上空にあらわれました。大量の焼夷弾（しょういだん）が落とされ、町は一晩で火の海になりました。市街地のほとんどが焼け、亡くなった人は2700人をこえるといわれます。戦争が終わる、わずか2週間前のことでした。","夜が明けたとき、見わたすかぎりの焼け野原の中に、電気ビルは立っていました。鉄筋コンクリートの頑丈な建物だったからです。«あのビルが残っとる!» ―― 焼け出された人びとにとって、その姿はどれほど心強く見えたことでしょう。戦後、ビルは町の復興を見守り、進駐軍が使った時期もあったといわれます。","いま、ビルの中にはホテルやレストランが入り、結婚式やパーティーも開かれています。華やかな時間が流れる一方で、壁の中には空襲の夜の記憶が眠っています。訪れたときには、ビルが耐えたあの夜のこと、そして焼け跡から立ち上がった人びとのことも、少しだけ思い出してください。"],"tl":[["1936年","富山電気ビルデイングが完成する"],["1941年ごろ","電力会社の統合が進む（戦時の電力国家管理）"],["1945年8月1〜2日","富山大空襲。市街地の大部分が焼けるが、ビルは焼け残る"],["戦後","町の復興を見守る。一時は進駐軍に使われたといわれる"],["2000年代","国の登録有形文化財になる"],["現在","ホテル・レストランとして使われている"]],"who":[["富山電気の関係者","富山の電力事業を担った人びと。ビルを本社として建てた"],["空襲を受けた富山市民","8月2日未明の空襲で家や家族を失った人びと"],["戦後の富山の人びと","焼け跡から町を立て直した"]],"deep":["富山大空襲では、市街地の約99.5%が焼けたといわれ、全国の地方都市への空襲の中でも特に被害の割合が大きかったとされます。","建物名の «ビルデイング» は、昔の表記です。«ディ» ではなく «デイ» と書くところに、昭和初期の雰囲気が残っています。","戦前の日本では、電力会社が多数あって競争していましたが、戦時中に国の管理のもとで統合されました。戦後は地域ごとの電力会社に再編され、富山は北陸電力の管内となりました。","電気ビルは、のちに増築されたとされ、建てられた時期の違う部分があるといわれます。外観をよく見て、つなぎ目を探してみるのもおもしろいでしょう。","焼夷弾は、木造の家が多い日本の町を焼くために使われました。コンクリートの建物は燃えにくく、全国の空襲でも焼け残った建物が戦後の町のシンボルになった例がいくつもあります。"],"look":["昭和初期のモダンな外観（丸みのある角や窓の並び）","ロビーやホールなど、見学できる範囲の内装","ビル前を走る路面電車との組み合わせ","近くの富山城址公園（空襲後に再建された町並みと比べて）"],"q":["富山大空襲があったのは何年の何月？","1945年8月1日の夜から2日の未明にかけてです。終戦のわずか2週間前でした。"],"koji":[],"myth":"焼失率・死者数・進駐軍の使用などは資料により数字や表現が異なる。登録文化財の登録年は要確認。","img":["富山大空襲","北陸電力"],"wp":"富山電気ビルデイング","rel":{"ev":[],"grave":[]},"ph":[["c:1/18/Toyama_Denki_Building.jpg",3648,2736,"富山電気ビルデイング"],["c:f/f0/Nihonkaidenki_in_1936.jpg",1429,1181],["c:2/2e/Bombing_of_Toyama%2811%29.jpg",2477,2393,"富山大空襲"]]},{"id":"16_arimine","n":"有峰ダム（水没した有峰村）","yomi":"ありみねだむ","cat":"昭和","rank":"B","y":1959,"era":["taisho","showa"],"sh":"","ad":"富山市有峰","st":"車でないと行けない。有峰林道（有料・夏〜秋のみ通行可）を使う","la":36.488,"lo":137.428,"hook":"高さ140mのダム湖の底に、かつて «平家の落人の村» と伝わる山里が眠っている。","lead":"有峰ダムは、富山県の南部の山奥にある大きなダムです。発電のためにつくられ、昭和30年代に完成しました。その湖（有峰湖）のあたりには、かつて «有峰村» という山里があり、人びとが暮らしていました。村はダムができるより前に、住む人がいなくなりました。","story":["富山市の南のはずれ、岐阜県との県境に近い山の中に、青く広がる湖があります。有峰湖です。周りはブナなどの深い森。夏でも空気がひんやりとしています。この湖をせき止めているのが有峰ダム。そして、この湖の周りには、昔、人びとが暮らす村がありました。","有峰村は、深い山の中の小さな村でした。冬は雪にとざされ、外の世界との行き来は大変でした。村人は焼畑や狩り、炭焼きなどで暮らしていたといわれます。村には、源平の戦いにやぶれた平家の人たちが逃げてきて住みついた、という «落人伝説» も伝わっていました。","大正時代になると、富山県は、立山連峰の豊かな水を電気に変える «電源開発» に乗り出します。有峰は、その水を集める場所として注目されました。県が村の土地を買いとることになり、村の人たちは、ふるさとを離れて山を下りていきました。«先祖代々の家を出ていく» ―― その決断は、どれほどつらかったでしょうか。","ダムの工事は戦争などで何度も止まりましたが、戦後、北陸電力のもとで本格的に進められ、1959年ごろに完成しました。高さは約140m。集めた水は発電所に送られ、富山の家庭や工場に電気を届けました。«ふるさとの水が、町を明るくしている» ―― 村を離れた人びとは、そんな思いでダムを見上げたのかもしれません。","いま、湖のほとりには、有峰の暮らしや森の自然を紹介する施設があります。湖の周りの森は大切に守られ、夏から秋にはキャンプや登山の人でにぎわいます。静かな湖面を見つめながら、そこに眠る村の記憶にも耳をすませてみてください。"],"tl":[["江戸時代","有峰は加賀藩の領内の山奥の村として続く"],["大正時代","富山県の電源開発計画で、有峰の土地が県に買い取られ、村人が山を下りる"],["昭和初め","県営で工事が始まるが、たびたび中断する"],["1951年","北陸電力が発足し、事業を受けつぐ"],["1959年ごろ","有峰ダムが完成する"],["現在","有峰湖周辺は森林公園として整備され、夏〜秋に公開"]],"who":[["有峰村の人びと","山奥で暮らし、電源開発のため村を離れた"],["富山県","大正時代に電源開発を計画し、村の土地を買い取った"],["北陸電力","戦後に工事を受けつぎ、ダムを完成させた"]],"deep":["有峰村の人びとが村を離れたのは、ダムが完成するよりずっと前の大正時代でした。«ダムで村が沈んだ» と語られることもありますが、実際には、村がなくなってから長い時間をおいてダムが完成しています。","有峰ダムは、コンクリートの重さで水をせき止める «重力式コンクリートダム» です。高さ約140mは、完成当時、全国でも有数の規模でした。","有峰の «平家の落人伝説» は、全国の山村に見られる落人伝説の一つです。確かな史料があるわけではなく、山深い村の成り立ちを説明する言い伝えと考えられます。","有峰の森は、県が水源を守るために管理してきたため、豊かなブナ林が残りました。電源開発が結果として森を守ったという、意外な側面もあります。","有峰へ向かう有峰林道は、例年、雪のない時期だけ通行でき、料金がかかります。公開の期間は年によって変わるので、行く前に確認が必要です。"],"look":["有峰ダムの堤体（高さを実感）","有峰湖と周りのブナの森","有峰の暮らしを伝える記念館などの展示","湖の周りの展望地"],"q":["有峰村の人びとが村を離れたのは、ダム完成より前？後？","前です。大正時代に県が土地を買い取り、村の人びとは山を下りました。ダムの完成は昭和30年代です。"],"koji":[],"myth":"平家の落人伝説は伝承。村の戸数・移住の年など細部は資料により異なる。完成年は1959年とも1960年とも書かれる。","img":["有峰湖","北陸電力"],"wp":"有峰ダム","rel":{"ev":[],"grave":[]},"ph":[["c:e/e4/Arimine_Dam_survey.jpg",2112,2816,"有峰ダム"],["c:6/6b/Arimine_Dam_Lake_Aerial_photograph.1977.jpg",3926,5207],["c:1/13/Omata_Dam.jpg",3072,2304],["c:d/db/Oguchigawa_Dam.jpg",3072,2304],["c:1/13/Arimine_III_power_station.jpg",3072,2304],["c:b/b4/Shinnakachiyama_power_station.jpg",2875,2156],["c:b/bf/Arimine_Dam_spillway_exit.jpg",2816,2112],["c:a/a5/Arimine_Dam_office.jpg",2112,2816]]},{"id":"16_honmiya","n":"本宮堰堤（常願寺川の砂防）","yomi":"ほんぐうえんてい","cat":"近代","rank":"B","y":1937,"era":["showa"],"sh":"国の重要文化財","ad":"富山市本宮","st":"富山地方鉄道立山線 本宮駅から歩いて約15分","la":36.587,"lo":137.364,"hook":"«これは川ではない、滝だ» ―― そう言われた暴れ川を、日本一の «砂の貯金箱» がなだめている。","lead":"本宮堰堤（ほんぐうえんてい）は、常願寺川の上流にある大きな «砂防えん堤» です。山からくずれ落ちてくる土砂をためて、下流の町や田んぼを守ります。1937年に完成し、ためられる土砂の量は日本有数です。国の重要文化財に指定されています。","story":["常願寺川は、立山から富山湾へ流れる川です。山から海までの距離が短く、とても急な流れで、昔から何度も洪水を起こしてきました。とくに大変だったのが、江戸時代の終わりの1858年に起きた大地震のあとです。立山の «鳶山（とんびやま）» が大きく崩れ、大量の土砂が川をせき止めました。","せき止められた水は、やがて土砂の壁をこわして、どっと流れ下りました。富山平野の村々は、土砂と水に飲みこまれ、多くの人が亡くなったといわれます。しかも、崩れた土砂は山の上にまだたくさん残っていました。«次の大雨で、また土砂が流れてくるかもしれない» ―― 富山の人たちは、この不安とずっと向き合うことになったのです。","明治時代、オランダから来た技術者デ・レーケは、常願寺川を見て «これは川ではない、滝だ» と言ったと伝えられています。それほど急な川だったのです。ただし、この言葉を本当に言ったのが誰だったかについては、別の説もあります。いずれにしても、常願寺川は日本でも指折りの暴れ川でした。","大正時代の終わりから、国が直接、常願寺川の砂防工事に取り組むようになりました。中心となったのが、«砂防の父» と呼ばれる赤木正雄です。山の奥に次々と砂防えん堤がつくられ、その一つとして1937年に完成したのが本宮堰堤でした。高さは約22m、ためられる土砂の量は約500万立方メートル。これは日本最大級です。","いま、本宮堰堤のダム湖には土砂がたまり、平らな河原になっています。«もう満杯なら、役に立っていないの?» と思うかもしれません。実は、たまった土砂が川の坂をゆるやかにし、流れを弱めることでも町を守っているのです。えん堤の上を流れ落ちる水のカーテンを見ながら、見えないところで働く «守り神» のことを考えてみてください。"],"tl":[["1858年","飛越地震。立山の鳶山が大きく崩れる"],["1858年","せき止められた水と土砂が流れ下り、下流に大きな被害"],["1891年","常願寺川で大きな水害。デ・レーケらによる改修が行われる"],["1926年","国による常願寺川の直轄砂防工事が始まる"],["1937年","本宮堰堤が完成する"],["2017年","本宮堰堤などが国の重要文化財に指定される"]],"who":[["赤木正雄","内務省の技術者。«砂防の父» と呼ばれ、常願寺川の砂防を進めた"],["ヨハニス・デ・レーケ","明治にオランダから来た土木技術者。常願寺川の改修に関わった"],["富山平野の人びと","何度も洪水に苦しみ、砂防工事を支えた"]],"deep":["«砂防えん堤» は、水をためる発電用のダムとは違い、土砂をためるための施設です。満杯になっても、川の勾配をゆるやかにし、土砂が一気に流れ出るのを防ぐ働きを続けます。","本宮堰堤の貯砂量約500万立方メートルは、日本の砂防えん堤の中でも最大級とされます。東京ドームの容積（約124万立方メートル）の約4倍にあたります。","1858年の地震は、越中と飛騨の境あたりで起きたことから «飛越地震（ひえつじしん）» と呼ばれます。崩れた土砂の多くは、今も立山カルデラの中に残っているといわれます。","«これは川ではない、滝だ» という言葉は、デ・レーケの言葉として有名ですが、同じ時代の確かな記録では確認できず、別の人物の発言とする説もあります。","常願寺川の砂防施設では、本宮堰堤のほかに白岩堰堤も国の重要文化財に指定されています。白岩堰堤は立山カルデラの出口にあり、日本の砂防技術の歴史を代表する施設です。"],"look":["えん堤から流れ落ちる水のカーテン","土砂で埋まった上流側の平らな河原","近くの説明板や展望地","立山カルデラ砂防博物館（立山駅近く）もあわせて"],"q":["本宮堰堤のような、川の上流で土砂をためる施設を何という？","«砂防えん堤（砂防ダム）» です。土砂が一気に流れ出るのを防ぎ、下流の町を守ります。"],"koji":[{"w":"これは川ではない、滝だ","m":"常願寺川の急流ぶりを表した言葉。デ・レーケの言葉として有名だが、確かな記録はない"}],"myth":"«これは川ではない、滝だ» の発言者には諸説ある。重要文化財指定の年は資料で確認を。","img":["赤木正雄","飛越地震","白岩堰堤"],"wp":"常願寺川","rel":{"ev":[],"grave":[]},"ph":[["c:c/c3/Jyouganji_river.jpg",1644,2192,"常願寺川"],["c:d/dc/Joganji_river01s3200.jpg",3200,2130],["c:d/d5/20081003%E7%AB%8B%E5%B1%B1%E9%80%A3%E5%B3%B0Tagged.jpg",1280,960],["c:5/53/Masao_Akagi.jpg",1084,1472,"赤木正雄"],["c:8/85/Siraiwadam.jpg",800,530,"白岩堰堤"]]},{"id":"16_shimoyama","n":"下山芸術の森発電所美術館（旧三峰発電所）","yomi":"しもやまげいじゅつのもりはつでんしょびじゅつかん","cat":"近代","rank":"B","y":1926,"era":["taisho","heisei"],"sh":"","ad":"下新川郡入善町下山","st":"あいの風とやま鉄道 入善駅から車で約15分（バスの本数は少ない）","la":36.868,"lo":137.551,"hook":"水が落ち、タービンが回っていた発電所が、いまはアートが «電気» のように人の心をゆさぶる場所になった。","lead":"下山芸術の森発電所美術館は、大正時代に建てられた水力発電所の建物を、そのまま美術館に生まれ変わらせた施設です。黒部川のほとりにあり、発電所の高い天井や水路の跡を生かした、ほかにはない展示空間になっています。","story":["黒部川が山から平野へ出てくるところ、入善町の下山に、古びたレンガ色とコンクリートの建物があります。一見すると工場のようですが、入口には «美術館» の文字。中に入ると、天井の高いがらんとした空間が広がり、上のほうから水の通り道の跡がのぞいています。ここは、もともと水力発電所だったのです。","大正時代、富山県では立山や黒部の豊かな水を使った水力発電が次々に始まりました。雪どけ水をたっぷり集める黒部川は、発電にぴったりの川でした。この建物は «三峰（みつみね）発電所» として大正時代の終わりに建てられ、山から引いた水を高いところから落として、タービンを回していました。","発電所は長いあいだ電気を送り続けましたが、やがて新しい発電所ができて役目を終えます。«古い建物をこわしてしまうのは惜しい。何かに使えないか?» ―― そう考えた人たちの手で、平成のはじめ、発電所は美術館として生まれ変わりました。","この美術館の特徴は、ふつうの美術館のような «白い壁の部屋» ではないことです。発電機が置かれていた大きな空間、水が流れ落ちていた壁。作家たちは、この場所のためだけの作品を考えて展示します。水や光、音を使った作品も多く、«発電所の記憶» とアートが重なり合う不思議な体験ができます。","建物の外に出ると、黒部川の扇状地が広がり、山からの水の力を感じられます。大正の技術者たちがつくった発電所が、100年後に芸術の場所になる ―― «建物にも第二の人生がある» ことを教えてくれる場所です。"],"tl":[["大正時代","黒部川流域で水力発電の開発が進む"],["1926年ごろ","三峰発電所が建てられる"],["昭和時代","黒部川の電源開発がさらに進み、新しい発電所が次々とできる"],["平成初め","発電所の役目を終える"],["1995年ごろ","下山芸術の森発電所美術館として開館"],["現在","発電所の空間を生かした現代美術の展示が行われる"]],"who":[["発電所を建てた技術者たち","大正時代に黒部川の水を電気に変えた"],["入善町の人びと","古い発電所を美術館として生かす道を選んだ"],["展示する作家たち","発電所の空間のための作品をつくる"]],"deep":["黒部川は、急流と豊富な水量から、日本有数の «発電の川» です。大正から昭和にかけて、上流へ向かって次々と発電所がつくられ、その集大成が昭和の黒部ダムでした。","三峰発電所は、山の上から管で水を落とし、その勢いで発電機を回す «水路式» の発電所だったと考えられます。美術館の中に残る水路の跡は、その名残です。","産業遺産を美術館に変える例は、世界各地にあります。ロンドンの «テート・モダン» も、もとは火力発電所でした。下山の美術館は、日本でのその先がけの一つともいわれます。","入善町は黒部川がつくった扇状地の上にあります。扇状地は水が地下にしみこみやすく、あちこちに湧き水が出る土地で、水と人の暮らしの深いつながりが見られます。","開館年や発電所の完成年、発電の停止年については、資料によって書き方が異なることがあります。訪問時に館内の説明で確かめるとよいでしょう。"],"look":["天井の高い発電所の空間そのもの","壁の上に残る水路の跡","その時々の現代美術の展示","周りの黒部川扇状地の風景"],"q":["ロンドンの美術館 «テート・モダン» も、もとは何の施設だった？","発電所（火力発電所）です。下山の美術館と同じく、発電所を美術館に変えた例です。"],"koji":[],"myth":"建設年・発電停止年・開館年は資料により細部が異なる。展示内容は時期によって変わる。","img":["黒部川","入善町"],"wp":"下山芸術の森発電所美術館","rel":{"ev":[],"grave":[]},"ph":[["c:5/5c/Kokuto_III_power_station_and_Nizayama_Forest_Art_Museum_1.jpg",3739,2104,"下山芸術の森発電所美術館"],["c:4/4b/Kurobe_River.jpg",800,600,"黒部川"],["c:9/9b/%E6%9D%89%E6%B2%A2%E3%81%AE%E6%B2%A2%E3%82%B9%E3%82%AE%E3%81%AE%E6%B1%A0.jpg",2048,1536,"入善町"]]},{"id":"16_munakata","n":"棟方志功の疎開の地（福光・愛染苑）","yomi":"むなかたしこうのそかいのち（ふくみつ・あいぜんえん）","cat":"学び","rank":"B","y":1945,"era":["showa"],"sh":"","ad":"南砺市福光","st":"JR城端線 福光駅から歩いて約15分","la":36.557,"lo":136.874,"hook":"«わだばゴッホになる» と叫んだ青森の版画家は、戦争を逃れた富山の小さな町で、新しい自分に出会った。","lead":"世界的な版画家・棟方志功は、太平洋戦争の終わりごろ、東京から富山県の福光町（今の南砺市）に疎開し、約6年間くらしました。その家 «鯉雨画斎（りうがさい）» などが «愛染苑（あいぜんえん）» として残り、棟方の作品と暮らしにふれることができます。","story":["青森に生まれた棟方志功は、子どものころにゴッホのひまわりの絵を見て、«わだば（わたしは）ゴッホになる!» と心に決めたといわれます。やがて東京に出て、木に彫って刷る «版画» の世界で、力強く、自由な作品を次々と生み出していきました。棟方は自分の作品を «版画» ではなく «板画（はんが）» と書きました。«板の命を生かしたい» という思いからだといいます。","1945年、戦争はいよいよ激しくなり、東京も空襲にさらされるようになりました。棟方は家族とともに、富山県の福光町に疎開します。福光のお寺の住職と親しくしていたことがきっかけでした。まもなく東京の家は空襲で焼け、それまでの版木の多くが失われたといわれます。","福光の町は、浄土真宗の信仰があつい土地でした。人びとは朝夕に念仏をとなえ、仏さまとともに暮らしていました。棟方はその空気の中で、«他力（たりき）»、つまり «自分の力だけでなく、大きな力に生かされている» という考え方に深く打たれたといわれます。«自分が彫っているのではない。板が、仏さまが、彫らせてくれるのだ» ―― そんな境地に近づいていったのです。","福光で暮らした家を、棟方は «鯉雨画斎» と名づけました。家の中のふすまや戸、さらにはトイレの中にまで、棟方の絵が描かれているといわれます。近所の子どもたちと遊び、町の人たちと語り合いながら、棟方はこの町で数多くの作品を生み出しました。","1951年、棟方は東京に戻り、その後、国際的な美術展で大きな賞を受けて «世界のムナカタ» と呼ばれるようになります。その飛躍の土台には、福光での6年間がありました。愛染苑をたずね、棟方が見ていた庭や、彼が絵を描いた戸をながめると、戦争の時代にも失われなかった «描く喜び» が伝わってきます。"],"tl":[["1903年","棟方志功が青森に生まれる"],["1920年代","東京に出て、版画の道を歩みはじめる"],["1945年","福光町に疎開。東京の家は空襲で焼ける"],["1946年ごろ","福光に家を建て «鯉雨画斎» と名づける"],["1951年","東京に戻る"],["1956年","ヴェネツィア・ビエンナーレで国際版画大賞を受賞"],["1975年","亡くなる"]],"who":[["棟方志功","青森出身の板画家。福光に疎開し約6年暮らした"],["福光の寺の住職","棟方と親しく、疎開のきっかけをつくったとされる"],["福光の町の人びと","棟方の家族を迎え入れ、交流した"]],"deep":["棟方の «板画» という書き方は、彫刻刀で板を彫る行為そのものを大切にする考えから来ています。彼は «板の生まれた質» を生かすことを語りました。","福光のある砺波地方は «真宗王国» とも呼ばれるほど浄土真宗がさかんな地域です。棟方の作品に仏教的なテーマが多いのは、福光での体験が大きく影響したとされます。","鯉雨画斎の «鯉雨» という名前は、雨の中を鯉がのぼる姿のような力強さへの思いがこめられているともいわれますが、名づけの理由には諸説あります。","愛染苑には、鯉雨画斎のほか、棟方の作品を展示する記念館があります。近くの光徳寺などにも棟方ゆかりの作品が伝わるといわれ、町全体が «棟方の足あと» を感じられる場所になっています。","1956年のヴェネツィア・ビエンナーレでの国際版画大賞は、日本人の美術家が国際的に高く評価された大きな出来事でした。その多くの作品の考え方は、福光時代に育まれたといわれます。"],"look":["鯉雨画斎（家の中の戸やふすまの絵）","棟方の作品の展示","愛染苑の庭","近くの寺など、町に残る棟方ゆかりの場所"],"q":["棟方志功が子どものころ «わだばゴッホになる» と言ったとされるのは、ゴッホの何という絵を見たから？","«ひまわり» の絵（の複製）を見たからだといわれます。"],"koji":[{"w":"わだばゴッホになる","m":"棟方志功のことばとして知られる。«わたしはゴッホになる» という、絵の道への強い決意"}],"myth":"疎開のきっかけ、家の名前の由来、トイレの絵などの逸話は、伝記や本人の語りによるもので細部に諸説ある。","img":["南砺市","ヴェネツィア・ビエンナーレ"],"wp":"棟方志功","rel":{"ev":[],"grave":[]},"ph":[["c:d/d9/Shik%C5%8D_Munakata.jpg",250,342,"棟方志功"],["c:3/31/Katsuretsu-an%2C_entrance.jpg",4160,3120],["c:f/f1/Fukumitsu%2C_Nanto%2C_Toyama_Prefecture_939-1610%2C_Japan_-_panoramio_%281%29.jpg",5184,3456],["c:c/c1/%E9%87%8E%E6%85%88%E5%A7%91_Sagittaria_trifolia_-%E9%AB%98%E9%9B%84%E5%8E%9F%E7%94%9F%E6%A4%8D%E7%89%A9%E5%9C%92_Kaohsiung_Original_Botanical_Garden%2C_Taiwan-_%2826111914217%29.jpg",2736,3648],["c:4/46/Chunichi1967-03-11-1.jpg",2324,2115],["c:e/e2/Upali_%28Ubari%29%2C_from_the_series_%E2%80%9CTwo_Bodhisattva_and_Ten_Great_Disciples_of_Sakyamuni%E2%80%9D.jpg",843,2057],["c:7/78/Munakata_Shiko_Memorial_Museum_of_Art.jpg",1284,942],["c:5/56/Bundesarchiv_Bild_183-41810-0004%2C_Franz_Konwitschny.jpg",542,774]]},{"id":"16_namerikawa_kome","n":"滑川の米騒動の地（米の積み出し浜）","yomi":"なめりかわのこめそうどうのち","cat":"事件","rank":"B","y":1918,"era":["taisho"],"sh":"","ad":"滑川市（旧北国街道沿いの浜・瀬羽町周辺）","st":"あいの風とやま鉄道・富山地方鉄道 滑川駅から歩いて約10分","la":36.77,"lo":137.344,"hook":"«米を持っていかんといて!» ―― 浜に集まった女たちの声が、日本の政治を動かした。","lead":"1918年の夏、富山県の海ぞいの町で、米の値段が上がりすぎたことに苦しむ漁師の家の女性たちが、«米を町から運び出さないで» と集まりました。滑川でも大きな騒ぎになり、そのニュースが新聞で全国に広がって «米騒動» になりました。","story":["1918年（大正7年）の夏。富山湾ぞいの町々では、米の値段がどんどん上がっていました。第一次世界大戦で物の値段が上がり、さらに «シベリア出兵» のうわさで米を買いしめる商人があらわれたのです。漁師の家では、夫が遠くへ出かせぎの漁に出ていて、家を守る女性たちが毎日の米の心配をしていました。","«この町の米が、よその町へ運び出されていく。それでまた値段が上がる!» ―― 富山湾沿いの町では、米を船に積みこむ浜に、女性たちが集まりはじめました。7月の下旬に魚津で起きた動きが知られていますが、8月に入ると、滑川でも多くの人が米屋や米の積み出しの場所に集まり、米を安く売ってほしいと訴えました。","新聞は、この出来事を «越中の女一揆» などと大きく伝えました。すると、同じように米の値段に苦しんでいた全国の人びとが、次々と立ち上がります。都会でも農村でも、米屋や商人の家に人びとが押しかけ、騒ぎは全国に広がりました。軍隊が出動する地域もあり、多くの人が罪に問われました。","騒ぎの責任をとる形で、寺内正毅の内閣は総辞職し、代わって原敬が首相になります。原内閣は、大臣の多くを政党の人びとが占める、本格的な «政党内閣» でした。«浜の女たちの声が、国の政治を変えた» ―― 米騒動は、ふつうの人びとの行動が歴史を動かした出来事として、教科書にものっています。","いま、滑川の浜ぞいの古い町並みを歩くと、北国街道の宿場町だったころの面影が残っています。100年あまり前、ここで声をあげた女性たちは、特別な英雄ではなく、家族のご飯を心配するふつうのお母さんたちでした。«自分たちの暮らしを守るために、声をあげる» ―― その勇気を思いながら歩いてみてください。"],"tl":[["1914年","第一次世界大戦が始まる。物の値段が上がりはじめる"],["1918年7月","シベリア出兵のうわさなどで米の値段が急に上がる。魚津で女性たちが集まる"],["1918年8月","滑川などで多くの人が集まり、新聞で全国に伝わる"],["1918年8月〜9月","全国各地に騒ぎが広がる（米騒動）"],["1918年9月","寺内内閣が総辞職し、原敬内閣が成立する"]],"who":[["漁師の家の女性たち","米の積み出しを止め、安く売るよう訴えた"],["寺内正毅","当時の首相。米騒動の責任をとって辞職"],["原敬","米騒動のあとに首相となり、本格的な政党内閣をつくった"],["新聞記者","富山の出来事を全国に伝え、騒動が広がるきっかけとなった"]],"deep":["«米騒動発祥の地» については、魚津・滑川・水橋など富山湾沿いの複数の町に、それぞれ «ここが始まり» とする見方があります。一つの町だけで始まったのではなく、湾沿いの町々で同じころに動きがあったと考えるのが自然です。","富山湾沿いの漁師の多くは、夏に北海道や樺太などへ出かせぎの漁に出ていました。そのため町に残っていた女性たちが、騒ぎの中心になったといわれます。","新聞の見出しの «越中女一揆» ということばは、騒動を実際より激しく書き立てた面があるとも指摘されています。報道が騒ぎを全国に広げた一方、富山の実際のようすは «嘆願» に近いものだったともいわれます。","全国の米騒動では、軍隊が出動して死者が出た地域もありました。多くの人が逮捕・起訴され、社会に深い傷を残した出来事でもあります。","米騒動は、のちの普通選挙を求める運動や、労働運動・農民運動の高まりにもつながったと考えられています。"],"look":["浜ぞいの古い町並み（旧北国街道・宿場町の面影）","米騒動に関する記念碑・説明板（場所は市の案内で確認）","滑川の海岸と富山湾の眺め","魚津の旧十二銀行米倉など、ほかの町の関連地"],"q":["米騒動のあとに首相になり、本格的な政党内閣をつくった人は？","原敬です。«平民宰相» とも呼ばれました。"],"koji":[{"w":"平民宰相","m":"爵位を持たない首相という意味で、原敬を呼んだことば"}],"myth":"«発祥の地» は魚津・滑川など複数の説がある。滑川で人が集まった日付や人数は資料により異なる。","img":["米騒動","原敬","魚津市"],"wp":"滑川市","rel":{"ev":[],"grave":[]},"ph":[["c:5/5c/Hotaruika_Museum%2C_Toyama%2C_Japan.jpg",4032,3024,"滑川市"],["c:0/07/Thalassopia%2C_Toyama%2C_Japan.jpg",4032,3024],["c:8/81/Namerikawa_city_center_area_Aerial_photograph.2021.jpg",10787,7649],["c:7/70/Namerikawa_Post_Office.jpg",2240,1680],["c:d/d7/%E6%BB%91%E5%B7%9D_%EF%BC%88%E9%A7%85%E8%88%8E%EF%BC%89.JPG",2048,1536],["c:2/2e/Namerikawa_City_Hall.jpg",1600,1200],["c:5/5f/Nakanamerikawa-station_2018.jpg",1024,768],["c:b/bf/Takashi_Hara_formal.jpg",1024,1319,"原敬"]]},{"id":"16_takaoka_mikuruma","n":"高岡御車山会館（前田利長ゆかりの山車）","yomi":"たかおかみくるまやまかいかん","cat":"学び","rank":"B","y":1609,"era":["azuchi","edo"],"sh":"","ad":"高岡市守山町","st":"万葉線 片原町電停から歩いて約5分／JR高岡駅から歩いて約15分","la":36.752,"lo":137.02,"hook":"秀吉が天皇を迎えた «御所車» が、高岡の町人の手で400年以上引かれ続けている、と伝わる。","lead":"高岡御車山会館は、毎年5月1日に行われる «高岡御車山祭（みくるまやままつり）» の山車（だし）を展示し、祭りの歴史を紹介する施設です。御車山は、豊臣秀吉ゆかりの御所車がもとになったと伝わり、加賀藩の前田利長が町の人たちに与えたといわれます。","story":["5月1日の朝、高岡の山町筋に、金や漆で飾られた豪華な山車があらわれます。車輪には美しい模様、屋根の上には花のような «鉾（ほこ）»。ゆっくりと町を進む7基の山車は、«御車山（みくるまやま）» と呼ばれます。その始まりには、天下人・豊臣秀吉の名前が出てきます。","伝えによれば、秀吉は京都の聚楽第（じゅらくだい）に後陽成天皇を迎えたとき、天皇が乗る «御所車» を用意しました。その車を、のちに前田利家が秀吉から受けつぎ、さらに息子の前田利長へと伝わったといいます。«天皇が乗った車が、北陸の町に?» ―― 話を聞いただけでわくわくします。","1609年、利長は高岡に城を築き、新しい町を開きました。このとき利長が、町の人たちに御所車を与えたのが、御車山の始まりだと伝わります。町人たちはこれを大切にし、自分たちの町ごとに山車に仕立てて、祭りで引くようになりました。利長が亡くなり、高岡城が廃城になったあとも、町人たちは祭りを続け、町を商工業の町として発展させていきました。","御車山には、高岡が誇る金工（金属の細工）や漆工（うるし塗り）の技が、たっぷり使われています。高岡は銅器や漆器の町として知られ、職人たちは自分の技のすべてを山車にそそぎこみました。御車山は «動く美術館» ともいわれ、国の重要有形民俗文化財と重要無形民俗文化財の両方に指定されています。","会館では、実物の御車山を間近に見られるほか、映像や模型で祭りのようすを知ることができます。細かな飾りのひとつひとつに、町の人たちの400年の思いがこめられています。«自分たちの町の宝を、自分たちで守る» ―― その心意気こそが、高岡の町の一番の宝なのかもしれません。"],"tl":[["1588年","秀吉が聚楽第に後陽成天皇を迎える（御所車の伝承の由来）"],["1609年","前田利長が高岡城を築き、町を開く。御所車を町人に与えたと伝わる"],["1614年","利長が亡くなる"],["1615年","一国一城令の流れで高岡城は廃城となる"],["昭和〜平成","御車山が国の重要有形・無形民俗文化財に指定される"],["2015年","高岡御車山会館が開館"],["2016年","ユネスコ無形文化遺産 «山・鉾・屋台行事» の一つに登録"]],"who":[["前田利長","加賀藩二代藩主。高岡を開き、御所車を町人に与えたと伝わる"],["豊臣秀吉","聚楽第に天皇を迎えた天下人。御所車の伝承の出発点"],["前田利家","加賀藩の祖。秀吉から車を受けたと伝わる"],["高岡の町人・職人","山車をつくり、守り、祭りを続けてきた人びと"]],"deep":["御車山は、ほかの地方の山車のように «屋根の上で人がおどる舞台» がありません。上に鉾を立てた、御所車の形をよく残した山車で、これが大きな特徴とされます。","秀吉の御所車が由来という話は、町に伝わる伝承です。現在の山車は、江戸時代以降に何度も修理や新調をくり返しながら受けつがれてきたものです。","高岡は、利長の死後、城がなくなったことで町がさびれかけましたが、三代藩主の前田利常が商工業を保護したことで、«商工の町» として立ち直ったといわれます。御車山祭は、その町人文化の象徴です。","2016年にユネスコ無形文化遺産に登録された «山・鉾・屋台行事» は、全国33の祭りをまとめたもので、京都の祇園祭なども含まれます。高岡御車山祭もその一つです。","高岡の銅器は、利長が鋳物師（いもじ）を招いたことから始まったといわれます。御車山の金具には、その鋳物・金工の技術が生かされています。"],"look":["実物の御車山（車輪の飾り・鉾に注目）","祭りの映像・模型","金工・漆工の細部","会館の前の山町筋の町並み"],"q":["高岡御車山祭が行われるのは毎年何月何日？","5月1日です。7基の御車山が山町筋などを巡ります。"],"koji":[],"myth":"御所車が秀吉→利家→利長と伝わったという話は伝承で、史料で確かめられない部分がある。","img":["前田利長","高岡城","聚楽第"],"wp":"高岡御車山祭","rel":{"ev":[],"grave":[]},"ph":[["c:b/b2/%E9%AB%98%E5%B2%A1%E5%B8%82%E8%A1%97%E3%81%AE%E9%A2%A8%E6%99%AF_-_panoramio.jpg",4752,3168,"高岡御車山祭"],["c:e/e4/%E5%9C%9F%E8%94%B5%E9%80%A0%E3%82%8A%E3%81%AE%E7%94%BA%E4%B8%A6%E3%81%BF_-_panoramio_%284%29.jpg",4752,3168],["c:8/8d/Kihunemachi-takaoka_mikurumayama.JPG",2448,3264],["c:0/07/Sugano_House_1-1.jpg",2272,1704],["c:c/c4/Onmadashimachi-takaoka_mikurumayama.jpg",1340,2498],["c:f/f1/%E9%AB%98%E5%B2%A1%E5%BE%A1%E8%BB%8A%E5%B1%B1%E7%A5%AD%E5%8F%8A%E3%81%B3%E9%83%B7%E7%A4%BE%E9%96%A2%E9%87%8E%E7%A5%9E%E7%A4%BE.jpg",1933,1333],["c:6/68/Maeda_Toshinaga.jpg",354,396,"前田利長"],["c:a/af/Takaoka_Castle.jpg",4608,3456,"高岡城"]]},{"id":"16_kurikara_temple","n":"倶利迦羅不動寺（峠の不動尊）","yomi":"くりからふどうじ","cat":"寺社","rank":"B","y":1183,"era":["nara","heian","edo"],"sh":"","ad":"小矢部市石坂〜石川県河北郡津幡町倶利伽羅（倶利伽羅峠一帯。不動寺の本堂は石川県側）","st":"あいの風とやま鉄道 石動駅から車で約20分。峠道は車が便利","la":36.685,"lo":136.805,"hook":"越中と加賀の境の峠。木曽義仲が平家の大軍を谷へ追い落とした «火牛の計» の舞台に、不動明王がまつられている。","lead":"倶利伽羅峠は、富山県小矢部市と石川県津幡町の境にある峠です。峠には、剣に竜が巻きついた «倶利迦羅不動» をまつる不動寺があり、古くから旅人が道中の安全を祈りました。1183年には源平合戦の «倶利伽羅峠の戦い» の舞台になりました。なお、不動寺の本堂そのものは石川県側にあります。","story":["富山県と石川県の境には、低いけれど深い森におおわれた山並みがあります。そこを越える道が倶利伽羅峠です。昔の北陸道はこの峠を通っていて、都と越中・越後をむすぶ大切な道でした。峠には «倶利迦羅不動» がまつられ、旅人は «どうか無事に峠を越えられますように» と手を合わせました。","«倶利迦羅（くりから）» とは、不動明王が持つ剣に巻きついた竜の名前です。不動寺は、奈良時代にインドから来たお坊さんが開いたと伝わりますが、これは寺の言い伝えです。いずれにしても、峠の不動尊は、長いあいだ旅人を見守ってきました。","1183年（寿永2年）、この峠が歴史の大舞台になります。都から平維盛の率いる平家の大軍が北陸へ攻めてきました。迎え撃ったのは、信濃から来た木曽（源）義仲です。義仲は、夜になるのを待って平家の陣を攻め、平家の軍は倶利伽羅の谷へ追い落とされて大敗しました。この勝利で、義仲は一気に都へ攻め上ることになります。","この戦いには、有名な «火牛（かぎゅう）の計» の話があります。牛の角にたいまつを結びつけ、平家の陣へ突っこませた、というものです。«牛が火をつけて走ってきたら、それは驚くよね!» と思いますが、この話は『源平盛衰記』という軍記物語に出てくるもので、本当にあったかどうかは疑問視されています。中国の古い戦いの話をもとにした、物語上の演出とも考えられています。","江戸時代になると、倶利伽羅峠は加賀藩の大名行列が江戸へ向かう道になりました。いまは «源平ライン» と呼ばれる道が通り、峠には戦いの跡を伝える碑や、火牛の像などが立っています。春には八重桜が美しく、多くの人が訪れます。静かな森の中で、合戦で倒れた人びとのことも思いながら歩いてみてください。"],"tl":[["奈良時代","峠に不動尊がまつられたと伝わる（寺伝）"],["1183年","倶利伽羅峠の戦い。木曽義仲が平家の大軍を破る"],["1183年","義仲が京都に入る"],["江戸時代","北陸道の峠として、加賀藩の参勤交代の道になる"],["明治以降","鉄道・道路の発達で、峠越えの道は静かになる"],["現在","峠一帯が源平の古戦場として整備され、不動寺が参拝者を迎える"]],"who":[["木曽（源）義仲","倶利伽羅峠の戦いで平家に大勝した武将"],["平維盛","平家の大将。倶利伽羅峠で大敗した"],["今井兼平・樋口兼光","義仲に仕えた武将たち"],["峠の旅人たち","不動尊に道中の安全を祈った"]],"deep":["«火牛の計» は『源平盛衰記』に見える話で、同じころの記録や『平家物語』の多くの本には書かれていません。中国の戦国時代、斉の田単が牛に火をつけて敵を破った話が元になっているともいわれます。","倶利伽羅峠の戦いの前に、義仲は富山県側の埴生（はにゅう）八幡宮（今の護国八幡宮、小矢部市）で戦勝を祈り、願文をおさめたと伝わります。峠とあわせてたずねたい場所です。","«倶利迦羅» はサンスクリット語の音をあてた言葉で、不動明王の剣に巻きつく竜王を指します。峠の名前も、この不動信仰から来ていると考えられます。","平家方の兵が落とされた谷は «地獄谷» などと呼ばれ、伝承の地名がいくつも残ります。人骨が出た、などの話も語られますが、確かめられた記録ではありません。","峠の県境は、そのまま越中と加賀の国境でした。この峠を越えると «加賀百万石» の本国に入るという意味で、加賀藩にとっても重要な守りの地点でした。"],"look":["峠の不動寺（本堂は石川県側）","源平の古戦場の碑や火牛の像","峠からの砺波平野の眺め","小矢部市側の護国八幡宮（義仲の願文の伝承）"],"q":["牛の角にたいまつをつけて敵陣に突っこませたという作戦を何という？","«火牛の計» です。ただし軍記物語の話で、本当にあったかは疑問視されています。"],"koji":[{"w":"火牛の計","m":"牛に火をつけて敵に突っこませる奇策。中国の故事や源平の軍記に見える"}],"myth":"不動寺の開創（奈良時代・インド僧）は寺伝。火牛の計は『源平盛衰記』の話で、史実とは考えにくい。不動寺本堂は石川県津幡町にある。","img":["倶利伽羅峠の戦い","源義仲","護国八幡宮"],"wp":"倶利伽羅峠","rel":{"ev":[],"grave":[]},"ph":[["c:f/f1/R8_Kurikara_Tunnel.JPG",2048,1536],["c:c/c6/Battle_of_Kurikaradani_Kassen_Zu.jpg",8498,4293,"倶利伽羅峠の戦い"],["c:2/27/Minamoto_no_Yoshinaka.jpg",843,767,"源義仲"],["c:8/82/Hanyu_Gokoku_Hachiman-gu_Shrine.jpg",3417,2026,"護国八幡宮"]]},{"id":"16_unazuki","n":"宇奈月温泉（電源開発が生んだ温泉町）","yomi":"うなづきおんせん","cat":"近代","rank":"B","y":1923,"era":["taisho","showa"],"sh":"","ad":"黒部市宇奈月温泉","st":"富山地方鉄道 宇奈月温泉駅からすぐ","la":36.814,"lo":137.583,"hook":"山奥の源泉から、木の管で7kmも湯を引いてつくった温泉町。そこには «電気の夢» と «日本一有名な裁判» の物語がある。","lead":"宇奈月温泉は、黒部峡谷の入り口にある温泉町です。大正時代、黒部川の電源開発を進めた会社が、上流の黒薙（くろなぎ）温泉からお湯を引いてつくりました。もともと «温泉がわいていなかった場所» に生まれた、めずらしい温泉町です。","story":["黒部峡谷のトロッコ電車に乗る人たちでにぎわう宇奈月温泉。駅前には旅館やホテルが並び、湯けむりが立ちのぼっています。でも、じつはこの場所には、もともと温泉はわいていませんでした。«じゃあ、お湯はどこから?» ―― 答えは、さらに山奥の黒薙温泉です。","大正時代、黒部川の豊かな水を使って電気を起こし、アルミニウムをつくろうとする会社がありました。アルミをつくるには、たくさんの電気が必要だったのです。工事のために人や資材を運ぶ鉄道がつくられ、その玄関口として、宇奈月に新しい町をつくる計画が生まれました。«せっかくなら、温泉町にしてしまおう!» ―― こうして、黒薙温泉から木の管でお湯を引いてくることになったのです。","1923年ごろ、約7kmもの長い木管を通って、黒薙のお湯が宇奈月に届きました。何もなかった河原に、旅館や家が建ち、工事で働く人や観光客が集まる温泉町が生まれました。工事用の鉄道は、のちに観光客も乗れる «黒部峡谷鉄道» になっていきます。","ところが、この温泉が思わぬ裁判を生みます。お湯を引く管が、ほんの少しだけ他人の土地を通っていたのです。その土地を買った人が «管をどけるか、まわりの土地をまとめて高く買え» と迫りました。裁判の結果、1935年、大審院（今の最高裁判所）は «その要求は、権利をわざと悪く使うもの（権利の濫用）で認められない» と判断しました。これが、法律を学ぶ人ならだれでも知っている «宇奈月温泉事件» です。","いま、宇奈月温泉は黒部峡谷の観光の拠点として、一年中多くの人を迎えています。温泉につかりながら、«電気の夢» から生まれたこの町の歴史と、«権利は正しく使わなければならない» という教えを思い出してみてください。お湯の味わいが、少し変わるかもしれません。"],"tl":[["大正時代","黒部川の電源開発が本格化する"],["1923年ごろ","黒薙温泉から木管で湯を引き、宇奈月温泉が生まれる"],["大正末〜昭和初め","工事用の軌道が延び、宇奈月が峡谷の玄関口になる"],["1935年","大審院が «宇奈月温泉事件» の判決を出す"],["1953年","黒部峡谷鉄道が一般の旅客営業を正式に始める"],["現在","黒部峡谷観光の拠点としてにぎわう"]],"who":[["電源開発を進めた会社の人びと","アルミ製造のための電源開発と、宇奈月の町づくりを進めた"],["宇奈月温泉事件の当事者","引湯管が通る土地をめぐって争った"],["大審院の裁判官","«権利の濫用» を理由に訴えを退けた"]],"deep":["宇奈月温泉事件の判決は、のちに民法第1条に «権利の濫用は、これを許さない» という条文が加えられるきっかけの一つになったとされます（1947年の改正）。","事件で問題になった土地は、引湯管が通るほんのわずかな面積だったといわれます。わずかな土地を理由に大きな利益を得ようとしたことが «権利の濫用» と判断されたのです。","引湯管は、はじめ木の管でしたが、のちに別の素材に取りかえられてきました。長い距離をお湯を運ぶため、温度が下がらない工夫も必要でした。","黒部峡谷鉄道は、もとは電源開発の資材を運ぶための軌道で、一般の人は «便乗» という形で «命の保証はしない» 条件で乗せていたという話が有名です。","宇奈月の電源開発は、その後、昭和の黒部ダム（くろよん）へとつながっていきます。宇奈月は «黒部の電源開発の物語» の入り口でもあるのです。"],"look":["温泉街と、湯のもとになった黒薙温泉の方角","黒部峡谷鉄道の宇奈月駅とトロッコ電車","近くの山彦橋や新山彦橋（峡谷の景色）","黒部川の電源開発を紹介する展示施設"],"q":["宇奈月温泉事件で、裁判所が «認められない» とした理由を表すことばは？","«権利の濫用（らんよう）» です。権利をわざと悪く使うことは許されない、という考え方です。"],"koji":[{"w":"権利の濫用は、これを許さない","m":"民法第1条の条文。権利があっても、それを不当に使うことは認められないという原則"}],"myth":"開湯年・引湯管の長さは資料により細かな違いがある。黒部峡谷鉄道の «命の保証はしない» の話は有名だが表現は資料によって異なる。","img":["宇奈月温泉事件","黒部峡谷鉄道","黒薙温泉"],"wp":"宇奈月温泉","rel":{"ev":[],"grave":[]},"ph":[["c:e/e7/Unaduki_Onsens.jpg",1200,900,"宇奈月温泉"],["c:6/6d/Unazuki-jinja%2C_haiden.jpg",6014,3998],["c:f/f4/Unazuki-Onsen-STA.jpg",5194,3462],["c:4/43/Hotel_Kurobe.JPG",2560,1920],["c:7/7e/Unazuki_Onsen_incident_monument.jpg",1600,1200],["c:6/6f/%E6%88%A6%E5%89%8D%E3%81%AE%E5%AE%87%E5%A5%88%E6%9C%88%E6%B8%A9%E6%B3%89.jpg",1465,1015],["c:6/62/Kuronagi-onsen01.JPG",1280,960],["c:c/cf/Unaduki_Koen_s.jpg",1200,900]]},{"id":"16_alpen_route","n":"立山黒部アルペンルート（くろよんの工事道）","yomi":"たてやまくろべあるぺんるーと","cat":"昭和","rank":"B","y":1963,"era":["showa"],"sh":"","ad":"中新川郡立山町芦峅寺（黒部ダム付近）","st":"立山駅（富山側）または扇沢（長野側）からケーブルカー・バスなどを乗りついで黒部ダムへ。冬期は運休","la":36.566,"lo":137.662,"hook":"«黒部の太陽» の舞台。171人の命と引きかえに、人間が北アルプスの奥に巨大なダムを築いた。","lead":"立山黒部アルペンルートは、富山県の立山駅から長野県の扇沢まで、北アルプスをつらぬいて走る山岳観光ルートです。途中にある黒部ダムは、昭和30年代に «世紀の難工事» と呼ばれた工事で完成しました。ルートの一部は、その工事のためにつくられたトンネルがもとになっています。","story":["戦争が終わったあと、日本は急速に復興し、工場や家庭で使う電気が足りなくなりました。とくに関西では停電が続き、«電気がなければ、国が立ち直れない» という声が高まります。そこで、関西電力が目をつけたのが、北アルプスの奥深く、黒部川の上流でした。ここに巨大なダムをつくる ―― それが «くろよん（黒部川第四発電所）» の計画です。","問題は、そこへ行く道がないことでした。資材を運ぶため、まず長野県側の大町から山をつらぬくトンネルを掘ることになりました。ところが工事の途中で、岩がくだけ、冷たい水と土砂がふき出す «破砕帯（はさいたい）» にぶつかります。わずか80mほどを進むのに、7か月もかかったといわれます。«もう無理だ» という声もあがる中、作業員たちは水と闘い続け、ついに突破しました。","1963年、黒部ダムは完成しました。高さ186m、日本一の高さのアーチ式ダムです。でも、その陰で、工事全体では171人もの人が命を落としました。ダムのそばには殉職者の慰霊碑が建てられています。この工事の物語は、映画 «黒部の太陽» として広く知られるようになりました。","工事のためにつくられた道やトンネルは、その後、観光のために整えられていきます。富山側からは立山のケーブルカーやバス、立山トンネル、黒部側のケーブルカーやロープウェイがつながり、1971年、ついに立山から長野県の大町までを結ぶ «立山黒部アルペンルート» が全線開通しました。","いま、ダムの観光放水の迫力や、室堂の «雪の大谷» を見に、国内外から多くの人が訪れます。ただ、ゴーゴーと音を立てて流れ落ちる水を見るとき、その向こうに、トンネルの中で水と闘った人たち、帰らなかった人たちがいたことを、少しだけ思い出してほしいと思います。"],"tl":[["1956年","くろよん（黒部川第四発電所）の工事が始まる"],["1957〜1958年","大町トンネル（今の関電トンネル）で破砕帯にぶつかり、苦闘の末に突破"],["1963年","黒部ダムが完成する"],["1968年","映画 «黒部の太陽» が公開される"],["1971年","立山黒部アルペンルートが全線開通"],["現在","山岳観光ルートとして国内外から観光客が訪れる"]],"who":[["太田垣士郎","関西電力の社長。くろよんの建設を決断した"],["工事の作業員たち","破砕帯などの難所と闘い、171人が殉職した"],["石原裕次郎・三船敏郎","映画 «黒部の太陽» の主演。工事の物語を広めた"]],"deep":["破砕帯があったのは長野県側の大町トンネル（今の関電トンネル）です。富山県側の立山トンネルとは別のトンネルなので、混同しないように注意。","黒部ダムは、堤高186mで日本一の高さのダムです。アーチ式のダムで、水の力を両岸の岩盤に伝えて支えます。","«171人» は、くろよん建設工事全体の殉職者数として一般に示されている数字です。ダムの近くには慰霊碑があり、工事関係者の名前が刻まれています。","アルペンルートの乗り物は時代とともに変わっています。関電トンネルのトロリーバスは2019年に電気バスに代わり、立山トンネルのトロリーバスも2024年に電気バスに切りかえられました。","くろよんの工事資材は、戦前の黒部の電源開発でつくられた «水平歩道» や上流の軌道も使いながら運ばれた、とも言われます。黒部の開発は大正から昭和へ一続きの物語です。"],"look":["黒部ダムの観光放水（例年、夏〜秋）","殉職者の慰霊碑","ダムの展望台と黒部湖","室堂の立山の景色（春の «雪の大谷»）"],"q":["くろよんの工事で、大量の水と土砂がふき出して工事を苦しめた岩盤のことを何という？","«破砕帯（はさいたい）» です。80mほど進むのに約7か月かかったといわれます。"],"koji":[],"myth":"破砕帯の長さ・日数は資料により表現が異なる。映画は事実をもとにした創作をふくむ。","img":["黒部ダム","黒部の太陽","関電トンネル"],"wp":"立山黒部アルペンルート","rel":{"ev":["kurobe"],"grave":[]},"ph":[["c:4/4a/DaikanboView.jpg",3600,1600,"立山黒部アルペンルート"],["c:e/e8/MurododairaToRaichoso.JPG",4000,3000],["c:0/0d/Lake_Kurobe01s4592.jpg",4592,3056],["c:5/5b/KurobeDamObservatoryFromOtherside.JPG",4000,3000],["c:e/e6/KurobeCablecarInterchange.JPG",4000,3000],["c:3/32/Kurobe-daira04s4592.jpg",4592,3056],["c:7/73/Bijodaira03nt3200.jpg",2130,3200],["c:d/d6/Kurobe_dam.jpg",2816,2112]]},{"id":"16_hojozu_hachiman","n":"放生津八幡宮（大伴家持ゆかりの社）","yomi":"ほうじょうづはちまんぐう","cat":"寺社","rank":"B","y":750,"era":["nara","muromachi"],"sh":"","ad":"射水市八幡町","st":"万葉線 東新湊電停から歩いて約10分","la":36.781,"lo":137.099,"hook":"«あゆの風» が吹く奈呉の浦。万葉の歌人・大伴家持が、海辺に八幡さまを招いたと伝わる。","lead":"放生津八幡宮（ほうじょうづはちまんぐう）は、射水市の新湊にある古い神社です。奈良時代に越中の国司だった大伴家持が、このあたりに八幡の神をまつったのが始まりと伝わります。秋には、豪華な曳山（ひきやま）や築山（つくりやま）が出るお祭りで知られています。","story":["新湊の海の近く、松の木が立つ境内に、放生津八幡宮があります。このあたりの海は、昔 «奈呉（なご）の浦» と呼ばれていました。奈良時代、越中の国司としてやってきた大伴家持は、この海の景色を歌によみました。«あゆの風 いたく吹くらし 奈呉の海人の 釣する小舟 漕ぎ隠る見ゆ» ―― 風が強く吹いて、漁師の小舟が波間に見え隠れする、という意味です。","«あゆの風» とは、北陸で春から夏に吹く、海からの風のことだといわれます。家持は都の生まれで、雪の多い越中の暮らしにはじめはとまどったことでしょう。けれども、この地で数多くの歌をよみ、万葉集の中でも越中でよまれた歌は大きなまとまりになっています。","神社の伝えでは、家持が九州の宇佐八幡宮から神をまねいて、この地にまつったのが始まりとされます。八幡の神は、武運や国の守りの神として広く信仰されていました。«放生津» という地名は、生き物を放して命を大切にする «放生会（ほうじょうえ）» という八幡宮の儀式から来ているといわれます。","室町時代の終わりには、この放生津が大きな事件の舞台になります。都を追われた将軍・足利義材（よしき）が、越中の守護代・神保長誠（ながのぶ）をたよって放生津に移り、ここで «幕府» のような政治を行ったといわれるのです。«越中公方（えっちゅうくぼう）» と呼ばれたこの時期、小さな港町は一時、全国の注目を集めました。","いまも秋のお祭りでは、華やかな曳山が町を練り歩き、浜辺の町は大いににぎわいます。家持の歌を口ずさみながら海辺を歩けば、1200年以上前の «奈呉の浦» の風が、ほおをなでていくような気がします。"],"tl":[["746年","大伴家持が越中守として赴任する"],["奈良時代","家持が八幡の神をこの地にまつったと伝わる"],["751年","家持が越中を去り、都へ戻る"],["1493年","明応の政変。将軍・足利義材が都を追われる"],["1490年代後半","義材が越中放生津に移り、«越中公方» と呼ばれたといわれる"],["江戸時代","放生津の町の鎮守としてあつく信仰される"],["現在","秋の祭りで曳山・築山が出る"]],"who":[["大伴家持","奈良時代の越中国司。万葉集の編者の一人とされる。神社の創建を伝えられる"],["足利義材（義稙）","室町幕府の将軍。都を追われ放生津に身を寄せた"],["神保長誠","越中の守護代。義材を迎え入れた"],["放生津の町の人びと","祭りを受けつぎ、神社を守ってきた"]],"deep":["家持の «あゆの風» の歌は万葉集巻17に収められています。«東風» と書いて «あゆのかぜ» と読ませる表記が知られ、越中の方言が歌に取り入れられた例として注目されます。","家持の越中時代（746〜751年）によまれた歌は約220首といわれ、万葉集の中でも重要なまとまりです。富山県には家持ゆかりの地が多く、«万葉の故地» として整備されています。","«放生会» は、捕らえた魚や鳥を放して殺生を戒める仏教の儀式で、八幡宮で盛んに行われました。石清水八幡宮や宇佐八幡宮の放生会がよく知られています。","明応の政変（1493年）で将軍の座を追われた足利義材は、越中放生津を拠点に京への復帰をめざしました。越中滞在の期間や拠点の具体的な場所については研究者の間で議論があります。","家持が神社を創建したという話は、神社の由緒として伝わるもので、奈良時代の確かな記録で裏づけられているわけではありません。"],"look":["境内の家持の歌碑","海に近い社殿と松の木々","秋祭りの曳山・築山（開催日を確認）","近くの内川の町並み（«日本のベニス» とも呼ばれる水辺）"],"q":["大伴家持の歌にある «あゆの風» とは、どんな風？","北陸で、海から吹いてくる風のこととされます。春から夏にかけての風といわれます。"],"koji":[{"w":"あゆの風","m":"北陸で海から吹く風。大伴家持の歌に «東風（あゆのかぜ）» としてよまれた"}],"myth":"家持による創建は神社の由緒で、確かな史料はない。義材の越中での滞在期間・拠点の細部は諸説ある。","img":["大伴家持","足利義稙","放生津"],"wp":"放生津八幡宮","rel":{"ev":[],"grave":[]},"ph":[["c:5/5d/%E6%94%BE%E7%94%9F%E6%B4%A5%E5%85%AB%E5%B9%A1%E5%AE%AE%E6%8B%9D%E6%AE%BF.JPG",4608,3456,"放生津八幡宮"],["c:2/23/%E6%94%BE%E7%94%9F%E6%B4%A5%E5%85%AB%E5%B9%A1%E5%AE%AE07.jpg",640,480],["c:e/e5/%E6%94%BE%E7%94%9F%E6%B4%A5%E5%85%AB%E5%B9%A1%E5%AE%AE06.jpg",640,480],["c:7/76/%E6%94%BE%E7%94%9F%E6%B4%A5%E5%85%AB%E5%B9%A1%E5%AE%AE05.jpg",640,480],["c:5/5d/%E6%94%BE%E7%94%9F%E6%B4%A5%E5%85%AB%E5%B9%A1%E5%AE%AE02.jpg",640,480],["c:e/e7/%E6%94%BE%E7%94%9F%E6%B4%A5%E5%85%AB%E5%B9%A1%E5%AE%AE01.jpg",640,480],["c:3/3e/Sanj%C5%ABrokkasen-gaku_-_5_-_Kan%C5%8D_Tan%E2%80%99y%C5%AB_-_Ch%C5%ABnagon_Yakamochi.jpg",1000,1450,"大伴家持"],["c:6/64/Ashikaga_Yoshitane.jpg",1729,1984,"足利義稙"]]},{"id":"16_etchu_seto","n":"越中瀬戸焼の窯跡（加賀藩の御用窯）","yomi":"えっちゅうせとやきのかまあと","cat":"産業","rank":"B","y":1590,"era":["azuchi","edo"],"sh":"","ad":"中新川郡立山町瀬戸新・上瀬戸周辺","st":"富山地方鉄道 立山線の駅（岩峅寺駅など）から車で約10分。車が便利","la":36.63,"lo":137.308,"hook":"尾張の瀬戸から来た職人が、立山のふもとの土で焼きはじめた器。«瀬戸» という地名が、その記憶を今に残す。","lead":"越中瀬戸焼は、立山町の瀬戸地区で400年以上前から焼かれてきた焼き物です。戦国時代の終わりごろ、加賀藩の前田利長が、焼き物の本場・尾張の瀬戸（愛知県）から職人を招いたのが始まりと伝わります。江戸時代には加賀藩の «御用窯» として栄えました。","story":["立山町の西のほう、田んぼの広がる中に «瀬戸» という地名があります。«瀬戸» と聞くと、愛知県の «瀬戸物» を思い浮かべる人も多いでしょう。じつは、この地名は偶然ではありません。400年あまり前、尾張の瀬戸からやってきた焼き物職人たちが、ここで窯を開いたことに由来するといわれているのです。","時は戦国時代の終わり。越中を治めることになった前田利長は、領地の産業を育てようと考えました。«よい焼き物がつくれれば、国が豊かになる» ―― そこで、焼き物の本場・瀬戸から職人を招いたと伝わります。このあたりの丘には、焼き物に向いた良い土があったのです。","江戸時代、越中瀬戸焼は加賀藩の «御用窯» として、藩のための器を焼きました。茶の湯の道具や日用の器など、さまざまなものがつくられたといわれます。窯の数も増え、瀬戸の村は焼き物の村としてにぎわいました。«殿さまの器を焼いている» という誇りが、職人たちの腕をみがいたことでしょう。","けれども明治になり、藩がなくなると、御用窯としての支えを失います。安い焼き物が大量に出回るようになり、越中瀬戸焼の窯は次々と火を消していきました。«このままでは、400年の火が消えてしまう» ―― 昭和になって、地元の人たちや陶芸家が伝統を復活させようと立ち上がり、再び窯に火が入りました。","いま、瀬戸の里にはいくつかの窯元があり、昔の窯跡や、焼き物の歴史を伝える施設もあります。土を手に取り、ろくろを回す職人の姿を見ていると、尾張から来た職人たちの技が、形を変えながら受けつがれてきたことを感じられます。"],"tl":[["1590年ごろ","前田利長が尾張の瀬戸から職人を招き、窯を開いたと伝わる"],["江戸時代","加賀藩の御用窯として栄える"],["明治時代","藩の保護を失い、しだいにおとろえる"],["昭和時代","地元の人びとや陶芸家によって復興される"],["現在","複数の窯元が越中瀬戸焼の伝統を受けついでいる"]],"who":[["前田利長","加賀藩二代藩主。瀬戸から職人を招いたと伝わる"],["尾張瀬戸から来た陶工","越中で窯を開いたとされる職人たち"],["昭和の陶芸家たち","途絶えかけた越中瀬戸焼を復興させた"]],"deep":["越中瀬戸焼の始まりは天正年間（1573〜1592年）とされることが多く、尾張瀬戸の陶工の名も伝えられていますが、同時代の史料は限られ、細部は伝承によります。","«御用窯» とは、藩のために器を焼く特別な窯のことです。加賀藩には九谷焼や大樋焼などもあり、越中瀬戸焼はその中で越中を代表する窯でした。","越中瀬戸焼の特徴としてよく挙げられるのが、地元の土を生かした素朴な風合いと、落ち着いた色合いの釉薬（うわぐすり）です。窯元ごとに作風が異なります。","立山町の瀬戸地区には、古い窯の跡が確認されており、発掘調査も行われてきたといわれます。窯跡の場所や公開状況は、町の案内で確かめてください。","«瀬戸» という地名は、焼き物産地の名前が職人とともに移り住んだ例です。人の移動とともに地名が運ばれる現象は、ほかの地方でも見られます。"],"look":["窯元の工房や作品（見学は事前に確認）","焼き物の歴史を伝える施設の展示","窯跡の案内板（あれば）","立山のふもとの里の風景"],"q":["越中瀬戸焼の職人は、どこの焼き物の産地から招かれたと伝わる？","尾張の瀬戸（今の愛知県瀬戸市）です。地名の «瀬戸» もそれに由来するといわれます。"],"koji":[],"myth":"創始の年・陶工の名は伝承による。窯跡の指定状況や公開の有無は要確認。","img":["立山町","前田利長","瀬戸焼"],"wp":"越中瀬戸焼","rel":{"ev":[],"grave":[]},"ph":[["c:7/78/Kurobe_Dam_survey_2.jpg",2112,2816,"立山町"],["c:6/68/Maeda_Toshinaga.jpg",354,396,"前田利長"],["c:5/5d/Found_MUJI_Setoyaki_%286910176253%29.jpg",3344,2224,"瀬戸焼"]]},{"id":"16_abugashima","n":"虻が島（氷見沖の小島・有磯海）","yomi":"あぶがしま","cat":"島","rank":"B","y":1689,"era":["nara","edo"],"sh":"県指定天然記念物","ad":"氷見市姿（沖合）","st":"島へは定期便がなく、上陸はふつうできない。JR氷見駅から車で約20分の姿地区の海岸から眺めるのが基本","la":36.94,"lo":137.0,"hook":"家持がうたい、芭蕉があこがれた «有磯海（ありそうみ）»。その海に、小さな島がぽつんと浮かんでいる。","lead":"虻が島（あぶがしま）は、氷見市の北の沖合に浮かぶ小さな無人島です。暖かい地方の植物と寒い地方の植物が一緒に育つめずらしい島として、富山県の天然記念物になっています。このあたりの海は、万葉集や芭蕉の句にもよまれた «有磯海» として知られています。","story":["氷見の海岸を北へ進むと、沖に小さな緑の島が見えてきます。これが虻が島です。周りはわずか数百メートルほどの小さな島。人は住んでいません。でも、この島は、たくさんの «歴史のことば» にかこまれた島なのです。","このあたりの海は、昔から «有磯海（ありそうみ）» と呼ばれてきました。«荒い磯の海» という意味だといわれます。奈良時代、越中の国司だった大伴家持は、この海の景色を歌によみました。そして江戸時代、松尾芭蕉は «奥の細道» の旅で越中を通り、«わせの香や 分け入る右は 有磯海» という句を残しています。","«わせ» とは、早く実る稲のこと。稲の香りがただよう田んぼの道を進むと、右手に有磯海が広がっている ―― そんな情景です。じつは芭蕉は、有磯海のあたりの歌枕をたずねたかったのに、たずねられずに先へ進んだともいわれます。«あの海を見たかったなあ» という思いが、この句にこめられているのかもしれません。","虻が島は、植物の島としても有名です。島には、南の暖かい地方に多い植物と、北の寒い地方に多い植物が、同じ島に育っているといわれます。«なぜ、こんな小さな島に?» ―― 対馬海流という暖かい海流が近くを流れていることや、人の手が入りにくかったことが理由と考えられています。","«虻が島» という名前の由来にはいくつかの説があり、島の形が虫のアブに似ているから、ともいわれます。海岸から島をながめ、家持と芭蕉がよんだ «有磯海» を思いうかべれば、この小さな島が、1300年の文学の歴史を背負っていることに気づくでしょう。"],"tl":[["746〜751年","大伴家持が越中国司として在任。越中の海をよむ"],["1689年","松尾芭蕉が «奥の細道» の旅で越中を通り、有磯海の句をよむ"],["江戸時代","有磯海は歌枕として知られる"],["昭和時代","島の植物が富山県の天然記念物に指定される"],["現在","能登半島国定公園の一部として、海岸から眺められる"]],"who":[["大伴家持","越中国司。有磯海を歌によんだ"],["松尾芭蕉","«わせの香や 分け入る右は 有磯海» の句をよんだ俳人"],["河合曾良","芭蕉の旅に同行し、旅日記を残した弟子"]],"deep":["«有磯海» がどの海を指すかには諸説あり、富山湾西部の氷見〜伏木あたりの海岸とする考え方がよく知られています。歌枕は、時代によって指す場所が変わることもあります。","芭蕉の句の «分け入る右は» は、北へ向かう芭蕉から見て右手、つまり東側に海が広がっていたことを示しています。旅の道すじが、句の中に地図のように表れています。","曾良の旅日記によると、芭蕉は越中で体調をくずしながらの旅だったともいわれ、氷見方面の名所をたずねることはできなかったと考えられています。","虻が島の植物は、暖地性・寒地性の植物がまじる点が注目されます。どの種類がどれだけ生えているかは調査によって異なるので、くわしくは県や市の資料を確かめてください。","虻が島の周りの海は、磯の生き物が豊かで、ダイビングの場所としても知られるといわれます。上陸や海での活動は、地元のルールや安全に十分注意する必要があります。"],"look":["姿地区の海岸から見る虻が島","晴れた日に海の向こうに見える立山連峰","近くの海岸の磯と岩場","氷見市内の芭蕉や家持の句碑・歌碑"],"q":["芭蕉が «わせの香や 分け入る右は 有磯海» とよんだのは、何という旅の途中？","«奥の細道» の旅（1689年）の途中です。"],"koji":[{"w":"わせの香や 分け入る右は 有磯海","m":"芭蕉の句。早稲の香りの中を進むと、右手に有磯海が広がる、という越中の情景"}],"myth":"島の名の由来、有磯海の範囲には諸説ある。天然記念物の指定年、上陸の可否は要確認。","img":["有磯海","奥の細道","大伴家持"],"wp":"虻が島","rel":{"ev":[],"grave":[]},"ph":[["c:7/72/Abuga-Shima_island_Aerial_Photograph.JPG",1072,800,"虻が島"],["c:d/d6/%E8%99%BB%E3%82%AC%E5%B3%B6%EF%BC%88%E5%AF%8C%E5%B1%B1%E7%9C%8C%E6%B0%B7%E8%A6%8B%E5%B8%82%EF%BC%8920260221-IMG_5696.jpg",1600,1067],["c:3/3e/Sanj%C5%ABrokkasen-gaku_-_5_-_Kan%C5%8D_Tan%E2%80%99y%C5%AB_-_Ch%C5%ABnagon_Yakamochi.jpg",1000,1450,"大伴家持"]]}];
